def chooses(markup: str, subject: str) -> bool:
    norm = lambda t: re.sub(
        r"\s+", " ", re.sub(r"\s*([=:])\s*", r"\1", t.replace("'", '"'))
    )
    return bool(
        re.search(
            r"(?:^|(?<=[\s<{;,(]))" + re.escape(norm(markup)) + r"(?![\w-])",
            norm(subject),
        )
    )

def filled(field: re.Match | None) -> bool:
    return bool(
        field and field.group(1).strip() and not field.group(1).lstrip().startswith("[")
    )

def gate_decisions(
    decisions_path: Path | None, findings: list[GateFinding]
) -> list[tuple[int, str, str]]:
    if not decisions_path or not decisions_path.is_file():
        return []
    blank = lambda m: re.sub(r"[^\n]", " ", m.group(0))
    text = FENCE.sub(blank, HTML_COMMENT.sub(blank, read(decisions_path) or ""))
    heading = re.search(r"^##\s+(?:Decisions|Decisões)\b", text, re.MULTILINE)
    if not heading:
        return []
    found = []
    for n, raw in enumerate(
        text[heading.start() :].split("\n"), line_of(text, heading.start())
    ):
        if raw.lstrip().startswith(">") or "~~" in raw:
            continue
        for match in DECISION_GATE.finditer(raw):
            check, markup = match.group(1), match.group(2).strip()
            if check not in SOURCE_CHECKS:
                findings.append(
                    GateFinding(
                        "WARN",
                        "registers",
                        f"A11Y-DECISIONS.md:{n} names `{check}`, which is not a check this gate runs.",
                    )
                )
            elif check not in CHOICE_CHECKS:
                findings.append(
                    GateFinding(
                        "WARN",
                        "registers",
                        f"A11Y-DECISIONS.md:{n} names `{check}`, which flags a failure, not a choice between conformant alternatives. Fix it, or accept it in EXCEPTIONS.md with an owner, an approver and an expiry.",
                    )
                )
            elif not MARKUP.fullmatch(markup):
                findings.append(
                    GateFinding(
                        "WARN",
                        "registers",
                        f'A11Y-DECISIONS.md:{n} names `{markup}`, which is not one attribute or declaration with its value (`role="list"`, `outline: none`). A fragment would cover every `{check}` finding in the project.',
                    )
                )
            else:
                found.append((n, check, markup))
    return found

def gate_exceptions(
    root: Path, src: Path, exceptions_path: Path | None, findings: list[GateFinding]
) -> list[tuple[str, list[str], list[str], str, dt.date | None, bool]]:
    if not exceptions_path or not exceptions_path.is_file():
        return []
    entries = exception_entries(exceptions_path)
    stray = sum(
        1 for m in GATE_FIELD.finditer(read(exceptions_path) or "") if filled(m)
    ) - sum(1 for _, block in entries if filled(GATE_FIELD.search(block)))
    if stray > 0:
        findings.append(
            GateFinding(
                "WARN",
                "registers",
                f"EXCEPTIONS.md has {stray} Gate finding field(s) outside an entry the gate can read. They cover nothing.",
            )
        )
    found = []
    today = dt.datetime.now(dt.timezone.utc).date()
    for label, block in entries:
        field = GATE_FIELD.search(block)
        if field is None or not filled(field):
            continue
        tokens = re.findall(r"`([^`]+)`", field.group(1))
        checks = [t for t in tokens if t in SOURCE_CHECKS]
        files, strangers = [], []
        for name in (as_path(t) for t in tokens if t not in SOURCE_CHECKS):
            for base in (root, src):
                if name and (base / name).is_file():
                    files.append((base / name).relative_to(root).as_posix())
                    break
            else:
                strangers.append(name or "(empty)")
        if not checks or not files or strangers:
            findings.append(
                GateFinding(
                    "WARN",
                    "registers",
                    f"{label}: the Gate finding field must name at least one check the gate runs and each file it covers, in backticks (`clickable-div` in `src/legacy/Grid.tsx`)"
                    + (
                        f"; not a file in this project: {', '.join(strangers)}"
                        if strangers
                        else ""
                    )
                    + ". A directory would cover a whole rule (EXCEPTIONS.md rule 3).",
                )
            )
            if not checks or not files:
                continue
        unsigned = [
            f
            for f, pattern in (
                ("risk owner", r"(Risk Owner|Dono do Risco)"),
                ("approver", r"(Approved by|Aprovado por)"),
                ("tracking issue", r"(Tracking Issue|Issue de Rastreio)"),
            )
            if (m := re.search(pattern + r":\*{0,2}[ \t]*(.*)", block))
            and UNSIGNED.search(m.group(2).strip())
        ]
        approver = re.search(r"(?:Approved by|Aprovado por):\*{0,2}[ \t]*(.*)", block)
        if approver and AGENT.search(approver.group(1)) and "approver" not in unsigned:
            unsigned.append("approver")
        if unsigned and not missing_fields(block):
            findings.append(
                GateFinding(
                    "WARN",
                    "registers",
                    f"{label} names a gate finding but its {' and '.join(unsigned)} name(s) nobody who can sign ('pending', 'TBD', 'none', an AI agent): it covers nothing until a person signs.",
                )
            )
        date_val = re.search(
            r"(?:Expiry|Expiração)[^:\n]*:\*{0,2}[ \t]*\[?(\d{4}-\d{2}-\d{2})", block
        )
        date = dt.date.fromisoformat(date_val.group(1)) if date_val else None
        in_force = (
            not missing_fields(block)
            and not unsigned
            and date is not None
            and date >= today
        )
        found.append(
            (
                label,
                checks,
                files,
                (approver.group(1).strip() if approver else "")[:40],
                date,
                in_force,
            )
        )
    return found

def apply_registers(
    root: Path,
    src: Path,
    exceptions_path: Path | None,
    decisions_path: Path | None,
    findings: list[GateFinding],
) -> None:
    exceptions = gate_exceptions(root, src, exceptions_path, findings)
    decisions = gate_decisions(decisions_path, findings)
    if not exceptions and not decisions:
        return
    used: set[int] = set()
    for i, f in enumerate(findings):
        at = FINDING_AT.match(f.message)
        if f.level == "REGISTERED" or f.check not in SOURCE_CHECKS or not at:
            continue
        rel = Path(at.group(1)).as_posix()
        record = None
        for k, (label, checks, files, approver, date, in_force) in enumerate(
            exceptions
        ):
            if f.check in checks and rel in files:
                used.add(k)
                if in_force and not record:
                    record = (
                        f"EXCEPTIONS.md {label}, approved by {approver}, until {date}"
                    )
        if not record and f.subject:
            record = next(
                (
                    f"A11Y-DECISIONS.md:{n}"
                    for n, chosen, markup in decisions
                    if chosen == f.check and chooses(markup, f.subject)
                ),
                None,
            )
        if record:
            findings[i] = GateFinding(
                "REGISTERED", f.check, f"{f.message} [{record}]", f.subject
            )
    scanned = src.resolve()
    for k, (label, checks, files, _, _, in_force) in enumerate(exceptions):
        if (
            in_force
            and k not in used
            and any((root / f).resolve().is_relative_to(scanned) for f in files)
        ):
            findings.append(
                GateFinding(
                    "WARN",
                    "registers",
                    f"{label} covers {', '.join(f'`{c}`' for c in checks)} in {', '.join(files)}, and this run finds none there. If it was fixed, close the exception.",
                )
            )

def expiry_of(block: str) -> dt.date | None:
    expiry = re.search(
        r"(?:Expiry|Expiração)[^:\n]*:\*{0,2}[ \t]*\[?(\d{4}-\d{2}-\d{2})", block
    )
    return dt.date.fromisoformat(expiry.group(1)) if expiry else None

def git(root: Path, *args: str) -> str | None:
    try:
        out = subprocess.run(
            ["git", "-C", str(root), *args],
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
        return out.stdout.strip() if out.returncode == 0 else None
    except (OSError, subprocess.SubprocessError):
        return None

def missing_fields(block: str) -> list[str]:
    missing = []
    for field, pattern in SIGN_OFF:
        m = re.search(pattern + r":\*{0,2}[ \t]*(.*)", block)
        if not m or not m.group(2).strip() or PLACEHOLDER.search(m.group(2)):
            missing.append(field)
    return missing

def read(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None

def body_of(report: Path) -> str:
    text = read(report) or ""
    return "\n".join(l for l in text.splitlines() if not l.lstrip().startswith(">"))

def check_gitignore(root: Path, findings: list[GateFinding]) -> None:
    gitignore = root / ".gitignore"
    if not gitignore.is_file():
        return
    patterns = [
        l.strip()
        for l in (read(gitignore) or "").splitlines()
        if l.strip() and not l.startswith("#")
    ]
    for artifact in ARTIFACTS:
        for pattern in patterns:
            if pattern.strip("/") == artifact or pattern in ("*.md", "**/*.md"):
                findings.append(
                    GateFinding(
                        "ERROR",
                        "gitignore",
                        f"{artifact} is excluded by .gitignore rule '{pattern}'. Project artifacts must be versioned.",
                    )
                )
                break

def exception_entries(path: Path | None) -> list[tuple[str, str]]:
    if not path or not path.is_file():
        return []
    text = read(path) or ""
    blocks = re.split(
        r"^#{2,4}\s+\d+\.\s*(?:Basic Details|Detalhes Básicos)",
        text,
        flags=re.MULTILINE,
    )[1:]
    entries = []
    for i, block in enumerate(blocks, 1):
        entry_id = re.search(r"(?:Exception ID|ID da Exceção):\*{0,2}[ \t]*(.*)", block)
        label = (entry_id.group(1).strip() if entry_id else f"entry #{i}")[:40]
        if label and not PLACEHOLDER.search(label):
            entries.append((label, block))
    return entries

def check_exceptions(path: Path | None, findings: list[GateFinding]) -> None:
    if not path or not path.is_file():
        return
    today = dt.datetime.now(dt.timezone.utc).date()
    for label, block in exception_entries(path):
        for field in missing_fields(block):
            findings.append(
                GateFinding("ERROR", "exceptions", f"{label}: missing {field}.")
            )
        date = expiry_of(block)
        if not date:
            findings.append(
                GateFinding(
                    "ERROR",
                    "exceptions",
                    f"{label}: missing or unparseable expiry date (use YYYY-MM-DD).",
                )
            )
        elif date < today:
            findings.append(
                GateFinding(
                    "ERROR",
                    "exceptions",
                    f"{label}: expired on {date} — review, fix or consciously renew it.",
                )
            )
        elif (date - today).days <= 14:
            findings.append(
                GateFinding(
                    "WARN",
                    "exceptions",
                    f"{label}: expires in {(date - today).days} day(s).",
                )
            )

def source_files(root: Path, src: Path) -> Generator[Path, None, None]:
    for path in src.rglob("*"):
        if path.is_file() and path.suffix.lower() in SOURCE_SUFFIXES:
            try:
                rel_parts = path.relative_to(root).parts
            except ValueError:
                rel_parts = path.parts
            if not any(part in SKIP_DIRS for part in rel_parts):
                yield path

def check_report_freshness(
    root: Path, report: Path, src: Path, findings: list[GateFinding]
) -> None:
    try:
        src_rel = str(src.relative_to(root)) if src != root else "."
    except ValueError:
        src_rel = "."

    last_ui = git(root, "log", "-1", "--format=%cI", "--", src_rel)
    last_report = git(root, "log", "-1", "--format=%cI", "--", report.name)
    if last_ui and last_report:
        if last_report < last_ui:
            findings.append(
                GateFinding(
                    "ERROR",
                    "freshness",
                    f"REPORT.md (last commit {last_report[:10]}) is older than the last "
                    f"interface change ({last_ui[:10]}). Revisit the entries that change affects.",
                )
            )
        return
    newest = max((p.stat().st_mtime for p in source_files(root, src)), default=None)
    if newest and report.stat().st_mtime < newest:
        findings.append(
            GateFinding(
                "ERROR",
                "freshness",
                "REPORT.md is older than the most recently modified source file.",
            )
        )

def status_claims_pass(body: str) -> bool:
    status = re.search(
        r"(?:Compliance Status|Status de Conformidade):?\*{0,2}[ \t]*(.*)",
        body,
        re.IGNORECASE,
    )
    value = status.group(1).strip() if status else ""
    conditional = re.search(r"CONDITIONAL|CONDICIONAL", value, re.IGNORECASE)
    return bool(
        not conditional
        and (re.search(r"\bPASS\b", value, re.IGNORECASE) or "✅" in value)
    )

def check_report_independence(report: Path, findings: list[GateFinding]) -> None:
    body = body_of(report)
    field = re.search(
        r"(?:Verification Independence|Independência da Verificação):?\*{0,2}[ \t]*(.*)",
        body,
        re.IGNORECASE,
    )
    if not field:
        findings.append(
            GateFinding(
                "ERROR",
                "independence",
                "REPORT.md has no Verification Independence field. Add it from "
                "templates/REPORT.md and declare who reproduced the automated checkpoints "
                "(A11Y.md §2, Independent Verification).",
            )
        )
        return

    value = field.group(1).strip()
    levels = [
        name
        for name in ("cross-agent", "fresh-context", "self-reported")
        if name in value.lower()
    ]
    if len(levels) != 1:
        findings.append(
            GateFinding(
                "ERROR",
                "independence",
                "REPORT.md does not declare exactly one verification level — expected "
                f"cross-agent, fresh-context or self-reported, found {len(levels)}. An untouched template menu counts as undeclared.",
            )
        )
        return

    level = levels[0]
    if level == "self-reported":
        if status_claims_pass(body):
            findings.append(
                GateFinding(
                    "ERROR",
                    "independence",
                    "REPORT.md claims PASS on self-reported verification — the agent that "
                    "generated the code is the only witness that it conforms. Re-run the "
                    "automated checkpoints in a fresh session (or with another agent), or "
                    "lower the status to CONDITIONAL.",
                )
            )
        else:
            findings.append(
                GateFinding(
                    "WARN",
                    "independence",
                    "Verification is self-reported: the generating agent checked its own "
                    "output. Ceiling is CONDITIONAL. A new chat over this project, without "
                    "the conversation that produced the code, raises it to fresh-context.",
                )
            )

    if re.fullmatch(
        r"(cross-agent|fresh-context|self-reported)\W*", value, re.IGNORECASE
    ):
        findings.append(
            GateFinding(
                "WARN",
                "independence",
                f"Verification level is '{level}' but nobody is named. Record which "
                "model/agent and which session reproduced the checkpoints — an "
                "unattributed level is not reproducible evidence.",
            )
        )

def without_code_samples(text: str | None) -> str | None:
    if text is None:
        return None
    return CODE_SAMPLE.sub(
        lambda m: m.group(1) + re.sub(r"[^\n]", " ", m.group(3)) + m.group(4), text
    )

def without_comments(text: str | None, suffix: str) -> str | None:
    if text is None:
        return None
    blank = lambda m: re.sub(r"[^\n]", " ", m.group(0))
    if suffix in SCRIPT_SUFFIXES or suffix in (".css", ".scss"):
        text = BLOCK_COMMENT.sub(blank, text)
    if suffix in SCRIPT_SUFFIXES:
        text = LINE_COMMENT.sub(blank, text)
    if suffix in MARKUP_SUFFIXES:
        text = HTML_COMMENT.sub(blank, text)
    return text

def check_guide_coverage(
    root: Path, report: Path, src: Path, findings: list[GateFinding]
) -> None:
    body = body_of(report)
    section = re.search(
        r"^#{2,3}\s*3\.[^\n]*\n(.*?)(?=^##\s|\Z)", body, re.MULTILINE | re.DOTALL
    )
    named = section.group(1).lower() if section else ""
    claims_pass = status_claims_pass(body)

    for path in sorted(source_files(root, src)):
        suffix = path.suffix.lower()
        if suffix in (".css", ".scss"):
            continue
        text = scannable(path)
        if not text:
            continue
        flags = re.IGNORECASE if suffix in (".html", ".htm") else 0
        for guide, patterns in GUIDE_SIGNATURES.items():
            if guide in named:
                continue
            for pattern in patterns:
                m = re.search(pattern, text, flags)
                if m:
                    try:
                        rel = path.relative_to(root)
                    except ValueError:
                        rel = path
                    line = text.count("\n", 0, m.start()) + 1
                    where = f"{rel}:{line}"
                    if claims_pass:
                        findings.append(
                            GateFinding(
                                "ERROR",
                                "guide-coverage",
                                f"REPORT.md claims PASS but does not cover `{guide}` in §3, while {where} contains its component ({m.group(0)[:40]!r}). Run that guide's scenarios before claiming PASS (A11Y.md §7).",
                            )
                        )
                    else:
                        findings.append(
                            GateFinding(
                                "WARN",
                                "guide-coverage",
                                f"{where} matches `{guide}`, but REPORT.md §3 does not name it. If the interface contains that component, run its scenarios (A11Y.md §7).",
                            )
                        )
                    break

def hex_rgb(token: str) -> tuple[int, int, int]:
    h = token.lstrip("#")
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)

def normalize_hex(token: str) -> str:
    h = token.lstrip("#").lower()
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return h

def run_selftest(runner_func: Callable[..., Any]) -> tuple[int, str]:
    ok = True
    lines = []
    for item in SELF_TEST_CASES:
        name: str = item[0]  # type: ignore[assignment]
        files: dict[str, str] = item[1]  # type: ignore[assignment]
        want_err: set[str] = item[2]  # type: ignore[assignment]
        want_warn: set[str] = item[3]  # type: ignore[assignment]
        forbid: set[str] = item[4]  # type: ignore[assignment]
        want_reg: Any = item[5:]
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for rel, content in files.items():
                path = root / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
            res = runner_func(root, root / "src")
            errs = {f.check for f in res.errors}
            warns = {f.check for f in res.warnings}
            regs = {f.check for f in res.registered}
            seen = errs | warns
            missing = (want_err - errs) | (want_warn - warns)
            unexpected = (forbid & seen) | (errs - want_err - want_warn)
            if want_reg:
                missing |= want_reg[0] - regs
                unexpected |= regs - want_reg[0]
            passed = not missing and not unexpected
            ok &= passed
            lines.append(f"  {'OK' if passed else 'FAIL'} {name}")
            if not passed:
                for f in res.findings:
                    lines.append(f"      {f.level} [{f.check}] {f.message[:110]}")
                if missing:
                    lines.append(f"      missing: {sorted(missing)}")
                if unexpected:
                    lines.append(f"      unexpected: {sorted(unexpected)}")
    lines.append(f"self-test: {'PASS' if ok else 'FAIL'}")
    return (0 if ok else 1, "\n".join(lines))

def _paeth_predict(a: int, b: int, c: int) -> int:
    p = a + b - c
    pa = abs(p - a)
    pb = abs(p - b)
    pc = abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c

def _safe_rel(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root)).replace("\\", "/")
    except ValueError:
        return str(p).replace("\\", "/")

def _dir_has_entries(path: Path) -> bool:
    try:
        return path.is_dir() and any(path.iterdir())
    except OSError:
        return False

def _available_docs(paths: FeaturePaths, include_tasks: bool) -> list[str]:
    docs: list[str] = []
    if paths.research.is_file():
        docs.append("research.md")
    if paths.data_model.is_file():
        docs.append("data-model.md")
    if _dir_has_entries(paths.contracts_dir):
        docs.append("contracts/")
    if paths.quickstart.is_file():
        docs.append("quickstart.md")
    if include_tasks and paths.tasks.is_file():
        docs.append("tasks.md")
    return docs

def _parse_args(argv: list[str]) -> Args:
    json_mode = False
    require_tasks = False
    include_tasks = False
    paths_only = False
    template_name = None

    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--json":
            json_mode = True
        elif arg == "--require-tasks":
            require_tasks = True
        elif arg == "--include-tasks":
            include_tasks = True
        elif arg == "--paths-only":
            paths_only = True
        elif arg == "--template":
            index += 1
            if index >= len(argv):
                print(
                    "ERROR: --template requires a template name",
                    file=sys.stderr,
                )
                raise SystemExit(1)
            template_name = argv[index]
        elif arg in {"--help", "-h"}:
            sys.stdout.write(HELP_TEXT)
            raise SystemExit(0)
        else:
            print(
                f"ERROR: Unknown option '{arg}'. Use --help for usage information.",
                file=sys.stderr,
            )
            raise SystemExit(1)
        index += 1

    return Args(
        json_mode=json_mode,
        require_tasks=require_tasks,
        include_tasks=include_tasks,
        paths_only=paths_only,
        template_name=template_name,
    )

def _status_marker(ok: bool) -> str:
    glyph = "✓" if ok else "✗"
    try:
        glyph.encode(getattr(sys.stdout, "encoding", None) or "utf-8")
    except (LookupError, UnicodeEncodeError):
        return "[OK]" if ok else "[FAIL]"
    return glyph

def main(argv: list[str] | None = None) -> int:
    args = _parse_args(list(argv if argv is not None else sys.argv[1:]))

    try:
        paths = get_feature_paths(
            no_persist=args.paths_only,
            script_file=Path(__file__),
        )
    except SystemExit as exc:
        if exc.code == 0:
            return 0
        print("ERROR: Failed to resolve feature paths", file=sys.stderr)
        return int(exc.code) if isinstance(exc.code, int) else 1

    if args.paths_only:
        _print_paths_only(paths, args.json_mode)
        return 0

    if not paths.feature_dir.is_dir():
        print(
            f"ERROR: Feature directory not found: {paths.feature_dir}", file=sys.stderr
        )
        print(
            f"Run {format_speckit_command('specify', paths.repo_root)} first to create the feature structure.",
            file=sys.stderr,
        )
        return 1

    if not paths.impl_plan.is_file():
        print(f"ERROR: plan.md not found in {paths.feature_dir}", file=sys.stderr)
        print(
            f"Run {format_speckit_command('spec-plan', paths.repo_root)} first to create the implementation plan.",
            file=sys.stderr,
        )
        return 1

    if args.require_tasks and not paths.tasks.is_file():
        print(f"ERROR: tasks.md not found in {paths.feature_dir}", file=sys.stderr)
        print(
            f"Run {format_speckit_command('spec-tasks', paths.repo_root)} first to create the task list.",
            file=sys.stderr,
        )
        return 1

    docs = _available_docs(paths, args.include_tasks)
    template_content = None
    if args.template_name:
        try:
            template_content = resolve_template_content(
                args.template_name, paths.repo_root
            )
        except TemplateResolutionError as exc:
            print(f"ERROR: {exc}", file=sys.stderr)
            return 1
        if template_content is None:
            print(
                f"ERROR: Could not resolve required {args.template_name} from template stack",
                file=sys.stderr,
            )
            return 1

    if args.json_mode:
        payload: dict[str, object] = {
            "FEATURE_DIR": str(paths.feature_dir),
            "AVAILABLE_DOCS": docs,
        }
        if args.template_name:
            payload["TEMPLATE_CONTENT"] = template_content
        sys.stdout.write(_json_line(payload))
    else:
        _print_text_results(paths, args.include_tasks)
    return 0

def _conventional_template(base_dir: Path, template_name: str) -> Path | None:
    for candidate in (
        base_dir / "templates" / f"{template_name}.md",
        base_dir / f"{template_name}.md",
    ):
        if candidate.is_file():
            return candidate
    return None

def _get_bundled_template_content(template_name: str) -> str | None:
    try:
        template_file = (
            resources.files("buddhi.templates.agents.templates") / f"{template_name}.md"
        )
        if template_file.is_file():
            return template_file.read_text(encoding="utf-8")
    except (OSError, UnicodeError, AttributeError, ModuleNotFoundError, TypeError):
        pass
    return None

def _is_safe_component(value: object) -> bool:
    return (
        isinstance(value, str) and _SAFE_COMPONENT_PATTERN.fullmatch(value) is not None
    )

def _normalize_priority(value: object) -> int:
    if isinstance(value, bool):
        return 10
    if isinstance(value, (int, str)):
        try:
            priority = int(value)
            return priority if priority >= 1 else 10
        except (TypeError, ValueError, OverflowError):
            return 10
    return 10

def _trim_trailing_separators(value: Path) -> str:
    text = str(value)
    while len(text) > 1 and text.endswith((os.sep, "/")):
        text = text[:-1]
    return text

def find_buddhi_root(start_dir: Path | None = None) -> Path | None:
    current = (start_dir or Path.cwd()).resolve()
    while True:
        if (
            (current / ".buddhi").is_dir()
            or (current / ".agents").is_dir()
            or (current / ".specify").is_dir()
        ):
            return current
        parent = current.parent
        if parent == current:
            return None
        current = parent

def format_speckit_command(command_name: str, repo_root: Path | None = None) -> str:
    name = command_name.lstrip("/")
    if name.startswith("speckit."):
        name = name[len("speckit.") :]
    elif name.startswith("speckit-"):
        name = name[len("speckit-") :]
    elif name.startswith("sdd-"):
        name = name[len("sdd-") :]
    name = _CANONICAL_COMMANDS.get(name, name)
    return f"/{name}"

def get_current_branch() -> str:
    env_branch = os.environ.get("SPECIFY_FEATURE", "")
    if env_branch:
        return env_branch
    try:
        res = subprocess.run(
            ["git", "branch", "--show-current"],
            capture_output=True,
            text=True,
            check=False,
        )
        if res.returncode == 0 and res.stdout.strip():
            return res.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return ""

def read_feature_json_feature_directory(repo_root: Path) -> str:
    for candidate in [
        repo_root / ".buddhi" / "feature.json",
        repo_root / ".specify" / "feature.json",
    ]:
        if candidate.is_file():
            try:
                data = json.loads(candidate.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    val = data.get("feature_directory")
                    if isinstance(val, str) and val.strip():
                        return val.strip()
            except (OSError, UnicodeError, json.JSONDecodeError):
                pass
    return ""

def persist_feature_json(repo_root: Path, feature_dir_value: str) -> None:
    value = feature_dir_value
    relative = Path(value)
    if relative.is_absolute():
        try:
            value = relative.relative_to(repo_root).as_posix()
        except ValueError:
            value = str(relative)

    current = read_feature_json_feature_directory(repo_root)
    if current == value:
        return

    buddhi_dir = repo_root / ".buddhi"
    buddhi_dir.mkdir(parents=True, exist_ok=True)
    (buddhi_dir / "feature.json").write_bytes(
        _json_dump({"feature_directory": value}).encode("utf-8")
    )

def resolve_specify_init_dir() -> Path:
    raw = os.environ.get("SPECIFY_INIT_DIR", "")
    candidate = Path(raw)
    if not candidate.is_absolute():
        candidate = Path.cwd() / candidate
    try:
        init_root = candidate.resolve(strict=True)
    except OSError:
        print(
            f"ERROR: SPECIFY_INIT_DIR does not point to an existing directory: {raw}",
            file=sys.stderr,
        )
        raise SystemExit(1)
    if not init_root.is_dir():
        print(
            f"ERROR: SPECIFY_INIT_DIR does not point to an existing directory: {raw}",
            file=sys.stderr,
        )
        raise SystemExit(1)
    return init_root

def get_repo_root(script_file: Path | None = None) -> Path:
    if os.environ.get("SPECIFY_INIT_DIR"):
        return resolve_specify_init_dir()

    root = find_buddhi_root()
    if root is not None:
        return root

    if script_file is not None:
        script_root = find_buddhi_root(script_file.resolve().parent)
        if script_root is not None:
            return script_root

    return Path.cwd().resolve()

def get_feature_paths(
    *, no_persist: bool = False, script_file: Path | None = None
) -> FeaturePaths:
    repo_root = get_repo_root(script_file)
    current_branch = get_current_branch()

    feature_dir_raw = os.environ.get("SPECIFY_FEATURE_DIRECTORY", "")
    if feature_dir_raw:
        feature_dir = Path(feature_dir_raw)
        if not feature_dir.is_absolute():
            feature_dir = repo_root / feature_dir
        if not no_persist:
            persist_feature_json(repo_root, feature_dir_raw)
    else:
        stored = read_feature_json_feature_directory(repo_root)
        if stored:
            feature_dir = Path(stored)
            if not feature_dir.is_absolute():
                feature_dir = repo_root / feature_dir
        elif current_branch:
            # Check if .buddhi/specs/<branch> or specs/<branch> exists
            buddhi_spec_dir = repo_root / ".buddhi" / "specs" / current_branch
            root_spec_dir = repo_root / "specs" / current_branch
            if buddhi_spec_dir.is_dir():
                feature_dir = buddhi_spec_dir
            elif root_spec_dir.is_dir():
                feature_dir = root_spec_dir
            else:
                feature_dir = buddhi_spec_dir
        else:
            print(
                "ERROR: Feature directory not found. Set SPECIFY_FEATURE_DIRECTORY "
                "or run the /specify command to create .buddhi/specs/<feature>.",
                file=sys.stderr,
            )
            raise SystemExit(1)

    if not current_branch:
        current_branch = Path(_trim_trailing_separators(feature_dir)).name

    return FeaturePaths(
        repo_root=repo_root,
        current_branch=current_branch,
        feature_dir=feature_dir,
        feature_spec=feature_dir / "spec.md",
        impl_plan=feature_dir / "plan.md",
        tasks=feature_dir / "tasks.md",
        research=feature_dir / "research.md",
        data_model=feature_dir / "data-model.md",
        quickstart=feature_dir / "quickstart.md",
        contracts_dir=feature_dir / "contracts",
    )

def resolve_template_content(template_name: str, repo_root: Path) -> str | None:
    """Resolve and compose template content through the project layer stack."""
    if not _is_safe_component(template_name):
        return None

    # 1. Project overrides and templates under .agents/templates/
    agents_templates = repo_root / ".agents" / "templates"
    override = agents_templates / "overrides" / f"{template_name}.md"
    if override.is_file():
        try:
            return override.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {override}: {exc}") from exc

    core = agents_templates / f"{template_name}.md"
    if core.is_file():
        try:
            return core.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {core}: {exc}") from exc

    # 2. Legacy .specify/templates/
    specify_templates = repo_root / ".specify" / "templates"
    specify_override = specify_templates / "overrides" / f"{template_name}.md"
    if specify_override.is_file():
        try:
            return specify_override.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(
                f"Failed to read {specify_override}: {exc}"
            ) from exc

    specify_core = specify_templates / f"{template_name}.md"
    if specify_core.is_file():
        try:
            return specify_core.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(
                f"Failed to read {specify_core}: {exc}"
            ) from exc

    # 3. Built-in bundled template fallback
    bundled = _get_bundled_template_content(template_name)
    if bundled is not None:
        return bundled

    return None

def _clean_branch_name(name: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]", "-", name.lower())
    cleaned = re.sub(r"-+", "-", cleaned)
    return cleaned.strip("-")

def _generate_branch_name(description: str) -> str:
    clean = re.sub(r"[^a-z0-9]", " ", description.lower())
    meaningful: list[str] = []
    for word in clean.split():
        if word in _STOP_WORDS:
            continue
        if len(word) >= 3 or re.search(
            rf"(?<![0-9A-Za-z_]){re.escape(word.upper())}(?![0-9A-Za-z_])",
            description,
        ):
            meaningful.append(word)

    if meaningful:
        max_words = 4 if len(meaningful) == 4 else 3
        return "-".join(meaningful[:max_words])

    cleaned = _clean_branch_name(description)
    return "-".join([part for part in cleaned.split("-") if part][:3])

def _int64_from_digits(value: str) -> int | None:
    normalized = value.lstrip("0") or "0"
    maximum = str(_MAX_FEATURE_NUMBER)
    if len(normalized) > len(maximum) or (
        len(normalized) == len(maximum) and normalized > maximum
    ):
        return None
    return int(normalized, 10)

def _get_highest_from_specs(specs_dir: Path) -> int:
    highest = 0
    if not specs_dir.is_dir():
        return highest
    for entry in specs_dir.iterdir():
        if not entry.is_dir():
            continue
        name = entry.name
        if re.match(r"^[0-9]{3,}-", name) and not re.match(
            r"^[0-9]{8}-[0-9]{6}-", name
        ):
            m = re.match(r"^[0-9]+", name)
            if m is not None:
                number = _int64_from_digits(m.group())
                if number is not None:
                    highest = max(highest, number)
    return highest

def _persistence_assignments(
    branch_name: str, feature_dir: str, *, powershell: bool
) -> tuple[str, str]:
    if powershell:
        quoted_branch = "'" + branch_name.replace("'", "''") + "'"
        quoted_dir = "'" + feature_dir.replace("'", "''") + "'"
        return (
            f"$env:SPECIFY_FEATURE = {quoted_branch}",
            f"$env:SPECIFY_FEATURE_DIRECTORY = {quoted_dir}",
        )
    return (
        f"export SPECIFY_FEATURE={shlex.quote(branch_name)}",
        f"export SPECIFY_FEATURE_DIRECTORY={shlex.quote(feature_dir)}",
    )

def _spec_prefix_exists(specs_dir: Path, feature_num: str) -> bool:
    try:
        return any(
            entry.is_dir() and entry.name.startswith(f"{feature_num}-")
            for entry in specs_dir.iterdir()
        )
    except OSError:
        return False

def _has_spec_prefix_conflict(
    specs_dir: Path,
    feature_num: str,
    requested_dir: Path,
    *,
    allow_existing: bool,
) -> bool:
    if allow_existing and requested_dir.is_dir():
        return False

    return _spec_prefix_exists(specs_dir, feature_num)

def _usage(argv0: str) -> str:
    return (
        f"Usage: {argv0} [--json] [--dry-run] [--allow-existing-branch] "
        "[--short-name <name>] [--number N] [--timestamp] <feature_description>"
    )

def _parse_args(argv: list[str], argv0: str) -> Args:
    json_mode = False
    dry_run = False
    allow_existing = False
    short_name = ""
    branch_number = ""
    use_timestamp = False
    rest: list[str] = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--json":
            json_mode = True
        elif arg == "--dry-run":
            dry_run = True
        elif arg == "--allow-existing-branch":
            allow_existing = True
        elif arg in {"--short-name", "--number"}:
            if i + 1 >= len(argv) or argv[i + 1].startswith("--"):
                print(f"Error: {arg} requires a value", file=sys.stderr)
                raise SystemExit(1)
            i += 1
            if arg == "--short-name":
                short_name = argv[i]
            else:
                branch_number = argv[i]
        elif arg == "--timestamp":
            use_timestamp = True
        elif arg in {"--help", "-h"}:
            sys.stdout.write(_help_text(argv0))
            raise SystemExit(0)
        else:
            rest.append(arg)
        i += 1

    description = " ".join(rest).strip()
    if not description:
        if rest:
            print(
                "Error: Feature description cannot be empty or contain only whitespace",
                file=sys.stderr,
            )
        else:
            print(_usage(argv0), file=sys.stderr)
        raise SystemExit(1)

    return Args(
        json_mode=json_mode,
        dry_run=dry_run,
        allow_existing=allow_existing,
        short_name=short_name,
        branch_number=branch_number,
        use_timestamp=use_timestamp,
        description=description,
    )

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("template_name")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)

    repo_root = get_repo_root(Path(__file__))
    try:
        content = resolve_template_content(args.template_name, repo_root)
    except TemplateResolutionError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    if content is None:
        print(
            f"ERROR: Could not resolve required {args.template_name} from template stack",
            file=sys.stderr,
        )
        return 1

    if args.json:
        print(
            json.dumps(
                {
                    "TEMPLATE_NAME": args.template_name,
                    "TEMPLATE_CONTENT": content,
                },
                ensure_ascii=False,
                separators=(",", ":"),
            )
        )
    else:
        sys.stdout.write(content)
    return 0

def main(argv: list[str] | None = None) -> int:
    args = list(argv if argv is not None else sys.argv[1:])
    json_mode = False
    for arg in args:
        if arg == "--json":
            json_mode = True
        elif arg in {"--help", "-h"}:
            sys.stdout.write(_help_text(sys.argv[0]))
            return 0

    try:
        paths = get_feature_paths(script_file=Path(__file__))
    except SystemExit as exc:
        if exc.code == 0:
            return 0
        print("ERROR: Failed to resolve feature paths", file=sys.stderr)
        return int(exc.code) if isinstance(exc.code, int) else 1

    paths.feature_dir.mkdir(parents=True, exist_ok=True)

    if paths.impl_plan.is_file():
        if not json_mode:
            print(f"Plan already exists at {paths.impl_plan}, skipping template copy")
    else:
        try:
            template_content = resolve_template_content("plan-template", paths.repo_root)
        except TemplateResolutionError as exc:
            print(f"Error: {exc}", file=sys.stderr)
            return 1
        if template_content is not None:
            paths.impl_plan.write_bytes(template_content.encode("utf-8"))
            if not json_mode:
                print(f"Copied plan template to {paths.impl_plan}")
        else:
            if not json_mode:
