function checkAxe() {
  const dir = path.resolve(__dirname, '..', 'harness');
  const lock = fs.readFileSync(path.join(dir, 'axe.lock'), 'utf8');
  const version = (lock.match(/version:\s*(\S+)/) || [])[1];
  const expected = (lock.match(/sha256:\s*([0-9a-f]{64})/) || [])[1];
  const source = fs.readFileSync(path.join(dir, 'axe.min.js'));
  const actual = crypto.createHash('sha256').update(source).digest('hex');
  if (actual !== expected) {
    console.error(`axe.min.js does not match axe.lock (${actual} != ${expected})`);
    process.exit(1);
  }
  return { source: source.toString('utf8'), version };
}

function serve(dirs) {
  // /0/<file>, /1/<file> — one prefix per --dir, nothing else reachable.
  return http.createServer((req, res) => {
    const m = req.url.match(/^\/(\d+)\/(.+)$/);
    const dir = m && dirs[Number(m[1])];
    const file = dir && path.join(dir, decodeURIComponent(m[2]));
    if (!file || !file.startsWith(dir) || !fs.existsSync(file)) {
      res.writeHead(404).end();
      return;
    }
    // fix 2026-08-24: every file was served as text/html, so browsers silently
    // rejected external stylesheets (strict MIME for <link rel=stylesheet>).
    // Study 2 was the first design with non-inlined assets — see DEVIATIONS.md.
    const MIME = { '.html': 'text/html; charset=utf-8', '.css': 'text/css',
                   '.js': 'text/javascript', '.svg': 'image/svg+xml',
                   '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp',
                   '.json': 'application/json' };
    const type = MIME[path.extname(file).toLowerCase()] || 'application/octet-stream';
    res.writeHead(200, { 'content-type': type });
    res.end(fs.readFileSync(file));
  });
}

def composite(fg, bg):
    """Composite fg (with alpha) over an opaque bg. Returns opaque (r, g, b)."""
    a = fg[3]
    return tuple(fg[i] * a + bg[i] * (1 - a) for i in range(3))

def parse_color(token: str):
    """Return (r, g, b, a) in 0–255 / 0–1, or None if unparseable."""
    t = token.strip().lower()
    if t in NAMED:
        return NAMED[t]
    if t.startswith("#"):
        h = t[1:]
        if len(h) in (3, 4):
            h = "".join(c * 2 for c in h)
        if len(h) == 6:
            h += "ff"
        if len(h) != 8:
            return None
        r, g, b, a = (int(h[i:i + 2], 16) for i in (0, 2, 4, 6))
        return (r, g, b, a / 255.0)
    m = re.match(r"(rgba?|hsla?)\(([^)]+)\)", t)
    if not m:
        return None
    fn, body = m.group(1), m.group(2)
    parts = [p.strip() for p in re.split(r"[,/]", body) if p.strip()]
    if len(parts) < 3:
        return None
    try:
        if fn.startswith("rgb"):
            vals = []
            for p in parts[:3]:
                vals.append(float(p[:-1]) * 2.55 if p.endswith("%") else float(p))
            a = float(parts[3][:-1]) / 100 if len(parts) > 3 and parts[3].endswith("%") \
                else float(parts[3]) if len(parts) > 3 else 1.0
            r, g, b = (_clamp(v) for v in vals)
            return (r, g, b, a)
        # hsl
        h = float(re.sub(r"deg$", "", parts[0]))
        s = float(parts[1].rstrip("%")) / 100
        l = float(parts[2].rstrip("%")) / 100
        a = float(parts[3][:-1]) / 100 if len(parts) > 3 and parts[3].endswith("%") \
            else float(parts[3]) if len(parts) > 3 else 1.0
        c = (1 - abs(2 * l - 1)) * s
        x = c * (1 - abs((h / 60) % 2 - 1))
        mm = l - c / 2
        r1, g1, b1 = (
            (c, x, 0) if h < 60 else (x, c, 0) if h < 120 else
            (0, c, x) if h < 180 else (0, x, c) if h < 240 else
            (x, 0, c) if h < 300 else (c, 0, x)
        )
        return ((r1 + mm) * 255, (g1 + mm) * 255, (b1 + mm) * 255, a)
    except ValueError:
        return None

def check_links(root: Path) -> None:
    for lang in LANGS:
        base = root / "docs" / lang
        for path in [core(root, lang)] + sorted(base.glob("templates/*.md")) + sorted(base.glob("references/*.md")):
            text = path.read_text(encoding="utf-8")
            for target in re.findall(r"\]\((?!https?:|#|mailto:)([^)]+)\)", text):
                resolved = (path.parent / target.split("#")[0]).resolve()
                if not resolved.exists():
                    fail("links", f"{path.relative_to(root)} → broken relative link '{target}'")

def check_optional_label(root: Path) -> None:
    for path in sorted((root / "docs").rglob("*.md")):
        for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            if re.search(r"(Optional Templates|Templates Opcionais)", line):
                fail("optional",
                     f"{path.relative_to(root)}:{line_no} — project artifacts labelled optional while the "
                     f"body requires them. This exact contradiction caused the 2026-08-01 field failure.")

def check_orphans(root: Path) -> None:
    for lang in LANGS:
        text = core(root, lang).read_text(encoding="utf-8")
        linked = set(re.findall(r"guide-[a-z0-9-]+\.md", text))
        on_disk = {p.name for p in (root / "docs" / lang / "references").glob("guide-*.md")}
        for orphan in sorted(on_disk - linked):
            fail("orphans", f"docs/{lang}/references/{orphan} is not linked from the core file — "
                            f"lazy loading can never discover it")

def check_parity(root: Path) -> None:
    listings = {}
    for lang in LANGS:
        base = root / "docs" / lang
        listings[lang] = {p.relative_to(base).as_posix() for p in base.rglob("*.md")}
    only_en = listings["en"] - listings["pt-BR"]
    only_pt = listings["pt-BR"] - listings["en"]
    for name in sorted(only_en):
        fail("parity", f"docs/en/{name} has no pt-BR counterpart")
    for name in sorted(only_pt):
        fail("parity", f"docs/pt-BR/{name} has no en counterpart")

    counts = {}
    for lang in LANGS:
        text = core(root, lang).read_text(encoding="utf-8")
        contract = re.search(r"## 2\..*?(?=\n## 3\.)", text, re.S)
        counts[lang] = (
            len(re.findall(r"^#{1,6} ", text, re.M)),
            len(re.findall(r"^- \*\*", contract.group(0), re.M)) if contract else 0,
        )
    if counts["en"][0] != counts["pt-BR"][0]:
        fail("parity", f"heading count differs: en={counts['en'][0]} pt-BR={counts['pt-BR'][0]}")
    if counts["en"][1] != counts["pt-BR"][1]:
        fail("parity", f"AI Behavior Contract rule count differs: "
                       f"en={counts['en'][1]} pt-BR={counts['pt-BR'][1]}")

def check_phase_triggers(root: Path) -> None:
    """Phase triggers never fire in continuously delivered projects."""
    patterns = (
        re.compile(r"(in case of|at|on|upon)\s+final\s+delivery", re.I),
        re.compile(r"em caso de entrega final|na entrega final", re.I),
        re.compile(r"(at|during)\s+(the\s+)?(final\s+)?QA cycle", re.I),
        re.compile(r"no ciclo de QA", re.I),
    )
    for path in sorted((root / "docs").rglob("*.md")):
        for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            # the design principle in the governance guide quotes these on purpose
            if "gatilhos por fase" in line or "phase triggers" in line:
                continue
            for pattern in patterns:
                if pattern.search(line):
                    fail("phase-trigger",
                         f"{path.relative_to(root)}:{line_no} — rule fires on a project phase, not an event. "
                         f"Use 'before any delivery to an end user' (see Release Evidence, §2).")

def check_wiki_drift(root: Path) -> None:
    """The Wiki is the project's public documentation but lives outside version
    control (see .gitignore), so nothing stops it from drifting away from the
    standard it documents. Skipped when the folder is absent — most clones
    will not have it."""
    wiki = root / "WIKI"
    if not wiki.is_dir():
        return

    contract = re.search(r"## 2\..*?(?=\n## 3\.)", core(root, "en").read_text(encoding="utf-8"), re.S)
    core_rules = len(re.findall(r"^- \*\*", contract.group(0), re.M)) if contract else 0
    page = wiki / "AI-Behavioral-Contract.md"
    if page.is_file():
        wiki_rules = len(re.findall(r"^### \d+\. ", page.read_text(encoding="utf-8"), re.M))
        if wiki_rules != core_rules:
            fail("wiki", f"WIKI/AI-Behavioral-Contract.md documents {wiki_rules} rules, "
                         f"the core file defines {core_rules}")

    library = wiki / "Reference-Library.md"
    if library.is_file():
        listed = set(re.findall(r"guide-[a-z0-9-]+\.md", library.read_text(encoding="utf-8")))
        on_disk = {p.name for p in (root / "docs" / "en" / "references").glob("guide-*.md")}
        for missing in sorted(on_disk - listed):
            fail("wiki", f"WIKI/Reference-Library.md does not list {missing}")

def main() -> int:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    if not core(root, "en").is_file():
        print(f"error: {root} does not look like the A11Y.md repository", file=sys.stderr)
        return 2

    for check in (check_parity, check_orphans, check_triggers, check_links,
                  check_phase_triggers, check_placement, check_optional_label, check_wiki_drift):
        check(root)

    for name, message in findings:
        print(f"✗ [{name}] {message}")
    print()
    print(f"FAIL — {len(findings)} issue(s)." if findings else "PASS — standard is internally consistent.")
    return 1 if findings else 0

def as_path(token: str) -> str:
    path = token.strip().replace("\\", "/")
    while path.startswith("./"):
        path = path[2:]
    return path.strip("/")

def chooses(markup: str, subject: str) -> bool:
    """The flagged element carries the markup the decision chose, whole and as
    its own attribute: `role="list"` is not inside `role="listitem"`, nor
    inside `data-role="list"`, nor inside another attribute's value."""
    norm = lambda t: re.sub(r"\s+", " ", re.sub(r"\s*([=:])\s*", r"\1", t.replace("'", '"')))
    return bool(re.search(r"(?:^|(?<=[\s<{;,(]))" + re.escape(norm(markup)) + r"(?![\w-])", norm(subject)))

def expiry_of(block: str) -> dt.date | None:
    expiry = re.search(r"(?:Expiry|Expiração)[^:\n]*:\*{0,2}[ \t]*\[?(\d{4}-\d{2}-\d{2})", block)
    return dt.date.fromisoformat(expiry.group(1)) if expiry else None

def filled(field: re.Match | None) -> bool:
    """A field with a value that is not the template's bracketed placeholder."""
    return bool(field and field.group(1).strip() and not field.group(1).lstrip().startswith("["))

def git(root: Path, *args: str) -> str | None:
    try:
        out = subprocess.run(["git", "-C", str(root), *args],
                             capture_output=True, text=True, timeout=15)
        return out.stdout.strip() if out.returncode == 0 else None
    except (OSError, subprocess.SubprocessError):
        return None

def hex_rgb(token: str) -> tuple[int, int, int]:
    h = token.lstrip("#")
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)

def missing_fields(block: str) -> list[str]:
    missing = []
    for field, pattern in SIGN_OFF:
        m = re.search(pattern + r":\*{0,2}[ \t]*(.*)", block)
        if not m or not m.group(2).strip() or PLACEHOLDER.search(m.group(2)):
            missing.append(field)
    return missing

def normalize_hex(token: str) -> str:
    h = token.lstrip("#").lower()
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return h

def read(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None

def body_of(report: Path) -> str:
    """The report without its blockquotes: the template explains every field
    inside `>` notes, and a document-wide search would find the explanation."""
    text = read(report) or ""
    return "\n".join(l for l in text.splitlines() if not l.lstrip().startswith(">"))

def check_gitignore(root: Path) -> None:
    """Artifacts are versioned records; hiding them defeats their purpose."""
    gitignore = root / ".gitignore"
    if not gitignore.is_file():
        return
    patterns = [l.strip() for l in (read(gitignore) or "").splitlines()
                if l.strip() and not l.startswith("#")]
    for artifact in ARTIFACTS:
        for pattern in patterns:
            if pattern.strip("/") == artifact or pattern in ("*.md", "**/*.md"):
                fail("gitignore", f"{artifact} is excluded by .gitignore rule '{pattern}'. "
                                  f"Project artifacts must be versioned.")
                break

def source_files(root: Path, src: Path):
    for path in src.rglob("*"):
        if path.is_file() and path.suffix.lower() in SOURCE_SUFFIXES:
            if not any(part in SKIP_DIRS for part in path.relative_to(root).parts):
                yield path

def check_report_freshness(root: Path, report: Path, src: Path) -> None:
    """The report must be newer than the last interface change."""
    last_ui = git(root, "log", "-1", "--format=%cI", "--", str(src.relative_to(root)) if src != root else ".")
    last_report = git(root, "log", "-1", "--format=%cI", "--", "REPORT.md")
    if last_ui and last_report:
        if last_report < last_ui:
            fail("freshness", f"REPORT.md (last commit {last_report[:10]}) is older than the last "
                              f"interface change ({last_ui[:10]}). Revisit the entries that change affects.")
        return
    # no git history available — fall back to mtime
    newest = max((p.stat().st_mtime for p in source_files(root, src)), default=None)
    if newest and report.stat().st_mtime < newest:
        fail("freshness", "REPORT.md is older than the most recently modified source file.")

def status_claims_pass(body: str) -> bool:
    status = re.search(r"(?:Compliance Status|Status de Conformidade):?\*{0,2}[ \t]*(.*)", body, re.I)
    value = status.group(1).strip() if status else ""
    conditional = re.search(r"CONDITIONAL|CONDICIONAL", value, re.I)
    return bool(not conditional and (re.search(r"\bPASS\b", value, re.I) or "✅" in value))

def check_exceptions(root: Path) -> None:
    """Every exception needs owner, approver, tracking issue and a future expiry."""
    today = dt.date.today()
    for label, block in exception_entries(root):
        for field in missing_fields(block):
            fail("exceptions", f"{label}: missing {field}.")
        date = expiry_of(block)
        if not date:
            fail("exceptions", f"{label}: missing or unparseable expiry date (use YYYY-MM-DD).")
        elif date < today:
            fail("exceptions", f"{label}: expired on {date} — review, fix or consciously renew it.")
        elif (date - today).days <= 14:
            warn("exceptions", f"{label}: expires in {(date - today).days} day(s).")

def without_code_samples(text: str | None) -> str | None:
    """Blank the text quoted inside <pre>/<code>, keeping every newline so the
    line numbers reported for the rest of the file still point at the right place."""
    if text is None:
        return None
    return CODE_SAMPLE.sub(lambda m: m.group(1) + re.sub(r"[^\n]", " ", m.group(3)) + m.group(4), text)

def without_comments(text: str | None, suffix: str) -> str | None:
    """Blank comments for the file's language, keeping every newline."""
    if text is None:
        return None
    blank = lambda m: re.sub(r"[^\n]", " ", m.group(0))
    if suffix in SCRIPT_SUFFIXES or suffix in (".css", ".scss"):
        text = BLOCK_COMMENT.sub(blank, text)
    if suffix in SCRIPT_SUFFIXES:
        text = LINE_COMMENT.sub(blank, text)
    if suffix in MARKUP_SUFFIXES:
        text = HTML_COMMENT.sub(blank, text)
    return text

def scannable(path: Path) -> str | None:
    """The file as the source scan sees it: no quoted samples, no comments."""
    return without_comments(without_code_samples(read(path)), path.suffix.lower())

def check_aria_soup(root: Path, src: Path) -> None:
    """ARIA where native HTML already provides the semantics (A11Y.md §6):
    redundant roles, aria-label repeating the visible text, and aria-expanded
    hardcoded in markup that no script ever toggles."""
    redundant = re.compile(r"<(" + "|".join(REDUNDANT_ROLES) + r"|a)\b" + ATTRS + r">")
    dup_label = re.compile(r"<(a|button)\b" + ATTRS + r"\baria-label\s*=\s*[\"']([^\"']+)[\"']" + ATTRS + r">\s*([^<{]+?)\s*<", re.I)
    static_expanded = re.compile(r"\baria-expanded\s*=\s*[\"'](?:true|false)[\"']")
    dynamic_expanded = re.compile(r"aria-expanded(?!\s*=\s*[\"'](?:true|false)[\"'])|ariaExpanded")

    files = [(p, scannable(p)) for p in source_files(root, src)]
    # The script that toggles aria-expanded rarely lives beside the markup: `--src`
    # scopes the interface, so the search for the toggle spans the whole project.
    toggled = any(p.suffix in SCRIPT_SUFFIXES and dynamic_expanded.search(scannable(p) or "")
                  for p in source_files(root, root))

    for path, text in files:
        if not text or path.suffix in (".css", ".scss"):
            continue
        rel = path.relative_to(root)
        for match in redundant.finditer(text):
            tag, attrs = match.group(1).lower(), match.group(2)
            role = re.search(r"\brole\s*=\s*[\"']([\w-]+)[\"']", attrs)
            if not role:
                continue
            if tag == "a":
                if role.group(1) == "link" and re.search(r"\bhref\s*=", attrs):
                    fail("aria-soup", f"{rel}:{line_of(text, match.start())} — role=\"link\" on <a href>: "
                                      f"redundant role on a native element (ARIA Soup, A11Y.md §6)", match.group(0))
                continue
            if role.group(1) in REDUNDANT_ROLES.get(tag, ()):
                fail("aria-soup", f"{rel}:{line_of(text, match.start())} — role=\"{role.group(1)}\" on <{tag}>: "
                                  f"redundant role on a native element (ARIA Soup, A11Y.md §6)", match.group(0))
        for match in dup_label.finditer(text):
            label, visible = match.group(3), match.group(5)
            if re.sub(r"\s+", " ", label).strip().lower() == re.sub(r"\s+", " ", visible).strip().lower():
                warn("aria-soup", f"{rel}:{line_of(text, match.start())} — aria-label repeats the visible text "
                                  f"of <{match.group(1)}>. Drop it: when the two drift apart it becomes an "
                                  f"SC 2.5.3 failure (ARIA Soup, A11Y.md §6)", match.group(0))
        if not toggled:
            for match in static_expanded.finditer(text):
                warn("aria-soup", f"{rel}:{line_of(text, match.start())} — aria-expanded hardcoded and no script "
                                  f"in the project ever toggles it: a state that never updates is worse than "
                                  f"none (SC 4.1.2, ARIA Soup, A11Y.md §6)", match.group(0))

def check_placeholder_labels(root: Path, src: Path) -> None:
    """placeholder as the only label (A11Y.md §6, Placeholder Labels).

    axe accepts a placeholder as an accessible name, so this never fails axe.
    Labeled means: aria-label/aria-labelledby on the field, a <label for> (or
    htmlFor) pointing at its id in the same file, or the field wrapped in a
    <label>. Dynamic ids (`:id`, `id={…}`) cannot be resolved and are skipped.
    """
    field = re.compile(r"<(input|textarea)\b" + ATTRS + r">")
    skip_types = ("hidden", "submit", "button", "reset", "checkbox", "radio", "file", "range", "color", "image")
    for path in source_files(root, src):
        text = scannable(path)
        if text is None or path.suffix in (".css", ".scss", ".js", ".ts"):
            continue
        for match in field.finditer(text):
            attrs = match.group(2)
            if not re.search(r"\bplaceholder\s*=", attrs):
                continue
            kind = re.search(r"\btype\s*=\s*[\"']([\w-]+)", attrs)
            if kind and kind.group(1).lower() in skip_types:
                continue
            if re.search(r"\baria-label(ledby)?\s*=|\btitle\s*=", attrs):
                continue
            if re.search(r"(?<![:\w])id\s*=\s*\{", attrs) or re.search(r":id\s*=|v-bind:id", attrs):
                continue  # dynamic id — not resolvable statically
            id_match = re.search(r"(?<![:\w-])id\s*=\s*[\"']([^\"'{}]+)[\"']", attrs)
            if id_match and re.search(r"\b(?:for|htmlFor)\s*=\s*[\"']" + re.escape(id_match.group(1)) + r"[\"']", text):
                continue
            before = text[:match.start()]
            if before.rfind("<label") > before.rfind("</label>"):
                continue  # wrapped in a <label>
            fail("placeholder-label", f"{path.relative_to(root)}:{line_of(text, match.start())} — "
                                      f"<{match.group(1)}> labeled only by its placeholder. The label disappears "
                                      f"while typing; give it a visible <label> (A11Y.md §6)", match.group(0))

def __getattr__(name: str) -> str:
    # PEP 562: lazily resolve the legacy always-on section constants for external
    # importers (e.g. the install-string tests). In-module code calls _always_on()
    # directly; nothing is read at import time, so a missing block can no longer
    # brick the CLI on `import graphify.__main__` (#1121 follow-up).
    base = _ALWAYS_ON_ALIASES.get(name)
    if base is not None:
        return _always_on(base)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def _silence_broken_pipe() -> None:
    """Handle a downstream reader that closed the pipe early. Redirect stdout to
    devnull so the interpreter's shutdown flush does not raise a second time, then
    exit 0 — the reader (head, `Select-Object -First N`, `sed q`) has what it needs."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except Exception:
        pass
    sys.exit(0)

def _skill_platforms() -> list[str]:
    """Every platform with a user-scope skill directory, gemini included."""
    return list(dict.fromkeys([*_PLATFORM_CONFIG, "gemini"]))

def _version_tuple(version: str) -> tuple[int, ...]:
    """Parse a version string into a comparable integer tuple (``0.9.2`` -> ``(0, 9, 2)``).

    Reads the leading digits of each dot-segment, so pre/post-release suffixes
    (``1.0.0rc1``) compare by their numeric core. A non-numeric or empty segment
    becomes 0, so a malformed stamp degrades to a conservative comparison rather
    than raising.
    """
    parts: list[int] = []
    for segment in str(version).split("."):
        digits = ""
        for ch in segment:
            if ch.isdigit():
                digits += ch
            else:
                break
        parts.append(int(digits) if digits else 0)
    return tuple(parts)

def _check_skill_version(skill_dst: Path, platform_names: "list[str] | None" = None) -> None:
    """Warn if the installed skill is from an older graphify version.

    ``platform_names`` are the platforms installing into this destination
    (resolved here when not given - the call site passes one positional
    argument only, because tests stub this function with one-arg lambdas), so
    the warning can name the exact command that refreshes THIS copy (#3144):
    a plain `graphify install` only refreshes the detected platform, and a
    stale marker at another platform's destination made the warning permanent
    - the user followed the advice, the warning stayed, and only editing the
    marker by hand cleared it.
    """
    if platform_names is None:
        try:
            platform_names = [
                name for name in _skill_platforms()
                if _platform_skill_destination(name) == skill_dst
            ]
        except Exception:
            platform_names = []
    version_file = skill_dst.parent / ".graphify_version"
    try:
        if not version_file.exists():
            return
    except OSError:
        return
    try:
        skill_exists = skill_dst.exists()
    except OSError:
        return
    if not skill_exists:
        print("  warning: skill dir exists but SKILL.md is missing. Run 'graphify install' to repair.", file=sys.stderr)
        return
    # A progressive SKILL.md links to its references/ sidecar. If the body points
    # at references/ but the dir is gone (manual delete, partial upgrade), the
    # on-demand fragments won't load — flag it for repair.
    try:
        body = skill_dst.read_text(encoding="utf-8")
    except OSError:
        body = ""
    if "references/" in body and not (skill_dst.parent / "references").exists():
        print("  warning: skill references/ sidecar is missing. Run 'graphify install' to repair.", file=sys.stderr)
    try:
        installed = version_file.read_text(encoding="utf-8").strip()
    except OSError:
        return
    if installed != __version__:
        if _version_tuple(installed) > _version_tuple(__version__):
            # The skill on disk is NEWER than the running package. `graphify install`
            # writes the package's OWN (older) bundled skill and re-stamps the version,
            # so following the old "run install" advice would silently DOWNGRADE the
            # skill. The real fix is to upgrade the package (#1568). Common for a stale
            # `uv tool` CLI, or a contributor whose dev checkout stamped a newer skill.
            print(
                f"  warning: skill is from graphify {installed}, but the package is "
                f"{__version__} (older). Upgrade the package "
                f"(e.g. 'uv tool upgrade graphifyy' or 'pip install -U graphifyy'); "
                f"running 'graphify install' would downgrade the skill.",
                file=sys.stderr,
            )
        else:
            _cmd = (
                f"graphify install --platform {platform_names[0]}"
                if platform_names else "graphify install"
            )
            print(
                f"  warning: skill at {skill_dst.parent} is from graphify {installed}, "
                f"package is {__version__}. Run '{_cmd}' to update it "
                f"(a plain 'graphify install' refreshes only the detected platform).",
                file=sys.stderr,
            )

def _stale_stamp(skill_dst: Path) -> str | None:
    """The version stamped beside ``skill_dst`` if it is older than the package."""
    version_file = skill_dst.parent / ".graphify_version"
    try:
        if not (version_file.is_file() and skill_dst.is_file()):
            return None
        installed = version_file.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    if installed == __version__ or _version_tuple(installed) > _version_tuple(__version__):
        return None
    return installed

def _lsh_integrate(f, lo: float, hi: float, n: int = 128) -> float:
    """Numerical integration — replaces scipy.integrate.quad for LSH param search."""
    h = (hi - lo) / n
    return h * sum(f(lo + i * h) for i in range(n))

def _optimal_lsh_params(threshold: float, num_perm: int) -> tuple[int, int]:
    """Find (bands, rows) that minimise weighted FP+FN error, without scipy."""
    key = (threshold, num_perm)
    if key in _LSH_PARAMS_CACHE:
        return _LSH_PARAMS_CACHE[key]
    best_err, best = float("inf"), (1, 1)
    for b in range(1, num_perm + 1):
        for r in range(1, num_perm // b + 1):
            fp = _lsh_integrate(
                lambda s, _b=float(b), _r=float(r): 1 - (1 - s ** _r) ** _b,
                0.0, threshold,
            )
            fn = _lsh_integrate(
                lambda s, _b=float(b), _r=float(r): 1 - (1 - (1 - s ** _r) ** _b),
                threshold, 1.0,
            )
            err = 0.5 * fp + 0.5 * fn
            if err < best_err:
                best_err, best = err, (b, r)
    _LSH_PARAMS_CACHE[key] = best
    return best

def _format_location(data: dict) -> str:
    source_file = data.get("source_file") or "-"
    source_location = data.get("source_location")
    if source_location:
        return f"{source_file}:{source_location}"
    return str(source_file)

def _node_label(graph: nx.Graph, node_id: str) -> str:
    data = graph.nodes[node_id]
    return str(data.get("label") or node_id)

def _supertypes(graph: nx.DiGraph, type_id: str, cache: dict[str, list[str]]) -> list[str]:
    """Every type ``type_id`` derives from, nearest first (cycles cut)."""
    if type_id in cache:
        return cache[type_id]
    found: list[str] = []
    seen = {type_id}
    frontier = [type_id]
    while frontier:
        nxt = []
        for t in frontier:
            for _s, base, data in graph.out_edges(t, data=True):
                base = str(base)
                if str(data.get("relation", "")) in _SUPERTYPE_RELATIONS and base not in seen:
                    seen.add(base)
                    found.append(base)
                    nxt.append(base)
        frontier = nxt
    cache[type_id] = found
    return found

def load_graph(path: Path) -> nx.Graph:
    import json
    from networkx.readwrite import json_graph

    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        raise RuntimeError(
            f"Cannot read graph file {path}: {exc}. "
            "Re-run 'graphify extract' to regenerate it."
        ) from exc
    # Force directed so stored caller→callee direction survives the round-trip;
    # mirrors serve.py and __main__.py (#1174).
    raw = {**raw, "directed": True}
    # Normalize the edge key: graphify's `extract` output uses "edges" while
    # networkx's node_link_data default is "links". Without this, an edges-keyed
    # graph.json raises an uncaught KeyError: 'links' here — every other loader
    # (__main__.py) already normalizes this (#738; same class as #1198).
    if "links" not in raw and "edges" in raw:
        raw = dict(raw, links=raw["edges"])
    try:
        return json_graph.node_link_graph(raw, edges="links")
    except TypeError:
        return json_graph.node_link_graph(raw)

def resolve_seed(graph: nx.Graph, query: str, root: Path | None = None) -> str | None:
    # A trailing path separator must not change a source-file match — serve's
    # _find_node tokenizes the path (which drops it), so strip it here for parity
    # (otherwise `affected "src/x.ts/"` returned None while `explain` resolved it).
    query = query.rstrip("/\\") or query
    if query in graph:
        return query
    query_lower = _normalize_label(query)
    exact_label_matches = [
        str(node_id)
        for node_id, data in graph.nodes(data=True)
        if _normalize_label(str(data.get("label", ""))) == query_lower
    ]
    if len(exact_label_matches) == 1:
        return exact_label_matches[0]
    # Callable labels are decorated ("name()"), so a bare "name" query falls
    # through exact matching and then ties with any "name*" sibling in the
    # contains pass. Match on the undecorated name before giving up.
    query_bare = _bare_name(query_lower)
    bare_name_matches = [
        str(node_id)
        for node_id, data in graph.nodes(data=True)
        if _bare_name(str(data.get("label", ""))) == query_bare
    ]
    if len(bare_name_matches) == 1:
        return bare_name_matches[0]
    # Compare paths in repo-relative form. Only this branch is path-shaped; the
    # label branches above keep the query verbatim.
    query_path = _normalize_label(_as_repo_relative(query, root))
    exact_source_matches = [
        str(node_id)
        for node_id, data in graph.nodes(data=True)
        if _normalize_label(str(data.get("source_file", ""))) in (query_lower, query_path)
    ]
    if len(exact_source_matches) == 1:
        return exact_source_matches[0]
    if exact_source_matches:
        preferred_file_node = _prefer_file_node(
            graph, exact_source_matches, _as_repo_relative(query, root)
        )
        if preferred_file_node is not None:
            return preferred_file_node
    contains_matches = [
        str(node_id)
        for node_id, data in graph.nodes(data=True)
        if query_lower in _normalize_label(str(data.get("label", "")))
    ]
    if len(contains_matches) == 1:
        return contains_matches[0]
    return None

def format_affected(
    graph: nx.Graph,
    query: str,
    *,
    relations: Iterable[str] = DEFAULT_AFFECTED_RELATIONS,
    depth: int = 2,
    root: Path | None = None,
) -> str:
    relation_list = tuple(relations)
    seed = resolve_seed(graph, query, root)
    if seed is None:
        return f"No unique node match for {query}"

    hits = affected_nodes(graph, seed, relations=relation_list, depth=depth)
    lines = [
        f"Affected nodes for {_node_label(graph, seed)}",
        f"Relations: {', '.join(relation_list)}",
        f"Depth: {depth}",
    ]
    if not hits:
        lines.append("No affected nodes found.")
        return "\n".join(lines)

    for hit in hits:
        data = graph.nodes[hit.node_id]
        if hit.via_location:
            # The relation SITE in this node's file (call/import/reference line),
            # labeled by [via_relation] so it's never mistaken for a def line.
            location = f"{hit.via_file or data.get('source_file') or '-'}:{hit.via_location}"
        else:
            location = _format_location(data)  # honest fallback: the node's own def line
        lines.append(
            f"- {_node_label(graph, hit.node_id)} [{hit.via_relation}] {location}"
        )
    return "\n".join(lines)

def _file_category(path: str) -> str:
    ext = ("." + path.rsplit(".", 1)[-1].lower()) if "." in path else ""
    if ext in CODE_EXTENSIONS:
        return "code"
    if ext in PAPER_EXTENSIONS:
        return "paper"
    if ext in IMAGE_EXTENSIONS:
        return "image"
    return "doc"

def _node_community_map(communities: dict[int, list[str]]) -> dict[str, int]:
    """Invert communities dict: node_id -> community_id."""
    return {n: cid for cid, nodes in communities.items() for n in nodes}

def surprising_connections(
    G: nx.Graph,
    communities: dict[int, list[str]] | None = None,
    top_n: int = 5,
) -> list[dict]:
    """
    Find connections that are genuinely surprising - not obvious from file structure.

    Strategy:
    - Multi-file corpora: cross-file edges between real entities (not concept nodes).
      Sorted AMBIGUOUS → INFERRED → EXTRACTED.
    - Single-file / single-source corpora: cross-community edges that bridge
      distant parts of the graph (betweenness centrality on edges).
      These reveal non-obvious structural couplings.

    Concept nodes (empty source_file, or injected semantic annotations) are excluded
    from surprising connections because they are intentional, not discovered.
    """
    # Identify unique source files (ignore empty/null source_file)
    source_files = {
        data.get("source_file", "")
        for _, data in G.nodes(data=True)
        if data.get("source_file", "")
    }
    is_multi_source = len(source_files) > 1

    if is_multi_source:
        return _cross_file_surprises(G, communities or {}, top_n)
    else:
        return _cross_community_surprises(G, communities or {}, top_n)

def _query_subgraph_tokens(G: nx.Graph, question: str, depth: int = 3, token_budget: int = 2000) -> int:
    """Estimated tokens of the answer query_graph returns for ``question`` (BFS,
    the MCP tool's defaults), 0 when nothing in the graph matches it. The
    answer is the real one an agent receives: seeds, budget cut and notices."""
    text = _query_graph_text(G, question, mode="bfs", depth=depth, token_budget=token_budget)
    if text == "No matching nodes found.":
        return 0
    return _estimate_tokens(text)

def _hr(width: int = 50) -> str:
    """Horizontal rule that survives non-UTF-8 stdout (e.g. Windows cp1252 console)."""
    return _safe("─", "-") * width

def _abs_identity(p: str | None, root: str | None = None) -> str | None:
    """Return a form-insensitive absolute identity for a source_file.

    prune/replace matching in build_merge otherwise compares raw strings against
    ``_norm_source_file`` output, so a node whose source_file survived in a THIRD
    form — absolute where prune_sources is relative, or vice versa, or a symlinked
    root — slips past every equality check and its nodes/edges are never pruned
    (silent survival of a deleted file's graph, #2012). Anchoring relative paths
    at ``root`` and resolving both sides to a canonical absolute posix path gives
    a fallback that matches regardless of which form each side happens to hold.
    """
    if not p:
        return None
    q = p.replace("\\", "/")
    pp = Path(q)
    if not _is_abs(q) and root:
        pp = Path(root) / q
    try:
        return pp.resolve().as_posix()
    except OSError:
        return pp.as_posix()

def _coerce_id(value: object) -> object:
    """Return a str for a numeric id, else the value unchanged.

    ``bool`` is excluded despite subclassing ``int``: an id of ``True`` is not a
    number the model meant to name a node, and ``"True"`` would invent a label.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return value
    return str(value)

def _derive_prune_root(prune_sources: "list[str]", stored_sfs: "set[str]") -> "str | None":
    """Derive the scan root from absolute prune paths that matched nothing (#2446).

    When build_merge/merge_raw_extraction receive absolute prune_sources but no
    ``root``, :func:`_infer_merge_root`'s guess can be wrong for non-standard
    layouts (``graph.json`` not under ``<root>/graphify-out/``), so every prune
    entry silently no-ops. Each absolute prune path ``P`` that ends with a
    stored RELATIVE source_file ``S`` implies the candidate root
    ``P[:-len(S)-1]``. Within one graph all relative source_files share a single
    scan root, so the candidate is accepted only when it is unique and
    consistent across every suffix-matched entry; on ambiguity (or no suffix
    match at all) returns None and the caller falls through to the zero-match
    warning.
    """
    rel_sfs = [
        sf.replace("\\", "/")
        for sf in stored_sfs
        if sf and isinstance(sf, str) and not _is_abs(sf.replace("\\", "/"))
    ]
    if not rel_sfs:
        return None
    roots: set[str] = set()
    for p in prune_sources:
        if not p or not isinstance(p, str):
            continue
        q = p.replace("\\", "/")
        if not _is_abs(q):
            continue
        hits = {q[: -len(s) - 1] for s in rel_sfs if q.endswith("/" + s)}
        if len(hits) > 1:
            return None  # one entry implies two different roots — ambiguous
        roots |= hits
    if len(roots) == 1:
        return next(iter(roots))
    return None

def _doc_twin_remap(nodes: list) -> dict[str, str]:
    """Map a markdown quick-scan's bare doc node ``<slug>`` to the semantic
    ``<slug>_doc`` node for the SAME file (#1799).

    The markdown quick-scan (``extract_markdown``) mints a file node with the
    bare id ``_make_id(path)`` while the semantic pass mints ``<slug>_doc`` for
    the same document. A ``graphify update`` after a semantic build leaves both,
    splitting the file's edges across two disconnected nodes. Canonicalize to the
    semantic ``_doc`` node (it carries the richer references/hyperedges). Gated to
    ``file_type == "document"`` on BOTH twins with an identical ``source_file``,
    so an unrelated code symbol ``foo`` and ``foo_doc`` never merge.
    """
    by_id: dict[str, dict] = {}
    for n in nodes:
        if isinstance(n, dict) and n.get("id"):
            by_id[str(n["id"])] = n
    remap: dict[str, str] = {}
    for nid, node in by_id.items():
        if not nid.endswith("_doc"):
            continue
        bare = by_id.get(nid[:-4])
        if bare is None:
            continue
        sf = node.get("source_file")
        if not sf or bare.get("source_file") != sf:
            continue
        if node.get("file_type") != "document" or bare.get("file_type") != "document":
            continue
        remap[nid[:-4]] = nid
    return remap

def _has_global_id(node: dict) -> bool:
    """Whether ``node``'s ID is global by construction rather than file-derived."""
    meta = node.get("metadata")
    if not isinstance(meta, dict):
        return False
    return meta.get("mcp_kind") in _MCP_GLOBAL_ID_KINDS

def _hashable(value: object) -> bool:
    """True when value can be a dict key / set member (same probe as the
    inline ``try: hash(m)`` in build_from_json's hyperedge revalidation)."""
    try:
        hash(value)
    except TypeError:
        return False
    return True

def _infer_merge_root(graph_path: Path) -> str | None:
    """Best-effort scan root for relativizing paths in build_merge when the caller
    passes no ``root`` (#1571).

    Prefers the committed ``graphify-out/.graphify_root`` marker — the authoritative
    scan root graphify records at build/watch time (#686/#1423) — then falls back to
    the directory that contains the output dir (``graph.json``'s grandparent, i.e.
    ``<root>/graphify-out/graph.json`` -> ``<root>``). The grandparent heuristic is
    applied only when ``graph.json``'s own directory actually looks like a graphify
    out-dir (named like one, or holding the marker/manifest); for arbitrary layouts
    (``<root>/graph.json``, #2446) the grandparent is NOT the scan root, and guessing
    it made absolute prune_sources silently no-op. Returns None if neither resolves,
    in which case normalization is a no-op (prior behavior) and prune matching can
    still recover via :func:`_derive_prune_root`.
    """
    parent = graph_path.parent
    try:
        marker = parent / ".graphify_root"
        if marker.exists():
            recorded = marker.read_text(encoding="utf-8-sig").strip()
            recorded_path = Path(recorded)
            if recorded and recorded_path.is_dir():
                return str(recorded_path.resolve())
    except OSError:
        pass
    from .paths import GRAPHIFY_OUT
    try:
        if (
            parent.name == Path(GRAPHIFY_OUT).name
            or (parent / ".graphify_root").exists()
            or (parent / "manifest.json").exists()
        ):
            return str(parent.parent.resolve())
    except Exception:
        pass
    return None

def _is_ast_tier(item: dict) -> bool:
    """AST vs semantic tier. _origin wins when present; unstamped legacy items
    (pre-0.9.16) fall back to shape: deterministic extractors emit
    source_location 'L<line>', the semantic spec emits null (#2334)."""
    o = item.get("_origin")
    if o is not None:
        return o == "ast"
    loc = item.get("source_location")
    return isinstance(loc, str) and bool(_AST_LOC_RE.match(loc))

def _is_file_node_label(label: "str | None", source_file: "str | None") -> bool:
    """Whether *label* is a file node's label for *source_file* — the bare
    basename, OR a directory-qualified suffix produced by the disambiguation pass
    below (#2032). Used both to recognize file nodes when relabeling and by the
    downstream file-node predicates (analyze/tree/serve)."""
    if not label or not source_file:
        return False
    sf = str(source_file).replace("\\", "/")
    lbl = str(label)
    if lbl == sf.rsplit("/", 1)[-1]:
        return True
    return "/" in lbl and (sf == lbl or sf.endswith("/" + lbl))

def _norm_label(label: str | None) -> str:
    """Canonical dedup key — Unicode-aware, preserves CJK/word characters."""
    if not isinstance(label, str):
        label = "" if label is None else str(label)
    label = unicodedata.normalize("NFKC", label)
    return re.sub(r"[\W_ ]+", " ", label.casefold(), flags=re.UNICODE).strip()

def _build_prune_sets(
    prune_sources: "list[str] | None",
    eff_root: "str | None",
    new_sources: "set[str]",
) -> "tuple[dict[str, str], dict[str, str]]":
    """Prune match sets for build_merge / merge_raw_extraction.

    Returns ``(prune_set, prune_abs)`` mapping every match form of each prune
    entry — the raw string, the :func:`_norm_source_file` relative form, and the
    :func:`_abs_identity` absolute form — back to the ORIGINAL entry, so callers
    can report which entries actually matched something (#2446). Membership
    tests read like the old set-based code (``sf in prune_set``).

    "Replace" wins over a contradictory "delete" of the same source (#1796), in
    both string and absolute-identity space (#2012): every form belonging to a
    source re-extracted this run is removed.
    """
    prune_set: dict[str, str] = {}
    prune_abs: dict[str, str] = {}
    for p in (prune_sources or []):
        if not p:
            continue
        prune_set.setdefault(p, p)
        norm = _norm_source_file(p, eff_root)
        if norm:
            prune_set.setdefault(norm, p)
        a = _abs_identity(p, eff_root)
        if a:
            prune_abs.setdefault(a, p)
    for s in new_sources:
        prune_set.pop(s, None)
        a = _abs_identity(s, eff_root)
        if a:
            prune_abs.pop(a, None)
    return prune_set, prune_abs

def _shortest_unique_suffix(sf: str, all_sfs: "set[str]") -> str:
    """Shortest trailing path suffix (basename + k parent dirs) of *sf* that is
    unique among *all_sfs*. `a/b/index.ts` vs `c/b/index.ts` -> `a/b/index.ts`;
    `x/index.ts` vs `y/index.ts` -> `x/index.ts`. Derived from the path (never the
    current label) so relabeling is idempotent across incremental rebuilds."""
    parts = [p for p in sf.replace("\\", "/").split("/") if p]
    others = [
        [p for p in o.replace("\\", "/").split("/") if p]
        for o in all_sfs if o != sf
    ]
    for k in range(1, len(parts) + 1):
        suffix = parts[-k:]
        if all(o[-k:] != suffix for o in others):
            return "/".join(suffix)
    return "/".join(parts)

def _file_label_reassignments(items: "list[tuple]") -> dict:
    """Given (key, label, source_file) triples, return {key: new_label} for file
    nodes whose basename collides with another's — the shortest unique
    directory-qualified suffix (#2032). Keys of non-colliding/basename-unique file
    nodes are omitted (their label stays bare)."""
    from collections import defaultdict
    groups: dict[str, list[tuple]] = defaultdict(list)
    for key, label, sf in items:
        if sf and label and _is_file_node_label(str(label), str(sf)):
            basename = str(sf).replace("\\", "/").rsplit("/", 1)[-1]
            groups[basename].append((key, str(sf)))
    out: dict = {}
    for members in groups.values():
        distinct = {sf for _, sf in members}
        if len(distinct) < 2:
            continue  # no collision — leave the bare basename label
        for key, sf in members:
            out[key] = _shortest_unique_suffix(sf, distinct)
    return out

def _tier_replacement_sources(
    chunks: "Iterable[dict]",
    root: "str | Path | None" = None,
    ast_sources: "Iterable[str | Path] | None" = None,
) -> tuple[set[str], set[str]]:
    """Compute (new_ast_sources, new_sem_sources) for tier-scoped replacement.

    #3411: AST replacement ownership is derived from explicit extraction
    provenance (ast_sources or chunk-level "extracted_sources"), so cross-file
    stub nodes emitted by extractors (e.g. .sln project stubs or ProjectReference
    stubs) do not pollute the replacement set and wipe the target project's
    nodes/edges. Falls back to AST node source_file only when no provenance is
    provided.
    """
    explicit_ast_sources: set[str] = set()
    if ast_sources is not None:
        for s in ast_sources:
            if s:
                explicit_ast_sources.add(str(s))
    for ch in chunks:
        if isinstance(ch, dict):
            for s in (ch.get("extracted_sources") or []):
                if s:
                    explicit_ast_sources.add(str(s))

    new_ast_sources: set[str] = set()
    new_sem_sources: set[str] = set()

    if explicit_ast_sources:
        for sf in explicit_ast_sources:
            new_ast_sources.add(sf)
            norm = _norm_source_file(sf, root)
            if norm:
                new_ast_sources.add(norm)
    else:
        for ch in chunks:
            if not isinstance(ch, dict):
                continue
            for n in ch.get("nodes", []):
                if not isinstance(n, dict):
                    continue
                sf = n.get("source_file")
                if not sf or not _is_ast_tier(n):
                    continue
                new_ast_sources.add(sf)
                norm = _norm_source_file(sf, root)
                if norm:
                    new_ast_sources.add(norm)

    for ch in chunks:
        if not isinstance(ch, dict):
            continue
        for n in ch.get("nodes", []):
            if not isinstance(n, dict):
                continue
            sf = n.get("source_file")
            if not sf or _is_ast_tier(n):
                continue
            new_sem_sources.add(sf)
            norm = _norm_source_file(sf, root)
            if norm:
                new_sem_sources.add(norm)

    return new_ast_sources, new_sem_sources

def dedupe_nodes(nodes: list[dict]) -> list[dict]:
    """Collapse nodes sharing an ``id``, last-writer-wins on attributes.

    Mirrors what ``build_from_json``'s ``G.add_node`` does implicitly (idempotent;
    a later node overwrites an earlier one's attributes). The ``--no-cluster``
    write path dumps the raw node list without building a graph, so same-id nodes
    — e.g. a Swift ``type=module`` anchor emitted once per importing file (#1327)
    — would otherwise appear as duplicates. Insertion order follows each id's
    first appearance; the retained dict is the last one seen.
    """
    by_id: dict = {}
    for n in nodes:
        nid = n.get("id")
        if nid is None:
            continue
        by_id[nid] = n
    return list(by_id.values())

def disambiguate_file_labels_in_nodes(nodes: "list") -> None:
    """Relabel colliding-basename file nodes on a raw node-dict list, in place
    (#2032). Used by the extract --no-cluster path, which writes the merged
    extraction directly without going through build_from_json."""
    items = [
        (i, n.get("label"), n.get("source_file"))
        for i, n in enumerate(nodes) if isinstance(n, dict)
    ]
    for i, new_label in _file_label_reassignments(items).items():
        nodes[i]["label"] = new_label

def edge_data(G: nx.Graph, u: str, v: str) -> dict:
    """Return one edge attribute dict for (u, v), tolerating MultiGraph.

    For MultiGraph/MultiDiGraph there can be multiple parallel edges;
    this returns the first one (sufficient for callers that only need
    relation/confidence for rendering). Fixes #796.
    """
    raw = G[u][v]
    if isinstance(G, (nx.MultiGraph, nx.MultiDiGraph)):
        return next(iter(raw.values()), {})
    return raw

def edge_datas(G: nx.Graph, u: str, v: str) -> list[dict]:
    """Return every edge attribute dict for (u, v); always a list."""
    raw = G[u][v]
    if isinstance(G, (nx.MultiGraph, nx.MultiDiGraph)):
        return list(raw.values())
    return [raw]

def prune_repo_from_graph(G: nx.Graph, repo_tag: str) -> int:
    """Remove all nodes tagged with repo_tag from G in-place. Returns count removed."""
    to_remove = [n for n, d in G.nodes(data=True) if d.get("repo") == repo_tag]
    G.remove_nodes_from(to_remove)
    return len(to_remove)

def _absolutize_source_files_in(payload: dict, root: Path) -> None:
    """Inverse of :func:`_relativize_source_files_in`.

    Re-anchor relative ``source_file`` fields against ``root`` so callers
    that load a cached fragment see the same absolute-path shape that a
    fresh in-process extraction would produce. Legacy cache entries with
    absolute ``source_file`` values pass through unchanged.
    """
    try:
        root_resolved = Path(root).resolve()
    except OSError:
        return
    for bucket in ("nodes", "edges", "hyperedges", "raw_calls"):
        for item in payload.get(bucket, []):
            if not isinstance(item, dict):
                continue
            # Mirror of the relativize side: definition_file re-anchors too (#3223).
            for key in ("source_file", "definition_file"):
                source = item.get(key)
                if not source:
                    continue
                sp = Path(source)
                if sp.is_absolute():
                    continue
                try:
                    item[key] = str(root_resolved / sp)
                except (TypeError, OSError):
                    continue

def _body_content(content: bytes) -> bytes:
    """Strip YAML frontmatter from Markdown content, returning only the body."""
    text = content.decode(errors="replace")
    opener = _FRONTMATTER_DELIM.match(text)
    if opener is None:
        return content
    closer = _FRONTMATTER_DELIM.search(text, opener.end())
    if closer is None:
        return content
    # Slice right after the closing `---` (not after its line) so the output
    # stays byte-identical with the historical implementation for well-formed
    # frontmatter -- existing semantic-cache hashes must not churn.
    return text[closer.start() + 3:].encode()

def _cleanup_stale_ast_entries(ast_base: Path, current_dir: Path) -> None:
    """Remove AST cache entries left behind by other graphify versions or
    grammar sets.

    Sweeps sibling ``v*/`` directories and unversioned ``*.json`` entries
    (the pre-versioning layout) under ``cache/ast/``. Best-effort: failures
    are ignored, stragglers are retried on the next run.
    """
    key = str(current_dir)
    if key in _cleaned_ast_dirs:
        return
    _cleaned_ast_dirs.add(key)
    if not ast_base.is_dir():
        return
    import shutil

    for child in ast_base.iterdir():
        if child == current_dir:
            continue
        try:
            if child.is_dir() and child.name.startswith("v"):
                shutil.rmtree(child, ignore_errors=True)
            elif child.suffix == ".json":
                child.unlink()
        except OSError:
            pass

def _grammar_fingerprint() -> str:
    """Short stable fingerprint of the installed tree-sitter grammar set.

    AST output depends on the grammar packages, not just graphify's own
    version: upgrading ``tree-sitter-swift`` changes what the extractor
    produces for the same file, so the cache namespace must change too,
    otherwise stale pre-upgrade extractions are served indefinitely
    (#4236). Covers the ``tree-sitter`` runtime, every ``tree-sitter-*``
    distribution, and bundled packs like ``tree-sitter-language-pack``."""
    global _GRAMMAR_FINGERPRINT_CACHE
    if _GRAMMAR_FINGERPRINT_CACHE is not None:
        return _GRAMMAR_FINGERPRINT_CACHE
    parts: list[str] = []
    try:
        from importlib.metadata import distributions

        for dist in distributions():
            try:
                name = (dist.metadata.get("Name") or "").lower()
            except Exception:
                continue
            if name == "tree-sitter" or name.startswith("tree-sitter-") or name.startswith("tree_sitter"):
                parts.append(f"{name}=={dist.version}")
    except Exception:
        _GRAMMAR_FINGERPRINT_CACHE = "unknown"
        return _GRAMMAR_FINGERPRINT_CACHE
    if not parts:
        _GRAMMAR_FINGERPRINT_CACHE = "none"
        return _GRAMMAR_FINGERPRINT_CACHE
    digest = hashlib.sha256(";".join(sorted(parts)).encode("utf-8")).hexdigest()
    _GRAMMAR_FINGERPRINT_CACHE = digest[:12]
    return _GRAMMAR_FINGERPRINT_CACHE

def _mtime_granularity_ns() -> int:
    """Return the assumed filesystem mtime granularity in nanoseconds.

    Read fresh on every call so the env var can be set after import (and so
    tests can flip it without reloading the module).
    """
    raw = os.environ.get("GRAPHIFY_MTIME_GRANULARITY_MS", "").strip()
    if raw:
        try:
            ms = float(raw)
        except ValueError:
            return _MTIME_GRANULARITY_NS
        if ms >= 0:
            return int(ms * 1_000_000)
    return _MTIME_GRANULARITY_NS

def _normalize_path(path: Path) -> Path:
    """Normalize path for consistent cache keys across Windows path spellings."""
    import sys
    if sys.platform != "win32":
        return path
    s = str(path)
    if s.startswith("\\\\?\\"):
        s = s[4:]  # strip extended-length prefix \\?\
    return Path(os.path.normcase(s))

def _normalize_source_file_value(src: "str | Path", root_resolved: Path) -> str:
    """Return ``src`` in portable form: backslashes flipped to forward slashes,
    then relativized against ``root_resolved`` when the path is in-root.

    Windows ``detect()`` emits absolute backslash paths, and a semantic
    fragment carrying one verbatim used to be persisted as-is — poisoning later
    ``graphify update`` runs with a machine-specific ``source_file`` (#2197).
    Out-of-root absolute paths pass through (slash-normalized only), same
    in/out rule and ``..``-rejection as :func:`_relativize_source_files_in`.
    """
    s = str(src).replace("\\", "/")
    p = Path(s)
    if not p.is_absolute():
        return s
    try:
        rel = os.path.relpath(p, root_resolved)
    except (ValueError, OSError):
        return s  # out-of-root (e.g. Windows cross-drive)
    if rel == ".." or rel.startswith(".." + os.sep) or rel.startswith("../"):
        return s  # escaped root — keep absolute
    return rel.replace(os.sep, "/")

def _rewrite_strings(obj: object, fn) -> None:
    """Apply ``fn`` to every string VALUE reachable in ``obj``, in place.

    Values only, never dict keys: rewriting keys blindly could silently
    collide two entries into one. The single id-keyed bucket -
    ``objc_field_types["tables"]`` - is handled by
    :func:`_rewrite_id_keyed_table_keys` beside each call to this (#3150).
    """
    if isinstance(obj, dict):
        items: "Iterable" = obj.items()
    elif isinstance(obj, list):
        items = enumerate(obj)
    else:
        return
    for key, value in list(items):
        if isinstance(value, str):
            new = fn(value)
            if new != value:
                obj[key] = new  # type: ignore[index]
        else:
            _rewrite_strings(value, fn)

def _salted_key(h: str, salt: str | None) -> str:
    """Derive the on-disk key from a content hash plus optional salt."""
    if not salt:
        return h
    return hashlib.sha256(f"{h}:{salt}".encode("utf-8")).hexdigest()

def _semantic_entry_matches_path(result: dict, path: Path, root: Path) -> bool:
    """Whether cached semantic groups belong to the requested walked path.

    Before walked paths entered the cache salt, a symlink could overwrite its
    target's unversioned semantic entry. Rejecting that mismatched legacy
    payload makes the next extraction self-heal instead of replaying it forever.
    """
    expected = _normalize_path(Path(os.path.abspath(path)))
    for bucket in ("nodes", "edges", "hyperedges"):
        for item in result.get(bucket, []):
            if not isinstance(item, dict):
                continue
            source = item.get("source_file")
            if not source:
                continue
            source_path = Path(source)
            if not source_path.is_absolute():
                source_path = Path(root) / source_path
            if _normalize_path(Path(os.path.abspath(source_path))) != expected:
                return False
    return True

def _stat_key_to_absolute(key: str, anchor: Path) -> str:
    """Inverse of :func:`_stat_key_to_relative`.

    Re-anchor a stored relative key against ``anchor``. Already-absolute keys
    (legacy indexes, out-of-anchor entries) pass through unchanged so an index
    written by an older graphify remains readable.
    """
    p = Path(key)
    if p.is_absolute():
        return str(p)
    return str(anchor / p)

def _stat_key_to_relative(key: str, anchor: Path) -> str:
    """Return ``key`` as a forward-slash relative path from ``anchor``.

    Local duplicate of :func:`graphify.detect._to_relative_for_storage` —
    detect imports cache, so cache cannot import detect without a cycle
    (and pulling detect in during the atexit flush would be fragile).
    Out-of-anchor and already-relative keys pass through unchanged, and
    ``..``-escaping relpaths are rejected (kept absolute), mirroring the
    manifest's portability rules.
    """
    p = Path(key)
    if not p.is_absolute():
        return key
    try:
        rel = os.path.relpath(p, anchor)
    except (ValueError, OSError):
        return key  # outside anchor (e.g. Windows cross-drive)
    if rel == ".." or rel.startswith(".." + os.sep) or rel.startswith("../"):
        return key  # escaped anchor — keep absolute
    return rel.replace(os.sep, "/")

def _flush_stat_index() -> None:
    global _stat_index_dirty, _stat_index_root
    if not _stat_index_dirty or _stat_index_root is None:
        return
    # Use the path captured when this root was bound (#3989), not a fresh
    # _stat_index_file(_stat_index_root) call: a mid-process root switch runs
    # this to flush the OUTGOING root, by which point a caller following the
    # documented set-_GRAPHIFY_OUT-then-call pattern has already pointed
    # _GRAPHIFY_OUT at the NEW root, and re-deriving here would flush the old
    # root's entries into the new root's file instead of its own.
    p = _stat_index_path if _stat_index_path is not None else _stat_index_file(_stat_index_root)
    # Build the on-disk form (#2199): prune entries whose file is gone (the
    # index otherwise grows without bound), then store in-anchor keys as
    # forward-slash relative paths so the index survives a corpus move/clone.
    # Out-of-anchor keys stay absolute (same rule as the detect manifest); a
    # reader tells the formats apart by absoluteness, so no version marker is
    # needed. In-memory keys are untouched — only the serialization changes.
    on_disk: dict[str, dict] = {}
    for k, v in _stat_index.items():
        try:
            if not os.path.exists(k):
                continue
        except OSError:
            continue
        dk = _stat_key_to_relative(k, _stat_index_anchor) if _stat_index_anchor is not None else k
        on_disk[dk] = v
    # Never resurrect a corpus that was deleted while graphify was running
    # (#2974): a hook-launched `graphify update . &` in a short-lived worktree
    # outlives `git worktree remove`, and an unconditional `mkdir -p` here
    # rebuilt the dead path as a husk holding nothing but this index. The
    # index is a pure optimisation, so when its root is gone it is simply not
    # written. Creating graphify-out/cache/ under a root that still exists is
    # unchanged (a first run writes the index before anything else does).
    try:
        if not _stat_index_root.is_dir():
            _stat_index_dirty = False
            return
    except OSError:
        _stat_index_dirty = False
        return
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=p.parent, prefix="stat-index.", suffix=".tmp")
        try:
            os.write(fd, json.dumps(on_disk, separators=(",", ":")).encode())
            os.close(fd)
            _os_replace_with_fallback(tmp, p)
        except Exception:
            try:
                os.close(fd)
            except OSError:
                pass
            try:
                os.unlink(tmp)
            except OSError:
                pass
    except OSError:
        pass
    _stat_index_dirty = False

def _target_file_present(target: str, root: Path) -> bool:
    candidate = Path(target)
    if not candidate.is_absolute():
        candidate = Path(root) / candidate
    try:
        return candidate.is_file()
    except (OSError, ValueError):
        return False

def _present_target_files(result: dict, root: Path) -> list[str]:
    """The ``target_file`` stamps in ``result`` that name an existing file."""
    present: set[str] = set()
    for edge in result.get("edges", []) or []:
        if not isinstance(edge, dict):
            continue
        target = edge.get("target_file")
        if isinstance(target, str) and target and target not in present:
            if _target_file_present(target, root):
                present.add(target)
    return sorted(present)

def clear_cache(root: Path = Path(".")) -> None:
    """Delete all cache entries (ast/, semantic/, semantic-deep/, and legacy
    flat entries)."""
    base = Path(root).resolve() / _GRAPHIFY_OUT / "cache"
    # Legacy flat entries
    if base.is_dir():
        for f in base.glob("*.json"):
            f.unlink()
    # Namespaced entries, all globbed recursively: ast/ has per-version subdirs,
    # semantic-deep/ holds --mode deep entries (#1894), and both semantic kinds
    # have per-prompt-fingerprint subdirs (#1939).
    for kind in ("ast", "semantic", "semantic-deep"):
        d = base / kind
        if d.is_dir():
            for f in d.glob("**/*.json"):
                f.unlink()

def _community_text(nodes: list, label: str = "") -> str:
    parts = [label]
    for node in nodes[:80]:
        parts.append(str(node.get("label", "")))
        parts.append(str(node.get("source_file", "")))
        parts.append(str(node.get("node_type", "")))
        parts.append(str(node.get("file_type", "")))
    return " ".join(parts).lower()

def _keyword_score(text: str, keywords: set[str]) -> int:
    score = 0
    for keyword in keywords:
        score += len(re.findall(rf"(?<![a-z0-9]){re.escape(keyword)}(?![a-z0-9])", text))
    return score

def build_section_node_map(sections: list, comm_idx: dict) -> dict:
    """Map section_id -> list of nodes belonging to its communities."""
    section_nodes = {}
    for sec in sections:
        sid = sec["id"]
        if sid == "overview":
            section_nodes[sid] = []
            continue
        nodes = []
        for cid in sec.get("communities", []):
            nodes.extend(comm_idx.get(str(cid), []))
        section_nodes[sid] = nodes
    return section_nodes

def classify_edges(edges: list, section_nodes_map: dict) -> dict:
    """Classify edges as intra-section or inter-section.

    Returns:
        {
            "intra": {section_id: [edges]},
            "inter": [edges],
            "orphan": [edges]  # one endpoint not in any section
        }
    """
    # Build node -> section lookup
    node_section = {}
    for sid, nodes in section_nodes_map.items():
        for n in nodes:
            node_section[n.get("id")] = sid

    intra = defaultdict(list)
    inter = []
    orphan = []

    for e in edges:
        src = e.get("source", "")
        tgt = e.get("target", "")
        src_sec = node_section.get(src)
        tgt_sec = node_section.get(tgt)

        if src_sec is None or tgt_sec is None:
            orphan.append(e)
        elif src_sec == tgt_sec:
            intra[src_sec].append(e)
        else:
            inter.append(e)

    return {"intra": dict(intra), "inter": inter, "orphan": orphan, "node_section": node_section}

def detect_lang(lang: str, nodes: list, labels: dict) -> str:
    """Resolve auto language from labels and node names."""
    if lang and lang.lower() != "auto":
        return lang
    sample = " ".join(
        list(labels.values())[:50]
        + [str(n.get("label", "")) for n in nodes[:200]]
        + [str(n.get("source_file", "")) for n in nodes[:100]]
    )
    return "zh-CN" if re.search(r"[\u4e00-\u9fff]", sample) else "en"

def first_list(*values) -> list:
    """Return the first list from a set of possible schema locations."""
    for value in values:
        if isinstance(value, list):
            return value
    return []

def first_present(mapping: dict, *keys, default=None):
    """Return the first non-empty value for any candidate key."""
    for key in keys:
        if key in mapping and mapping[key] not in (None, ""):
            return mapping[key]
    return default

def endpoint_id(value) -> str:
    """Normalize edge endpoints that may be strings or node-like objects."""
    if isinstance(value, dict):
        value = first_present(value, "id", "node_id", "key", "name", "qualified_name")
    return str(value or "")

def generate_nav(sections: list) -> str:
    """Generate the sticky navigation bar."""
    links = []
    for sec in sections:
        links.append(f'    <a href="#{escape(sec["id"], quote=True)}">{escape(sec["name"])}</a>')
    return '<div class="nav">\n' + "\n".join(links) + "\n</div>"

def html_comment_text(text: str) -> str:
    """Keep generated HTML comments well-formed."""
    return str(text or "").replace("--", "- -").replace("\n", " ")

def infer_project_name(graph_path: str, meta: dict) -> str:
    """Infer a display project name when graph metadata does not include one."""
    if meta.get("project_name"):
        return meta["project_name"]
    path = Path(graph_path).resolve()
    if path.parent.name == GRAPHIFY_OUT_NAME and len(path.parents) > 1:
        return path.parents[1].name
    return path.parent.name or "Project"

def is_zh(lang: str) -> bool:
    """Return true when localized strings should be Chinese."""
    return (lang or "").lower().startswith("zh")

def load_report(path: str | Path | None) -> str:
    """Load GRAPH_REPORT.md if it exists."""
    if path and os.path.exists(path):
        return Path(path).read_text(encoding="utf-8")
    return ""

def node_in_section(node_id: str, section_node_ids: set) -> bool:
    """Check if a node belongs to a section."""
    return node_id in section_node_ids

def node_kind(node: dict) -> str:
    """Classify a graph node for Mermaid styling and table tags."""
    label = str(node.get("label") or node.get("id") or "").lower()
    source_file = str(node.get("source_file") or "").lower()
    file_type = str(node.get("file_type") or "").lower()
    node_type = str(node.get("node_type") or "").lower()
    if node_type in {"class", "klass", "struct", "interface", "enum", "trait", "model"}:
        return "klass"
    if node_type in {"module", "file", "package", "namespace"}:
        return "module"
    if node_type in {"endpoint", "route", "api", "handler", "controller"}:
        return "api"
    if node_type in {"test", "spec"}:
        return "test"
    if node_type in {"component", "hook", "view", "page"}:
        return "ui"
    if file_type in {"rationale", "document"}:
        return "concept"
    if "test" in source_file or label.startswith("test_") or "spec" in source_file:
        return "test"
    if any(word in label for word in ("endpoint", "router", "api", "route")):
        return "api"
    if any(word in label for word in ("cli", "command", "click", "typer")):
        return "entry"
    if any(word in label for word in ("async", "await", "stream", "sse")):
        return "async"
    raw_label = str(node.get("label") or "")
    hook_like = raw_label.startswith("use") and len(raw_label) > 3 and (raw_label[3].isupper() or raw_label[3] in "_-")
    if any(word in label for word in ("component", "props", "hook", "store")) or hook_like or source_file.endswith((".tsx", ".jsx", ".vue", ".svelte")):
        return "ui"
    raw = raw_label
    if raw[:1].isupper() and not raw.endswith("()"):
        return "klass"
    if raw.endswith((".py", ".ts", ".tsx", ".js", ".jsx", ".go", ".rs", ".java", ".kt", ".rb", ".php", ".cs", ".swift", ".vue", ".svelte")):
        return "module"
    return "function"

def normalize_communities(value) -> list:
    """Normalize section community lists from JSON or simple strings."""
    if isinstance(value, list):
        return value
    if value in (None, ""):
        return []
    if isinstance(value, str):
        return [part.strip() for part in value.split(",") if part.strip()]
    return [value]

def pick_text(lang: str, zh: str, en: str) -> str:
    """Small localization helper for generated copy."""
    return zh if is_zh(lang) else en

def _describe_node(label: str, source_file: str, file_type: str, lang: str) -> str:
    """Generate a compact human-readable description for a graph node."""
    lower = label.lower()
    source = source_file or pick_text(lang, "项目", "project")
    if file_type == "rationale":
        return pick_text(lang, f"设计说明：{label}", f"Design note for {label}.")
    if file_type == "document":
        return pick_text(lang, f"文档入口，描述 {label} 相关能力。", f"Documentation node describing {label}.")
    if label.endswith(".py") or label.endswith(".tsx") or label.endswith(".ts"):
        return pick_text(lang, f"{source} 中的模块文件，承载该层主要实现。", f"Module file in {source}.")
    if "config" in lower:
        return pick_text(lang, "读取、解析或持久化项目配置。", "Reads, resolves, or persists project configuration.")
    if "scan" in lower:
        return pick_text(lang, "触发项目扫描或处理扫描状态。", "Starts scanning or handles scan status.")
    if "ingest" in lower or "clone" in lower or "git" in lower:
        return pick_text(lang, "把本地目录或远程仓库转换为分析上下文。", "Turns a local path or remote repository into analysis context.")
    if "prompt" in lower:
        return pick_text(lang, "构造发送给 LLM 的结构化提示。", "Builds structured prompts for model calls.")
    if "analy" in lower:
        return pick_text(lang, "编排分析流程并产出结构化文档数据。", "Orchestrates analysis and returns structured documentation data.")
    if "graph" in lower or "dependency" in lower:
        return pick_text(lang, "构建依赖关系并提供排序或图形化数据。", "Builds dependency relationships and graph data.")
    if "export" in lower or "markdown" in lower or "html" in lower:
        return pick_text(lang, "将文档数据导出为目标格式。", "Exports documentation data to a target format.")
    if "chat" in lower or "rag" in lower or "retrieve" in lower:
        return pick_text(lang, "支撑检索增强问答或流式聊天。", "Supports retrieval-augmented Q&A or streaming chat.")
    if "wiki" in lower or "page" in lower or "sidebar" in lower:
        return pick_text(lang, "组织文档页面、侧边栏或内容读取。", "Organizes documentation pages, navigation, or content lookup.")
    if "cache" in lower or "hash" in lower:
        return pick_text(lang, "缓存分析结果或生成缓存键。", "Caches analysis results or computes cache keys.")
    if "test" in lower:
        return pick_text(lang, "验证导入、入口点或版本等基础行为。", "Verifies imports, entry points, or version behavior.")
    return pick_text(lang, f"{source} 中的 {label} 节点。", f"{label} node in {source}.")

def _report_highlights(report_text: str, lang: str) -> str:
    """Extract a compact highlights card from GRAPH_REPORT.md."""
    if not report_text.strip():
        return ""

    lines = report_text.splitlines()
    keep: list[str] = []
    in_gods = False
    in_summary = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("## "):
            in_summary = stripped == "## Summary"
            in_gods = stripped.startswith("## God Nodes")
            continue
        if in_summary and stripped.startswith("- "):
            keep.append(stripped[2:])
        elif in_gods and re.match(r"^\d+\.", stripped):
            keep.append(stripped)
        if len(keep) >= 6:
            break

    if not keep:
        return ""

    title = pick_text(lang, "图谱报告摘要", "Graph Report Highlights")
    items = "\n".join(f"      <li>{escape(item)}</li>" for item in keep)
    return f"""<div class="card">
    <h4>{title}</h4>
    <ul>
{items}
    </ul>
  </div>"""

def _suggest_tag(label: str, file_type: str, lang: str, kind: str = "") -> str:
    """Heuristic tag suggestion based on label name and file type."""
    lower = label.lower()
    names = {
        "concept": ("概念", "Concept", "tag-func"),
        "entry": ("入口", "Entry", "tag-cmd"),
        "api": ("API", "API", "tag-endpoint"),
        "async": ("异步", "Async", "tag-async"),
        "klass": ("类", "Class", "tag-class"),
        "ui": ("UI", "UI", "tag-hook"),
        "module": ("模块", "Module", "tag-class"),
        "test": ("测试", "Test", "tag-func"),
        "function": ("函数", "Function", "tag-func"),
    }
    if kind in names:
        zh, en, cls = names[kind]
        return f'<span class="tag {cls}">{pick_text(lang, zh, en)}</span>'
    if file_type == "rationale":
        return f'<span class="tag tag-func">{pick_text(lang, "概念", "Concept")}</span>'
    if any(kw in lower for kw in ("cli", "command", "scan", "serve", "chat", "config")):
        if "group" in lower or "command" in lower:
            return f'<span class="tag tag-cmd">{pick_text(lang, "CLI命令", "CLI")}</span>'
    if any(kw in lower for kw in ("router", "endpoint", "api", "/api/")):
        return f'<span class="tag tag-endpoint">{pick_text(lang, "API端点", "API")}</span>'
    if any(kw in lower for kw in ("async", "await", "stream")):
        return f'<span class="tag tag-async">{pick_text(lang, "异步", "Async")}</span>'
    if any(kw in lower for kw in ("class", "model", "schema", "dataclass", "pydantic")):
        return f'<span class="tag tag-class">{pick_text(lang, "类", "Class")}</span>'
    if any(kw in lower for kw in ("hook", "usestate", "useeffect", "store")):
        return '<span class="tag tag-hook">Hook</span>'
    if any(kw in lower for kw in ("component", "props", "tsx", "jsx", "render")):
        return f'<span class="tag tag-class">{pick_text(lang, "组件", "Component")}</span>'
    return f'<span class="tag tag-func">{pick_text(lang, "函数", "Function")}</span>'

def normalize_sections(sections: list, lang: str) -> list:
    """Ensure sections have safe unique IDs and an overview section first."""
    overview_name = pick_text(lang, "架构总览", "Architecture Overview")
    normalized = [{"id": "overview", "name": overview_name, "communities": []}]
    used = {"overview", "hyperedges", "stats"}

    for index, raw in enumerate(sections or [], 1):
        if not isinstance(raw, dict):
            continue
        raw_id = str(raw.get("id") or raw.get("key") or raw.get("name") or f"section-{index}")
        raw_name = str(raw.get("name") or raw.get("label") or raw_id)
        if raw_id.lower() == "overview":
            normalized[0]["name"] = raw_name or overview_name
            continue

        sid = html_anchor_id(raw_id, f"section-{index}", used)
        normalized.append({
            "id": sid,
            "name": raw_name,
            "communities": normalize_communities(raw.get("communities", raw.get("community"))),
        })
    return normalized

def read_json(path: str | Path, default=None):
    """Read JSON with a useful error message."""
    if not path:
        return default
    path = Path(path)
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise SystemExit(f"ERROR: invalid JSON in {path}: {exc}") from exc

def load_labels(path: str | Path | None) -> dict:
    """Load community labels from .graphify_labels.json, tolerating wrapper keys."""
    data = read_json(path, default={})
    if not isinstance(data, dict):
        return {}
    if isinstance(data.get("labels"), dict):
        data = data["labels"]
    if isinstance(data.get("communities"), dict):
        data = data["communities"]
    labels = {}
    for key, value in data.items():
        if isinstance(value, dict):
            value = first_present(value, "label", "name", "title", default=key)
        labels[str(key)] = str(value)
    return labels

def load_sections(path: str | Path | None) -> list:
    """Load section definitions from JSON file."""
    data = read_json(path, default=[])
    if isinstance(data, dict) and isinstance(data.get("sections"), list):
        data = data["sections"]
    if not isinstance(data, list):
        raise SystemExit(f"ERROR: sections file must contain a JSON array: {path}")
    return data

def safe_file_path(path: str) -> str:
    """Return a short, safe display path."""
    # Truncate long paths for display
    parts = path.split("/")
    if len(parts) > 3:
        return "/".join(parts[-3:])
    return path

def group_nodes_by_file(nodes: list) -> dict:
    """Group selected nodes by source file for Mermaid subgraphs."""
    groups = defaultdict(list)
    for node in nodes:
        source_file = safe_file_path(node.get("source_file", "")) or "External / generated"
        groups[source_file].append(node)
    return dict(sorted(groups.items(), key=lambda item: (-len(item[1]), item[0])))

def section_keywords(nodes: list, limit: int = 5) -> list:
    """Pick representative words from labels and file names."""
    counts = Counter()
    stopwords = {
        "the", "and", "for", "with", "from", "this", "that", "class", "function",
        "method", "file", "src", "lib", "core", "index", "main", "init", "py",
        "ts", "tsx", "js", "jsx", "go", "rs", "java", "html", "css",
    }
    for node in nodes:
        text = f"{node.get('label', '')} {node.get('source_file', '')}".replace("/", " ").replace("_", " ").replace("-", " ")
        for raw in text.split():
            word = "".join(ch for ch in raw.lower() if ch.isalnum())
            if len(word) < 3 or word in stopwords:
                continue
            counts[word] += 1
    return [word for word, _ in counts.most_common(limit)]

def label_for_community(cid: str, labels: dict, nodes: list, lang: str) -> str:
    """Choose a readable section name for a community."""
    if str(cid) in labels and labels[str(cid)]:
        return labels[str(cid)]
    keywords = section_keywords(nodes, 3)
    if keywords:
        return " ".join(word.title() for word in keywords[:3])
    return pick_text(lang, f"社区 {cid}", f"Community {cid}")

def derive_sections_from_communities(nodes: list, labels: dict, lang: str, max_sections: int) -> list:
    """Derive architecture-oriented sections when no sections JSON is supplied."""
    comm_idx = build_community_index(nodes)
    sections = [{"id": "overview", "name": pick_text(lang, "架构总览", "Architecture Overview"), "communities": []}]
    grouped = {}
    unassigned = []

    for cid, community_nodes in sorted(comm_idx.items(), key=lambda item: (-len(item[1]), str(item[0]))):
        label = label_for_community(cid, labels, community_nodes, lang)
        text = _community_text(community_nodes, label)
        best = None
        best_score = 0
        for priority, (sid, zh_name, en_name, keywords) in enumerate(SECTION_ARCHETYPES):
            score = _keyword_score(text, keywords)
            if score > best_score:
                best = (priority, sid, zh_name, en_name)
                best_score = score

        if best and best_score >= 2:
            priority, sid, zh_name, en_name = best
            sec = grouped.setdefault(
                sid,
                {
                    "id": sid,
                    "name": pick_text(lang, zh_name, en_name),
                    "communities": [],
                    "node_count": 0,
                    "priority": priority,
                },
            )
            sec["communities"].append(cid)
            sec["node_count"] += len(community_nodes)
        else:
            unassigned.append((cid, community_nodes, label))

    selected, overflow_communities = _rank_grouped_sections(grouped, max(1, int(max_sections or 15)) - 1)
    sections.extend(
        {"id": sec["id"], "name": sec["name"], "communities": sec["communities"]}
        for sec in selected
    )

    remaining_slots = max(0, int(max_sections or 15) - (len(sections) - 1) - 1)
    for cid, community_nodes, label in unassigned[:remaining_slots]:
        sections.append({"id": str(label or f"community-{cid}"), "name": label, "communities": [cid]})

    other_communities = overflow_communities + [cid for cid, _, _ in unassigned[remaining_slots:]]
    if other_communities:
        sections.append({
            "id": "other",
            "name": pick_text(lang, "其他", "Other"),
            "communities": other_communities,
        })
    return sections

def mermaid_section_id(section_id: str) -> str:
    """Convert a section ID (like 'cli-entry') to a safe Mermaid ID (like 'CLI_ENTRY')."""
    return stable_ascii_id(section_id, "section").upper()

def node_mermaid_id(node: dict) -> str:
    """Generate a safe Mermaid node ID from a graph node.

    Mermaid IDs must match [a-zA-Z][a-zA-Z0-9_]* — no dots, hyphens, slashes.
    """
    return stable_ascii_id(node.get("id", "unknown"), "node")

def to_float(value, default: float = 0.0) -> float:
    """Convert graph numeric fields that may be serialized as strings."""
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def edge_score(edge: dict) -> float:
    """Rank edges by confidence and usefulness for diagrams."""
    relation = edge.get("relation", "")
    score = to_float(edge.get("confidence_score", 1.0), 1.0)
    if str(edge.get("confidence", "")).upper() == "EXTRACTED":
        score += 2.0
    if relation in {"calls", "uses", "method"}:
        score += 1.0
    elif relation in {"imports", "imports_from"}:
        score += 0.6
    elif relation == "contains":
        score -= 0.2
    elif relation == "rationale_for":
        score -= 0.6
    return score

def node_importance(node: dict) -> float:
    """Use graphify centrality fields when available."""
    for key in ("pagerank", "page_rank", "pageRank", "rank", "centrality", "score"):
        if key in node:
            return to_float(node.get(key), 0.0)
    return 0.0

def load_graph(path: str | Path) -> tuple:
    """Load graph.json. Returns normalized (nodes, edges, hyperedges, metadata)."""
    if path:
        from graphify.security import check_graph_file_size_cap
        try:
            check_graph_file_size_cap(Path(path))
        except ValueError as exc:
            raise SystemExit(f"ERROR: {exc}") from exc
    data = read_json(path)
    if not isinstance(data, dict):
        raise SystemExit(f"ERROR: graph file must contain a JSON object: {path}")

    graph_block = data.get("graph") if isinstance(data.get("graph"), dict) else {}
    meta_block = data.get("metadata") if isinstance(data.get("metadata"), dict) else {}

    node_link = _node_link_payload(data)
    if node_link:
        raw_nodes, raw_edges = node_link
    else:
        raw_nodes = first_list(data.get("nodes"), data.get("vertices"), graph_block.get("nodes"), graph_block.get("vertices"))
        raw_edges = first_list(data.get("links"), data.get("edges"), graph_block.get("links"), graph_block.get("edges"))
    hyperedges = first_list(data.get("hyperedges"), graph_block.get("hyperedges"), data.get("groups"), graph_block.get("groups"))

    nodes = [normalize_node(n, i) for i, n in enumerate(raw_nodes) if isinstance(n, dict)]
    edges = []
    for i, raw_edge in enumerate(raw_edges):
        if not isinstance(raw_edge, dict):
            continue
        edge = normalize_edge(raw_edge, i)
        if edge:
            edges.append(edge)

    meta = dict(graph_block)
    meta.update(meta_block)
    for key in ("built_at_commit", "commit", "project_name", "repo", "repository", "language_breakdown"):
        if data.get(key) and not meta.get(key):
            meta[key] = data.get(key)
    if meta.get("commit") and not meta.get("built_at_commit"):
        meta["built_at_commit"] = meta["commit"]

    return nodes, edges, hyperedges, meta

def should_include_edge(edge: dict) -> bool:
    """Decide whether to auto-include an edge in Mermaid output."""
    conf = str(edge.get("confidence", "EXTRACTED")).upper()
    score = to_float(edge.get("confidence_score", 1.0), 1.0)

    if conf == "EXTRACTED":
        return True
    if conf == "INFERRED" and score >= 0.85:
        return True
    # Low-confidence INFERRED or AMBIGUOUS: comment out for LLM review
    return False

def preferred_edges(edges: list, allow_structure: bool = False) -> list:
    """Filter to edges that make a readable call-flow diagram."""
    primary = {"calls", "uses", "method", "imports", "imports_from"}
    secondary = {"contains", "rationale_for", "conceptually_related_to"}
    selected = []
    for edge in edges:
        if not should_include_edge(edge):
            continue
        relation = edge.get("relation", "")
        if relation in primary or (allow_structure and relation in secondary):
            selected.append(edge)
    if selected:
        return selected
    return [edge for edge in edges if should_include_edge(edge)]

def derive_flow_chain(sections: list, classified_edges: dict) -> str:
    """Derive a readable section flow from inter-section edges."""
    section_names = {sec["id"]: sec.get("name", sec["id"]) for sec in sections}
    order = [sec["id"] for sec in sections if sec["id"] != "overview"]
    if not order:
        return "Graph nodes -> documentation"

    outgoing = defaultdict(Counter)
    incoming = Counter()
    for (src, tgt), data in section_edge_summary(classified_edges).items():
        outgoing[src][tgt] += data["count"]
        incoming[tgt] += data["count"]

    start = min(order, key=lambda sid: (incoming.get(sid, 0), order.index(sid)))
    chain = [start]
    seen = {start}
    current = start
    while len(chain) < min(7, len(order)):
        candidates = [(count, tgt) for tgt, count in outgoing.get(current, {}).items() if tgt not in seen]
        if candidates:
            _, nxt = max(candidates)
        else:
            remaining = [sid for sid in order if sid not in seen]
            if not remaining:
                break
            nxt = remaining[0]
        chain.append(nxt)
        seen.add(nxt)
        current = nxt
    return " -> ".join(section_names.get(sid, sid) for sid in chain)

def truncate_text(text: str, limit: int) -> str:
    """Truncate without splitting Mermaid syntax."""
    text = " ".join(str(text or "").split())
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 3)].rstrip() + "..."

def humanize_label(label: str, source_file: str = "") -> str:
    """Convert graph labels into short labels people can scan in a diagram."""
    label = str(label or "").strip()
    if not label:
        return Path(source_file).name if source_file else "Unknown"
    if label.startswith(".") and label.endswith("()"):
        return label[1:]
    if label.endswith((".py", ".ts", ".tsx", ".js", ".jsx", ".go", ".rs", ".java", ".rb")):
        return Path(label).name
    if "_" in label and " " not in label and len(label) > 28:
        parts = [p for p in label.split("_") if p]
        if parts:
            label = " ".join(parts[-3:])
    return truncate_text(label, 42)

def node_display_name(node: dict | None, fallback: str = "") -> str:
    """Readable node label for tables and summaries."""
    if not node:
        return str(fallback or "")
    label = str(node.get("label") or node.get("id") or fallback or "")
    return humanize_label(label, node.get("source_file", ""))

def format_node_refs(node_ids: set, node_by_id: dict, lang: str, empty_text: str, limit: int = 3) -> str:
    """Render node references as readable labels instead of internal IDs."""
    if not node_ids:
        return escape(empty_text)
    parts = []
    for nid in sorted(node_ids, key=lambda item: node_display_name(node_by_id.get(item), item).lower())[:limit]:
        node = node_by_id.get(nid)
        label = node_display_name(node, nid)
        source = safe_file_path((node or {}).get("source_file", ""))
        if source:
            parts.append(f"<code>{escape(label)}</code><br><small style=\"color:var(--muted)\">{escape(source)}</small>")
        else:
            parts.append(f"<code>{escape(label)}</code>")
    if len(node_ids) > limit:
        parts.append(escape(pick_text(lang, f"+{len(node_ids) - limit} 个更多", f"+{len(node_ids) - limit} more")))
    return "<br>".join(parts)

def node_label(node: dict) -> str:
    """Build a readable Mermaid node label."""
    label = humanize_label(node.get("label") or node.get("id"), node.get("source_file", ""))
    source_file = safe_file_path(node.get("source_file", ""))
    if source_file and not label.endswith(Path(source_file).name):
        return f"{safe_mermaid_text(label)}<br/><small>{safe_mermaid_text(source_file)}</small>"
    return safe_mermaid_text(label)

def _load_toml(path: Path) -> dict[str, Any]:
    try:
        import tomllib  # type: ignore[import-not-found]
    except ModuleNotFoundError:
        try:
            import tomli as tomllib  # type: ignore[import-not-found,no-redef]
        except ModuleNotFoundError:
            raise ImportError(
                "--cargo on Python 3.10 needs tomli. Install with: pip install tomli"
            ) from None

    with path.open("rb") as manifest:
        return tomllib.load(manifest)

def _member_manifest_paths(root: Path, root_data: dict[str, Any]) -> list[Path]:
    paths: list[Path] = []
    if isinstance(root_data.get("package"), dict):
        paths.append(root / "Cargo.toml")

    workspace = root_data.get("workspace")
    members = workspace.get("members", []) if isinstance(workspace, dict) else []
    if not isinstance(members, list):
        return paths

    for pattern in members:
        if not isinstance(pattern, str):
            continue
        for member in sorted(root.glob(pattern)):
            manifest = member / "Cargo.toml"
            if manifest.is_file() and manifest not in paths:
                paths.append(manifest)
    return paths

def introspect_cargo(root: str | Path) -> dict[str, Any]:
    """Return crate nodes and internal dependency edges from Cargo manifests."""
    root_path = Path(root).resolve()
    root_manifest = root_path / "Cargo.toml"
    if not root_manifest.is_file():
        discovered = _discover_root_manifest(root_path)
        if discovered is not None:
            root_manifest = discovered
    root_data = _load_toml(root_manifest)
    workspace = root_data.get("workspace")
    workspace_dependencies = workspace.get("dependencies", {}) if isinstance(workspace, dict) else {}
    if not isinstance(workspace_dependencies, dict):
        workspace_dependencies = {}

    # Workspace members are resolved relative to the manifest's OWN
    # directory, not necessarily root_path (#3678: the manifest can live in
    # a discovered subdirectory, e.g. src-tauri/).
    manifests = _member_manifest_paths(root_manifest.parent, root_data)
    crates: dict[str, tuple[str, Path, dict[str, Any]]] = {}

    for manifest in manifests:
        data = root_data if manifest == root_manifest else _load_toml(manifest)
        package = data.get("package")
        if not isinstance(package, dict):
            continue
        name = package.get("name")
        if isinstance(name, str):
            crates[name] = (f"crate:{name}", manifest, data)

    nodes = [
        {
            "id": crate_id,
            "label": name,
            "source_file": manifest.relative_to(root_path).as_posix(),
            "source_location": "L1",
        }
        for name, (crate_id, manifest, _data) in sorted(crates.items())
    ]

    edges: list[dict[str, Any]] = []
    for source_name, (source_id, manifest, data) in sorted(crates.items()):
        dependencies = data.get("dependencies", {})
        if not isinstance(dependencies, dict):
            continue
        source_file = manifest.relative_to(root_path).as_posix()
        for dep_key, spec in sorted(dependencies.items()):
            inherited = isinstance(spec, dict) and "workspace" in spec
            if inherited:
                if spec["workspace"] is not True:
                    continue
                spec = workspace_dependencies.get(dep_key)
                if not isinstance(spec, dict) or not isinstance(spec.get("path"), str):
                    continue
            # Cargo lets a dep table entry rename the crate via `package = "..."`:
            #   db = { path = "../storage", package = "internal-storage" }
            # The key `db` is the name used in `use db::…;`; the actual crate
            # published under `[package].name = "internal-storage"` is what
            # `crates` is keyed by. Without honoring `package`, every renamed
            # workspace-internal dep silently drops its edge (#1858).
            real_name = dep_key
            if isinstance(spec, dict):
                pkg_override = spec.get("package")
                if isinstance(pkg_override, str) and pkg_override:
                    real_name = pkg_override
            target = crates.get(real_name)
            if target is None:
                continue
            if inherited:
                # Shared paths are relative to the workspace root, not the member.
                # A matching name alone cannot prove a registry/git dep is local.
                inherited_manifest = (root_path / spec["path"] / "Cargo.toml").resolve()
                if inherited_manifest != target[1].resolve():
                    continue
            edges.append(
                {
                    "source": source_id,
                    "target": target[0],
                    "relation": "crate_depends_on",
                    "context": "cargo_dependency",
                    "weight": 1.0,
                    "confidence": _CONFIDENCE_EXTRACTED,
                    "source_file": source_file,
                    "source_location": "L1",
                }
