def package_name(manifest: Path) -> str | None:
    """A Cargo.toml's `[package] name` as Rust spells it in a path (`-` -> `_`).

    Returns None when the manifest has no package name, cannot be read, or
    cannot be parsed. Callers that scope a Rust import to a crate treat "no
    name" as "no crate", never as an error, so this stays silent.
    """
    try:
        package = _load_toml(manifest).get("package")
    except (OSError, ValueError):
        return None
    except ImportError:  # Python 3.10 without tomli: recover the one key we need
        try:
            text = manifest.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return None
        match = re.search(r'^\[package\][^\[]*?^name\s*=\s*"([^"]+)"', text, re.M | re.S)
        name = match.group(1) if match else None
    else:
        name = package.get("name") if isinstance(package, dict) else None
    return name.replace("-", "_") if isinstance(name, str) and name else None

def _gc_hook_session_markers(d: "Path") -> None:
    """Best-effort removal of per-session hook markers older than 24h."""
    try:
        cutoff = time.time() - 86400
        for entry in os.scandir(d):
            try:
                if entry.stat().st_mtime < cutoff:
                    os.unlink(entry.path)
            except OSError:
                pass
    except OSError:
        pass

def _hook_strict_enabled(flag: bool) -> bool:
    """Resolve strict mode: GRAPHIFY_HOOK_STRICT env overrides the baked-in flag
    (truthy forces on without a reinstall, falsy is the kill switch); unset defers
    to the flag the installed hook command carried."""
    v = os.environ.get("GRAPHIFY_HOOK_STRICT", "").strip().lower()
    if v in ("1", "true", "yes", "on"):
        return True
    if v in ("0", "false", "no", "off"):
        return False
    return flag

def _print_cloud_cta(out_dir: "Path") -> None:
    """Nudge toward Graphify Cloud once after a successful local graph build.

    Kept precise and shown only to humans running the CLI interactively:
    suppressed in non-interactive/CI runs (stdout is not a TTY, which also
    covers the AI-assistant pipeline), when the user opts out
    (``GRAPHIFY_NO_TIPS``/``GRAPHIFY_NO_CTA``), and after the first time per
    project (a marker under ``graphify-out/``) so repeat builds stay quiet.
    """
    if os.environ.get("GRAPHIFY_NO_TIPS") or os.environ.get("GRAPHIFY_NO_CTA"):
        return
    try:
        if not sys.stdout.isatty():
            return
    except Exception:
        return
    marker = out_dir / ".cloud-cta-shown"
    try:
        if marker.exists():
            return
    except Exception:
        return
    print()
    print("  Graphify Cloud: faster indexing, fewer tokens, cross-repo search,")
    print("  and PR review, with your whole SDLC mapped and always current.")
    print("  Connect a repo at https://app.graphify.com")
    try:
        marker.parent.mkdir(parents=True, exist_ok=True)
        marker.write_text("1", encoding="utf-8")
    except Exception:
        pass

def _query_stamp_fresh() -> bool:
    """True if a query/explain/path ran within GRAPHIFY_HOOK_STRICT_TTL (default
    1800s) — recent orientation, so strict mode does not block this read."""
    from graphify.paths import out_path
    try:
        ttl = float(os.environ.get("GRAPHIFY_HOOK_STRICT_TTL", "1800"))
        return (time.time() - out_path("cache", "last_query_stamp").stat().st_mtime) < ttl
    except Exception:
        return False

def _record_extract_cost(graphify_out: Path, input_tokens: int, output_tokens: int, files: int) -> None:
    """Append this run's token usage to graphify-out/cost.json, the same ledger the
    skill writes, so `graphify extract` refreshes are counted too (#1769). An
    unreadable ledger is left alone rather than replaced with one run."""
    from datetime import datetime, timezone
    from graphify.paths import write_json_atomic

    cost_path = graphify_out / "cost.json"
    cost = {"runs": [], "total_input_tokens": 0, "total_output_tokens": 0}
    if cost_path.exists():
        try:
            cost = json.loads(cost_path.read_text(encoding="utf-8"))
            cost.setdefault("runs", [])
            cost.setdefault("total_input_tokens", 0)
            cost.setdefault("total_output_tokens", 0)
            if not isinstance(cost["runs"], list) or not all(
                type(cost[k]) is int for k in ("total_input_tokens", "total_output_tokens")
            ):
                raise ValueError("unexpected layout")
        except (OSError, ValueError, AttributeError) as exc:
            print(f"[graphify extract] warning: could not read {cost_path}, not updating it: {exc}", file=sys.stderr)
            return
    cost["runs"].append({
        "date": datetime.now(timezone.utc).isoformat(),
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "files": files,
    })
    cost["total_input_tokens"] += input_tokens
    cost["total_output_tokens"] += output_tokens
    try:
        write_json_atomic(cost_path, cost, indent=2, ensure_ascii=False)
    except OSError as exc:
        print(f"[graphify extract] warning: could not write {cost_path}: {exc}", file=sys.stderr)

def _reenter_main() -> None:
    from graphify.__main__ import main
    main()

def _rel_to_root(file_path: str, root: "Path") -> "str | None":
    """The read target as a root-relative POSIX path, the form graph.json stores."""
    if not file_path:
        return None
    try:
        p = Path(file_path.replace("\\", "/"))
        return (p if p.is_absolute() else root / p).resolve().relative_to(root).as_posix()
    except (ValueError, OSError, RuntimeError):
        return None

def _search_hint_terms(t: dict) -> list[str]:
    """Words the agent searched for: the Grep `pattern`, or the pattern argument of
    a shell content search. Empty when there is nothing to go on."""
    cmd = str(t.get("command") or "")
    if not cmd:
        return _pattern_terms(str(t.get("pattern") or ""))
    import shlex
    try:
        tokens = shlex.split(cmd)
    except ValueError:
        return []
    for i, tok in enumerate(tokens):
        name = tok.replace("\\", "/").rsplit("/", 1)[-1].lower().removesuffix(".exe")
        # Content searches only: find/fd match file names, which labels do not, and
        # a search fed by a pipe filters that output, not the code.
        if name not in _SEARCH_COMMANDS or name in ("find", "fd") or (i and tokens[i - 1] == "|"):
            continue
        rest = iter(tokens[i + 1:])
        for arg in rest:
            if arg in ("-e", "--regexp"):
                return _pattern_terms(next(rest, ""))
            if arg in _HINT_VALUE_FLAGS:
                next(rest, None)
                continue
            if arg.startswith("-"):
                continue
            return _pattern_terms(arg)  # the first positional argument is the pattern
        return []
    return []

def _target_is_indexed(file_path: str, root: "Path") -> bool:
    """Guard the strict deny: only block a read of a file the graph actually indexes.
    Reads manifest.json (cheap, capped); on any doubt (missing/corrupt/oversized
    manifest, unresolvable path) returns True so the once-per-session deny still
    applies — that block is self-limiting, so erring toward it is safe."""
    from graphify.paths import out_path
    if not file_path:
        return True
    try:
        mp = out_path("manifest.json")
        st = mp.stat()
        if st.st_size > 2_000_000:
            return True
        manifest = json.loads(mp.read_text(encoding="utf-8"))
        if not isinstance(manifest, dict) or not manifest:
            return True
        p = Path(file_path)
        rels = set()
        try:
            rels.add(p.resolve().relative_to(root).as_posix())
        except (ValueError, OSError, RuntimeError):
            pass
        rels.add(p.name)
        keys = {str(k).replace("\\", "/") for k in manifest}
        abskey = str(p).replace("\\", "/")
        return abskey in keys or any(r and (r in keys or any(k.endswith("/" + r) or k == r for k in keys)) for r in rels)
    except Exception:
        return True

def _touch_query_stamp(graph_path: "Path") -> None:
    """Record that graphify oriented the agent recently, next to the queried graph.
    The strict guard suppresses its block while this stamp is fresh. Fail-silent."""
    try:
        from graphify.paths import write_text_atomic
        stamp = Path(graph_path).parent / "cache" / "last_query_stamp"
        stamp.parent.mkdir(parents=True, exist_ok=True)
        write_text_atomic(stamp, str(time.time()))
    except Exception:
        pass

def _zero_node_stamped_code_sources(
    graph_path: Path,
    scan_root: Path,
    unchanged_code: list[str],
    manifest_path: Path | None = None,
) -> list[str]:
    """Manifest-stamped code files with a registered extractor but ZERO nodes
    in the existing graph.json (#2543 heal).

    The failed-source unstamping only covers failures that happen AFTER it
    shipped; a manifest poisoned by an earlier run (extraction failed, hashes
    stamped anyway) keeps reporting the file unchanged forever, and the only
    documented recovery was deleting graphify-out/. A stamped file that the
    graph has no nodes for, despite an extractor being wired up for it, is
    exactly that state — re-queue it as changed. Bounded by the same no-wedge
    property: if it fails again this run it is now left unstamped, and if it
    succeeds its nodes enter graph.json so the next scan stops re-queuing it.

    A file the extractor declines by design (data JSON, #2879) is a legitimate
    stamped-but-zero-node row, not a poisoned one. Its manifest row carries
    ``ast_empty: true``; skip those here or the heal re-queues them on every
    incremental forever. A pre-#2879 manifest lacks the marker, so such a file
    is re-queued once more, then stamped with it and left alone thereafter.

    Membership mirrors the ``source_file`` spellings extracts store (#1897/
    #1941: scan-root-relative, forward slash; absolute for out-of-root) and
    compares NFC-normalized (#2210/#2221).
    """
    if not unchanged_code:
        return []
    from graphify.paths import nfc
    ast_empty: set[str] = set()
    if manifest_path is not None:
        from graphify.detect import load_manifest
        for _k, _v in load_manifest(str(manifest_path), root=scan_root).items():
            if isinstance(_v, dict) and _v.get("ast_empty"):
                ast_empty.add(nfc(_k))
    try:
        data = json.loads(graph_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    if not isinstance(data, dict):
        return []
    try:
        root_res = scan_root.resolve()
    except (OSError, RuntimeError):
        root_res = scan_root
    # <out>/graphify-out/graph.json — legacy relative source_files may be
    # anchored here instead of the scan root (<=0.9.16, #555/#1899).
    out_base = graph_path.parent.parent
    try:
        out_base = out_base.resolve()
    except (OSError, RuntimeError):
        pass

    present: set[str] = set()
    for n in data.get("nodes", []):
        if not isinstance(n, dict):
            continue
        sf = n.get("source_file")
        if not sf or not isinstance(sf, str):
            continue
        present.add(nfc(sf))
        p = Path(sf)
        if p.is_absolute():
            try:
                present.add(nfc(str(p.resolve())))
            except (OSError, RuntimeError):
                pass
        else:
            rel = sf.replace("\\", "/")
            for base in (root_res, out_base):
                present.add(nfc(os.path.normpath(str(base / rel))))

    from graphify.extract import _get_extractor
    healed: list[str] = []
    for f in unchanged_code:
        p = Path(f)
        if _get_extractor(p) is None:
            continue  # no extractor: absence from the graph is expected
        spellings = {nfc(str(p))}
        try:
            spellings.add(nfc(str(p.resolve())))
        except (OSError, RuntimeError):
            pass
        try:
            spellings.add(nfc(p.resolve().relative_to(root_res).as_posix()))
        except (ValueError, OSError, RuntimeError):
            pass
        if spellings & present:
            continue  # the graph has this file: stamp is honest
        if spellings & ast_empty:
            continue  # declined by design (#2879): zero nodes is intended
        healed.append(f)
    return healed

def _zero_node_stamped_semantic_sources(
    graph_path: Path,
    scan_root: Path,
    unchanged_semantic: list[str],
) -> list[str]:
    """Manifest-stamped semantic files (doc/paper/image) with ZERO nodes
    and ZERO hyperedges in the existing graph.json (#2927 heal).

    A manifest poisoned before #2927 (edge-only result cached and stamped)
    keeps reporting the file unchanged forever, freezing it out of the graph.
    Re-queue any unchanged semantic file that has neither nodes nor hyperedges
    in graph.json. If it succeeds, its nodes enter graph.json; if it produces
    no nodes or fails, it is now left unstamped, so this cannot wedge.

    Membership mirrors the ``source_file`` spellings extracts store (#1897/
    #1941: scan-root-relative, forward slash; absolute for out-of-root) and
    compares NFC-normalized (#2210/#2221).
    """
    if not unchanged_semantic:
        return []
    from graphify.paths import nfc
    try:
        data = json.loads(graph_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    if not isinstance(data, dict):
        return []
    try:
        root_res = scan_root.resolve()
    except (OSError, RuntimeError):
        root_res = scan_root
    out_base = graph_path.parent.parent
    try:
        out_base = out_base.resolve()
    except (OSError, RuntimeError):
        pass

    present: set[str] = set()
    for n in data.get("nodes", []):
        if not isinstance(n, dict):
            continue
        sf = n.get("source_file")
        if not sf or not isinstance(sf, str):
            continue
        present.add(nfc(sf))
        p = Path(sf)
        if p.is_absolute():
            try:
                present.add(nfc(str(p.resolve())))
            except (OSError, RuntimeError):
                pass
        else:
            rel = sf.replace("\\", "/")
            for base in (root_res, out_base):
                present.add(nfc(os.path.normpath(str(base / rel))))

    hyper_items = list(data.get("hyperedges", []) or [])
    if isinstance((data.get("graph") or {}).get("hyperedges"), list):
        hyper_items.extend(data["graph"]["hyperedges"])
    for h in hyper_items:
        if not isinstance(h, dict):
            continue
        sf = h.get("source_file")
        if not sf or not isinstance(sf, str):
            continue
        present.add(nfc(sf))
        p = Path(sf)
        if p.is_absolute():
            try:
                present.add(nfc(str(p.resolve())))
            except (OSError, RuntimeError):
                pass
        else:
            rel = sf.replace("\\", "/")
            for base in (root_res, out_base):
                present.add(nfc(os.path.normpath(str(base / rel))))

    healed: list[str] = []
    for f in unchanged_semantic:
        p = Path(f)
        spellings = {nfc(str(p))}
        try:
            spellings.add(nfc(str(p.resolve())))
        except (OSError, RuntimeError):
            pass
        try:
            spellings.add(nfc(p.resolve().relative_to(root_res).as_posix()))
        except (ValueError, OSError, RuntimeError):
            pass
        if spellings & present:
            continue  # the graph has nodes or hyperedges for this file: stamp is honest
        healed.append(f)
    return healed

def _split_community(G: nx.Graph, nodes: list[str]) -> list[list[str]]:
    """Run a second Leiden pass on a community subgraph to split it further."""
    subgraph = G.subgraph(nodes)
    if subgraph.number_of_edges() == 0:
        # No edges - split into individual nodes
        return [[n] for n in sorted(nodes)]
    try:
        sub_partition = _partition(subgraph)
        sub_communities: dict[int, list[str]] = {}
        for node, cid in sub_partition.items():
            sub_communities.setdefault(cid, []).append(node)
        if len(sub_communities) <= 1:
            return [sorted(nodes)]
        return [sorted(v) for v in sub_communities.values()]
    except Exception:
        return [sorted(nodes)]

def label_still_applies(
    cid: int,
    current_members: list[str],
    previous_node_community: dict[str, int],
    saved_sig: str | None,
    current_sig: str | None,
) -> bool:
    """Whether a saved label still names this community (#2298).

    An equal membership signature keeps the label. Otherwise the label stays
    only when the nodes shared with the previous assignment are a strict
    majority of both the previous set and the current set. A one-node fragment
    of a large community fails that test, so remap reusing the old id is not
    enough to keep the name.
    """
    if saved_sig is not None and current_sig is not None and saved_sig == current_sig:
        return True
    saved = {str(node) for node, old in previous_node_community.items() if old == cid}
    current = {str(node) for node in current_members}
    if not saved or not current:
        return False
    overlap = len(saved & current)
    return overlap * 2 > len(saved) and overlap * 2 > len(current)

def remap_communities_to_previous(
    communities: dict[int, list[str]],
    previous_node_community: dict[str, int],
) -> dict[int, list[str]]:
    """Remap community IDs to maximize overlap with a previous assignment.

    Uses greedy one-to-one matching by intersection size, then assigns fresh IDs
    to unmatched communities in deterministic order (size desc, lexical tie-break).
    """
    if not communities:
        return {}

    new_sets = {cid: set(nodes) for cid, nodes in communities.items()}
    old_sets: dict[int, set[str]] = {}
    for node, old_cid in previous_node_community.items():
        old_sets.setdefault(old_cid, set()).add(node)

    overlaps: list[tuple[int, int, int]] = []
    for old_cid, old_nodes in old_sets.items():
        for new_cid, new_nodes in new_sets.items():
            overlap = len(old_nodes & new_nodes)
            if overlap > 0:
                overlaps.append((overlap, old_cid, new_cid))
    overlaps.sort(key=lambda x: (-x[0], x[1], x[2]))

    new_to_final: dict[int, int] = {}
    used_old_ids: set[int] = set()
    matched_new_ids: set[int] = set()
    for _overlap, old_cid, new_cid in overlaps:
        if old_cid in used_old_ids or new_cid in matched_new_ids:
            continue
        new_to_final[new_cid] = old_cid
        used_old_ids.add(old_cid)
        matched_new_ids.add(new_cid)

    unmatched = [cid for cid in communities if cid not in matched_new_ids]
    unmatched.sort(key=lambda cid: (-len(communities[cid]), tuple(sorted(communities[cid]))))
    next_id = 0
    for new_cid in unmatched:
        while next_id in used_old_ids:
            next_id += 1
        new_to_final[new_cid] = next_id
        used_old_ids.add(next_id)
        next_id += 1

    remapped: dict[int, list[str]] = {}
    for new_cid, nodes in communities.items():
        remapped[new_to_final[new_cid]] = sorted(nodes)
    return dict(sorted(remapped.items(), key=lambda kv: kv[0]))

def _index_declarations(merged: "nx.Graph") -> tuple[dict[str, list[str]], set[str]]:
    """Index sourced type declarations by bare name. Returns (index, id set)."""
    by_name: dict[str, list[str]] = defaultdict(list)
    type_ids: set[str] = set()
    for node, data in merged.nodes(data=True):
        if not data.get("_callable_class") or not data.get("source_file"):
            continue
        if not data.get("repo"):
            continue
        name = _key(data.get("label"))
        if not name:
            continue
        by_name[name].append(node)
        type_ids.add(node)
    return by_name, type_ids

def _index_members(
    merged: "nx.Graph", type_ids: set[str]
) -> dict[str, dict[tuple[str, str], list[str]]]:
    """Index each declaration's members by relation, then by name.

    The merged graph is undirected, and a ``method`` edge carries no reliable
    direction once composed, so the owner is identified as the endpoint that is a
    type declaration. A nested declaration puts a type on both ends; that pair is
    skipped rather than guessed at.

    Kept per relation rather than pooled: ``defines`` covers fields as well as
    C++'s in-class member declarations, so only a language that needs it may look
    there, and only when no ``method`` of that name exists.
    """
    by_relation: dict[str, dict[tuple[str, str], list[str]]] = {
        relation: defaultdict(list) for relation in _MEMBER_RELATIONS
    }
    for u, v, data in merged.edges(data=True):
        relation = data.get("relation")
        if relation not in by_relation:
            continue
        if u in type_ids and v not in type_ids:
            owner, member = u, v
        elif v in type_ids and u not in type_ids:
            owner, member = v, u
        else:
            continue
        name = _key(merged.nodes[member].get("label"))
        if name:
            by_relation[relation][(owner, name)].append(member)
    return by_relation

def _member_keys(lang: str, callee: str) -> tuple[str, ...]:
    """Which member-index keys a parked callee may answer to.

    An ObjC selector carries no class/instance distinction, so both sigils are
    tried; a type declaring `+greet` and `-greet` both is an ambiguity, not a hit.
    A selector cannot itself begin with a sigil, so stripping one first keeps an
    entry that already carries it from asking for `--greet`.
    """
    if lang == "objc":
        selector = callee.lstrip("+-")
        return (f"-{selector}", f"+{selector}")
    return (callee,)

def _parked_entries(data: dict) -> list[dict]:
    metadata = data.get("metadata")
    if not isinstance(metadata, dict):
        return []
    parked = metadata.get(UNRESOLVED_CALLS_KEY)
    if not isinstance(parked, list):
        return []
    return [entry for entry in parked if isinstance(entry, dict)]

def link_shared_type_declarations(merged: "nx.Graph") -> int:
    """Link identically declared types across repos. Returns the edge count added.

    A candidate node is a sourced type declaration carrying a namespace and a
    repo tag. A group qualifies when its members span at least two repos, and
    every pair inside a qualifying group gets one edge. Groups are the handful of
    types two repos genuinely share, so the pairwise walk stays small.
    """
    by_declaration: dict[tuple[str, str], list[str]] = defaultdict(list)
    for node, data in merged.nodes(data=True):
        if not data.get("_callable_class") or not data.get("source_file"):
            continue
        namespace = str((data.get("metadata") or {}).get("namespace") or "")
        label = str(data.get("label") or "")
        if not namespace or not label or not data.get("repo"):
            continue
        by_declaration[(namespace, label)].append(node)

    added = 0
    for (namespace, label), nodes in by_declaration.items():
        if len(nodes) < 2:
            continue
        if len({merged.nodes[n].get("repo") for n in nodes}) < 2:
            continue
        for index, left in enumerate(nodes):
            for right in nodes[index + 1:]:
                if merged.nodes[left].get("repo") == merged.nodes[right].get("repo"):
                    continue
                if merged.has_edge(left, right):
                    continue
                merged.add_edge(
                    left,
                    right,
                    relation=SHARED_TYPE_RELATION,
                    context="cross_repo",
                    confidence="INFERRED",
                    confidence_score=0.85,
                    source_file=str(merged.nodes[left].get("source_file") or ""),
                    weight=1.0,
                    _src=left,
                    _tgt=right,
                )
                added += 1
    return added

def _content_richness(n: dict) -> int:
    """How much actual content a node carries, for survivor selection (#3372).

    Counts populated fields beyond the identity/placement baseline, weighting
    ``attributes`` by entry count and ``_merged_from`` by its history length —
    a node that already absorbed prior merges is the established record.
    """
    score = 0
    for key, value in n.items():
        if key in _RICHNESS_IGNORED_KEYS:
            continue
        if value is None or value == "" or value == [] or value == {}:
            continue
        score += 1
        if key == "attributes" and isinstance(value, dict):
            score += len(value)
        elif key == "_merged_from" and isinstance(value, list):
            score += len(value)
    return score

def _full_stem(source_file: str) -> str:
    """The extension-stripped, slugified full-path stem a file's own IDs start with."""
    stem = _EXTENSION.sub("", source_file.replace("\\", "/"))
    return "_".join(s for s in (normalize_id(p) for p in stem.split("/")) if s)

def _is_variant_pair(a: str, b: str) -> bool:
    """True if a and b are sibling model/SKU variants (same stem, different suffix).

    Only applied to short labels (< 12 chars); long labels go through JW normally.
    """
    if a == b:
        return False
    if max(len(a), len(b)) >= 12:
        return False
    ma, mb = _VARIANT_SUFFIX.match(a), _VARIANT_SUFFIX.match(b)
    if not (ma and mb):
        return False
    return ma.group(1) == mb.group(1) and ma.group(2) != mb.group(2)

def _norm(label: str | None) -> str:
    """Lowercase + collapse non-word runs to space (Unicode-aware).

    Combining marks stay part of the word (see ``_is_label_char``); punctuation,
    underscores and whitespace collapse to a single space as before. Known gap:
    ZWJ/ZWNJ (category Cf) still count as separators.
    """
    if not isinstance(label, str):
        label = "" if label is None else str(label)
    label = unicodedata.normalize("NFKC", label).casefold()
    out: list[str] = []
    pending_sep = False
    for ch in label:
        if _is_label_char(ch):
            if pending_sep and out:
                out.append(" ")
            pending_sep = False
            out.append(ch)
        else:
            pending_sep = True
    return "".join(out)

def _entropy(label: str) -> float:
    """Shannon entropy in bits/char of the normalised label."""
    s = _norm(label)
    if not s:
        return 0.0
    freq: dict[str, int] = defaultdict(int)
    for ch in s:
        freq[ch] += 1
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in freq.values())

def _rank_path(source_file: str, root: Path | None) -> str:
    """The root-relative form of ``source_file`` used for collision ranking.

    With a scan root, an absolute stored path and its repo-relative twin rank
    identically, and the checkout location's own segments never participate
    (#2532). A relative stored path is already root-relative and is used as-is;
    unlike ``_source_key`` in extractors/resolution.py, it is not resolved
    against the CWD, so a run from a subdirectory of the root keys it the same
    (#4281). Without a root (or when relativizing fails) the normalized stored
    path is used as-is.
    """
    normalized = source_file.replace("\\", "/")
    if root is not None and normalized and Path(normalized).is_absolute():
        try:
            return Path(normalized).resolve().relative_to(root).as_posix()
        except Exception:
            pass
    return normalized

def _remap_hyperedge_members(hyperedges: list[dict], remap: dict[str, str]) -> None:
    """Rewire hyperedge member ids onto dedup survivors, in place.

    Members come in both shapes the rest of the codebase tolerates — a bare id
    string, or an object carrying one — so both are handled;
    ``_normalize_hyperedge_members`` fixes the SHAPE but never resolves a member
    against surviving node ids, which is why this is needed as well.

    Two members that remap onto the same survivor collapse to one entry. That
    shrinks the group, but honestly: they were the same entity, and the previous
    behaviour dropped the loser without promoting it, which shrank the group
    *and* lost the participant. Order is preserved so a rebuilt graph does not
    churn.
    """
    for he in hyperedges:
        if not isinstance(he, dict):
            continue
        members = he.get("nodes")
        if not isinstance(members, list):
            continue
        seen: set = set()
        rewired: list = []
        for m in members:
            if isinstance(m, str):
                new_id = remap.get(m, m)
                entry = new_id
            elif isinstance(m, dict):
                raw = m.get("id")
                new_id = remap.get(raw, raw) if isinstance(raw, str) else raw
                entry = dict(m, id=new_id) if new_id != raw else m
            else:
                new_id, entry = None, m
            if isinstance(new_id, str):
                if new_id in seen:
                    continue
                seen.add(new_id)
            rewired.append(entry)
        he["nodes"] = rewired

def _shingles(text: str, k: int = 3) -> set[str]:
    """Return k-gram character shingles of text."""
    if len(text) < k:
        return {text}
    return {text[i : i + k] for i in range(len(text) - k + 1)}

def _make_minhash(text: str, num_perm: int = 128) -> MinHash:
    # Strip spaces so "graph extractor" and "graphextractor" share shingles
    m = MinHash(num_perm=num_perm)
    for shingle in _shingles(text.replace(" ", "")):
        m.update(shingle.encode("utf-8"))
    return m

def _slice_references(nodes: list[dict], root: Path | None) -> set[tuple[str, str]]:
    """``(id, file)`` of nodes whose id is a SHORTER path slice of a file that has its
    own page (#4281). They rank as references, like a ``_mentions`` entry."""
    own_page = _own_page_files(nodes, root)
    found: set[tuple[str, str]] = set()
    for node in nodes:
        nid, sf = node.get("id"), node.get("source_file")
        if not nid or not isinstance(nid, str) or not sf or not isinstance(sf, str):
            continue
        k = _rank_path(sf, root)
        if k in own_page and nid in _id_prefixes(k) and nid != _full_stem(k):
            found.add((nid, k))
    return found

def _auto_follow_symlinks(root: Path) -> bool:
    """Return whether ``root`` has any direct symlinked child.

    Kept for callers that import the private helper, but detection no longer
    enables symlink following automatically. Following symlinks is now an
    explicit opt-in, and out-of-root symlink targets are never indexed.
    """
    try:
        for p in root.iterdir():
            if p.is_symlink():
                return True
    except (OSError, PermissionError):
        pass
    return False

def _docx_children(parent, tag: str):
    for child in parent:
        if child.tag == f"{_W}{tag}":
            yield child
        elif child.tag in _DOCX_WRAPPERS:
            content = child.find(f"{_W}sdtContent")
            yield from _docx_children(child if content is None else content, tag)

def _docx_inside(element, stop, tags) -> bool:
    node = element.getparent()
    while node is not None and node is not stop:
        if node.tag in tags:
            return True
        node = node.getparent()
    return False

def _docx_blocks(container):
    """Yield the w:p and w:tbl elements of a container in document order, looking through
    content controls and custom XML, with each text box's content after its paragraph."""
    for child in container:
        if child.tag == f"{_W}p":
            yield child
            for box in child.iter(f"{_W}txbxContent"):
                if not _docx_inside(box, child, _DOCX_SKIPPED):
                    yield from _docx_blocks(box)
        elif child.tag == f"{_W}tbl":
            yield child
        elif child.tag in _DOCX_WRAPPERS:
            content = child.find(f"{_W}sdtContent")
            yield from _docx_blocks(child if content is None else content)

def _docx_paragraph_text(p) -> str:
    """Paragraph.text reads only the runs directly under the paragraph, so it drops tracked
    insertions, content controls, simple fields and smart tags."""
    return "".join(
        str(element)
        for element in p.iter(*_DOCX_RUN_TEXT)
        if not _docx_inside(element, p, _DOCX_SKIPPED)
    )

def _docx_cell_markdown(tc) -> str:
    """A cell's text on one line with pipes escaped, so it cannot break its table row."""
    parts = []
    for block in _docx_blocks(tc):
        if block.tag == f"{_W}p":
            parts.append(_docx_paragraph_text(block))
        else:  # a nested table, flattened into the cell
            parts.extend(
                _docx_cell_markdown(cell)
                for row in _docx_children(block, "tr")
                for cell in _docx_children(row, "tc")
            )
    return " ".join(" ".join(part.split()) for part in parts if part.strip()).replace("|", "\\|")

def _file_within_size_cap(path: Path, cap: int = _OFFICE_MAX_RAW_BYTES) -> bool:
    """True if *path* exists and its on-disk size is within *cap*."""
    try:
        return path.stat().st_size <= cap
    except OSError:
        return False

def _git_info_exclude(vcs_root: Path) -> Path | None:
    """Resolve ``$GIT_DIR/info/exclude`` for the repo rooted at ``vcs_root``.

    ``info/exclude`` is where git records local-only, uncommitted excludes — and
    where ``git worktree add`` writes nested worktree paths — so a repo can ignore
    a directory without any ``.gitignore`` entry. graphify only read
    ``.gitignore``/``.graphifyignore``, so it walked into those worktree copies and
    the graph exploded (#1810). Handles the linked-worktree/submodule case where
    ``.git`` is a file (``gitdir: <path>``) and the real excludes live in the
    shared common git dir. Returns None when there is no readable exclude file.
    """
    dot_git = vcs_root / ".git"
    git_dir: Path | None = None
    if dot_git.is_dir():
        git_dir = dot_git
    elif dot_git.is_file():
        try:
            content = dot_git.read_text(encoding="utf-8", errors="ignore").strip()
        except OSError:
            content = ""
        if content.startswith("gitdir:"):
            gd = Path(content[len("gitdir:"):].strip())
            if not gd.is_absolute():
                gd = (vcs_root / gd).resolve()
            git_dir = gd
            # A linked worktree's gitdir holds a `commondir` file pointing at the
            # shared git dir, where info/exclude actually lives.
            commondir = gd / "commondir"
            if commondir.exists():
                try:
                    cd_raw = commondir.read_text(encoding="utf-8", errors="ignore").strip()
                except OSError:
                    cd_raw = ""
                if cd_raw:
                    cd = Path(cd_raw)
                    git_dir = cd if cd.is_absolute() else (gd / cd).resolve()
    if git_dir is None:
        return None
    exclude = git_dir / "info" / "exclude"
    return exclude if exclude.is_file() else None

def _has_coverage_artifacts(d: "Path") -> bool:
    """True only when *d* holds files a coverage tool actually generated.

    ``coverage`` is a legitimate package name (a Python package, a Go/Rust module,
    a domain namespace), so pruning it by name alone silently drops real source —
    an entire 5-module package in #2339, with its dependents left in the graph so
    queries still returned plausible neighbours. Prune it only on real evidence,
    mirroring the ``snapshots``/``env`` gating (#1666/#2058): a coverage report
    file, or an Istanbul/lcov HTML report subtree.
    """
    try:
        for name in _COVERAGE_ARTIFACT_FILES:
            if (d / name).is_file():
                return True
        for name in _COVERAGE_ARTIFACT_DIRS:
            if (d / name).is_dir():
                return True
    except OSError:
        pass
    return False

def _has_venv_markers(d: "Path") -> bool:
    """True only when *d* has actual virtualenv/conda structure on disk.

    ``env``/``.env``/``*_env`` is a real source-directory convention (UVM/ASIC
    verification trees, and others), so pruning it by name alone silently drops
    legitimate source with no trace (#2058). Prune it only on real evidence: a
    ``pyvenv.cfg``, an ``activate`` script, a ``lib/python*`` tree, or conda's
    ``conda-meta/`` (``conda create -p ./env`` writes no pyvenv.cfg).
    """
    try:
        if (d / "pyvenv.cfg").is_file():
            return True
        if (d / "bin" / "activate").is_file() or (d / "Scripts" / "activate").is_file():
            return True
        if next(d.glob("lib/python*"), None) is not None:
            return True
        if (d / "conda-meta").is_dir():
            return True
    except OSError:
        pass
    return False

def _is_env_template(name: str) -> bool:
    """True for `.env.example` / `.envrc.sample` style committed templates (#2184)."""
    lower = name.lower()
    if not lower.endswith(_ENV_TEMPLATE_SUFFIXES):
        return False
    # Basename must still be an .env* / .envrc* file (not e.g. secrets.example).
    return bool(re.match(r"\.(env|envrc)\.", lower))

def _is_installed_graphify_file(path: "Path") -> bool:
    """True for a single file `graphify install` wrote into the project (#4057)."""
    return path.parts[-3:] in _GRAPHIFY_INSTALLED_FILES

def _is_noise_dir(part: str, parent: "Path | None" = None) -> bool:
    """Return True if this directory name looks like a venv, cache, or dep dir."""
    if part in _SKIP_DIRS:
        return True
    if part in ("env", ".env") or part.endswith("_env"):
        # Ambiguous: a real venv OR a real source dir. Prune only on actual venv
        # evidence, mirroring the "snapshots" gating (#1666/#2058).
        if parent is None:
            return False  # cannot verify; keep a possibly-real code dir
        return _has_venv_markers(parent / part)
    if part == "coverage":
        # Ambiguous: a generated report dir OR a real package named coverage.
        # Prune only on actual coverage-artefact evidence (#2339).
        if parent is None:
            return False  # cannot verify; keep a possibly-real code dir
        return _has_coverage_artifacts(parent / part)
    if part == "out":
        # Ambiguous: compiler/bundler output (IntelliJ, `next export`, a TS
        # outDir) OR the outbound layer of a hexagonal codebase
        # (adapter/out/, port/out/). Prune only on actual build-output
        # evidence (#3347).
        if parent is None:
            return False  # cannot verify; keep a possibly-real code dir
        return _has_build_output_markers(parent / part)
    if part in ("obj", "bin"):
        # Ambiguous: MSBuild intermediate/output dirs OR real source (Rust's
        # src/bin/, script dirs). Depths reach a legacy obj/<config>/ and a
        # RID-specific bin/<config>/<tfm>/<rid>/.
        if parent is None:
            return False  # cannot verify; keep a possibly-real code dir
        if part == "obj":
            return _has_msbuild_markers(parent / part, _MSBUILD_OBJ_MARKERS, 1)
        return _has_msbuild_markers(parent / part, _MSBUILD_BIN_MARKERS, 3)
    if part == "snapshots":
        # Prune only when it looks like an actual JS/Vitest snapshot dir.
        if parent is None:
            return False  # cannot verify; keep a possibly-real code dir
        snap_dir = parent / part
        if parent.name in _JS_SNAPSHOT_TEST_ROOTS:
            return True
        try:
            if next(snap_dir.glob("*.snap"), None) is not None:
                return True
        except OSError:
            pass
        return False
    # Catch *_venv (unambiguous — "venv" is always a virtualenv signal). "*_env"
    # is gated on markers above (#2058), not pruned by name.
    if part.endswith("_venv"):
        return True
    if part.endswith(".egg-info"):
        return True
    # worktrees/ nested inside a dotted dir (e.g. .claude/worktrees/, .git/worktrees/)
    if part == "worktrees" and parent is not None and parent.name.startswith("."):
        return True
    # graphify's own skill folder, as `graphify install --project` writes it
    # (#4057): <hidden dir>/skills/graphify/ (.claude, .codex, .agents, ...),
    # .pi/agent/skills/graphify/, .config/kilo/skills/graphify/ and
    # .aider/graphify/. Matched on the whole path shape rather than the bare
    # names "skills"/"graphify" (#2479), so graphify's own source tree
    # (graphify/skills/<host>/), a top-level skills/graphify/ and the user's
    # other skills under .claude/skills/ are still indexed.
    if part == "graphify" and parent is not None:
        if parent.name == ".aider":
            return True
        if parent.name == "skills":
            holder = parent.parent
            if holder.name.startswith(".") and holder.name != "..":
                return True
            return (holder.parent.name, holder.name) in _NESTED_SKILL_HOLDERS
    return False

def _is_prose_note(path: Path) -> bool:
    """A prose/note file (.md/.rst/...) whose stem is a multi-word topic slug is
    exempt from the generic-keyword drop (#2106). A stem that IS exactly a bare
    keyword (secrets / token / passwords) is NOT exempt — that still reads as a
    credential dump. The one exception is bare plural "tokens" (TOKENS.md),
    which reads as a design-token reference doc rather than a secret store
    (#3527)."""
    if path.suffix.lower() not in _PROSE_EXTS:
        return False
    stem = Path(path.name).stem.lstrip('.') or Path(path.name).stem
    if _BARE_PLURAL_TOKENS.fullmatch(stem):
        return True
    return not any(p.fullmatch(stem) for p in _GENERIC_KEYWORD_PATTERNS)

def _is_regular_file(path: Path) -> bool:
    """True only for regular files (symlinks followed).

    Named pipes, sockets and device nodes must never reach a reader:
    ``open()`` on a FIFO with no writer blocks forever and never raises, so a
    single ``pipe.py`` in a scanned repository hangs the run with no output.
    A symlink is resolved deliberately — a link pointing at a FIFO blocks
    exactly like the FIFO itself. A path that cannot be stat'ed is treated as
    not readable rather than raising.
    """
    try:
        return stat.S_ISREG(os.stat(path).st_mode)
    except OSError:
        return False

def _is_valid_git_marker(dot_git: Path) -> bool:
    """Whether ``dot_git`` is a ``.git`` that git itself would accept (#4444).

    A ``.git`` directory needs ``HEAD``, ``objects/`` and ``refs/``, the same
    entries git's own repository check looks for. A ``.git`` file (linked
    worktree, submodule) must start with ``gitdir:``. An empty or partial
    ``.git`` directory, e.g. one left in a home directory, is not a repo and
    must not become the ignore-walk ceiling. No git subprocess is used.
    """
    try:
        if dot_git.is_dir():
            return (dot_git / "HEAD").is_file() and (dot_git / "objects").is_dir() and (dot_git / "refs").is_dir()
        if dot_git.is_file():
            with dot_git.open("rb") as fh:
                return fh.read(7) == b"gitdir:"
    except OSError:
        pass
    return False

def _has_vcs_marker(directory: Path) -> bool:
    for marker in _VCS_MARKERS:
        path = directory / marker
        if marker == ".git":
            if _is_valid_git_marker(path):
                return True
        elif path.exists():
            return True
    return False

def _find_vcs_root(start: Path) -> Path | None:
    """Walk upward from start; return the first directory containing a VCS marker.

    ``.git`` only counts when it is a valid repo marker (#4444).
    """
    current = start.resolve()
    home = Path.home()
    while True:
        if _has_vcs_marker(current):
            return current
        parent = current.parent
        if parent == current or current == home:
            return None
        current = parent

def _looks_like_paper(path: Path) -> bool:
    """Heuristic: does this text file read like an academic paper?"""
    try:
        # Only scan first 3000 chars for speed
        text = path.read_text(encoding="utf-8", errors="ignore")[:3000]
        hits = sum(1 for pattern in _PAPER_SIGNALS if pattern.search(text))
        return hits >= _PAPER_SIGNAL_THRESHOLD
    except Exception:
        return False

def _manifest_storage_anchor(manifest_path: str | Path | None, root: Path | None) -> Path | None:
    """When a manifest lives under <repo>/graphify-out/manifest.json and root
    is a subfolder of <repo>, stored relative keys are anchored to <repo> (#3785)."""
    if root is None or not manifest_path:
        return root
    try:
        mp = Path(manifest_path).resolve()
        if mp.parent.name in ("graphify-out", GRAPHIFY_OUT_NAME):
            manifest_base = mp.parent.parent
            root_resolved = Path(root).resolve()
            if root_resolved != manifest_base:
                try:
                    root_resolved.relative_to(manifest_base)
                    return manifest_base
                except ValueError:
                    pass
    except (OSError, RuntimeError):
        pass
    return root

def _match_globstar_parts(
    path_parts: tuple[str, ...],
    pattern_parts: tuple[str, ...],
    path_idx: int,
    pattern_idx: int,
    memo: dict[tuple[int, int], bool],
) -> bool:
    """Recursive ``**``-aware segment match, memoized via an explicit dict.

    Lifted out of ``_match_anchored_ignore_pattern`` (was a per-call
    ``@lru_cache`` closure): the decorated inner closure referenced itself, so
    every call leaked a reference cycle for the GC to reclaim on this hot path.
    A plain dict passed in avoids both the cycle and the per-call cache setup.
    """
    key = (path_idx, pattern_idx)
    cached = memo.get(key)
    if cached is not None:
        return cached

    if pattern_idx == len(pattern_parts):
        result = path_idx == len(path_parts)
    else:
        part = pattern_parts[pattern_idx]
        if part == "**":
            if pattern_idx == len(pattern_parts) - 1:
                result = path_idx < len(path_parts)
            else:
                result = _match_globstar_parts(
                    path_parts, pattern_parts, path_idx, pattern_idx + 1, memo
                ) or (
                    path_idx < len(path_parts)
                    and _match_globstar_parts(
                        path_parts, pattern_parts, path_idx + 1, pattern_idx, memo
                    )
                )
        else:
            result = (
                path_idx < len(path_parts)
                and fnmatch.fnmatchcase(path_parts[path_idx], part)
                and _match_globstar_parts(
                    path_parts, pattern_parts, path_idx + 1, pattern_idx + 1, memo
                )
            )
    memo[key] = result
    return result

def _match_anchored_ignore_pattern(path: str, pattern: str) -> bool:
    """Match an anchored gitignore pattern without letting ``*`` cross ``/``."""
    path_parts = tuple(path.split("/"))
    pattern_parts = tuple(pattern.split("/"))
    # Fast path: with no ``**`` the match is a straight segment-wise fnmatch of
    # equal-length paths, so skip the recursive matcher and its memo entirely.
    if "**" not in pattern_parts:
        if len(path_parts) != len(pattern_parts):
            return False
        return all(
            fnmatch.fnmatchcase(pp, qp) for pp, qp in zip(path_parts, pattern_parts)
        )
    return _match_globstar_parts(path_parts, pattern_parts, 0, 0, {})

def _md5_file(path: Path) -> str:
    """MD5 of file contents streamed in 64KB chunks — for change detection only."""
    import hashlib as _hl
    h = _hl.md5(usedforsecurity=False)
    try:
        with open(_os_path(path), "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
    except OSError:
        return ""
    return h.hexdigest()

def _checkout_prefix(abs_key: str, relative_keys: set[str]) -> str | None:
    """Longest directory prefix of ``abs_key`` whose suffix is in ``relative_keys``.

    The suffix is forward-slash and NFC. ``src/c.py`` beats a shorter ``c.py``.
    Prefixes ``""``, ``"/"``, and ``"\\"`` are skipped so a shorter suffix can
    still match. The prefix that remains must be a real directory.
    """
    parts = _nfc(abs_key).replace("\\", "/").split("/")
    best: tuple[int, str] | None = None
    for i in range(1, len(parts)):
        suffix = "/".join(parts[i:])
        if suffix not in relative_keys:
            continue
        prefix = "/".join(parts[:i])
        if prefix in ("", "/", "\\"):
            continue
        if not Path(prefix).is_dir():
            continue
        if best is None or len(suffix) > best[0]:
            best = (len(suffix), prefix)
    return None if best is None else best[1]

def _lexical_relative(
    target: Path, target_parts: tuple[str, ...], anchor: Path
) -> str | None:
    """String-space equivalent of ``_nfc(str(target.relative_to(anchor)).replace(os.sep, "/"))``.

    Returns None where ``relative_to`` raises ValueError (target not under
    anchor). ``relative_to`` is purely lexical — a parts-prefix check — so this
    performs the same comparison on the already-parsed ``parts`` tuples instead
    of constructing a Path object (and, on 3.12+, walking ``parents``
    quadratically) per pattern per scanned entry. That construction was the
    dominant cost of large scans (see CHANGELOG: 76k-file vault, 50+ min).
    """
    anchor_parts = anchor.parts
    if not anchor_parts:
        # Anchor without parts (Path(".")): defer to pathlib for its exact
        # "." / ValueError semantics. Real anchors are directories with parts,
        # so the hot path never lands here.
        try:
            return _nfc(str(target.relative_to(anchor)).replace(os.sep, "/"))
        except ValueError:
            return None
    n = len(anchor_parts)
    if len(target_parts) < n:
        return None
    head = target_parts[:n]
    if head != anchor_parts and (
        not _CASEFOLD_PATHS
        or tuple(map(os.path.normcase, head))
        != tuple(map(os.path.normcase, anchor_parts))
    ):
        return None
    tail = target_parts[n:]
    if not tail:
        return "."
    return _nfc("/".join(tail))

def _normpath_own_flavor(key: str) -> str:
    """``normpath`` an absolute ``key`` under its OWN platform's syntax.

    ``os.path.normpath`` applies the current platform's rules, so on Windows
    it rewrites a POSIX key ``/home/u/foo.py`` to ``\\home\\u\\foo.py`` —
    a string POSIX can no longer read back, since ``posixpath`` does not
    treat ``\\`` as a separator. Pick the flavor from the key itself: a
    drive letter or leading backslash is Windows, a leading ``/`` that the
    current platform does not consider absolute is POSIX.
    """
    if Path(key).is_absolute():
        return os.path.normpath(key)
    if key.startswith("\\") or _DRIVE_LETTER_RE.match(key):
        return ntpath.normpath(key)
    return posixpath.normpath(key)

def _path_identity(path: Path) -> str:
    """Portable comparison key for an existing filesystem path."""
    return _nfc(os.path.normcase(os.path.abspath(os.fspath(path))))

def _git_tracked_path_keys(root: Path) -> tuple[set[str], set[str]]:
    """Return tracked-file keys and their ancestor-directory keys under *root*.

    Gitignore rules do not apply to paths already present in Git's index. Ask
    Git once per scan/predicate construction with NUL-delimited output so every
    valid filename is preserved. Missing Git, a non-Git VCS marker, command
    failure, and malformed output all fail closed to the historical ignore
    behavior rather than making discovery fail (#2759).
    """
    root = root.resolve()
    vcs_root = _find_vcs_root(root)
    if vcs_root is None or not (vcs_root / ".git").exists():
        return set(), set()
    try:
        proc = subprocess.run(
            ["git", "-C", str(vcs_root), "ls-files", "-z", "--cached"],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=30,
            env={**os.environ, "GIT_OPTIONAL_LOCKS": "0"},
        )
    except (OSError, subprocess.SubprocessError):
        return set(), set()
    if proc.returncode != 0:
        return set(), set()

    tracked_files: set[str] = set()
    tracked_dirs: set[str] = set()
    for raw in proc.stdout.split(b"\0"):
        if not raw:
            continue
        path = Path(os.path.abspath(vcs_root / os.fsdecode(raw)))
        try:
            path.relative_to(root)
        except ValueError:
            continue
        # Deleted index entries and submodule gitlinks are not discoverable
        # files. Symlinks to regular files remain eligible; the existing
        # in-root target guard still decides whether they may enter the corpus.
        if not _is_regular_file(path):
            continue
        tracked_files.add(_path_identity(path))
        parent = path.parent
        while parent != root:
            parent_key = _path_identity(parent)
            if parent_key in tracked_dirs:
                break  # its ancestors were added with the first file below it
            tracked_dirs.add(parent_key)
            parent = parent.parent
    return tracked_files, tracked_dirs

def _resolves_under_root(path: Path, root: Path) -> bool:
    """True when ``path`` resolves to a target inside ``root``."""
    try:
        path.resolve().relative_to(root.resolve())
    except (OSError, RuntimeError, ValueError):
        return False
    return True

def _split_env_s(value: str, rest: list[str]) -> list[str]:
    """Re-tokenize an `env -S`/`--split-string` packed command, prepending the
    operand to any trailing args. Returns the unpacked argv."""
    packed = " ".join([value, *rest]).strip()
    return shlex.split(packed)

def _env_command_args(args: list[str], *, allow_split: bool = True) -> list[str]:
    """Strip leading env(1) options and var assignments, return the trailing
    command argv. Covers macOS/BSD and GNU coreutils env documented spellings.

    POSIX/macOS short forms:
        env [-0iv] [-C workdir] [-P utilpath] [-S string]
            [-u name] [name=value ...] [utility [argument ...]]

    GNU coreutils long/compact forms additionally supported:
        --argv0=ARG / -a ARG / -aARG
        --unset=NAME / --unset NAME / -u NAME / -uNAME
        --chdir=DIR / --chdir DIR / -C DIR / -CDIR
        --split-string=STRING / --split-string STRING
        -S STRING / -SSTRING / -vS STRING / -vSSTRING
        --ignore-environment / --null / --debug / --list-signal-handling
        --default-signal[=SIG] / --ignore-signal[=SIG] / --block-signal[=SIG]

    `-S` / `--split-string` payloads are themselves env-style argument lists
    per the GNU shebang synopsis:
        #!/usr/bin/env -[v]S[option]... [name=value]... command [args]...
    so after splitting the payload we recursively re-parse it with
    `allow_split=False` (a nested -S inside a split payload is rejected to
    bound recursion).

    Unknown hyphen-prefixed args yield [] (we refuse to guess whether
    their next token is an interpreter or an operand).
    """
    i = 0
    while i < len(args):
        arg = args[i]

        if arg == "--":
            return args[i + 1:]

        # Split-string forms: tokenize the packed payload, then re-parse it
        # as env args (so leading assignments/flags inside the payload are
        # skipped before the interpreter is identified).
        if allow_split:
            if arg == "-S":
                if i + 1 >= len(args):
                    return []
                return _env_command_args(
                    _split_env_s(" ".join(args[i + 1:]), []),
                    allow_split=False,
                )
            if arg.startswith("-S") and len(arg) > 2:
                return _env_command_args(
                    _split_env_s(arg[2:], args[i + 1:]),
                    allow_split=False,
                )
            if arg == "-vS":
                if i + 1 >= len(args):
                    return []
                return _env_command_args(
                    _split_env_s(" ".join(args[i + 1:]), []),
                    allow_split=False,
                )
            if arg.startswith("-vS") and len(arg) > 3:
                return _env_command_args(
                    _split_env_s(arg[3:], args[i + 1:]),
                    allow_split=False,
                )
            if arg.startswith("--split-string="):
                return _env_command_args(
                    _split_env_s(arg.split("=", 1)[1], args[i + 1:]),
                    allow_split=False,
                )
            if arg == "--split-string":
                if i + 1 >= len(args):
                    return []
                return _env_command_args(
                    _split_env_s(args[i + 1], args[i + 2:]),
                    allow_split=False,
                )

        # Options with separate required operand
        if arg in {"-u", "-C", "-P", "-a", "--unset", "--chdir", "--argv0"}:
            if i + 2 > len(args):
                return []
            i += 2
