def _stat_and_hash(path_str: str) -> tuple[str, float, str] | None:
    """Stat + MD5 a single file; returns None on OSError (e.g. deleted mid-run)."""
    try:
        p = Path(path_str)
        return path_str, os.stat(_os_path(p)).st_mtime, _md5_file(p)
    except OSError:
        return None

def _strip_interpreter_version(interp: str) -> str:
    """Map a version-suffixed interpreter onto the name it is a version of.

    Shebangs name a specific version as often as the generic one
    (``python3.12``, ``python2.7``, ``lua5.4``, ``php8.2``). Try the name with
    its major version (``python3``), then the bare name (``lua``), and keep the
    original when neither is a known code interpreter.
    """
    if interp in _SHEBANG_CODE_INTERPRETERS:
        return interp
    m = re.fullmatch(r"([A-Za-z]+)(\d+)(?:\.\d+)*", interp)
    if m:
        for candidate in (m.group(1) + m.group(2), m.group(1)):
            if candidate in _SHEBANG_CODE_INTERPRETERS:
                return candidate
    return interp

def _shebang_file_type(path: Path) -> FileType | None:
    """Peek at the first line of an extensionless file for a shebang."""
    interp = _shebang_interpreter(path)
    if interp in _SHEBANG_CODE_INTERPRETERS:
        return FileType.CODE
    return None

def _previous_checkout_absolute_keys(
    existing_keys: Iterable[Any],
    storage_root: Path | None,
    relative_keys: set[str],
) -> set[str]:
    """Absolute keys that still name a previous checkout (#3581).

    A key is a candidate only when :func:`_to_relative_for_storage` keeps it
    absolute against ``storage_root`` (a sibling row that becomes relative,
    including #3785, is not a candidate). Candidates that share one directory
    prefix are a previous checkout when that group has at least two keys. One
    absolute key is an include row and stays. ``storage_root is None`` yields
    an empty set.
    """
    if storage_root is None:
        return set()
    groups: dict[str, set[str]] = {}
    for key in existing_keys:
        if not isinstance(key, str) or not _looks_absolute(key):
            continue
        stored = _nfc(_to_relative_for_storage(key, storage_root))
        if not _looks_absolute(stored):
            continue
        prefix = _checkout_prefix(stored, relative_keys)
        if prefix is None:
            continue
        groups.setdefault(prefix, set()).add(key)
    stale: set[str] = set()
    for keys in groups.values():
        if len(keys) >= 2:
            stale.update(keys)
    return stale

def classify_file(path: Path) -> FileType | None:
    # Package manifests (apm.yml, pyproject.toml, Cargo.toml, go.mod, pom.xml) are parsed
    # deterministically, so route them to the AST path (CODE) rather than the LLM
    # document path — otherwise apm.yml (a .yml "document") would be LLM-extracted
    # and a package would split into duplicate file-anchored nodes (#1377).
    from graphify.manifest_ingest import is_package_manifest_path
    if is_package_manifest_path(path):
        return FileType.CODE
    # Compound extensions must be checked before simple suffix lookup
    if path.name.lower().endswith(".blade.php"):
        return FileType.CODE
    # A project may declare what an ambiguous extension means to it
    # (.graphifyrc `language.inc=php`, #2961); classify by the declared one.
    ext = effective_suffix(path).lower()
    if not ext:
        return _shebang_file_type(path)
    if ext in CODE_EXTENSIONS:
        return FileType.CODE
    if ext in PAPER_EXTENSIONS:
        # PDFs inside Xcode asset catalogs are vector icons, not papers
        if any(part.endswith(tuple(_ASSET_DIR_MARKERS)) for part in path.parts):
            return None
        return FileType.PAPER
    if ext in IMAGE_EXTENSIONS:
        return FileType.IMAGE
    if ext in DOC_EXTENSIONS:
        # Check if it's a converted paper
        if _looks_like_paper(path):
            return FileType.PAPER
        return FileType.DOCUMENT
    if ext in OFFICE_EXTENSIONS:
        return FileType.DOCUMENT
    if ext in GOOGLE_WORKSPACE_EXTENSIONS:
        return FileType.DOCUMENT
    if ext in VIDEO_EXTENSIONS:
        return FileType.VIDEO
    return None

def docx_to_markdown(path: Path) -> str:
    """Convert a .docx file to markdown text using python-docx."""
    if not _zip_within_caps(path):
        return ""
    try:
        from docx import Document
        from docx.table import Table
        from docx.text.paragraph import Paragraph
        doc = Document(str(path))
        lines = []
        # Walk the body in document order, so a table stays under the heading it belongs to.
        for block in _docx_blocks(doc.element.body):
            if block.tag == f"{_W}tbl":
                # python-docx's rows repeat a merged cell across the grid columns it spans,
                # which keeps the header and the rows the same width.
                rows = [[_docx_cell_markdown(cell._tc) for cell in row.cells] for row in Table(block, doc).rows]
                if not rows:
                    continue
                header = "| " + " | ".join(rows[0]) + " |"
                sep = "| " + " | ".join("---" for _ in rows[0]) + " |"
                lines.extend([header, sep])
                for row in rows[1:]:
                    lines.append("| " + " | ".join(row) + " |")
                continue
            para = Paragraph(block, doc)
            style = para.style.name if para.style else ""
            text = _docx_paragraph_text(block).strip()
            if not text:
                lines.append("")
                continue
            if style.startswith("Heading 1"):
                lines.append(f"# {text}")
            elif style.startswith("Heading 2"):
                lines.append(f"## {text}")
            elif style.startswith("Heading 3"):
                lines.append(f"### {text}")
            elif style.startswith("List"):
                lines.append(f"- {text}")
            else:
                lines.append(text)
        return "\n".join(lines)
    except ImportError:
        return ""
    except Exception:
        return ""

def extract_pdf_text(path: Path) -> str:
    """Extract plain text from a PDF file using pypdf.

    Returns ``""`` when the file cannot be read (malformed, encrypted, ...), the
    same as for a PDF with no text, but warns on stderr naming the file and the
    error first (#4527), so a failed read is not mistaken for an empty document.
    """
    if not _file_within_size_cap(path):
        return ""
    try:
        from pypdf import PdfReader
    except ImportError:
        global _pypdf_missing_warned
        if not _pypdf_missing_warned:
            _pypdf_missing_warned = True
            print(
                "[graphify] WARNING: PDF text extraction skipped: 'pypdf' is not "
                "installed. Install the pdf extra: uv tool install 'graphifyy[pdf]'",
                file=sys.stderr,
            )
        return ""
    try:
        reader = PdfReader(str(path))
        pages = []
        for page in reader.pages:
            text = page.extract_text()
            if text:
                pages.append(text)
        return "\n".join(pages)
    except Exception as exc:
        key = str(path)
        if key not in _pdf_failed_warned:
            _pdf_failed_warned.add(key)
            print(
                f"[graphify] WARNING: could not extract text from {path} "
                f"({type(exc).__name__}: {exc}); it contributes no content to "
                "the graph.",
                file=sys.stderr,
            )
        return ""

def load_manifest(
    manifest_path: str = _MANIFEST_PATH,
    *,
    root: Path | None = None,
) -> dict:
    """Load the manifest from a previous run. Returns {} on any error.

    When ``root`` is provided, stored relative keys are re-anchored against
    it so callers see absolute paths regardless of on-disk format. Legacy
    manifests with absolute keys pass through unchanged, so a graphify-out/
    written by an older version (or by a caller that didn't supply ``root``
    to :func:`save_manifest`) remains readable.

    Keys are NFC-normalized on load so a manifest written under one Unicode
    form still matches a scan that yields the other (#2221).
    """
    try:
        raw = json.loads(Path(manifest_path).read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(raw, dict):
        return raw
    if root is None:
        return _collapse_manifest_duplicates(raw.items(), _nfc)
    anchor = _manifest_storage_anchor(manifest_path, root) or root
    return _collapse_manifest_duplicates(
        raw.items(), lambda k: _nfc(_to_absolute_from_storage(k, anchor))
    )

def xlsx_to_markdown(path: Path) -> str:
    """Convert an .xlsx file to markdown text using openpyxl."""
    if not _zip_within_caps(path):
        return ""
    try:
        import openpyxl
        wb = openpyxl.load_workbook(str(path), read_only=True, data_only=True)
        sections = []
        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            rows = []
            for row in ws.iter_rows(values_only=True):
                if all(cell is None for cell in row):
                    continue
                rows.append([str(cell) if cell is not None else "" for cell in row])
            if not rows:
                continue
            sections.append(f"## Sheet: {sheet_name}")
            if len(rows) >= 1:
                header = "| " + " | ".join(rows[0]) + " |"
                sep = "| " + " | ".join("---" for _ in rows[0]) + " |"
                sections.extend([header, sep])
                for row in rows[1:]:
                    sections.append("| " + " | ".join(row) + " |")
        wb.close()
        return "\n".join(sections)
    except ImportError:
        return ""
    except Exception:
        return ""

def count_words(path: Path) -> int:
    try:
        ext = path.suffix.lower()
        if ext in _BINARY_MEDIA_EXTENSIONS:
            return 0
        if ext == ".pdf":
            return len(extract_pdf_text(path).split())
        if ext == ".docx":
            return len(docx_to_markdown(path).split())
        if ext == ".xlsx":
            return len(xlsx_to_markdown(path).split())
        # Only regular files may be opened. A repository can contain named
        # pipes, sockets and device nodes, and `clone <github-url>` exists to
        # point the scan at trees the operator did not write. open() on a FIFO
        # with no writer BLOCKS FOREVER — it never raises, so the except below
        # cannot help, and `graphify update` hangs with no output. os.stat
        # follows symlinks on purpose: a link pointing at a FIFO blocks exactly
        # like the FIFO itself.
        if not stat.S_ISREG(os.stat(_os_path(path)).st_mode):
            return 0
        with open(_os_path(path), encoding="utf-8", errors="ignore") as f:
            return len(f.read().split())
    except Exception:
        return 0

def _edge_list(extraction: dict[str, Any]) -> list[Any]:
    edges = extraction.get("edges")
    if edges is None:
        edges = extraction.get("links")
    return edges if isinstance(edges, list) else []

def _exact_signature(edge: Any) -> str:
    if not isinstance(edge, dict):
        return "<non-object>"
    normalized = dict(edge)
    if "source" not in normalized and "from" in normalized:
        normalized["source"] = normalized["from"]
    if "target" not in normalized and "to" in normalized:
        normalized["target"] = normalized["to"]
    normalized.pop("from", None)
    normalized.pop("to", None)
    return json.dumps(
        normalized,
        sort_keys=True,
        default=str,
        ensure_ascii=False,
        separators=(",", ":"),
    )

def _node_ids(extraction: dict[str, Any]) -> set[str]:
    nodes = extraction.get("nodes", [])
    if not isinstance(nodes, list):
        return set()
    return {
        str(node["id"])
        for node in nodes
        if isinstance(node, dict) and "id" in node and node.get("id") is not None
    }

def _read_json_file(path: str | Path) -> dict[str, Any]:
    """Read a JSON graph after applying Graphify's graph-load size cap."""
    from graphify.security import check_graph_file_size_cap

    json_path = Path(path)
    check_graph_file_size_cap(json_path)
    try:
        data = json.loads(json_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        raise RuntimeError(
            f"Cannot parse {json_path}: {exc}. "
            "The file may be corrupted — re-run 'graphify extract'."
        ) from exc
    if not isinstance(data, dict):
        raise ValueError("diagnostic input must be a JSON object")
    return data

def _safe_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (str, int, float, bool)):
        return str(value)
    return json.dumps(value, sort_keys=True, default=str, ensure_ascii=False)

def _tuple_arity_from_annotation(line: str) -> int:
    match = _TYPE_TUPLE_RE.search(line)
    if not match:
        return 0
    inside = match.group("inside").strip()
    if not inside:
        return 0
    return inside.count(",") + 1

def _variant_group_count(
    grouped_edges: dict[tuple[str, str], list[dict[str, str]]],
    field: str,
    *,
    relation_sensitive: bool = False,
) -> int:
    groups = 0
    for edges in grouped_edges.values():
        if relation_sensitive:
            by_relation: dict[str, set[str]] = defaultdict(set)
            for edge in edges:
                by_relation[edge["relation"]].add(edge[field])
            groups += sum(1 for values in by_relation.values() if len(values) > 1)
        elif len({edge[field] for edge in edges}) > 1:
            groups += 1
    return groups

def format_diagnostic_json(summary: dict[str, Any]) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "summary": {
            key: value
            for key, value in summary.items()
            if key not in {"examples", "producer_suppression"}
        },
        "examples": summary.get("examples", []),
        "producer_suppression": summary.get("producer_suppression", {}),
        "notes": [
            "Diagnostics are read-only.",
            "A normal graph.json is already post-build and cannot recover raw producer edges.",
            "Producer suppression sites are heuristic source-code evidence.",
        ],
    }

def scan_producer_suppression_sites(path: str | Path) -> dict[str, Any]:
    """Find likely `seen_*` producer-suppression sets in an extractor file."""
    source_path = Path(path)
    if not source_path.exists():
        return {
            "path": str(source_path),
            "total_sites": 0,
            "sites": [],
            "error": "file not found",
        }

    sites: list[dict[str, Any]] = []
    lines = source_path.read_text(encoding="utf-8").splitlines()
    for lineno, line in enumerate(lines, start=1):
        match = _SUPPRESSION_DECL_RE.match(line)
        if not match:
            continue
        sites.append(
            {
                "line": lineno,
                "name": match.group("name"),
                "tuple_arity": _tuple_arity_from_annotation(line),
                "sample": line.strip()[:120],
            }
        )

    return {
        "path": str(source_path),
        "total_sites": len(sites),
        "sites": sites,
        "error": "",
    }

def _graphify_version() -> str | None:
    """Return the installed graphify version for graph provenance."""
    try:
        from importlib.metadata import version

        return version("graphifyy")
    except Exception:
        return None

def _adopt_pre_manifest_notes(out: Path) -> set[str]:
    """Names of notes in *out* that graphify itself wrote before manifests existed.

    Deliberately limited to top-level ``*.md``: those are the only files graphify
    can identify as its own from their content. ``.obsidian/graph.json`` is NOT
    adopted — graphify writes one, but so does Obsidian, and with no manifest
    there is no way to tell whose it is. Leaving it unowned keeps the
    conservative behaviour for the one file where guessing wrong would cost the
    user their own vault configuration.
    """
    try:
        candidates = sorted(out.glob("*.md"))
    except OSError:
        return set()
    return {p.name for p in candidates if _is_graphify_note(p)}

def _strip_diacritics(text: str | None) -> str:
    import unicodedata
    if not isinstance(text, str):
        text = "" if text is None else str(text)
    nfkd = unicodedata.normalize("NFKD", text)
    return "".join(c for c in nfkd if not unicodedata.combining(c))

def _yaml_str(s: str) -> str:
    """Escape a value for safe embedding in a YAML double-quoted scalar (F-009).

    See `graphify.ingest._yaml_str` for the full rationale; duplicated here to
    avoid pulling the URL-fetching `ingest` module into export's dependency
    graph. Handles backslash, double-quote, all line breaks (\\n, \\r,
    U+2028, U+2029), tab, NUL, and other C0/DEL control characters that
    would otherwise let a hostile `source_file` / `community` / etc. break
    out of the YAML scalar and inject sibling keys.
    """
    if s is None:
        return ""
    out: list[str] = []
    for ch in str(s):
        cp = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\0":
            out.append("\\0")
        elif cp == 0x2028:
            out.append("\\L")
        elif cp == 0x2029:
            out.append("\\P")
        elif cp < 0x20 or cp == 0x7F:
            out.append(f"\\x{cp:02x}")
        else:
            out.append(ch)
    return "".join(out)

def existing_graph_node_count(path: "str | Path"):
    """Node count of an existing graph.json.

    Returns:
      - an ``int`` node count when the file parses;
      - ``None`` when there is verifiably nothing to protect — absent, empty, or
        over the size cap (matching how :func:`to_json` lets the new graph
        replace an empty/oversized file);
      - :data:`MALFORMED_GRAPH` when the file is present and non-empty but
        unparseable — the caller must treat this as fail-closed (refuse to
        overwrite), mirroring to_json's #479 handling of a corrupt/mid-write file.

    The raw ``--no-cluster`` write path uses this to apply the same #479 shrink
    guard that :func:`to_json` applies inline for the clustered path.
    """
    p = Path(path)
    if not p.exists():
        return None
    from graphify.security import check_graph_file_size_cap
    try:
        check_graph_file_size_cap(p)
    except Exception:
        # Oversized: reading it to compare would be the DoS the cap guards against.
        return None
    try:
        raw = p.read_text(encoding="utf-8")
    except Exception:
        # Present but unreadable: fail closed if it has bytes, else nothing to lose.
        try:
            return MALFORMED_GRAPH if p.stat().st_size > 0 else None
        except Exception:
            return None
    if not raw.strip():
        return None
    try:
        data = json.loads(raw)
    except Exception:
        return MALFORMED_GRAPH
    nodes = data.get("nodes") if isinstance(data, dict) else None
    return len(nodes) if isinstance(nodes, list) else MALFORMED_GRAPH

def prune_dangling_edges(graph_data: dict) -> tuple[dict, int]:
    """Remove edges whose source or target node is not in the node set.

    Returns the cleaned graph_data dict and the number of pruned edges.
    """
    node_ids = {n["id"] for n in graph_data["nodes"]}
    links_key = "links" if "links" in graph_data else "edges"
    before = len(graph_data[links_key])
    graph_data[links_key] = [
        e for e in graph_data[links_key]
        if e["source"] in node_ids and e["target"] in node_ids
    ]
    return graph_data, before - len(graph_data[links_key])

def _distinct_node_labels(G: nx.Graph) -> list[str]:
    """Distinct Cypher labels the node-upsert loop will write, sorted.

    The label is derived exactly as the push loops derive it, so the indexes
    created up front cover every label the MERGE statements will match against.
    """
    labels = set()
    for _, data in G.nodes(data=True):
        label = data.get("file_type", "Entity").capitalize()
        labels.add(re.sub(r"[^A-Za-z0-9_]", "", label) or "Entity")
    return sorted(labels)

