def _read_source_bytes(path: Path, *, warn: bool = True) -> bytes:
    """Read a source file as the UTF-8 bytes tree-sitter parses.

    tree-sitter treats its input as UTF-8. Raw bytes in another encoding were
    parsed as-is: a UTF-16 file (interleaved NUL bytes) produced no nodes at
    all, and a Windows-1252 identifier was cut at its first non-UTF-8 byte
    (``CaféOrder`` came out as ``Order``) — both silently.

    Valid UTF-8, with or without a BOM, is returned byte-for-byte, so node ids,
    byte offsets and cache keys for those files are unchanged. A UTF-16 or
    UTF-32 file with a BOM is decoded exactly and re-encoded as UTF-8. Anything
    else is decoded as cp1252, then latin-1 (which cannot fail), so names come
    out whole; line numbers are unchanged in every case. ``warn`` names the file
    once per process on that last, guessed path — pass ``warn=False`` from
    secondary passes that re-read a file the extractor already read.
    """
    raw = path.read_bytes()
    if raw.isascii():
        return raw
    try:
        raw.decode("utf-8")
        return raw
    except UnicodeDecodeError:
        pass
    for boms, encoding in ((_UTF32_BOMS, "utf-32"), (_UTF16_BOMS, "utf-16")):
        if raw.startswith(boms):
            try:
                return raw.decode(encoding).encode("utf-8")
            except UnicodeDecodeError:
                continue  # FF FE 00 00 is also UTF-16-LE: BOM + U+0000
    for encoding in _SOURCE_FALLBACK_ENCODINGS:
        try:
            text = raw.decode(encoding)
        except UnicodeDecodeError:
            continue
        key = str(path)
        if warn and key not in _warned_source_encodings:
            _warned_source_encodings.add(key)
            print(
                f"[graphify] WARNING: {path} is not valid UTF-8; read it as {encoding}. "
                "Re-save it as UTF-8 if names in the graph look wrong.",
                file=sys.stderr,
            )
        return text.encode("utf-8")
    return raw  # unreachable: latin-1 decodes every byte

def _starts_inside_string(code: str, offset: int) -> bool:
    """Whether *offset* lies inside a COBOL quoted literal."""
    for match in re.finditer(r"'(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"", code):
        if match.start() <= offset < match.end():
            return True
    return False

def _build_csharp_type_def_index(
    all_nodes: list[dict],
    all_edges: list[dict] | None = None,
) -> dict[tuple[str, str], str]:
    """Return deterministic ``(namespace, name) -> node_id`` C# type definitions."""
    non_type_ids: set[str] = set()

    if all_edges is not None:
        for edge in all_edges:
            rel = edge.get("relation")
            if rel in ("case_of", "defines", "method"):
                tgt = edge.get("_tgt") or edge.get("target")
                if isinstance(tgt, str):
                    non_type_ids.add(tgt)

    candidates: dict[tuple[str, str], list[dict]] = {}

    for node in all_nodes:
        if node.get("type") == "namespace":
            continue

        metadata = node.get("metadata") or {}
        if not isinstance(metadata, dict):
            metadata = {}

        if metadata.get("is_nested_type"):
            continue

        nid = node.get("id")
        label = node.get("label")

        if not (
            isinstance(nid, str)
            and nid
            and isinstance(label, str)
            and label
        ):
            continue

        if all_edges is not None and nid in non_type_ids:
            continue
        source_file = node.get("source_file")
        if not _is_cs_file(source_file) or node.get("file_type") != "code":
            continue
        if label.endswith(")") or label.startswith(".") or "." in label:
            continue
        namespace = metadata.get("namespace", "")
        if not isinstance(namespace, str):
            namespace = ""
        candidates.setdefault((namespace, label), []).append(node)

    return {
        key: sorted(
            nodes,
            key=lambda node: (
                str(node.get("source_file") or ""),
                str(node.get("source_location") or ""),
                str(node.get("id") or ""),
            ),
        )[0]["id"]
        for key, nodes in candidates.items()
    }

def _strip_trailing_csharp_generic_args(target_fqn: str) -> str:
    target_fqn = target_fqn.strip()
    if not target_fqn.endswith(">"):
        return target_fqn
    depth = 0
    for index in range(len(target_fqn) - 1, -1, -1):
        char = target_fqn[index]
        if char == ">":
            depth += 1
        elif char == "<":
            depth -= 1
            if depth == 0:
                return target_fqn[:index].strip()
    return target_fqn

def _resolve_cross_file_csharp_imports(
    per_file: list[dict],
    paths: list[Path],
    all_nodes: list[dict],
    all_edges: list[dict],
) -> None:
    """Re-point resolvable C# ``using`` import edges to canonical internal nodes.

    Namespace imports resolve only to canonical C# namespace nodes. Alias imports
    resolve only when the alias target's prefix is a known canonical namespace and
    the simple type name exists in the shared C# type-definition index. ``using
    static`` and nested type aliases remain deliberate gaps because they need
    member/nested-type modeling beyond this import pass.
    """
    _ = (per_file, paths)
    namespace_id_by_label: dict[str, str] = {}
    for node in sorted(
        all_nodes,
        key=lambda node: (
            str(node.get("source_file") or ""),
            str(node.get("source_location") or ""),
            str(node.get("id") or ""),
        ),
    ):
        if node.get("type") != "namespace":
            continue
        label = node.get("label")
        nid = node.get("id")
        if isinstance(label, str) and label and isinstance(nid, str) and nid:
            namespace_id_by_label.setdefault(label, nid)

    type_def_index = _build_csharp_type_def_index(all_nodes, all_edges)
    if not namespace_id_by_label and not type_def_index:
        return

    repointed_from: set[str] = set()
    for edge in all_edges:
        if edge.get("relation") != "imports":
            continue
        metadata = edge.get("metadata") or {}
        if not isinstance(metadata, dict):
            continue
        using_kind = metadata.get("using_kind")
        target_fqn = metadata.get("target_fqn")
        if not using_kind or not isinstance(target_fqn, str) or not target_fqn:
            continue

        resolved = None
        if using_kind == "namespace":
            resolved = namespace_id_by_label.get(target_fqn)
        elif using_kind == "alias":
            base_fqn = _strip_trailing_csharp_generic_args(html.unescape(target_fqn))
            prefix, sep, name = base_fqn.rpartition(".")
            if sep and prefix in namespace_id_by_label:
                resolved = type_def_index.get((prefix, name))

        old_target = edge.get("target")
        if resolved and resolved != old_target:
            edge["target"] = resolved
            if isinstance(old_target, str) and old_target:
                repointed_from.add(old_target)

    if not repointed_from:
        return

    still_referenced: set[str] = set()
    for edge in all_edges:
        still_referenced.add(edge.get("source"))
        still_referenced.add(edge.get("target"))
    all_nodes[:] = [
        node for node in all_nodes
        if node.get("id") not in repointed_from or node.get("id") in still_referenced
    ]

def _dmm_type_path(entry: str) -> str:
    brace = entry.find("{")
    if brace != -1:
        entry = entry[:brace]
    return entry.strip()

def _read_dmi_description(data: bytes) -> str:
    """Pull the BYOND metadata text out of a .dmi PNG, or empty string on failure."""
    import struct
    import zlib as _zlib
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        return ""
    i = 8
    while i + 8 <= len(data):
        length = struct.unpack(">I", data[i:i + 4])[0]
        chunk_type = data[i + 4:i + 8]
        payload = data[i + 8:i + 8 + length]
        if chunk_type in (b"tEXt", b"zTXt"):
            try:
                null = payload.index(b"\x00")
            except ValueError:
                return ""
            keyword = payload[:null]
            if keyword == b"Description":
                if chunk_type == b"zTXt":
                    return _zlib.decompressobj().decompress(payload[null + 2:], max_length=1024 * 1024).decode("utf-8", errors="replace")
                return payload[null + 1:].decode("utf-8", errors="replace")
        i += 8 + length + 4
    return ""

def _split_dmm_tile(body: str) -> list[str]:
    out: list[str] = []
    buf: list[str] = []
    depth = 0
    in_string = False
    escape = False
    for ch in body:
        if escape:
            buf.append(ch)
            escape = False
            continue
        if in_string:
            buf.append(ch)
            if ch == "\\":
                escape = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
            buf.append(ch)
        elif ch in "({[":
            depth += 1
            buf.append(ch)
        elif ch in ")}]":
            depth -= 1
            buf.append(ch)
        elif ch == "," and depth == 0:
            out.append("".join(buf).strip())
            buf = []
        else:
            buf.append(ch)
    tail = "".join(buf).strip()
    if tail:
        out.append(tail)
    return out

def extract_dmi(path: Path) -> dict:
    """Extract icon state names from a .dmi (BYOND PNG icon sheet)."""
    try:
        data = path.read_bytes()
    except Exception as e:
        return {"nodes": [], "edges": [], "error": str(e)}

    str_path = str(path)
    stem = _file_stem(path)
    file_nid = _make_id(str(path))
    nodes: list[dict] = [{"id": file_nid, "label": path.name, "file_type": "code",
                           "source_file": str_path, "source_location": "L1"}]
    edges: list[dict] = []
    seen: set[str] = {file_nid}

    description = _read_dmi_description(data)
    if not description:
        return {"nodes": nodes, "edges": edges}

    line_no = 0
    for raw_line in description.splitlines():
        line_no += 1
        stripped = raw_line.strip()
        if not stripped.startswith("state ="):
            continue
        value = stripped.split("=", 1)[1].strip()
        if value.startswith('"') and value.endswith('"') and len(value) >= 2:
            state_name = value[1:-1]
        else:
            state_name = value
        if not state_name:
            continue
        nid = _make_id(stem, "state", state_name)
        if nid in seen:
            continue
        seen.add(nid)
        nodes.append({"id": nid, "label": f'"{state_name}"', "file_type": "code",
                      "source_file": str_path, "source_location": f"L{line_no}"})
        edges.append({"source": file_nid, "target": nid, "relation": "contains",
                      "confidence": "EXTRACTED", "source_file": str_path,
                      "source_location": f"L{line_no}", "weight": 1.0})

    return {"nodes": nodes, "edges": edges}

def extract_dmm(path: Path) -> dict:
    """Extract type-path references from a .dmm map file's tile dictionary."""
    try:
        if path.stat().st_size > 50 * 1024 * 1024:
            return {"nodes": [], "edges": [], "error": "file too large (>50 MB)"}
        text = _read_source_text(path)
    except Exception as e:
        return {"nodes": [], "edges": [], "error": str(e)}

    str_path = str(path)
    file_nid = _make_id(str(path))
    nodes: list[dict] = [{"id": file_nid, "label": path.name, "file_type": "code",
                           "source_file": str_path, "source_location": "L1"}]
    edges: list[dict] = []

    grid_match = _DMM_GRID_RE.search(text)
    dict_text = text[:grid_match.start()] if grid_match else text

    seen_targets: set[str] = set()
    buf: list[str] = []
    open_line = 0
    depth = 0
    in_string = False
    escape = False
    for line_idx, line in enumerate(dict_text.splitlines(), start=1):
        for ch in line:
            if escape:
                escape = False
            elif in_string:
                if ch == "\\":
                    escape = True
                elif ch == '"':
                    in_string = False
            elif ch == '"':
                in_string = True
            elif ch == "(":
                if depth == 0:
                    open_line = line_idx
                depth += 1
            elif ch == ")":
                depth -= 1
            buf.append(ch)
        buf.append("\n")
        if depth == 0 and buf:
            chunk = "".join(buf)
            buf = []
            lp = chunk.find("(")
            rp = chunk.rfind(")")
            if lp == -1 or rp == -1 or rp <= lp:
                continue
            inner = chunk[lp + 1:rp]
            for entry in _split_dmm_tile(inner):
                tpath = _dmm_type_path(entry)
                if not tpath.startswith("/"):
                    continue
                tgt = _make_id(tpath)
                if tgt in seen_targets:
                    continue
                seen_targets.add(tgt)
                edges.append({"source": file_nid, "target": tgt, "relation": "uses",
                              "context": "map", "confidence": "EXTRACTED",
                              "source_file": str_path,
                              "source_location": f"L{open_line}", "weight": 1.0})

    return {"nodes": nodes, "edges": edges}

def _c_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]]) -> None:
    """Walk a C type expression; append (name, role) tuples for user-defined types.
    Skips primitive types and qualifiers; recognises type_identifier."""
    if node is None or node.type in _C_PRIMITIVE_TYPE_NODES:
        return
    t = node.type
    if t == "type_identifier":
        text = _read_text(node, source)
        if text:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t in ("pointer_declarator", "reference_declarator", "array_declarator",
             "type_qualifier", "type_descriptor", "abstract_pointer_declarator",
             "abstract_reference_declarator", "abstract_array_declarator"):
        for c in node.children:
            if c.is_named:
                _c_collect_type_refs(c, source, generic, out)

def _cpp_declarator_name(node, source: bytes) -> str | None:
    """Return the bare variable name from a C++ declaration declarator, unwrapping
    pointer/reference/init wrappers (``*f``, ``&r``, ``f = Foo()``). Returns None
    for anything that isn't a plain named local (arrays, function pointers,
    structured bindings) so the type table never records a guessed receiver."""
    t = node.type
    if t == "identifier":
        return _read_text(node, source)
    if t in ("pointer_declarator", "reference_declarator", "init_declarator"):
        inner = node.child_by_field_name("declarator")
        if inner is None:
            for c in node.children:
                if c.type in ("identifier", "pointer_declarator",
                              "reference_declarator"):
                    inner = c
                    break
        if inner is not None:
            return _cpp_declarator_name(inner, source)
    return None

def _cpp_declarator_type_name(declarator, source: bytes) -> str | None:
    """The name a typedef declarator introduces: `Handle`, `*HandlePtr`,
    `(*Fn)(int)`, `Arr[4]` each wrap one `type_identifier`."""
    node = declarator
    while node is not None and node.type != "type_identifier":
        inner = node.child_by_field_name("declarator")
        if inner is None and node.type == "parenthesized_declarator":
            inner = next(iter(node.named_children), None)
        node = inner
    return _read_text(node, source) if node is not None else None

def _cpp_local_var_types(body_node, source: bytes, table: dict[str, str]) -> None:
    """Collect ``var -> ClassName`` from local variable declarations in a C++
    function body, for receiver-type inference in the cross-file member-call pass
    (#1547). Handles ``Foo f;``, ``Foo* f;``, ``Foo *f = ...;``, ``Foo f = Foo();``.

    Only a class-like (``type_identifier``/``qualified_identifier``) type with a
    single named declarator is recorded — PRECISION over recall: a built-in type
    (``int x``), an ambiguous multi-declarator line, or an un-nameable declarator
    contributes nothing rather than a guess. A qualified type ``ns::Foo`` records
    its simple tail ``Foo`` so it keys to the type's definition node label.
    """
    stack = [body_node]
    while stack:
        n = stack.pop()
        if n.type in ("function_definition", "lambda_expression"):
            # Don't descend into a nested function/lambda: its locals are scoped
            # away and would pollute this body's table.
            if n is not body_node:
                continue
        if n.type == "declaration":
            type_node = n.child_by_field_name("type")
            if type_node is not None and type_node.type in (
                "type_identifier", "qualified_identifier"
            ):
                type_name = _read_text(type_node, source).split("::")[-1].strip()
                declarators = [
                    c for c in n.children
                    if c.type in ("identifier", "pointer_declarator",
                                  "reference_declarator", "init_declarator")
                ]
                # A single declarator only: `Foo a, b;` is ambiguous to attribute
                # to one receiver name cleanly, so skip multi-declarator lines.
                if type_name and type_name[:1].isupper() and len(declarators) == 1:
                    var = _cpp_declarator_name(declarators[0], source)
                    if var and var not in table:
                        table[var] = type_name
        for c in n.children:
            stack.append(c)

def _cpp_type_last_name(type_node, source: bytes) -> str | None:
    """`Bar` for `ns::Bar` or `ns::Bar<T>`: the name a qualified type ends in."""
    if type_node is not None and type_node.type == "type_descriptor":
        type_node = type_node.child_by_field_name("type")
    if type_node is None or type_node.type != "qualified_identifier":
        return None
    while type_node is not None and type_node.type == "qualified_identifier":
        type_node = type_node.child_by_field_name("name")
    if type_node is not None and type_node.type == "template_type":
        type_node = type_node.child_by_field_name("name")
    return _read_text(type_node, source) if type_node is not None else None

def _cpp_type_parameters_in_scope(node, source: bytes) -> frozenset[str]:
    """Return C++ template type-parameter names visible from ``node``.

    A `template<typename T, class U>` binds `T`/`U` as local names, not corpus
    symbols. Walking up to every enclosing `template_declaration`'s
    `template_parameter_list` collects the names from its
    `type_parameter_declaration`/`variadic_type_parameter_declaration` children.
    A non-type parameter (`int N`) is a value, not a type, and is left alone.
    """
    names: set[str] = set()
    scope = node
    while scope is not None:
        for child in scope.children:
            if child.type != "template_parameter_list":
                continue
            for param in child.children:
                if param.type not in (
                    "type_parameter_declaration",
                    "variadic_type_parameter_declaration",
                ):
                    continue
                for sub in param.children:
                    if sub.type == "type_identifier":
                        name = _read_text(sub, source)
                        if name:
                            names.add(name)
                        break
        scope = scope.parent
    return frozenset(names)

def _cpp_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]],
                           skip: frozenset[str] | None = None,
                           dialect_quals: frozenset[str] = frozenset()) -> None:
    """Walk a C++ type expression; append (name, role) tuples.
    Resolves qualified_identifier tails (std::string → string) and template_type
    base + arguments (std::vector<HttpClient> → vector + HttpClient as generic_arg).

    Template type parameters in scope (``skip``) are local bindings, not
    references; emitting one mints a sourceless stub (the bare `t` god node a
    `template<typename T>` class or function would otherwise share corpus-wide).

    ``dialect_quals`` holds GPU C++-dialect qualifiers (Metal/CUDA; only non-empty
    for those file extensions) that tree-sitter-cpp misparses as a leading
    `type_identifier`; they are language keywords, not corpus symbols."""
    if node is None or node.type in _C_PRIMITIVE_TYPE_NODES:
        return
    if skip is None:
        skip = _cpp_type_parameters_in_scope(node, source)
    t = node.type
    if t == "type_identifier":
        text = _read_text(node, source)
        if text and text not in skip and text not in dialect_quals:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t == "qualified_identifier":
        name_node = node.child_by_field_name("name")
        if name_node is not None:
            _cpp_collect_type_refs(name_node, source, generic, out, skip, dialect_quals)
        return
    if t == "template_type":
        name_node = node.child_by_field_name("name")
        if name_node is not None:
            text = _read_text(name_node, source)
            if text and text not in skip and text not in dialect_quals:
                out.append((text, "generic_arg" if generic else "type"))
        args_node = node.child_by_field_name("arguments")
        if args_node is not None:
            for c in args_node.children:
                if c.is_named:
                    _cpp_collect_type_refs(c, source, True, out, skip, dialect_quals)
        return
    if t in ("type_descriptor", "pointer_declarator", "reference_declarator",
             "array_declarator", "type_qualifier", "abstract_pointer_declarator",
             "abstract_reference_declarator", "abstract_array_declarator"):
        for c in node.children:
            if c.is_named:
                _cpp_collect_type_refs(c, source, generic, out, skip, dialect_quals)

def _csharp_argc(call_node) -> int | None:
    """Argument count of a C# invocation, or None for anything else."""
    if call_node.type != "invocation_expression":
        return None
    args = call_node.child_by_field_name("arguments")
    return sum(1 for c in args.children if c.type == "argument") if args is not None else 0

def _csharp_bare_call_name(name_node, source: bytes) -> str:
    """The callee identifier of a C# call-site name node.

    A plain `identifier` reads as-is; a `generic_name` (`Get<int>`) reads its
    identifier child so the type-argument list never leaks into the callee
    name (#3406). Falls back to raw text for anything else.
    """
    if name_node.type == "generic_name":
        for child in name_node.children:
            if child.type == "identifier":
                return _read_text(child, source)
    return _read_text(name_node, source)

def _csharp_classify_base(name: str, interface_names: set[str]) -> str:
    """`implements` if the base name is an interface (declared or by I-prefix convention), else `inherits`."""
    if name in interface_names:
        return "implements"
    if len(name) >= 2 and name[0] == "I" and name[1].isupper():
        return "implements"
    return "inherits"

def _csharp_loop_source(expr, source: bytes) -> tuple[str, str] | None:
    """``(field, suffix)`` for a ``foreach`` over ``f``, ``this.f``,
    ``f.Values`` or ``f.Keys``; None for anything else."""
    if expr is None:
        return None
    if expr.type == "identifier":
        return _read_text(expr, source), ""
    if expr.type != "member_access_expression":
        return None
    inner = expr.child_by_field_name("expression")
    name = expr.child_by_field_name("name")
    if inner is None or name is None or name.type != "identifier":
        return None
    member = _read_text(name, source)
    if inner.type in ("this", "this_expression"):
        return member, ""
    if member in ("Values", "Keys"):
        root = _csharp_loop_source(inner, source)
        if root is not None and root[1] == "":
            return root[0], "." + member
    return None

def _csharp_member_call_parts(fn_node):
    """``(name, receiver)`` nodes of a C# member call's ``function``, else None.

    `recv.M()` is a member_access_expression (`expression` + `name` fields).
    `recv?.M()` is the same call behind a null check: a
    conditional_access_expression whose `condition` is the receiver and whose
    member_binding_expression child carries the name. Reading both shapes here
    keeps `?.` on the receiver-typed path; the raw-text fallback split
    `_window?.Refresh` on the dot and recorded the receiver as `_window?`,
    which no receiver table types, so the call was dropped (#3797).
    """
    if fn_node is None:
        return None
    if fn_node.type == "member_access_expression":
        return fn_node.child_by_field_name("name"), fn_node.child_by_field_name("expression")
    if fn_node.type == "conditional_access_expression":
        for child in fn_node.named_children:
            if child.type == "member_binding_expression":
                return child.child_by_field_name("name"), fn_node.child_by_field_name("condition")
    return None

def _csharp_namespace_id(dotted_name: str) -> str:
    digest = hashlib.sha1(dotted_name.encode("utf-8")).hexdigest()[:16]
    return f"csharp_namespace:{digest}"

def _csharp_namespace_name(node, source: bytes) -> str:
    name_node = node.child_by_field_name("name")
    if name_node is not None:
        return _read_text(name_node, source).strip()
    for child in node.children:
        if child.type in ("identifier", "qualified_name"):
            return _read_text(child, source).strip()
    return ""

def _csharp_pick_overload(overloads: list[dict], argc: int | None) -> dict | None:
    """The one overload a call with ``argc`` arguments can mean, or None.

    ``overloads`` are the method nodes of one name on one type. Only the
    argument count is known at the call site, so two overloads that both
    accept it (``M(int)`` / ``M(string)``, or ``M(int)`` / ``M(params int[])``)
    stay undecided; C# would pick by argument types, which are not known here
    (#4584).
    """
    if argc is None:
        return None
    fits = []
    for n in overloads:
        meta = n.get("metadata") or {}
        arity = meta.get("arity")
        if not isinstance(arity, int):
            return None
        low = meta.get("min_arity", arity)
        if low <= argc and (argc <= arity or meta.get("variadic")):
            fits.append(n)
    return fits[0] if len(fits) == 1 else None

def _csharp_pre_scan_interfaces(root_node, source: bytes) -> set[str]:
    """Return names declared as `interface` in this C# compilation unit."""
    out: set[str] = set()
    stack = [root_node]
    while stack:
        n = stack.pop()
        if n.type == "interface_declaration":
            name_node = n.child_by_field_name("name")
            if name_node is not None:
                text = _read_text(name_node, source)
                if text:
                    out.add(text)
        stack.extend(n.children)
    return out

def _csharp_type_name_for_id(node, class_name: str) -> str:
    """A C# type's name as its node id spells it: the arity folds in (#4249).

    `Effect` and `Effect<T>` are different types, so the generic one is named
    the way C# metadata names it (`` Effect`1 ``); arity 0 is the bare name.
    """
    arity = sum(
        1 for c in node.children if c.type == "type_parameter_list"
        for _p in c.children if _p.type in ("type_parameter", "identifier")
    )
    return f"{class_name}`{arity}" if arity else class_name

def _csharp_type_parameters_in_scope(node, source: bytes) -> frozenset[str]:
    """Return C# type-parameter names visible from ``node``."""
    names: set[str] = set()
    scope = node
    while scope is not None:
        if scope.type in _CSHARP_TYPE_PARAMETER_SCOPE_DECLARATIONS:
            for child in scope.children:
                if child.type != "type_parameter_list":
                    continue
                for param in child.children:
                    if param.type == "type_parameter":
                        name_node = next(
                            (sub for sub in param.children if sub.type == "identifier"),
                            None,
                        )
                        if name_node is not None:
                            name = _read_text(name_node, source)
                            if name:
                                names.add(name)
                    elif param.type == "identifier":
                        name = _read_text(param, source)
                        if name:
                            names.add(name)
        scope = scope.parent
    return frozenset(names)

def _csharp_attribute_names(method_node, source: bytes) -> list[tuple[str, bool, str]]:
    """Collect attribute names from a C# method/declaration's attribute_list children."""
    names: list[tuple[str, bool, str]] = []
    skip = _csharp_type_parameters_in_scope(method_node, source)
    for child in method_node.children:
        if child.type != "attribute_list":
            continue
        for attr in child.children:
            if attr.type != "attribute":
                continue
            name_node = attr.child_by_field_name("name")
            if name_node is None:
                for sub in attr.children:
                    if sub.type in ("identifier", "qualified_name"):
                        name_node = sub
                        break
            if name_node is not None:
                qualified = name_node.type == "qualified_name"
                prefix, _, text = _read_text(name_node, source).rpartition(".")
                if text and text not in skip:
                    names.append((text, qualified, prefix if qualified else ""))
    return names

def _csharp_collect_type_refs(
    node,
    source: bytes,
    generic: bool,
    out: list[tuple[str, str, bool, str]],
    skip: frozenset[str] | None = None,
) -> None:
    """Walk a C# type expression; append (name, role, qualified, qualifier) tuples."""
    if node is None:
        return
    if skip is None:
        skip = _csharp_type_parameters_in_scope(node, source)
    t = node.type
    if t == "predefined_type":
        return
    if t == "identifier":
        name = _read_text(node, source)
        if name and name not in skip:
            out.append((name, "generic_arg" if generic else "type", False, ""))
        return
    if t == "qualified_name":
        prefix, _, text = _read_text(node, source).rpartition(".")
        text = text.split("<", 1)[0]
        if text and text not in skip:
            out.append((text, "generic_arg" if generic else "type", True, prefix))
        return
    if t == "generic_name":
        name_child = node.child_by_field_name("name")
        if name_child is None:
            for sub in node.children:
                if sub.type == "identifier":
                    name_child = sub
                    break
        if name_child is not None:
            qualified = name_child.type == "qualified_name"
            prefix, _, name = _read_text(name_child, source).rpartition(".")
            if name and name not in skip:
                out.append((name, "generic_arg" if generic else "type", qualified, prefix if qualified else ""))
        for sub in node.children:
            if sub.type == "type_argument_list":
                for arg in sub.children:
                    if arg.is_named:
                        _csharp_collect_type_refs(arg, source, True, out, skip)
        return
    if t in ("nullable_type", "array_type", "pointer_type", "ref_type"):
        for c in node.children:
            if c.is_named:
                _csharp_collect_type_refs(c, source, generic, out, skip)
        return
    if t == "tuple_type":
        # A named tuple element carries both a `type` and a `name` field
        # (`(int mode, string label)`). Only the `type` field feeds
        # type-reference collection; the `name` is an identifier, not a type
        # reference, and minting it produces junk "type" nodes (#3796).
        for el in node.children:
            if el.type == "tuple_element":
                type_child = el.child_by_field_name("type")
                if type_child is not None:
                    _csharp_collect_type_refs(type_child, source, generic, out, skip)
        return
    if node.is_named:
        for c in node.children:
            if c.is_named:
                _csharp_collect_type_refs(c, source, generic, out, skip)

def _find_body(node, config: LanguageConfig):
    """Find the body node using config.body_field, falling back to child types."""
    b = node.child_by_field_name(config.body_field)
    if b:
        return b
    for child in node.children:
        if child.type in config.body_fallback_child_types:
            return child
    return None

def _find_require_call(value_node):
    """Return the call_expression node if `value_node` is a `require(...)` call
    or `require(...).x` member access. Otherwise None."""
    if value_node is None:
        return None
    if value_node.type == "call_expression":
        fn = value_node.child_by_field_name("function")
        if fn is not None and fn.type == "identifier":
            return value_node
    if value_node.type == "member_expression":
        obj = value_node.child_by_field_name("object")
        return _find_require_call(obj)
    return None

def _first_multiline_error_line(root) -> int:
    """1-based line of the first ERROR that spans more than one line.

    The #2551 warning gate selects on a multiline region (or a total loss), so
    that region is the actionable location. Earlier single-line recoveries can
    sit far above it: in a decorator-heavy TS file, `@(Link().toMany())` errors
    on line 14 but keeps every symbol, while the multiline chain on line 33 is
    the one the reader needs (#4711).
    """
    best = None
    stack = [root]
    while stack:
        n = stack.pop()
        if n.type == "ERROR" and n.end_point[0] > n.start_point[0]:
            if best is None or n.start_byte < best.start_byte:
                best = n
        stack.extend(c for c in n.children if c.has_error)
    if best is None:
        return _first_parse_error_line(root)
    return best.start_point[0] + 1

def _get_cpp_func_name(node, source: bytes) -> str | None:
    """Recursively unwrap declarator to find the innermost identifier (C++)."""
    if node.type == "identifier":
        return _read_text(node, source)
    if node.type in ("field_identifier", "destructor_name", "operator_name"):
        return _read_text(node, source)
    if node.type == "qualified_identifier":
        # An out-of-class DEFINITION (`void Foo::bar() {}`) carries a
        # qualified_identifier declarator. Retaining the `Foo::` qualifier makes
        # _make_id(stem, "Foo::bar") normalize to the same id as the in-class
        # member _make_id(class_nid, "bar"), so the decl in Foo.h and the def in
        # Foo.cpp resolve to ONE method node instead of two (#1547). The full
        # qualified text also handles nested scopes (`A::B::bar`). Free functions
        # never have a qualified_identifier here, so their bare-name ids are
        # unchanged; only qualified definitions shift onto their owning class.
        return _read_text(node, source)
    decl = node.child_by_field_name("declarator")
    if decl:
        return _get_cpp_func_name(decl, source)
    for child in node.children:
        if child.type == "identifier":
            return _read_text(child, source)
    return None

def _java_annotation_nodes(declaration_node) -> list:
    """Return annotations from a Java declaration's `modifiers` child."""
    modifiers = None
    for child in declaration_node.children:
        if child.type == "modifiers":
            modifiers = child
            break
    if modifiers is None:
        return []
    return [
        child
        for child in modifiers.children
        if child.type in ("marker_annotation", "annotation")
    ]

def _java_annotation_names(declaration_node, source: bytes) -> list[tuple[str, str]]:
    """Collect ``(simple, raw)`` annotation names from a Java declaration's
    `modifiers` child. ``raw`` keeps the dotted qualifier of an inline-qualified
    annotation (``@org.pkg.Foo``); it equals ``simple`` when unqualified."""
    names: list[tuple[str, str]] = []
    for anno in _java_annotation_nodes(declaration_node):
        name_node = anno.child_by_field_name("name")
        if name_node is None:
            for sub in anno.children:
                if sub.type in ("identifier", "scoped_identifier", "type_identifier"):
                    name_node = sub
                    break
        if name_node is not None:
            raw = _read_text(name_node, source)
            text = raw.rsplit(".", 1)[-1]
            if text:
                names.append((text, raw))
    return names

def _java_bound_names(method_node, source: bytes) -> set[str]:
    """Every name a Java method binds itself, typed or not: parameters, locals
    (`var` too), lambda, catch, for-each, resource and pattern variables.

    A receiver outside this set and the class's own fields can only be a field
    the class inherits (or one of an enclosing class), never a local."""
    names: set[str] = set()
    stack = [method_node.child_by_field_name("parameters"), method_node.child_by_field_name("body")]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        if node.type in _JAVA_NAMED_BINDINGS:
            name_node = node.child_by_field_name("name")
            if name_node is not None and name_node.type == "identifier":
                names.add(_read_text(name_node, source))
        elif node.type in _JAVA_LISTED_BINDINGS:
            names.update(_read_text(c, source) for c in node.children if c.type == "identifier")
        elif node.type == "lambda_expression":
            params = node.child_by_field_name("parameters")
            if params is not None and params.type == "identifier":
                names.add(_read_text(params, source))
        stack.extend(node.children)
    return names

def _java_declarator_names(declaration_node, source: bytes) -> list[str]:
    names: list[str] = []
    for child in declaration_node.children:
        if child.type != "variable_declarator":
            continue
        name_node = child.child_by_field_name("name")
        if name_node is not None:
            name = _read_text(name_node, source)
            if name:
                names.append(name)
    return names

def _java_type_chain_leaf(chain: list, receiver_types: dict) -> list | None:
    """Replace the ["name", x] leaf of a receiver chain with x's declared type
    (["type", T]); a capitalized name nothing declares is a type itself
    (`Foo.create().run()`), as for a plain receiver. None when x is untyped."""
    if chain[0] == "call":
        if chain[2] is None:
            return chain
        inner = _java_type_chain_leaf(chain[2], receiver_types)
        return ["call", chain[1], inner] if inner else None
    if chain[0] == "name":
        declared = receiver_types.get(chain[1])
        if declared:
            return ["type", declared]
        return ["type", chain[1]] if chain[1][:1].isupper() else None
    return chain

def _java_type_parameters_in_scope(node, source: bytes) -> frozenset[str]:
    """Return Java type-parameter names visible from ``node``."""
    names: set[str] = set()
    scope = node
    while scope is not None:
        if scope.type in _JAVA_TYPE_PARAMETER_SCOPE_DECLARATIONS:
            params = scope.child_by_field_name("type_parameters")
            if params is not None:
