    node,
    source: bytes,
    generic: bool,
    out: list[tuple[str, str]],
    skip: frozenset[str] | None = None,
    preserve_qualified: bool = False,
) -> None:
    """Walk a Java type expression; append (name, role) tuples."""
    if node is None:
        return
