        raw = _read_text(node, source)
        simple = raw.rsplit(".", 1)[-1]
        text = raw if preserve_qualified else raw.rsplit(".", 1)[-1]
        if text and simple not in _JAVA_BUILTIN_TYPES:
            out.append((text, "generic_arg" if generic else "type"))
        return
