        for c in node.children:
            if c.type in ("type_identifier", "scoped_type_identifier"):
                raw = _read_text(c, source)
                simple = raw.rsplit(".", 1)[-1]
                text = (
                    raw
                    if preserve_qualified and c.type == "scoped_type_identifier"
                    else simple
