            if c.type == "type_arguments":
                for arg in c.children:
                    if arg.type == "type_projection":
                        for sub in arg.children:
                            if sub.is_named:
                                _kotlin_collect_type_refs(sub, source, True, out, skip)
                    elif arg.is_named:
                        _kotlin_collect_type_refs(arg, source, True, out, skip)
