def _php_method_return_type_node(method_node):
    """Return the named_type/primitive_type node sitting after formal_parameters."""
    saw_params = False
    for c in method_node.children:
        if c.type == "formal_parameters":
            saw_params = True
            continue
        if saw_params and c.is_named and c.type not in ("compound_statement",):
            if c.type in ("named_type", "primitive_type", "nullable_type",
                          "union_type", "intersection_type", "optional_type"):
                return c
    return None

def _php_name_text(node, source: bytes) -> str | None:
    """Return the unqualified name text from a PHP `name`/`qualified_name` node."""
    if node is None:
        return None
    return _read_text(node, source).rsplit("\\", 1)[-1] or None

def _php_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]]) -> None:
    """Walk a PHP type expression; append (name, role) tuples."""
    if node is None:
        return
    t = node.type
    if t == "primitive_type":
        return
    if t == "named_type":
        for c in node.children:
            if c.type in ("name", "qualified_name"):
                text = _php_name_text(c, source)
                if text:
                    out.append((text, "generic_arg" if generic else "type"))
                return
        return
    if t in ("name", "qualified_name"):
        text = _php_name_text(node, source)
        if text:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t in ("nullable_type", "union_type", "intersection_type", "optional_type"):
        for c in node.children:
            if c.is_named:
                _php_collect_type_refs(c, source, generic, out)
        return
    if node.is_named:
        for c in node.children:
            if c.is_named:
                _php_collect_type_refs(c, source, generic, out)

def _php_declared_type_name(node, source: bytes) -> str | None:
    """The single class name a PHP type annotation names, or None.

    Only `Greeter` and `?Greeter` qualify: a union, an intersection or a primitive names
    no one class, and binding a receiver to the first arm of `A|B` would be a guess.
    """
    if node is None:
        return None
    if node.type == "optional_type":
        node = next((c for c in node.children if c.is_named), None)
        if node is None:
            return None
    if node.type != "named_type":
        return None
    return next((_php_name_text(c, source) for c in node.children
                 if c.type in ("name", "qualified_name")), None)

def _php_first_declared_type(node, source: bytes) -> str | None:
    """The first single-class type annotation among ``node``'s direct children."""
    return next((name for name in (_php_declared_type_name(c, source) for c in node.children)
                 if name), None)

def _php_variable_text(node, source: bytes) -> str | None:
    """The bare name a PHP `variable_name` binds: `$greeter` -> `greeter`."""
    if node is None or node.type != "variable_name":
        return None
    return next((_read_text(c, source) for c in node.children if c.type == "name"), None)

def _php_receiver_type_table(root, source: bytes, table: dict[str, str]) -> None:
    """Collect ``name -> TypeName`` for every PHP receiver whose type is written down.

    Four sources, all needed: a typed property (`private Greeter $g;`), a constructor
    promotion (`__construct(private Greeter $g)`), a typed parameter, and
    `$g = new Greeter()`. File-scoped and flat, first binding wins — a parameter
    shadowing a property in another method must not retype the property's own calls.
    Children are pushed reversed so the walk yields document order and "first" means
    first in the file.
    """
    stack = [root]
    while stack:
        n = stack.pop()
        t = n.type
        if t == "property_declaration":
            type_name = _php_first_declared_type(n, source)
            for element in n.children if type_name else ():
                if element.type != "property_element":
                    continue
                name = next((_php_variable_text(c, source) for c in element.children
                             if c.type == "variable_name"), None)
                if name and name not in table:
                    table[name] = type_name
        elif t in ("property_promotion_parameter", "simple_parameter"):
            type_name = _php_first_declared_type(n, source)
            name = next((_php_variable_text(c, source) for c in n.children
                         if c.type == "variable_name"), None)
            if name and type_name and name not in table:
                table[name] = type_name
        elif t == "assignment_expression":
            right = n.child_by_field_name("right")
            if right is not None and right.type == "object_creation_expression":
                name = _php_variable_text(n.child_by_field_name("left"), source)
                type_name = next((_php_name_text(c, source) for c in right.children
                                  if c.type in ("name", "qualified_name")), None)
                if name and type_name and name not in table:
                    table[name] = type_name
        stack.extend(reversed(n.children))

def _python_annotation_class(type_node, source: bytes) -> str | None:
    """`Client`, `mod.Client`, or the item of `Iterator[Client]` /
    `Generator[Client, None, None]` (a yield fixture); anything else is None."""
    node = type_node
    while node is not None and node.type == "type":
        node = next(iter(node.named_children), None)
    if node is None:
        return None
    if node.type == "generic_type":
        head = next((c for c in node.named_children if c.type in ("identifier", "attribute")), None)
        params = next((c for c in node.named_children if c.type == "type_parameter"), None)
        if head is None or params is None:
            return None
        if _read_text(head, source).rsplit(".", 1)[-1] not in _PYTHON_ITERATOR_WRAPPERS:
            return None
        return _python_annotation_class(next(iter(params.named_children), None), source)
    if node.type not in ("identifier", "attribute"):
        return None
    name = _read_text(node, source).rsplit(".", 1)[-1]
    return name if name[:1].isupper() else None

def _python_class_ref(node, source: bytes) -> str | None:
    """The single class a Python annotation or constructor callee names, else None.

    ``Request``, ``httpx.Request``, ``"Request"``, ``Optional[Request]`` and
    ``Request | None`` all name ``Request``. A container (``list[Request]``), a
    union of two classes, or a lowercase callee (``make_client``,
    ``Client.from_url``) names no single class, so it stays untyped.
    """
    if node is None:
        return None
    kind = node.type
    if kind == "type":
        named = [c for c in node.children if c.is_named]
        return _python_class_ref(named[0], source) if len(named) == 1 else None
    if kind == "identifier":
        name = _read_text(node, source)
        return name if name[:1].isupper() else None
    if kind == "attribute":
        return _python_class_ref(node.child_by_field_name("attribute"), source)
    if kind == "string":
        name = _read_text(node, source).strip("\"'").split(".")[-1].strip()
        return name if name.isidentifier() and name[:1].isupper() else None
    if kind == "subscript":  # typing.Optional[X]
        value = node.child_by_field_name("value")
        subs = node.children_by_field_name("subscript")
        if value is not None and _read_text(value, source).split(".")[-1] == "Optional" and len(subs) == 1:
            return _python_class_ref(subs[0], source)
        return None
    if kind == "generic_type":  # Optional[X]
        named = [c for c in node.children if c.is_named]
        if (
            len(named) == 2
            and named[0].type == "identifier"
            and _read_text(named[0], source) == "Optional"
            and named[1].type == "type_parameter"
        ):
            inner = [c for c in named[1].children if c.is_named]
            return _python_class_ref(inner[0], source) if len(inner) == 1 else None
        return None
    if kind == "binary_operator":
        left, right = node.child_by_field_name("left"), node.child_by_field_name("right")
        if right is not None and right.type == "none":
            return _python_class_ref(left, source)
        if left is not None and left.type == "none":
            return _python_class_ref(right, source)
    return None

def _python_collect_assignment_targets(node, source: bytes, out: set[str]) -> None:
    """Identifiers bound as `pattern` targets under a Python AST subtree.

    Recurses through `pattern_list` / `tuple_pattern` / `list_pattern` so tuple
    unpacking (`a, b = ...`, `for a, b in ...`) contributes every bound name.
    """
    if node is None:
        return
    if node.type == "identifier":
        out.add(_read_text(node, source))
        return
    if node.type in ("pattern_list", "tuple_pattern", "list_pattern"):
        for c in node.children:
            _python_collect_assignment_targets(c, source, out)

def _python_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]]) -> None:
    """Walk a Python type annotation; append (name, role) where role is 'type' or 'generic_arg'.

    Builtin/typing containers (list, dict, Optional, Union, …) are not emitted as refs themselves,
    but their nested type arguments still count as generic_arg.
    """
    if node is None:
        return
    t = node.type
    if t == "type":
        for c in node.children:
            if c.is_named:
                _python_collect_type_refs(c, source, generic, out)
        return
    if t == "identifier":
        name = _read_text(node, source)
        if name and name not in _PYTHON_TYPE_CONTAINERS and name not in _PYTHON_ANNOTATION_NOISE:
            out.append((name, "generic_arg" if generic else "type"))
        return
    if t == "attribute":
        tail = _read_text(node, source).rsplit(".", 1)[-1]
        if tail and tail not in _PYTHON_TYPE_CONTAINERS and tail not in _PYTHON_ANNOTATION_NOISE:
            out.append((tail, "generic_arg" if generic else "type"))
        return
    if t == "generic_type":
        for c in node.children:
            if c.type == "identifier":
                container = _read_text(c, source)
                if container and container not in _PYTHON_TYPE_CONTAINERS and container not in _PYTHON_ANNOTATION_NOISE:
                    out.append((container, "generic_arg" if generic else "type"))
            elif c.type == "type_parameter":
                for sub in c.children:
                    if sub.is_named:
                        _python_collect_type_refs(sub, source, True, out)
        return
    if t == "subscript":
        value = node.child_by_field_name("value")
        if value is not None:
            _python_collect_type_refs(value, source, generic, out)
        for c in node.children:
            if c is value or not c.is_named:
                continue
            _python_collect_type_refs(c, source, True, out)
        return
    if node.is_named:
        for c in node.children:
            if c.is_named:
                _python_collect_type_refs(c, source, generic, out)

def _python_collect_param_refs(params_node, source: bytes) -> list[tuple[str, str]]:
    """Collect type refs from each typed parameter under a `parameters` node."""
    out: list[tuple[str, str]] = []
    if params_node is None:
        return out
    for child in params_node.children:
        if child.type in ("typed_parameter", "typed_default_parameter"):
            type_node = child.child_by_field_name("type")
            _python_collect_type_refs(type_node, source, False, out)
    return out

def _python_decorator_name(deco_node, source: bytes) -> str | None:
    """Return the head symbol of a Python `decorator` node.

    The Python twin of `_ts_decorator_name`, differing only in grammar node
    names: `@traced` -> the identifier; `@retry(times=3)` -> the `function` of
    the `call`; `@app.route("/")` / `@mod.deco` -> the `attribute` (the symbol
    itself, not the module alias it is reached through).
    """
    for child in deco_node.children:
        if not child.is_named:
            continue
        target = child
        if target.type == "call":
            target = target.child_by_field_name("function") or target
        if target.type == "attribute":
            attr = target.child_by_field_name("attribute")
            return _read_text(attr, source) if attr else None
        if target.type == "identifier":
            return _read_text(target, source)
        return None
    return None

def _python_fixture_type(func_node, source: bytes, local_types: dict[str, str | None]) -> str:
    """The class a fixture returns or yields: its return annotation, else every
    `return` / `yield` naming one class (`return CliRunner()`, `yield client`
    after `client = Client()`). Anything else is PYTEST_FIXTURE_UNTYPED."""
    ret = func_node.child_by_field_name("return_type")
    if ret is not None:
        return _python_annotation_class(ret, source) or PYTEST_FIXTURE_UNTYPED
    found: set[str | None] = set()
    body = func_node.child_by_field_name("body")
    stack = list(body.children) if body is not None else []
    while stack:
        node = stack.pop()
        if node.type in ("function_definition", "class_definition", "lambda"):
            continue
        value = None
        if node.type == "return_statement":
            value = next(iter(node.named_children), None)
        elif node.type == "yield":
            value = next(iter(node.named_children), None)
        else:
            stack.extend(node.children)
            continue
        if value is None:
            continue
        if value.type == "call":
            fn = value.child_by_field_name("function")
            name = _read_text(fn, source).rsplit(".", 1)[-1] if fn is not None and fn.type in ("identifier", "attribute") else ""
            found.add(name if name[:1].isupper() else None)
        elif value.type == "identifier":
            found.add(local_types.get(_read_text(value, source)))
        else:
            found.add(None)
    if len(found) == 1:
        only = next(iter(found))
        if only:
            return only
    return PYTEST_FIXTURE_UNTYPED

def _python_is_property(func_node, source: bytes) -> bool:
    """`@property` / `@cached_property` / `@x.getter`: reading the attribute runs it."""
    parent = func_node.parent
    if parent is None or parent.type != "decorated_definition":
        return False
    for dec in parent.children:
        if dec.type != "decorator":
            continue
        expr = next(iter(dec.named_children), None)
        text = _read_text(expr, source) if expr is not None else ""
        if text in _PYTHON_PROPERTY_DECORATORS or text.endswith(".getter"):
            return True
    return False

def _python_is_pytest_fixture(func_node, source: bytes) -> bool:
    parent = func_node.parent
    if parent is None or parent.type != "decorated_definition":
        return False
    for dec in parent.children:
        if dec.type != "decorator":
            continue
        expr = next(iter(dec.named_children), None)
        if expr is not None and expr.type == "call":
            expr = expr.child_by_field_name("function")
        if expr is not None and _read_text(expr, source) in _PYTEST_FIXTURE_DECORATORS:
            return True
    return False

def _python_is_test_module(str_path: str) -> bool:
    name = str_path.replace("\\", "/").rsplit("/", 1)[-1]
    return name == "conftest.py" or (name.startswith("test_") and name.endswith(".py")) or name.endswith("_test.py")

def _python_param_names(params_node, source: bytes) -> set[str]:
    """Plain parameter identifiers declared on a Python `parameters` node.

    Covers positional/keyword params plus `*args` / `**kwargs` and typed or
    default forms — anything that binds a local name the function body can shadow
    a module-level definition with.
    """
    out: set[str] = set()
    if params_node is None:
        return out
    for child in params_node.children:
        if child.type == "identifier":
            out.add(_read_text(child, source))
        elif child.type in (
            "typed_parameter",
            "default_parameter",
            "typed_default_parameter",
            "list_splat_pattern",
            "dictionary_splat_pattern",
        ):
            # The bound name is the first identifier child (the rest is type/default).
            name_n = child.child_by_field_name("name")
            if name_n is None:
                name_n = next(
                    (c for c in child.children if c.type == "identifier"), None
                )
            if name_n is not None:
                out.add(_read_text(name_n, source))
    return out

def _python_self_attr(node, source: bytes) -> str | None:
    """``X`` when ``node`` is the attribute ``self.X`` (#2860), else None."""
    if node is None or node.type != "attribute":
        return None
    obj, attr = node.child_by_field_name("object"), node.child_by_field_name("attribute")
    if obj is None or attr is None or _read_text(obj, source) != "self":
        return None
    return _read_text(attr, source)

def _python_self_attr_bindings(body, source: bytes, local_types: dict[str, str | None] | None = None):
    """Yield ``(attr, type_name)`` for every ``self.attr = ...`` in a method body
    (#2860). ``type_name`` is the annotation (``self.attr: T = ...``) or the bare
    class of ``self.attr = Ctor(...)``, and None for any other value so the
    caller can poison the field; ``self.attr = None`` binds nothing. An unchanged
    typed parameter/local also carries its class through ``self.attr = value``."""
    local_types = local_types or {}
    stack = list(body.named_children)
    while stack:
        node = stack.pop()
        if node.type in ("function_definition", "class_definition", "lambda"):
            continue
        stack.extend(node.named_children)
        left = node.child_by_field_name("left") if node.type == "assignment" else None
        if left is None:
            continue
        value, right = node.child_by_field_name("type"), node.child_by_field_name("right")
        bound_type = None
        if value is None and right is not None:
            if right.type == "none":
                continue
            if right.type == "identifier":
                bound_type = local_types.get(_read_text(right, source))
            value = right.child_by_field_name("function") if right.type == "call" else None
        name = _read_text(value, source) if value is not None else (bound_type or "")
        typed = name.isidentifier() and name[:1].isupper()
        for target in (left.named_children if left.type == "pattern_list" else [left]):
            attr = _python_self_attr(target, source)
            if attr:
                yield attr, (name if typed and target is left else None)

def _python_untouched_params(func_node, source: bytes) -> set[str]:
    """Parameters with no annotation and no default that the body never rebinds:
    the ones pytest may fill with a fixture."""
    params = func_node.child_by_field_name("parameters")
    names: set[str] = set()
    if params is not None:
        for child in params.children:
            if child.type == "identifier":
                names.add(_read_text(child, source))
    rebound: set[str] = set()
    body = func_node.child_by_field_name("body")
    stack = list(body.children) if body is not None else []
    while stack:
        node = stack.pop()
        if node.type in ("function_definition", "class_definition", "lambda"):
            continue
        if node.type in ("assignment", "augmented_assignment", "for_statement", "for_in_clause"):
            _python_collect_assignment_targets(node.child_by_field_name("left"), source, rebound)
        elif node.type == "named_expression":
            _python_collect_assignment_targets(node.child_by_field_name("name"), source, rebound)
        elif node.type in ("as_pattern_target", "global_statement", "nonlocal_statement", "delete_statement"):
            stack_ids = [node]
            while stack_ids:
                cur = stack_ids.pop()
                if cur.type == "identifier":
                    rebound.add(_read_text(cur, source))
                stack_ids.extend(cur.children)
        stack.extend(node.children)
    return names - rebound - {"self", "cls"}

def _read_csharp_type_name(node, source: bytes) -> tuple[str, bool, str] | None:
    """Resolve a C# type name, whether it was qualified, and its qualifier prefix."""
    if node is None:
        return None
    if node.type in ("identifier", "predefined_type"):
        return (_read_text(node, source), False, "")
    if node.type == "qualified_name":
        prefix, _, tail = _read_text(node, source).rpartition(".")
        tail = tail.split("<", 1)[0]
        return (tail, True, prefix)
    if node.type == "generic_name":
        name_node = node.child_by_field_name("name")
        if name_node is not None:
            qualified = name_node.type == "qualified_name"
            prefix, _, tail = _read_text(name_node, source).rpartition(".")
            return (tail, qualified, prefix if qualified else "")
    for child in node.children:
        if not child.is_named:
            continue
        result = _read_csharp_type_name(child, source)
        if result:
            return result
    return None

def _csharp_deferred_call(invocation, source: bytes) -> list | None:
    """``[receiver, method, type args]`` for ``var x = R.M<A>(...)`` (#4266).

    The variable's type is the return type of the called method, which may be
    declared in another file, so the cross-file pass resolves it. ``receiver``
    is an identifier, ``"this"`` or ``""`` (unqualified call); each type
    argument is its class name or None. Any other call shape returns None.
    """
    fn = invocation.child_by_field_name("function")
    recv = ""
    if fn is not None and fn.type == "member_access_expression":
        inner = fn.child_by_field_name("expression")
        fn = fn.child_by_field_name("name")
        if inner is not None and inner.type in ("this", "this_expression"):
            recv = "this"
        elif inner is not None and inner.type == "identifier":
            recv = _read_text(inner, source)
        else:
            return None
    if fn is None or fn.type not in ("identifier", "generic_name"):
        return None
    args: list[str | None] = []
    if fn.type == "generic_name":
        tal = next((c for c in fn.children if c.type == "type_argument_list"), None)
        for arg in tal.named_children if tal is not None else []:
            args.append(_csharp_receiver_type_name(arg, source))
        name_node = next((c for c in fn.children if c.type == "identifier"), None)
    else:
        name_node = fn
    if name_node is None:
        return None
    return ["call", recv, _read_text(name_node, source), args]

def _csharp_element_type_name(type_node, source: bytes) -> str | None:
