    """Return Swift generic type-parameter names visible from ``node``.

    A `struct Stack<Element>` / `func map<R>(...)` binds `Element`/`R` as local
    names, not corpus symbols. Walking up to every enclosing declaration's
    `type_parameters` list collects them; a parameter's name is the first
    `type_identifier` of its `type_parameter` node (a constraint like
    `T: Equatable` is a separate `user_type` and is left to reference).
    """
    names: set[str] = set()
    scope = node
    while scope is not None:
        for child in scope.children:
            if child.type != "type_parameters":
                continue
            for param in child.children:
                if param.type != "type_parameter":
                    continue
                for sub in param.children:
                    if sub.type == "type_identifier":
                        name = _read_text(sub, source)
                        if name:
                            names.add(name)
                        break
        scope = scope.parent
    return frozenset(names)

def _swift_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]],
                             skip: frozenset[str] | None = None) -> None:
    """Walk a Swift type expression; append (name, role) tuples (role 'type' or 'generic_arg').

    Generic type parameters in scope (``skip``) are local bindings, not
    references; emitting one mints a sourceless stub (the bare `t` god node a
    `<T>` type or function would otherwise share corpus-wide)."""
    if node is None:
        return
    if skip is None:
        skip = _swift_type_parameters_in_scope(node, source)
    t = node.type
    if t == "type_annotation":
        for c in node.children:
            if c.is_named:
                _swift_collect_type_refs(c, source, generic, out, skip)
        return
    if t == "user_type":
        for c in node.children:
            if c.type == "type_identifier":
                text = _read_text(c, source)
                if text and text != "Self" and text not in skip:
                    out.append((text, "generic_arg" if generic else "type"))
                break
        for c in node.children:
            if c.type == "type_arguments":
                for arg in c.children:
                    if arg.is_named:
                        _swift_collect_type_refs(arg, source, True, out, skip)
        return
    if t == "type_identifier":
        text = _read_text(node, source)
        # `Self` names the enclosing type, not a corpus symbol. Emitting a ref
        # mints a sourceless stub with the bare id `self` that every `-> Self`
        # method collapses onto (a god node), the same keyword-type pitfall as
        # Rust's `Self`. A genuine type (including `Int`/`String` builtin hubs)
        # is unaffected.
        if text and text != "Self" and text not in skip:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t in ("optional_type", "implicitly_unwrapped_optional_type", "array_type",
             "dictionary_type", "tuple_type"):
        for c in node.children:
            if c.is_named:
                _swift_collect_type_refs(c, source, generic, out, skip)
        return
    if node.is_named:
        for c in node.children:
            if c.is_named:
                _swift_collect_type_refs(c, source, generic, out, skip)

def _swift_user_type_name(user_type_node, source: bytes) -> str | None:
    """Return the head type_identifier text from a Swift user_type node (without generics)."""
    if user_type_node is None:
        return None
    for c in user_type_node.children:
        if c.type == "type_identifier":
            text = _read_text(c, source)
            return text or None
    return None

def _ts_decorator_target_name(expr, source: bytes) -> str | None:
    """The symbol a decorator expression applies: the outermost call's name.

    `f` -> f; `f()` / `x.f()` -> f; `@Component({...})` -> Component. A
    parenthesized decorator is unwrapped first. tree-sitter-typescript 0.23.2
    cannot parse a call chain in decorator position (`@(Link().toMany())`): it
    wraps `Link().` in an ERROR and parses `toMany()` as a SIBLING of the ERROR
    inside the parentheses. The applied decorator is still that outermost call,
    which is the last named call child, never the one buried in the ERROR
    (#4711). Without this the whole parenthesized decorator contributed no edge,
    though most of its expression parsed.
    """
    if expr is None:
        return None
    if expr.type == "parenthesized_expression":
        calls = [c for c in expr.named_children if c.type == "call_expression"]
        if calls:
            return _ts_decorator_target_name(calls[-1], source)
        # A recovered non-call expression (an invalid `@(A, B)` sequence lands
        # here as ERROR + `B`) is not a decorator name: do not guess one.
        if any(c.type == "ERROR" for c in expr.named_children):
            return None
        named = [c for c in expr.named_children if c.type != "ERROR"]
        return _ts_decorator_target_name(named[0], source) if named else None
    if expr.type == "call_expression":
        fn = expr.child_by_field_name("function")
        if fn is None:
            return None
        if fn.type == "member_expression":
            prop = fn.child_by_field_name("property")
            return _read_text(prop, source) if prop else None
        if fn.type == "identifier":
            return _read_text(fn, source)
        return None
    if expr.type == "member_expression":
        prop = expr.child_by_field_name("property")
        return _read_text(prop, source) if prop else None
    if expr.type == "identifier":
        return _read_text(expr, source)
    return None

def _ts_decorator_name(deco_node, source: bytes) -> str | None:
    """Return the head symbol of a TS `decorator` node.

    `@Injectable` -> the identifier; `@Component({...})` / `@Input()` -> the
    `function` of the call_expression; `@ng.Component()` / `@core.Injectable` ->
    the `property` of the member_expression (the imported symbol, not the
    namespace alias); `@(Link().toMany())` -> the outermost call, `toMany`.
    """
    for child in deco_node.children:
        if not child.is_named:
            continue
        return _ts_decorator_target_name(child, source)
    return None

def _ts_field_destructured_from_this(ident, name: str, source: bytes) -> str | None:
    """The `this` field that ``name`` was destructured from, or None.

    `const { creator } = this` and `const { creator: c } = this` in the function
    around the call (or around an arrow function holding it, since an arrow keeps
    the outer `this`) make `creator` / `c` the `creator` field. The search stops at
    the first function that binds its own `this`, and only reads declarations of
    that function itself, not of functions nested in it."""
    node = ident.parent
    while node is not None:
        if node.type in _TS_FUNCTION_NODES:
            body = node.child_by_field_name("body")
            stack = [body] if body is not None else []
            while stack:
                n = stack.pop()
                if n.type == "variable_declarator":
                    pattern, value = n.child_by_field_name("name"), n.child_by_field_name("value")
                    if (pattern is not None and pattern.type == "object_pattern"
                            and value is not None and value.type == "this"):
                        for p in pattern.named_children:
                            if p.type == "shorthand_property_identifier_pattern" and _read_text(p, source) == name:
                                return name
                            if p.type == "pair_pattern":
                                key, val = p.child_by_field_name("key"), p.child_by_field_name("value")
                                if (key is not None and val is not None and val.type == "identifier"
                                        and _read_text(val, source) == name):
                                    return _read_text(key, source)
                stack.extend(c for c in n.children if c.type not in _TS_FUNCTION_NODES)
            if node.type != "arrow_function":
                return None
        node = node.parent
    return None

def _ts_in_static_method(node) -> bool:
    """Whether ``node`` runs in a `static` method, where `this` is the class.
    Arrow functions keep the enclosing `this`; other functions end the search."""
    while node is not None:
        if node.type == "method_definition":
            return any(c.type == "static" for c in node.children)
        if node.type in _TS_FUNCTION_NODES and node.type != "arrow_function":
            return False
        node = node.parent
    return False

def _ts_mark_public_twins(root, source: bytes, result: dict) -> None:
    """Mark the member nodes that stand for both a public `name` and `#name`.

    A class's `foo` and `#foo` get one node id (ids drop `#`), labeled after
    whichever is declared first, and a public property (`newResponse = () => ..`)
    has no node of its own, so it shares the `#newResponse()` node. A call
    written `c.foo()` may only reach that node when the class really declares a
    public `foo`; with `#foo` alone the public `foo` comes from somewhere else (a
    base class), and the node is not its target. The mark lives on the node so
    a changed-files rebuild, which reads unchanged files from graph.json, sees it.
    """
    shared: dict[str, set[str]] = {}
    stack = [root]
    while stack:
        n = stack.pop()
        if n.type == "class_body" and n.parent is not None:
            cls = n.parent.child_by_field_name("name")
            public: set[str] = set()
            private: set[str] = set()
            for member in n.named_children:
                if member.type not in ("method_definition", "public_field_definition", "field_definition"):
                    continue
                name = member.child_by_field_name("name") or member.child_by_field_name("property")
                if name is None:
                    continue
                text = _read_text(name, source)
                if name.type == "private_property_identifier":
                    private.add(text.lstrip("#"))
                elif name.type == "property_identifier":
                    public.add(text)
            if cls is not None and public & private:
                shared.setdefault(_read_text(cls, source), set()).update(public & private)
        stack.extend(n.children)
    if not shared:
        return
    labels = {n["id"]: n.get("label", "") for n in result.get("nodes", [])}
    marked = {
        e["target"]
        for e in result.get("edges", [])
        if e.get("relation") == "method"
        and str(labels.get(e["target"], "")).strip("()").lstrip(".").lstrip("#")
        in shared.get(str(labels.get(e["source"], "")), set())
    }
    for n in result.get("nodes", []):
        if n["id"] in marked:
            n["_ts_public_twin"] = True

def _js_member_nid(class_nid: str, member_node, name: str, source: bytes,
                   groups_cache: dict) -> str:
    """Node id for a JS/TS class member, salted when a sibling collides (#4475).

    ``make_id`` drops ``_``, ``$`` and ``#``, so ``updateHash`` / ``_updateHash``,
    ``close`` / ``#close`` and ``set`` / ``$set`` in one class body mint one id
    and the second declaration vanished. The member names of the enclosing
    class body are grouped by the id they would get (methods, signatures and
    function-valued fields, the members the walk turns into ``.name()`` nodes),
    then ``_underscore_salted_nid`` applies the Python/C# rule: a unique public
    name keeps the plain id, every other colliding name gets a salted one.
    Members that collide with nothing keep their old id. Getter/setter pairs
    and overloads share one name, so they are not a collision.
    """
    body = member_node.parent
    if body is None:
        return _make_id(class_nid, name)
    key = (class_nid, body.start_byte, body.end_byte)
    groups = groups_cache.get(key)
    if groups is None:
        names: dict[str, set[str]] = {}
        for c in body.children:
            if c.type in _JS_MEMBER_METHOD_TYPES:
                name_node = c.child_by_field_name("name")
            elif c.type in ("field_definition", "public_field_definition"):
                value = c.child_by_field_name("value")
                if value is None or value.type not in _JS_FUNCTION_VALUE_TYPES:
                    continue
                name_node = c.child_by_field_name("property") or c.child_by_field_name("name")
            else:
                continue
            text = _read_text(name_node, source) if name_node is not None else ""
            if text:
                names.setdefault(_make_id(class_nid, text), set()).add(text)
        groups = {nid: ns for nid, ns in names.items() if len(ns) >= 2}
        groups_cache[key] = groups
    return _underscore_salted_nid(_make_id(class_nid, name), name, groups,
                                  _JS_PRIVATE_MEMBER_PREFIXES)

def _atom(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] == "'":
        return value[1:-1]
    return value

def _descendants(node: Node) -> Iterable[Node]:
    for child in node.named_children:
        yield child
        yield from _descendants(child)

def resolve_erlang_remote_calls(
    per_file: list[dict], all_nodes: list[dict], all_edges: list[dict]
) -> None:
    """Resolve module-qualified calls by exact module, name, and arity."""
    functions: dict[tuple[str, str, int], list[str]] = {}
    for node in all_nodes:
        metadata = node.get("metadata")
        if not isinstance(metadata, dict) or metadata.get("language") != "erlang":
            continue
        if metadata.get("kind") != "function":
            continue
        module = metadata.get("module")
        name = metadata.get("name")
        arity = metadata.get("arity")
        if isinstance(module, str) and isinstance(name, str) and isinstance(arity, int):
            functions.setdefault((module, name, arity), []).append(node["id"])

    existing = {
        (edge.get("source"), edge.get("target"))
        for edge in all_edges
        if edge.get("relation") == "calls"
    }
    for result in per_file:
        for call in result.get("raw_calls", []):
            if call.get("language") != "erlang" or not call.get("remote_module"):
                continue
            key = (
                str(call["remote_module"]),
                str(call.get("callee", "")),
                int(call.get("arity", -1)),
            )
            candidates = functions.get(key, [])
            caller = call.get("caller_nid")
            if len(candidates) != 1 or candidates[0] == caller:
                continue
            pair = (caller, candidates[0])
            if pair in existing:
                continue
            existing.add(pair)
            all_edges.append({
                "source": caller,
                "target": candidates[0],
                "relation": "calls",
                "context": "remote_call",
                "confidence": "EXTRACTED",
                "confidence_score": 1.0,
                "source_file": call.get("source_file", ""),
                "source_location": call.get("source_location"),
                "weight": 1.0,
            })

def _go_collect_type_refs(node, source: bytes, generic: bool, out: list[tuple[str, str]],
                          skip: frozenset[str] = frozenset()) -> None:
    """Walk a Go type expression; append (name, role) tuples.

    Names in ``skip`` (the enclosing declaration's generic type parameters) are
    local bindings, not references, and are dropped.
    """
    if node is None:
        return
    t = node.type
    if t == "type_identifier":
        text = _read_text(node, source)
        if text and text not in _GO_PREDECLARED_TYPES and text not in skip:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t == "qualified_type":
        # Keep the package qualifier so the generic stub rewire cannot attach
        # `testing.T` to an unrelated local type or function named T.
        text = _read_text(node, source)
        if text:
            out.append((text, "generic_arg" if generic else "type"))
        return
    if t == "generic_type":
        type_field = node.child_by_field_name("type")
        if type_field is not None:
            sub: list[tuple[str, str]] = []
            _go_collect_type_refs(type_field, source, generic, sub, skip)
            out.extend(sub)
        for c in node.children:
            if c.type == "type_arguments":
                for arg in c.children:
                    if arg.is_named:
                        _go_collect_type_refs(arg, source, True, out, skip)
        return
    if t in ("pointer_type", "slice_type", "array_type", "map_type",
             "channel_type", "parenthesized_type"):
        for c in node.children:
            if c.is_named:
                _go_collect_type_refs(c, source, generic, out, skip)
        return
    if node.is_named:
        for c in node.children:
            if c.is_named:
                _go_collect_type_refs(c, source, generic, out, skip)

def _go_receiver_type_table(root, source: bytes) -> dict[str, str]:
    """Collect ``name -> TypeName`` for every Go receiver whose type is written down.

    Four sources: a struct field, a parameter (which covers the method receiver
    `func (s *Server)`), `var x T`, and `x := T{}` / `x := &T{}`. Flat over the subtree it is
    given, first binding wins — run over one function it is that function's own scope, and
    over the file it is the fallback for a struct field. Children are pushed reversed so the
    walk yields document order and "first" means first in the source.
    """
    table: dict[str, str] = {}
    stack = [root]
    while stack:
        n = stack.pop()
        t = n.type
        if t in ("field_declaration", "parameter_declaration", "var_spec"):
            type_name = _go_single_type_name(n.child_by_field_name("type"), source)
            for c in n.children if type_name else ():
                if c.type in ("field_identifier", "identifier"):
                    table.setdefault(_read_text(c, source), type_name)
        elif t == "short_var_declaration":
            left, right = n.child_by_field_name("left"), n.child_by_field_name("right")
            if left is not None and right is not None:
                names = [c for c in left.children if c.type == "identifier"]
                values = [c for c in right.children if c.is_named]
                for name_node, value in zip(names, values):
                    if value.type == "unary_expression":
                        value = value.child_by_field_name("operand") or value
                    if value.type != "composite_literal":
                        continue
                    type_name = _go_single_type_name(
                        value.child_by_field_name("type"), source)
                    if type_name:
                        table.setdefault(_read_text(name_node, source), type_name)
        stack.extend(reversed(n.children))
    return table

def _go_type_param_names(decl_node, source: bytes) -> frozenset[str]:
    """Names bound by a declaration's generic type parameters.

    Covers a function/type's own `[T any, R comparable]` list and, for a method,
    the receiver's `(b Box[T])` type arguments (Go methods cannot declare their
    own type parameters; they reuse the receiver's). These names are local
    bindings, not corpus symbols, so a signature's use of them must not mint a
    sourceless stub.
    """
    names: set[str] = set()
    for child in decl_node.children:
        if child.type != "type_parameter_list":
            continue
        for decl in child.children:
            if decl.type != "type_parameter_declaration":
                continue
            for c in decl.children:
                if c.type == "identifier":
                    text = _read_text(c, source)
                    if text:
                        names.add(text)
    receiver = decl_node.child_by_field_name("receiver")
    if receiver is not None:
        stack = [receiver]
        while stack:
            n = stack.pop()
            if n.type == "type_arguments":
                leaves = [n]
                while leaves:
                    leaf = leaves.pop()
                    if leaf.type == "type_identifier":
                        text = _read_text(leaf, source)
                        if text:
                            names.add(text)
                    leaves.extend(leaf.children)
                continue
            stack.extend(n.children)
    return frozenset(names)

def _is_external_link(target: str) -> bool:
    low = target.lower()
    return "://" in target or low.startswith(("mailto:", "tel:", "//", "data:"))

def _nfc(s: str) -> str:
    # Filesystems disagree on Unicode normalization (macOS decomposes, others
    # do not); a link typed in NFC must still find a file listed in NFD.
    return unicodedata.normalize("NFC", s)

def _build_link_index(root: Path) -> "dict[str, list[tuple[int, str, Path]]]":
    """Index every linkable document under *root* by NFC-normalized basename.

    Each entry maps basename -> [(depth, root-relative posix path, absolute
    path)]. Directories in detect._SKIP_DIRS, dot-directories, and paths
    excluded by .graphifyignore/.gitignore are pruned — the same corpus
    boundary the scanner draws, and Obsidian itself does not index dot-folders
    or ignored paths (#3822).
    """
    from graphify.detect import _SKIP_DIRS, ignored_predicate
    root = Path(root)
    ignored = ignored_predicate(root)
    index: dict[str, list[tuple[int, str, Path]]] = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dp = Path(dirpath)
        dirnames[:] = sorted(
            d for d in dirnames
            if not d.startswith(".") and d not in _SKIP_DIRS and not ignored(dp / d)
        )
        for fname in filenames:
            if Path(fname).suffix.lower() not in _MD_LINKABLE_EXTS:
                continue
            abs_path = dp / fname
            if ignored(abs_path):
                continue
            rel = os.path.relpath(str(abs_path), str(root)).replace("\\", "/")
            index.setdefault(_nfc(fname), []).append(
                (rel.count("/"), _nfc(rel), abs_path)
            )
    return index

def _parse_frontmatter_fallback(fm_lines: list[str]) -> dict:
    """Flat `key: value` parser for when PyYAML is not installed.

    Nested blocks and list items are skipped rather than guessed at; the keys
    that matter for graph filtering (``type``, ``review_status``, ``title``)
    are flat scalars in practice.
    """
    out: dict = {}
    for raw in fm_lines:
        if not raw[:1].strip():
            continue  # indented -> belongs to a nested block, skip
        m = _MD_FM_SCALAR_RE.match(raw.strip())
        if not m:
            continue
        key, value = m.group(1).strip(), m.group(2).strip()
        if not value:
            continue  # a bare `key:` opens a nested block
        out[key] = value.strip('"\'')
    return out

def _parse_frontmatter(fm_lines: list[str]) -> dict:
    """Parse frontmatter lines into a plain dict.

    Values are passed through ``sanitize_metadata`` by the caller, so nested
    dicts and lists survive (a review workflow's ``coherence_check:`` block,
    Obsidian ``aliases:``) while staying bounded and HTML-safe.
    """
    if not fm_lines:
        return {}
    text = "\n".join(fm_lines)
    try:
        import yaml
    except ImportError:
        return _parse_frontmatter_fallback(fm_lines)
    try:
        data = yaml.safe_load(text)
    except Exception:
        # Malformed YAML in one document must not fail the whole extraction.
        return _parse_frontmatter_fallback(fm_lines)
    return data if isinstance(data, dict) else {}

def _vault_lookup(target: str, root: Path) -> "Path | None":
    """Resolve *target* (a normalized wikilink path, `.md` already appended)
    against the corpus under *root*, or None when nothing matches.

    A bare name matches by basename; a path-qualified target
    (``folder/name.md``) must match its full segment suffix. Ties break to the
    shallowest match, then lexicographically — mirroring Obsidian, where a
    root-level file wins a bare-link name collision — so resolution is
    deterministic regardless of walk order.
    """
    root_key = str(root)
    index = _MD_LINK_INDEX_CACHE.get(root_key)
    if index is None:
        try:
            index = _build_link_index(root)
        except OSError:
            index = {}
        _MD_LINK_INDEX_CACHE[root_key] = index
    parts = _nfc(target.replace("\\", "/")).split("/")
    candidates = index.get(parts[-1])
    if not candidates:
        return None
    suffix = "/".join(parts)
    matches = [
        c for c in candidates
        if c[1] == suffix or c[1].endswith("/" + suffix)
    ]
    if not matches:
        # Obsidian writes vault-relative paths, so scanning a folder below the
        # vault root meets links that start with that folder's own path
        # ([[Corp/wiki/Fox]] from inside Corp/, #4559). Drop the longest such
        # leading run and match the rest from the scan root.
        root_parts = [_nfc(p) for p in Path(root).parts]
        for k in range(len(parts) - 1, 0, -1):
            if parts[:k] == root_parts[-k:]:
                rest = "/".join(parts[k:])
                matches = [c for c in candidates if c[1] == rest]
                break
    if not matches:
        return None
    return min(matches)[2]

def _objc_local_var_types(body_node, source: bytes, table: dict[str, str]) -> None:
    """Collect ``var -> ClassName`` from ObjC local declarations (``Foo *f = ...;``)
    in a method body, for receiver typing in the cross-file message-send pass
    (#1556). Only a capitalized ``type_identifier`` with a single named declarator
    is recorded; a built-in/lower-cased type or an un-nameable declarator is skipped
    (precision over recall). Reuses the C++ declarator unwrapper (identical grammar).
    """
    stack = [body_node]
    while stack:
        n = stack.pop()
        if n.type == "method_definition" and n is not body_node:
            continue
        if n.type == "declaration":
            type_node = n.child_by_field_name("type")
            if type_node is None:
                for c in n.children:
                    if c.type == "type_identifier":
                        type_node = c
                        break
            if type_node is not None and type_node.type == "type_identifier":
                type_name = _read_text(type_node, source).strip()
                declarators = [
                    c for c in n.children
                    if c.type in ("identifier", "pointer_declarator", "init_declarator")
                ]
                if type_name and type_name[:1].isupper() and len(declarators) == 1:
                    var = _cpp_declarator_name(declarators[0], source)
                    if var and var not in table:
                        table[var] = type_name
        for c in n.children:
            stack.append(c)

def _pascal_find_body(text: str, start: int) -> tuple[int, int]:
    """Find balanced begin..end after start. Returns (body_start, body_end).
    Returns (0, 0) if no begin found.
    """
    m = re.search(r"\bbegin\b", text[start:], re.IGNORECASE)
    if not m:
        return (0, 0)
    body_start = start + m.end()
    depth = 1
    for tok in _PAS_BEGIN_END_TOKEN_RE.finditer(text, body_start):
        kw = tok.group(1).lower()
        if kw in ("begin", "case", "try", "asm", "record"):
            depth += 1
        elif kw == "end":
            depth -= 1
            if depth == 0:
                return (body_start, tok.start())
    return (body_start, len(text))

def _pascal_split_bases(s: str) -> list[str]:
    """Split inheritance list, handling generics like TList<T, U>."""
    out, depth, buf = [], 0, []
    for ch in s:
        if ch == "<":
            depth += 1
            buf.append(ch)
        elif ch == ">":
            depth -= 1
            buf.append(ch)
        elif ch == "," and depth == 0:
            name = re.sub(r"<.*$", "", "".join(buf).strip())
            if name:
                out.append(name)
            buf = []
        else:
            buf.append(ch)
    name = re.sub(r"<.*$", "", "".join(buf).strip())
    if name:
        out.append(name)
    return [n for n in out if re.match(r"[A-Za-z_]\w*$", n)]

def _pascal_split_uses(s: str) -> list[str]:
    """Split a uses list string, handling 'Foo in ''bar.pas''' syntax."""
    out = []
    for chunk in s.split(","):
        name = re.split(r"\s+in\s+", chunk.strip(), maxsplit=1, flags=re.IGNORECASE)[0]
        name = name.strip().strip(";")
        if name and re.match(r"[A-Za-z_][\w.]*$", name):
            out.append(name)
    return out

def _unquote(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        return value[1:-1]
    return value

def resolve_r_sourced_calls(
    per_file: list[dict], all_nodes: list[dict], all_edges: list[dict]
) -> None:
    """Resolve calls only through an explicit source relationship."""
    file_source_by_id = {
        node["id"]: str(node["source_file"])
        for node in all_nodes
        if node.get("source_file")
        and node.get("label") == Path(str(node["source_file"])).name
    }
    sourced_files: dict[str, set[str]] = {}
    for edge in all_edges:
        if edge.get("relation") != "imports_from":
            continue
        target_id = edge.get("target")
        if not isinstance(target_id, str):
            continue
        target_source = file_source_by_id.get(target_id)
        if target_source:
            sourced_files.setdefault(edge["source"], set()).add(target_source)

    file_id_by_source = {source: nid for nid, source in file_source_by_id.items()}
    callables: dict[tuple[str, str], list[str]] = {}
    for node in all_nodes:
        if not node.get("_callable") or not node.get("source_file"):
            continue
        name = str(node.get("label", "")).strip("()")
        callables.setdefault((str(node["source_file"]), name), []).append(node["id"])

    existing = {
        (edge.get("source"), edge.get("target"))
        for edge in all_edges
        if edge.get("relation") == "calls"
    }
    for result in per_file:
        for call in result.get("raw_calls", []):
            if call.get("language") != "r":
                continue
            caller = call.get("caller_nid")
            caller_file = file_id_by_source.get(str(call.get("source_file", "")))
            if caller_file is None:
                continue
            candidates: list[str] = []
            for source in sourced_files.get(caller_file, set()):
                candidates.extend(callables.get((source, str(call.get("callee", ""))), []))
            if len(candidates) != 1 or candidates[0] == caller:
                continue
            pair = (caller, candidates[0])
            if pair in existing:
                continue
            existing.add(pair)
            all_edges.append({
                "source": caller,
                "target": candidates[0],
                "relation": "calls",
                "context": "sourced_call",
                "confidence": "EXTRACTED",
                "confidence_score": 1.0,
                "source_file": call.get("source_file", ""),
                "source_location": call.get("source_location"),
                "weight": 1.0,
            })

def _declared_language_suffixes(target_exts: tuple[str, ...]) -> tuple[str, ...]:
    """Return declared literal suffixes for these languages in deterministic order."""
    # Mapping keys must be single suffixes, never relative path fragments.
    suffixes = [
        source_ext
        for source_ext, target_ext in get_language_overrides().items()
        if target_ext in target_exts
        and Path(f"x{source_ext}").suffix == source_ext
    ]
    return tuple(sorted(suffixes))

def _importer_platform(start_dir: Path) -> str | None:
    """Best-effort platform of the importing file, from its directory path.

    Exports conditions and platform-suffixed files are chosen per importer
    (#3487), and `start_dir` is the importer's directory — the filename itself
    is not available at this point, so a platform-named segment is the signal.
    Returns None when nothing distinguishes the importer, which leaves every
    platform at the same priority afterwards."""
    for part in reversed(start_dir.parts):
        segment = part.lower()
        for platform, hints in _PLATFORM_PATH_HINTS:
            if segment in hints:
                return platform
    return None

def _is_python_package_dir(directory: Path, suffixes: tuple[str, ...] = (".py",)) -> bool:
    if any(
        (directory / f"__init__{suffix}").is_file()
        and effective_suffix(directory / f"__init__{suffix}") in suffixes
        for suffix in suffixes
    ):
        return True
    return any(
        (directory / f"__init__{suffix}").is_file()
        for suffix in _declared_language_suffixes(suffixes)
        if suffix not in suffixes
    )

def _is_type_like_definition(node: dict) -> bool:
    if node.get("type") == "namespace":
        return False
    label = str(node.get("label", "")).strip()
    if not label:
        return False
    if label.endswith(")") or label.startswith("."):
        return False
    # A dotted label names a namespace or module in most languages, but a SQL
    # table is `schema.name`: it is a type-like definition a reference can bind to.
    if "." in label and not str(node.get("source_file", "")).lower().endswith(".sql"):
        return False
    return node.get("file_type") == "code"

def _js_call_identifier(node, source: bytes) -> str | None:
    if node.type != "call_expression":
        return None
    function_node = node.child_by_field_name("function")
    if function_node is None:
        for child in node.children:
            if child.is_named:
                function_node = child
                break
    if function_node is not None and function_node.type in ("identifier", "type_identifier"):
        return _read_text(function_node, source)
    return None

def _js_default_import_name(node, source: bytes) -> str | None:
    """Local binding of a default import: the `Foo` in `import Foo from './x'`.

    The default binding is a bare identifier child of the import_clause (named
    imports live in a `named_imports` node, namespace imports in a
    `namespace_import` node), so it is also picked up from the mixed form
    `import Foo, { Bar } from './x'`.
    """
    for child in node.children:
        if child.type == "import_clause":
            for sub in child.children:
                if sub.type == "identifier":
                    return _read_text(sub, source)
    return None

def _js_export_clause(node):
    for child in node.children:
        if child.type == "export_clause":
            return child
    return None

def _js_lexical_aliases(node, source: bytes) -> list[tuple[str, str]]:
    aliases: list[tuple[str, str]] = []
    if node.type != "lexical_declaration":
        return aliases
    for child in node.children:
        if child.type != "variable_declarator":
            continue
        name_node = child.child_by_field_name("name")
        value_node = child.child_by_field_name("value")
        if (
            name_node is not None
            and value_node is not None
            and value_node.type in ("identifier", "type_identifier")
        ):
            aliases.append((_read_text(name_node, source), _read_text(value_node, source)))
    return aliases

def _js_exported_declaration_names(node, source: bytes) -> list[str]:
    names: list[str] = []
    declaration = node.child_by_field_name("declaration")
    if declaration is None:
        return names

    if declaration.type in ("lexical_declaration", "variable_declaration"):
        # Preserve legacy aggregate-pattern facts for identifier-valued lexical
        # declarations; individual destructured bindings are a separate feature.
        names.extend(alias for alias, _target in _js_lexical_aliases(declaration, source))
        for declarator in declaration.named_children:
            if declarator.type != "variable_declarator":
                continue
            name_node = declarator.child_by_field_name("name")
            if name_node is not None and name_node.type == "identifier":
                name = _read_text(name_node, source)
                if name not in names:
                    names.append(name)
        return names

    if declaration.type in (
        "class_declaration",
        "abstract_class_declaration",
        "interface_declaration",
        "type_alias_declaration",
        "function_declaration",
    ):
        name_node = declaration.child_by_field_name("name")
        if name_node is not None:
            names.append(_read_text(name_node, source))
    return names

def _js_module_specifier(node, source: bytes) -> str | None:
    source_node = node.child_by_field_name("source")
    if source_node is None and node.type != "export_statement":
        for child in node.children:
            if child.type == "string":
                source_node = child
                break
    if source_node is None:
        return None
    raw = _read_text(source_node, source).strip()
    return raw.strip("'\"`") or None

def _js_namespace_export_name(node, source: bytes) -> str | None:
    for child in node.children:
        if child.type != "namespace_export":
            continue
        for sub in child.children:
            if sub.type == "identifier":
                return _read_text(sub, source) or None
    return None

def _js_top_level_function_bodies(path: Path, root_node, source: bytes) -> list[tuple[str, object]]:
    bodies: list[tuple[str, object]] = []
    stem = _file_stem(path)
    # A top-level `export function f(){}` / `export const g = () => {}` is an
    # export_statement WRAPPING the declaration, not a bare program child, so
    # scanning only direct children missed every exported function — and the
    # calls inside them never became `uses` facts, so an aliased-import call
    # (`import { bar as baz }; baz()`) never resolved through the import table
    # (#3346). Unwrap a non-re-export export_statement to its inner declaration
    # so exported and non-exported functions are treated identically.
    top_nodes: list = []
    for node in root_node.children:
        if node.type == "export_statement" and not any(
            c.type == "string" for c in node.children  # `export ... from '...'` is a re-export
        ):
            top_nodes.extend(
                c for c in node.children
                if c.type in ("function_declaration", "lexical_declaration")
            )
        else:
            top_nodes.append(node)
    for node in top_nodes:
        if node.type == "function_declaration":
            name_node = node.child_by_field_name("name")
            body = node.child_by_field_name("body")
            if name_node is not None and body is not None:
                bodies.append((_make_id(stem, _read_text(name_node, source)), body))
            continue
        if node.type != "lexical_declaration":
            continue
        for child in node.children:
            if child.type != "variable_declarator":
                continue
            name_node = child.child_by_field_name("name")
            value_node = child.child_by_field_name("value")
            if (
                name_node is not None
                and value_node is not None
                and value_node.type == "arrow_function"
            ):
                bodies.append((_make_id(stem, _read_text(name_node, source)), value_node))
    return bodies

def _match_subpath_import(raw: str, pattern: str) -> "tuple[int, str, bool] | None":
    """Node semantics for an `imports` key: exact match, or a single `*` wildcard.

    Stricter than _match_tsconfig_alias on purpose: `#utils` must NOT match
    `#utils/x` (Node treats a non-wildcard key as an exact specifier). Returns
    (specificity, captured, is_wildcard); lower specificity wins, longest
    literal prefix first among wildcards, mirroring Node's pattern ranking.
    """
    if "*" in pattern:
        if pattern.count("*") != 1:
            return None
        prefix, suffix = pattern.split("*", 1)
        if not raw.startswith(prefix) or not raw.endswith(suffix):
            return None
        end = len(raw) - len(suffix) if suffix else len(raw)
        if end < len(prefix):
            return None
        return -len(prefix), raw[len(prefix):end], True
    if raw == pattern:
        return -(len(pattern) + 1_000_000), "", False
    return None

def _match_tsconfig_alias(raw: str, pattern: str) -> "tuple[tuple[int, int], str, bool] | None":
    """Return (specificity, captured text, is_wildcard) when pattern matches raw.

    Exact aliases win first. Wildcard aliases follow TypeScript's longest-prefix
    rule. The final branch preserves Graphify's existing support for treating a
    non-wildcard alias as a directory prefix, but only after real wildcard matches.
    """
    if "*" in pattern:
        if pattern.count("*") != 1:
            return None
        prefix, suffix = pattern.split("*", 1)
        if not raw.startswith(prefix) or not raw.endswith(suffix):
            return None
        end = len(raw) - len(suffix) if suffix else len(raw)
        if end < len(prefix):
            return None
        return (1, -len(prefix)), raw[len(prefix):end], True

    if raw == pattern:
        return (0, -len(pattern)), "", False

    prefix = pattern.rstrip("/")
    if prefix and raw.startswith(prefix + "/"):
        return (2, -len(prefix)), raw[len(prefix):].lstrip("/"), False
    return None

def _pascal_resolve_class(from_path: Path, class_name: str) -> str | None:
    """Resolve a Pascal class/interface name to the node ID of its defining file's class node.

    Pascal convention: TFooBar is defined in FooBar.pas, IFooBar in FooBar.pas.
    Strips the leading T/I prefix, finds the file, and returns
    _make_id(_file_stem(found_file), class_name).

    Returns None when no matching file is found on disk (RTL, stdlib, or
    unconventionally-named class — caller should create a stub node).
    """
    prefix = class_name[:1]
    unit_name = class_name[1:] if prefix in ("T", "I") else class_name

    root = _pascal_project_root(from_path)
    root_key = str(root)
    if root_key not in _pascal_class_stem_cache:
        stem_map: dict[str, str] = {}
        for ext in (".pas", ".pp", ".dpr", ".dpk"):
            for f in root.rglob("*" + ext):
                stem_map[f.stem.lower()] = _file_stem(f)
        _pascal_class_stem_cache[root_key] = stem_map

    file_stem = _pascal_class_stem_cache[root_key].get(unit_name.lower())
    if file_stem:
        return _make_id(file_stem, class_name)
    return None

def _pascal_resolve_unit(from_path: Path, unit_name: str) -> str:
    """Resolve a Pascal unit name to the graphify node ID of its source file.

    Scans all Pascal files under the project root (the highest ancestor that
    directly contains .pas/.dpr files) and returns _make_id(str(matched_path)).
    Result is cached per project root so the rglob runs at most once per
    project.  Falls back to _make_id(unit_name) for units not found on disk
    (e.g. standard RTL units like SysUtils, Windows).
    """
    root = _pascal_project_root(from_path)
    root_key = str(root)
    if root_key not in _pascal_unit_cache:
        unit_map: dict[str, str] = {}
        for ext in (".pas", ".pp", ".dpr", ".dpk", ".inc"):
            for f in root.rglob("*" + ext):
                unit_map[f.stem.lower()] = _make_id(str(f))
        _pascal_unit_cache[root_key] = unit_map
    return _pascal_unit_cache[root_key].get(unit_name.lower(), _make_id(unit_name))

def _pnpm_workspace_globs(workspace_file: Path) -> list[str]:
    globs: list[str] = []
    in_packages = False
    for raw_line in workspace_file.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("packages:"):
            in_packages = True
            continue
        if in_packages and line.startswith("-"):
            value = line[1:].strip().strip("'\"")
            if value and not value.startswith("!"):
                globs.append(value)
            continue
        if in_packages and not raw_line.startswith((" ", "\t")):
            break
    return globs

def _probe_declared_python_module_candidate(candidate: Path) -> Path | None:
    for suffix in _declared_language_suffixes((".py",)):
        init_path = candidate / f"__init__{suffix}"
        if init_path.is_file():
            return init_path
        if candidate.name:
            module_path = candidate.with_suffix(suffix)
            if module_path.is_file():
                return module_path
    return None

def _probe_python_module_candidate(candidate: Path) -> Path | None:
    """Resolve native Python modules and packages before declared suffixes."""
    if candidate.is_dir():
        init_path = candidate / "__init__.py"
        if init_path.is_file() and effective_suffix(init_path) == ".py":
            return init_path
    if candidate.is_file():
        return candidate
    if not candidate.name:
        return _probe_declared_python_module_candidate(candidate)
    py_candidate = candidate.with_suffix(".py")
    if py_candidate.is_file() and effective_suffix(py_candidate) == ".py":
        return py_candidate
    return _probe_declared_python_module_candidate(candidate)

def _python_call_identifier(node, source: bytes) -> str | None:
    if node.type != "call":
        return None
    function_node = node.child_by_field_name("function")
    if function_node is not None and function_node.type == "identifier":
        return _read_text(function_node, source)
    return None

def _python_import_from_module(node, source: bytes) -> tuple[int, str] | None:
    level = 0
    module_name = ""
    for child in node.children:
        if child.type == "import":
            break
        if child.type == "relative_import":
            raw = _read_text(child, source)
            level = len(raw) - len(raw.lstrip("."))
            remainder = raw.lstrip(".")
            if remainder:
                module_name = remainder
            for sub in child.children:
                if sub.type == "dotted_name":
                    module_name = _read_text(sub, source)
        elif child.type == "dotted_name":
            module_name = _read_text(child, source)
    if level == 0 and not module_name:
        return None
    return level, module_name

def _python_imported_names(node, source: bytes) -> list[tuple[str, str]]:
    names: list[tuple[str, str]] = []
    past_import = False
    for child in node.children:
        if child.type == "import":
            past_import = True
            continue
        if not past_import:
            continue
        if child.type == "dotted_name":
            name = _read_text(child, source)
            names.append((name, name.split(".")[-1]))
        elif child.type == "aliased_import":
            name_node = child.child_by_field_name("name")
            alias_node = child.child_by_field_name("alias")
            if name_node is None:
                continue
            name = _read_text(name_node, source)
            local = _read_text(alias_node, source) if alias_node is not None else name.split(".")[-1]
            names.append((name, local))
    return names

def _python_top_level_function_bodies(path: Path, root_node, source: bytes) -> list[tuple[str, object]]:
    bodies: list[tuple[str, object]] = []
    stem = _file_stem(path)
    for node in root_node.children:
        if node.type != "function_definition":
            continue
        name_node = node.child_by_field_name("name")
        body = node.child_by_field_name("body")
        if name_node is not None and body is not None:
            bodies.append((_make_id(stem, _read_text(name_node, source)), body))
    return bodies

def _contained_in_package(resolved: Path, package_dir: Path) -> bool:
    """Guard against `exports` targets that escape the package directory
    (e.g. "./evil": "../../../etc/passwd"). Only accept paths that stay
    within package_dir after resolution."""
    try:
        return _resolve_cached(resolved).is_relative_to(_resolve_cached(package_dir))
    except ValueError:
        return False

def _find_workspace_root(start_dir: Path) -> Path | None:
    current = _resolve_cached(start_dir)
    for candidate in [current, *current.parents]:
        if (candidate / "pnpm-workspace.yaml").exists():
            return candidate
        package_json = candidate / "package.json"
        if package_json.is_file():
            try:
                data = json.loads(package_json.read_text(encoding="utf-8"))
            except Exception:
                continue
            if "workspaces" in data:
                return candidate
    return None

def _go_import_path_for_file(
    source_file: str | Path,
    root: Path,
    module_cache: dict[Path, str | None] | None = None,
) -> str | None:
    """Return the canonical Go import path for a source file inside a module."""
    cache = module_cache if module_cache is not None else {}
    path = Path(source_file)
    if not path.is_absolute():
        path = root / path
    try:
        directory = _resolve_cached(path).parent
    except OSError:
        directory = path.absolute().parent

    module_dir: Path | None = None
    module_path: str | None = None
    for candidate in (directory, *directory.parents):
        if candidate in cache:
            cached = cache[candidate]
            if cached:
                module_dir, module_path = candidate, cached
            break
        go_mod = candidate / "go.mod"
        if not go_mod.is_file():
            continue
        try:
            match = re.search(
                r"(?m)^\s*module\s+([^\s]+)",
                go_mod.read_text(encoding="utf-8"),
            )
        except (OSError, UnicodeError):
            match = None
        module_dir = candidate
        module_path = match.group(1) if match else None
        cache[candidate] = module_path
        break

    if not module_dir or not module_path:
        return None
    try:
        relative_dir = directory.relative_to(module_dir)
    except ValueError:
        return None
    suffix = relative_dir.as_posix()
    return module_path if suffix == "." else f"{module_path}/{suffix}"

def _is_build_output_path(path: Path, package_dir: Path) -> bool:
    """True if path points into a known build-output directory within package_dir."""
    try:
        rel = _resolve_cached(path).relative_to(_resolve_cached(package_dir))
        return bool(rel.parts and rel.parts[0] in _BUILD_OUTPUT_DIRS)
    except ValueError:
        return False

def _js_source_path(source_file: str, root: Path) -> Path | None:
    if not source_file:
        return None
    path = Path(source_file)
    if not path.is_absolute():
        path = root / path
    try:
        return _resolve_cached(path)
    except Exception:
        return path

def _resolve_js_import_path(candidate: Path) -> Path:
    """Resolve a JS/TS/Svelte import target to a local file when it exists."""
    candidate = Path(os.path.normpath(candidate))
    try:
        if candidate.is_file():
            return candidate
    except OSError:
        return candidate

    # TS ESM convention: imports often spell .js/.jsx while source is .ts/.tsx.
    if candidate.suffix == ".js":
        for ts_candidate in (
            candidate.with_suffix(".ts"),
            candidate.with_suffix(".tsx"),
        ):
            if ts_candidate.is_file() and effective_suffix(ts_candidate) in _JS_CACHE_BYPASS_SUFFIXES:
                return ts_candidate
    elif candidate.suffix == ".jsx":
        tsx_candidate = candidate.with_suffix(".tsx")
        if tsx_candidate.is_file() and effective_suffix(tsx_candidate) in _JS_CACHE_BYPASS_SUFFIXES:
            return tsx_candidate

    declared_exts = _declared_language_suffixes(_JS_RESOLVE_EXTS)

    # Append extensions to the full filename, which covers extensionless imports,
    # multi-dot helpers, and Svelte 5 rune files like Foo.svelte.ts.
    # Native suffixes retain precedence over declared ones.
    for ext in _JS_RESOLVE_EXTS + declared_exts:
        with_ext = candidate.parent / f"{candidate.name}{ext}"
        if with_ext.is_file() and effective_suffix(with_ext) in _JS_CACHE_BYPASS_SUFFIXES:
            return with_ext

    # Only fall back to directory indexes after file candidates lose, native
    # index names before declared ones.
    if candidate.is_dir():
        for index_name in _JS_INDEX_FILES:
            index_candidate = candidate / index_name
            if index_candidate.is_file() and effective_suffix(index_candidate) in _JS_CACHE_BYPASS_SUFFIXES:
                return index_candidate
        for ext in declared_exts:
            index_candidate = candidate / f"index{ext}"
            if index_candidate.is_file():
                return index_candidate

    return candidate

def _resolve_lua_import_target(raw_module: str, str_path: str) -> str:
    """Resolve a Lua require() module name to a node id.

    Lua module names use dots as path separators: `require("pkg.b")` looks for
    `pkg/b.lua` (or `pkg/b/init.lua`) relative to a package root. We probe the
    importing file's directory and walk upward looking for a matching file on
    disk; if found, the returned id matches the file node id `_extract_generic`
    assigns to that file (`_make_id(str(path))`), so the edge lands on a real
    node. When nothing matches, fall back to `_make_id` of the full dotted
    module name so cross-file resolution can still complete via the symbol
    resolution pass instead of dropping the edge entirely (#1075).
    """
    if not raw_module:
        return ""
    rel = raw_module.replace(".", "/")
    try:
        start_dir = Path(str_path).parent
    except Exception:
        start_dir = None
    if start_dir is not None:
        probe = start_dir
        # Walk up a few levels so requires from nested files still resolve when
        # the package root is above the importing file.
        for _ in range(6):
            for suffix in (".lua", ".luau"):
                cand = probe / f"{rel}{suffix}"
                if cand.is_file():
                    return _make_id(str(cand))
            for suffix in (".lua", ".luau"):
                cand = probe / rel / f"init{suffix}"
                if cand.is_file():
                    return _make_id(str(cand))
            if probe.parent == probe:
                break
            probe = probe.parent
    return _make_id(raw_module)

def _resolve_tsconfig_alias(raw: str, aliases: dict[str, list[str]],
                            base_url: "Path | None" = None) -> "Path | None":
    """Resolve `raw` against the most specific matching tsconfig alias pattern.

    Within that pattern, try targets in declared order and return the first whose
    candidate resolves to a real file. If none exist, return the first candidate
    so existing phantom/external-edge behavior stays unchanged.

    `base_url` is a resolution root of last resort, tried only when NO declared
    alias matches (#2153). It must not participate in the specificity contest:
    a bare `*` alias would score (1, 0) and so beat a declared non-wildcard
    directory-prefix alias at (2, -len), silently shadowing it and regressing
    #1269. Unlike the alias path this returns a candidate only when it is a real
    file on disk, so a genuine external package (`import React from 'react'`)
    still resolves to nothing instead of a fabricated <baseUrl>/react edge.
    """
    best: "tuple[tuple[int, int], str, bool, list[str]] | None" = None
    for pattern, targets in aliases.items():
        match = _match_tsconfig_alias(raw, pattern)
        if match is None:
            continue
        specificity, captured, is_wildcard = match
        if best is None or specificity < best[0]:
            best = specificity, captured, is_wildcard, targets

    if best is None:
        if base_url is not None:
            candidate = Path(os.path.normpath(base_url / raw))
            resolved = _resolve_js_import_path(candidate)
            try:
                if resolved.is_file():
                    return resolved
            except OSError:
                pass
        return None

    _, captured, is_wildcard, targets = best
    first = None
    for target in targets:
        if is_wildcard:
            # TypeScript substitutes only when the matched star is non-empty.
            substituted = target.replace("*", captured, 1) if captured else target
            cand = Path(os.path.normpath(substituted))
        else:
            cand = Path(target)
            if captured:
                cand = Path(os.path.normpath(cand / captured))
        resolved = _resolve_js_import_path(cand)
        try:
            if resolved.is_file():
                return resolved
        except OSError:
            pass
        if first is None:
            first = cand
    return first

def _source_key(source_file: str, root: Path) -> str:
    if not source_file:
