def _walk_js_tree(node):
    # Pre-order walk with a TreeCursor, which skips building a ``.children``
    # list at every node. A cursor is bounded by the node it starts from, so
    # goto_parent() fails at ``node`` and a subtree walk never leaves it.
    cursor = node.walk()
    while True:
        yield cursor.node
        if cursor.goto_first_child():
            continue
        while not cursor.goto_next_sibling():
            if not cursor.goto_parent():
                return

def _js_named_specifiers(node, source: bytes, specifier_type: str) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for child in _walk_js_tree(node):
        if child.type != specifier_type:
            continue
        name_node = child.child_by_field_name("name")
        if name_node is None:
            continue
        alias_node = child.child_by_field_name("alias")
        name = _read_text(name_node, source)
        exposed = _read_text(alias_node, source) if alias_node is not None else name
        if name and exposed:
            pairs.append((name, exposed))
    return pairs

def _with_source_twins(
    package_dir: Path, candidates: list[Path], *, root_entry: bool = False
) -> list[Path]:
    """Follow `exports` that point only into build output back to the source.

    `"exports": {".": {"import": "./dist/index.js"}}` never names `src/`, and
    `dist/` is usually ignored and outside the corpus, so the import either
    became an external stub or did not resolve at all (#4485). Append each
    build-output target's source twin (`dist/sub.js` -> `src/sub`) and, for the
    root entry, `src/index` / `index` as the `main` path already does (#3834).
    They go last: _resolve_workspace_import prefers a file outside build output,
    so the source wins when it exists and the build file stays the fallback."""
    extra: list[Path] = []
    for candidate in candidates:
        try:
            rel = candidate.relative_to(package_dir)
        except ValueError:
            continue
        if len(rel.parts) < 2 or rel.parts[0] not in _BUILD_OUTPUT_DIRS:
            continue
        name = rel.name
        for suffix in _BUILD_OUTPUT_SUFFIXES:
            if name.endswith(suffix):
                name = name[: -len(suffix)]
                break
        extra.append(package_dir / "src" / Path(*rel.parts[1:-1]) / name)
    if root_entry:
        extra += [package_dir / "src/index", package_dir / "index"]
    return candidates + [path for path in dict.fromkeys(extra) if path not in candidates]

def _package_entry_candidates(
    package_dir: Path,
    subpath: str,
    platform: str | None = None,
) -> list[Path]:
    manifest = package_dir / "package.json"
    manifest_data: dict[str, Any] = {}
    try:
        manifest_data = json.loads(manifest.read_text(encoding="utf-8"))
    except Exception:
        pass

    if subpath:
        # Consult the package's `exports` subpath map before the bare-path
        # fallback (#1308): "./browser" -> conditions -> file, plus single
        # wildcard "./*" patterns. Every matching condition is kept in
        # preference order, so one whose target is not on disk does not take
        # the whole import down with it (#3487). Targets that escape the
        # package dir are rejected; resolution then falls through to the bare
        # path.
        exports = manifest_data.get("exports")
        if isinstance(exports, dict):
            subpath_key = "./" + subpath
            targets = _resolve_export_targets(exports.get(subpath_key), platform)
            if targets:
                candidates = _exports_candidates(package_dir, targets, platform)
                if candidates:
                    return _with_source_twins(package_dir, candidates)
            else:
                for pattern, pattern_value in exports.items():
                    if "*" in pattern and pattern.count("*") == 1:
                        prefix, suffix = pattern.split("*", 1)
                        if (subpath_key.startswith(prefix)
                                and (not suffix or subpath_key.endswith(suffix))):
                            matched = subpath_key[len(prefix):len(subpath_key) - len(suffix) if suffix else None]
                            wildcard_targets = [
                                resolved.replace("*", matched)
                                for resolved in _resolve_export_targets(pattern_value, platform)
                                if "*" in resolved
                            ]
                            if wildcard_targets:
                                candidates = _exports_candidates(
                                    package_dir, wildcard_targets, platform
                                )
                                if candidates:
                                    return _with_source_twins(package_dir, candidates)
        return [package_dir / subpath]

    exports = manifest_data.get("exports")
    if isinstance(exports, str):
        return _with_source_twins(package_dir, [package_dir / exports], root_entry=True)
    if isinstance(exports, dict):
        dot_targets = _resolve_export_targets(exports.get("."), platform)
        if dot_targets:
            return _with_source_twins(
                package_dir,
                _exports_candidates(package_dir, dot_targets, platform),
                root_entry=True,
            )

    candidates: list[Path] = []
    for key in ("svelte", "module", "main", "types"):
        value = manifest_data.get(key)
        if isinstance(value, str):
            candidates.append(package_dir / value)
    candidates.append(package_dir / "src/index")
    candidates.append(package_dir / "index")
    return candidates

def _workspace_globs(root: Path) -> list[str]:
    pnpm_workspace = root / "pnpm-workspace.yaml"
    if pnpm_workspace.exists():
        return _pnpm_workspace_globs(pnpm_workspace)

    package_json = root / "package.json"
    try:
        data = json.loads(package_json.read_text(encoding="utf-8"))
    except Exception:
        return []

    workspaces = data.get("workspaces")
    if isinstance(workspaces, list):
        return [item for item in workspaces if isinstance(item, str) and not item.startswith("!")]
    if isinstance(workspaces, dict):
        packages = workspaces.get("packages")
        if isinstance(packages, list):
            return [item for item in packages if isinstance(item, str) and not item.startswith("!")]
    return []

def _load_workspace_packages(start_dir: Path) -> dict[str, Path]:
    root = _find_workspace_root(start_dir)
    if root is None:
        return {}
    manifest_mtimes = tuple(
        (name, (root / name).stat().st_mtime_ns)
        for name in _WORKSPACE_MANIFEST_NAMES
        if (root / name).is_file()
    )
    key = str((root, manifest_mtimes))
    if key in _WORKSPACE_PACKAGE_CACHE:
        return _WORKSPACE_PACKAGE_CACHE[key]

    packages: dict[str, Path] = {}
    for pattern in _workspace_globs(root):
        package_dirs: list[Path] = [root] if pattern in (".", "./") else list(root.glob(pattern))
        for package_dir in package_dirs:
            manifest = package_dir / "package.json"
            if not manifest.is_file():
                continue
            try:
                data = json.loads(manifest.read_text(encoding="utf-8"))
            except Exception:
                continue
            name = data.get("name")
            if isinstance(name, str) and name:
                packages[name] = package_dir
    _WORKSPACE_PACKAGE_CACHE[key] = packages
    return packages

def _resolve_workspace_import(raw: str, start_dir: Path) -> Path | None:
    packages = _load_workspace_packages(start_dir)
    platform = _importer_platform(start_dir)
    for package_name, package_dir in packages.items():
        if raw == package_name:
            subpath = ""
        elif raw.startswith(package_name + "/"):
            subpath = raw[len(package_name) + 1:]
        else:
            continue
        build_fallback: Path | None = None
        for candidate in _package_entry_candidates(package_dir, subpath, platform):
            resolved = _resolve_js_import_path(candidate)
            if resolved.is_file():
                if _is_build_output_path(resolved, package_dir):
                    if build_fallback is None:
                        build_fallback = resolved
                else:
                    return resolved
        if build_fallback is not None:
            return build_fallback
    return None

def _rust_simple_generic_impl_key(node, source: bytes) -> str | None:
    """Return a stable owner/arity key for a deliberately narrow impl shape."""
    if node.child_by_field_name("trait") is not None:
        return None
    parameters = node.child_by_field_name("type_parameters")
    owner_type = node.child_by_field_name("type")
    if parameters is None or owner_type is None or owner_type.type != "generic_type":
        return None
    if any(child.type == "where_clause" for child in node.named_children):
        return None

    parameter_names: list[str] = []
    for parameter in parameters.named_children:
        if parameter.type != "type_parameter":
            return None
        named = parameter.named_children
        if len(named) != 1 or named[0].type != "type_identifier":
            return None
        name = _read_text(named[0], source)
        if not name or name in parameter_names:
            return None
        parameter_names.append(name)
    if not parameter_names:
        return None

    owner = owner_type.child_by_field_name("type")
    if owner is None or owner.type != "type_identifier":
        return None
    arguments = next(
        (child for child in owner_type.named_children if child.type == "type_arguments"),
        None,
    )
    if arguments is None:
        return None
    argument_names = [
        _read_text(argument, source)
        for argument in arguments.named_children
        if argument.type == "type_identifier"
    ]
    if len(argument_names) != len(arguments.named_children):
        return None
    if argument_names != parameter_names:
        return None

    owner_name = _read_text(owner, source)
    return f"{owner_name}/{len(parameter_names)}" if owner_name else None

def _rust_type_last_segment(text: str) -> str:
    """`crate::a::Foo<T>` -> `Foo`: the last path segment, generic arguments dropped.
    A leading `&`, `&'a mut` or `dyn` (`impl Tr for &'a Foo`) is not part of it."""
    text = re.sub(r"^(?:&\s*(?:'\w+\s+)?(?:mut\s+)?|dyn\s+)", "", text.strip())
    depth, kept = 0, []
    for ch in text:
        if ch == "<":
            depth += 1
        elif ch == ">":
            depth = max(depth - 1, 0)
        elif depth == 0:
            kept.append(ch)
    segments = [s.strip() for s in "".join(kept).split("::") if s.strip()]
    return segments[-1] if segments else ""

def _rust_use_module(argument: str) -> str:
    """The name a plain `use` imports from: the last path segment of its argument, as
    written (`a::b` -> `b`, `a::b as c` -> `b as c`, `a::*` -> `a`)."""
    clean = argument.split("{")[0].rstrip(":").rstrip("*").rstrip(":")
    return clean.split("::")[-1].strip()

def _callee_text(callee: Node, source: bytes) -> str:
    """The callee as written, e.g. ``super.supportsInterface`` or ``_check``.

    tree-sitter-solidity parses ``a || super.f(x)`` as a call of the member
    ``(a || super).f``: the binary expression is swallowed into the member's
    object. Read the right-most operand as the receiver instead, so the call
    is seen as ``super.f`` (and ``a && b.c(x)`` as ``b.c``).
    """
    inner = callee.named_children[0] if callee.type == "expression" and callee.named_children else callee
    if inner.type == "member_expression":
        obj = inner.child_by_field_name("object")
        prop = inner.child_by_field_name("property")
        if obj is not None and prop is not None:
            base = obj
            while True:
                unwrapped = base.named_children[0] if base.type == "expression" and base.named_children else base
                right = unwrapped.child_by_field_name("right") if unwrapped.type == "binary_expression" else None
                if right is None:
                    break
                base = right
            if base is not obj:
                return f"{_read_text(base, source)}.{_read_text(prop, source)}"
    return _read_text(callee, source)

def _unquote(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        return value[1:-1]
    return value

def resolve_solidity_type_references(
    _per_file: list[dict], all_nodes: list[dict], all_edges: list[dict]
) -> None:
    """Bind inheritance and using references to types in the file or its imports."""
    node_by_id = {node.get("id"): node for node in all_nodes}
    file_id_by_source = {
        str(node["source_file"]): node["id"]
        for node in all_nodes
        if node.get("source_file")
        and node.get("label") == Path(str(node["source_file"])).name
    }
    source_by_file_id = {nid: source for source, nid in file_id_by_source.items()}
    imported_sources: dict[str, set[str]] = {}
    for edge in all_edges:
        if edge.get("relation") != "imports_from":
            continue
        source_file = source_by_file_id.get(edge.get("source"))
        target_file = source_by_file_id.get(edge.get("target"))
        if source_file and target_file:
            imported_sources.setdefault(source_file, set()).add(target_file)

    types: dict[tuple[str, str], list[str]] = {}
    for node in all_nodes:
        metadata = node.get("metadata")
        if not isinstance(metadata, dict) or metadata.get("kind") not in _TYPE_DECLARATIONS.values():
            continue
        source_file = node.get("source_file")
        if source_file:
            types.setdefault((str(source_file), str(node.get("label", ""))), []).append(node["id"])

    for edge in all_edges:
        context = edge.get("context")
        if not isinstance(context, str) or not context.startswith("solidity_type:"):
            continue
        source_node = node_by_id.get(edge.get("source"))
        if not source_node or not source_node.get("source_file"):
            continue
        source_file = str(source_node["source_file"])
        name = context.split(":", 1)[1]
        candidates = list(types.get((source_file, name), []))
        for imported in imported_sources.get(source_file, set()):
            candidates.extend(types.get((imported, name), []))
        if len(candidates) == 1:
            edge["target"] = candidates[0]

def _clean_part(part: str) -> str:
    """One name part without T-SQL brackets. The parser hands over `dbo].[Orders`
    for `[dbo].[Orders]`, so a part may keep only one of its two brackets; `]]`
    inside a bracketed name is an escaped `]`."""
    return part.removeprefix("[").removesuffix("]").replace("]]", "]")

def _clean_ident(name: str) -> str:
    """Display form of an object name: T-SQL brackets removed, schema kept.

    `[dbo].[Orders]` and the parser's `dbo].[Orders` both give `dbo.Orders`.
    Double-quoted parts keep their quotes. Labels only: node ids come from the
    text as written and are not touched.
    """
    if "[" not in name and "]" not in name:
        return name
    return ".".join(
        p if p.startswith('"') else _clean_part(p) for p in (part.strip() for part in name.split("."))
    )

def _redact_value(key: str, value: object) -> object:
    """Redact a sensitive attribute value; recurse into map AND list values so a
    nested `password` inside a `tags`/`connection` map — or inside a list of
    objects — is redacted too.

    HCL routinely nests objects inside tuples (`list(object(...))` variables,
    `dynamic` blocks, tuple defaults), and `_parse_attr_value` turns those into
    Python lists of dicts. Recursing into dicts but not lists left
    `configs = [{ password = "x" }]` leaking verbatim while the map form
    `config = { password = "x" }` was redacted — the value still reaches
    graph.json and the MCP query/get_node surface unsanitized (#3644 follow-up).
    List elements are recursed under the same key: the list branch is only
    reached when `key` is NOT itself sensitive (a sensitive key redacts the whole
    value above), so a scalar element carries no key signal and is returned
    as-is, while a dict element is checked against its own inner keys."""
    if _SENSITIVE_KEY_RE.search(key):
        return _REDACTED
    if isinstance(value, dict):
        redacted = {k: _redact_value(str(k), v) for k, v in value.items()}
        # Name/value-pair idiom (ECS `environment`/`secrets`, `[{name, value}]`):
        # the secret signal is the `name` literal, not a key, so key matching
        # alone let `{ name = "DB_PASSWORD", value = "hunter2" }` leak (#3787).
        if any(
            str(k).lower() == "name" and isinstance(v, str) and _SENSITIVE_KEY_RE.search(v)
            for k, v in value.items()
        ):
            for k in redacted:
                if str(k).lower() in _PAIRED_VALUE_KEYS:
                    redacted[k] = _REDACTED
        return redacted
    if isinstance(value, (list, tuple)):
        return [_redact_value(key, item) for item in value]
    return value

def _scope_id(directory: str) -> str:
    # Hash the exact path too: make_id folds case and punctuation, which must
    # not merge e.g. dev/app with prod/app, or a-b with a_b.
    digest = hashlib.sha256(directory.encode("utf-8")).hexdigest()[:16]
    return _make_id("terraform", directory, digest)

def prepare_terraform(result: dict, path: Path, root: Path) -> None:
    """Make cached directory-scoped IDs portable before the common merge passes."""
    directory = path.parent.resolve()
    try:
        relative = directory.relative_to(root).as_posix()
    except ValueError:
        return
    old, new = _scope_id(directory.as_posix()), _scope_id(relative)
    for node in result.get("nodes", []):
        nid = node["id"]
        if nid.startswith(old + "_"):
            node["id"] = new + nid[len(old):]
        node["_terraform_directory"] = relative
    for edge in result.get("edges", []):
        for key in ("source", "target"):
            nid = edge[key]
            if nid.startswith(old + "_"):
                edge[key] = new + nid[len(old):]
    # Resolve paths only here, with the scan boundary available. The per-file
    # cache keeps syntax facts, never filesystem-dependent topology.
    for node in result.get("nodes", []):
        source = node.get("module_source", "")
        if not source.startswith(("./", "../")):
            continue
        try:
            target = (directory / source).resolve().relative_to(root)
        except (ValueError, OSError, RuntimeError):
            continue
        node["_terraform_source_directory"] = target.as_posix()

def refresh_terraform_paths(
    changed: list[Path], corpus: list[Path], invalidated: Sequence[Path] = (),
) -> list[Path]:
    """Reconcile directory ownership and incoming links on incremental scans.

    Callers pass only the permitted, live corpus. Cached syntax is reused for
    unchanged Terraform files; other languages keep their incremental behavior.
    """
    if not any(p.suffix == ".tf" or p.name in (".gitignore", ".graphifyignore")
               for p in [*changed, *invalidated]):
        return changed
    return list(dict.fromkeys([*changed, *(p for p in corpus if p.suffix == ".tf")]))

def resolve_terraform_modules(per_file: list[dict], nodes: list[dict], edges: list[dict]) -> None:
    """Connect module calls to scanned .tf directories without reading new files."""
    files: dict[str, list[dict]] = {}
    anchors = {}
    for node in nodes:
        directory = node.get("_terraform_directory")
        if directory is None:
            continue
        if node.get("type") == "terraform_file" and Path(node["source_file"]).suffix == ".tf":
            files.setdefault(directory, []).append(node)
        elif node.get("type") == "module" and node.get("language") == "terraform":
            anchors[directory] = node["id"]
    fresh_files = {
        node["id"] for result in per_file for node in result.get("nodes", [])
        if node.get("type") == "terraform_file"
    }
    known_ids = {n["id"] for n in nodes}
    for directory, members in sorted(files.items()):
        anchor = anchors.setdefault(directory, _make_id(_scope_id(directory), "directory"))
        if anchor not in known_ids:
            owner = min(members, key=lambda n: n["source_file"])
            nodes.append({
                "id": anchor, "label": f"Terraform module: {directory}",
                "type": "module", "language": "terraform", "file_type": "code",
                "source_file": owner["source_file"], "source_location": None,
                "_terraform_directory": directory,
            })
            known_ids.add(anchor)
        for member in members:
            if member["id"] in fresh_files:
                edges.append({
                    "source": anchor, "target": member["id"], "relation": "contains",
                    "confidence": "EXTRACTED", "weight": 1.0,
                    "source_file": member["source_file"], "source_location": None,
                })
    fresh_calls = {
        node["id"] for result in per_file for node in result.get("nodes", [])
        if "module_source" in node
    }
    for node in nodes:
        if node["id"] not in fresh_calls:
            continue
        target = anchors.get(node.get("_terraform_source_directory"))
        if target is not None:
            edges.append({
                "source": node["id"], "target": target, "relation": "module_source",
                "confidence": "EXTRACTED", "weight": 1.0,
                "source_file": node["source_file"],
                "source_location": node["module_source_location"],
            })

def resolve_vbnet_partial_calls(
    per_file: list[dict], all_nodes: list[dict], all_edges: list[dict]
) -> None:
    """Resolve calls across files that declare the same partial VB type."""
    methods: dict[tuple[str, str, int], list[str]] = {}
    for node in all_nodes:
        metadata = node.get("metadata")
        if not isinstance(metadata, dict) or metadata.get("language") != "vbnet":
            continue
        if metadata.get("kind") not in {"method", "constructor"}:
            continue
        owner = metadata.get("owner")
        name = metadata.get("name")
        accepted_arities = metadata.get("accepted_arities")
        if (
            isinstance(owner, str)
            and isinstance(name, str)
            and isinstance(accepted_arities, list)
        ):
            for arity in accepted_arities:
                if isinstance(arity, int):
                    methods.setdefault(
                        (owner.casefold(), name.casefold(), arity), []
                    ).append(node["id"])

    existing = {
        (edge.get("source"), edge.get("target"))
        for edge in all_edges
        if edge.get("relation") == "calls"
    }
    for result in per_file:
        for call in result.get("raw_calls", []):
            if call.get("language") != "vbnet" or not call.get("owner"):
                continue
            key = (
                str(call["owner"]).casefold(),
                str(call.get("callee", "")).casefold(),
                int(call.get("arity", -1)),
            )
            candidates = methods.get(key, [])
            caller = call.get("caller_nid")
            if len(candidates) != 1 or candidates[0] == caller:
                continue
            pair = (caller, candidates[0])
            if pair in existing:
                continue
            existing.add(pair)
            all_edges.append({
                "source": caller,
                "target": candidates[0],
                "relation": "calls",
                "context": "partial_type_call",
                "confidence": "EXTRACTED",
                "confidence_score": 1.0,
                "source_file": call.get("source_file", ""),
                "source_location": call.get("source_location"),
                "weight": 1.0,
            })

def _sv_child(node, type_name: str) -> object | None:
    if node is None:
        return None
    for child in node.children:
        if child.type == type_name:
            return child
    return None

def _sv_first_identifier(node, source: bytes) -> str | None:
    """First `simple_identifier` under node in pre-order, or None.

    tree-sitter-verilog 1.0.3 nests declaration names a few levels deep instead
    of exposing a `name` field. Scope the search to the right child node (e.g.
    `function_identifier`) or this returns the return-type instead of the name.
    """
    if node is None:
        return None
    for child in node.children:
        if child.type == "simple_identifier":
            return _read_text(child, source)
        found = _sv_first_identifier(child, source)
        if found:
            return found
    return None

def _sv_split_type_list(text: str) -> list[str]:
    parts: list[str] = []
    depth = 0
    start = 0
    for idx, ch in enumerate(text):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth = max(0, depth - 1)
        elif ch == "," and depth == 0:
            item = text[start:idx].strip()
            if item:
                parts.append(item)
            start = idx + 1
    item = text[start:].strip()
    if item:
        parts.append(item)
    return parts

def _sv_collect_type_refs(type_text: str, generic: bool = False,
                          skip: frozenset[str] = frozenset()) -> list[tuple[str, str]]:
    refs: list[tuple[str, str]] = []
    text = type_text.strip()
    if not text:
        return refs
    head = re.match(r"([A-Za-z_]\w*)", text)
    if head:
        name = head.group(1)
        # `skip` carries the enclosing class's `#(type T = ...)` parameters so
        # they are not mistaken for referenced types.
        if name not in _SV_BUILTIN_TYPES and name not in _SV_NON_TYPE_WORDS and name not in skip:
            refs.append((name, "generic_arg" if generic else "type"))
    params = re.search(r"#\s*\((" + _SV_PARENS_INNER + r")\)", text)
    if params:
        for arg in _sv_split_type_list(params.group(1)):
            refs.extend(_sv_collect_type_refs(arg, generic=True, skip=skip))
    return refs

def _sv_strip_comments(text: str) -> str:
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
    return re.sub(r"//.*", "", text)

def _doc_label(doc: Any, index: int) -> str:
    """A stable label for one document of a multi-document YAML stream."""
    if isinstance(doc, dict):
        kind = doc.get("kind")
        if isinstance(kind, str) and kind:
            meta = doc.get("metadata")
            nm = meta.get("name") if isinstance(meta, dict) else None
            return f"{kind} {nm}" if isinstance(nm, str) and nm else kind
    return f"doc {index}"

def _is_config_yaml(path: Path, data: Any) -> bool:
    """True if a YAML document is a recognized config/manifest worth extracting.

    Matches by filename first, then a ``.github/workflows`` path, then a
    top-level key probe. Skips clear data: a plain data array, an OpenAPI/Swagger
    spec, a JSON-Schema-in-YAML, and a flat all-scalar mapping with no config
    key (for example an i18n string bundle). Errs toward extracting (a mapping
    with any nested value is treated as config) so an arbitrarily-named real
    config is not silently dropped.
    """
    name = path.name.casefold()
    if name in _CONFIG_YAML_NAMES:
        return True
    if "/.github/workflows/" in path.as_posix().casefold():
        return True
    if isinstance(data, list):
        # A top-level sequence is config only when it is an ansible-style list of
        # plays/tasks; a plain data array is not.
        return any(
            isinstance(item, dict)
            and ({"hosts", "tasks", "roles"} & {str(k).casefold() for k in item})
            for item in data
        )
    if not isinstance(data, dict):
        return False
    keys = {str(k).casefold() for k in data.keys()}
    if ("openapi" in keys or "swagger" in keys) and "paths" in keys:
        return False  # an API spec is data-heavy, not a config to walk (#2255-style)
    if "$schema" in keys and ({"$defs", "definitions", "$id"} & keys):
        return False  # a JSON schema in YAML clothing
    if keys & _CONFIG_YAML_KEYS:
        return True
    # A mapping with at least one nested value is config-like; a flat all-scalar
    # mapping with no config key is treated as a data bundle and skipped.
    return any(isinstance(v, (dict, list)) for v in data.values())

def _is_tagged_union(node) -> bool:
    """True for a tagged union (`union(enum)` / `union(SomeTag)`), whose members
    are discriminant cases, not for a bare `union { ... }` whose members are typed
    data fields. A tagged union_declaration carries the tag in parentheses, so it
    has a `(` child; a bare union has none."""
    return node.type == "union_declaration" and any(
        child.type == "(" for child in node.children
    )

def _best_cut(text: str, start: int, end: int) -> int:
    """Return a cut index in ``(start, end]`` at the strongest nearby boundary.

    Searches the window ``text[start:end]`` for the latest heading, then blank
    line, then newline, and returns the index just *after* it (a heading cuts
    just *before* the ``#`` so the heading leads the next slice). Falls back to a
    hard cut at ``end`` when the window has no usable boundary, which still makes
    forward progress because ``end > start``.
    """
    window = text[start:end]
    for sep in _BOUNDARY_SEPARATORS:
        idx = window.rfind(sep)
        if idx > 0:  # a boundary strictly inside the window (non-empty prev slice)
            if sep == "\n#":
                return start + idx + 1  # keep the newline with the previous slice
            return start + idx + len(sep)
    return end

def unit_path(unit: "Path | FileSlice") -> Path:
    """The on-disk path a unit belongs to (the parent file for a slice)."""
    return unit.path if isinstance(unit, FileSlice) else unit

def unit_source_text(path: Path) -> str:
    """The text a unit contributes to the prompt, whatever its container.

    Plain-text files are read directly; converted types (PDF) go through their
    converter. Both `expand_oversized_files` and `read_slice_text` use this, so
    the offsets a slice carries always index the same string the model sees.
    """
    if path.suffix.lower() not in _CONVERTED_TEXT_SUFFIXES:
        return _read_source_text(path, warn=False)
    try:
        st = path.stat()
        key = (str(path), st.st_size, st.st_mtime_ns)
    except OSError:
        return _pdf_text(path)
    hit = _CONVERTED_TEXT_CACHE.get(key)
    if hit is not None:
        return hit
    text = _pdf_text(path)
    if len(_CONVERTED_TEXT_CACHE) >= _CONVERTED_TEXT_CACHE_MAX:
        _CONVERTED_TEXT_CACHE.clear()
    _CONVERTED_TEXT_CACHE[key] = text
    return text

def _load_global_graph() -> nx.Graph:
    if _GLOBAL_GRAPH.exists():
        from graphify.security import check_graph_file_size_cap
        check_graph_file_size_cap(_GLOBAL_GRAPH)
        data = json.loads(_GLOBAL_GRAPH.read_text(encoding="utf-8"))
        if "links" not in data and "edges" in data:
            data = dict(data, links=data["edges"])
        try:
            return _jg.node_link_graph(data, edges="links")
        except TypeError:
            return _jg.node_link_graph(data)
    return nx.Graph()

def _load_manifest() -> dict:
    if _GLOBAL_MANIFEST.exists():
        try:
            return json.loads(_GLOBAL_MANIFEST.read_text(encoding="utf-8"))
        except Exception as exc:
            # Don't silently wipe the user's manifest on a parse error: that
            # deletes every tracked repo. Back the bad file up and surface the
            # error so the user can recover or report it.
            backup = _GLOBAL_MANIFEST.with_suffix(
                _GLOBAL_MANIFEST.suffix + f".corrupt.{int(datetime.now(timezone.utc).timestamp())}"
            )
            try:
                _GLOBAL_MANIFEST.rename(backup)
                print(
                    f"[graphify global] manifest at {_GLOBAL_MANIFEST} failed to parse ({exc}); "
                    f"moved to {backup} and starting fresh. Restore from the backup if this was "
                    f"unexpected.",
                    file=sys.stderr,
                )
            except Exception as rename_exc:
                print(
                    f"[graphify global] manifest at {_GLOBAL_MANIFEST} failed to parse ({exc}) "
                    f"and could not be backed up ({rename_exc}). Starting fresh.",
                    file=sys.stderr,
                )
    return {"version": 1, "repos": {}}

def _save_global_graph(G: nx.Graph) -> None:
    _GLOBAL_DIR.mkdir(parents=True, exist_ok=True)
    try:
        data = _jg.node_link_data(G, edges="links")
    except TypeError:
        data = _jg.node_link_data(G)
    from graphify.paths import write_json_atomic
    write_json_atomic(_GLOBAL_GRAPH, data, compact=True)

