    return _load_manifest().get("repos", {})

def _extract_file_id_from_url(url: str) -> str | None:
    """Extract a Drive file ID from common Google Docs/Drive URL shapes."""
    if not url:
        return None
    parsed = urllib.parse.urlparse(url)
    query = urllib.parse.parse_qs(parsed.query)
    if query.get("id"):
        return query["id"][0]
    match = re.search(r"/(?:document|spreadsheets|presentation|file)/d/([^/?#]+)", parsed.path)
    if match:
        return match.group(1)
    return None

def _extract_resource_key(url: str, data: dict[str, Any]) -> str | None:
    for key in ("resource_key", "resourceKey"):
        value = data.get(key)
        if value:
            return str(value)
    if not url:
        return None
    parsed = urllib.parse.urlparse(url)
    query = urllib.parse.parse_qs(parsed.query)
    if query.get("resourcekey"):
        return query["resourcekey"][0]
    return None

def _safe_yaml_str(value: str) -> str:
    """Escape a value for a YAML double-quoted scalar.

    Same escaping as graphify.ingest._yaml_str (F-009): backslash, quote,
    tab, NUL and other C0/DEL controls, plus the Unicode line breaks
    U+2028, U+2029 and U+0085, so a hostile shortcut url or file id cannot
    break out of the scalar and inject sibling frontmatter keys.
    """
    if value is None:
        return ""
    out: list[str] = []
    for ch in str(value):
        cp = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\0":
            out.append("\\0")
        elif cp == 0x2028:
            out.append("\\L")
        elif cp == 0x2029:
            out.append("\\P")
        elif cp == 0x0085:
            out.append("\\x85")
        elif cp < 0x20 or cp == 0x7F:
            out.append(f"\\x{cp:02x}")
        else:
            out.append(ch)
    return "".join(out)

def google_workspace_enabled(value: str | None = None) -> bool:
    """Return True when Google Workspace shortcut export is enabled."""
    raw = value if value is not None else os.environ.get("GRAPHIFY_GOOGLE_WORKSPACE", "")
    return raw.strip().lower() in {"1", "true", "yes", "on"}

def read_google_shortcut(path: Path) -> dict[str, str | None]:
    """Read a .gdoc/.gsheet/.gslides shortcut and return export metadata."""
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"could not read Google Workspace shortcut {path}: {exc}") from exc

    url = str(data.get("url") or "")
    file_id = (
        data.get("doc_id")
        or data.get("file_id")
        or data.get("fileId")
        or data.get("id")
        or _extract_file_id_from_url(url)
    )
    if not file_id:
        resource_id = str(data.get("resource_id") or "")
        if ":" in resource_id:
            file_id = resource_id.split(":", 1)[1]

    if not file_id:
        raise RuntimeError(f"Google Workspace shortcut {path} does not include a Drive file ID")

    return {
        "file_id": str(file_id),
        "url": url or None,
        "resource_key": _extract_resource_key(url, data),
        "account": str(data.get("email")) if data.get("email") else None,
    }

def _comparable_block(text: str, marker: str, marker_end: str) -> str | None:
    """The graphify block in *text* with its per-install values blanked out, or
    None when the block has no end marker (install cannot rewrite those either)."""
    start = text.find(marker)
    end = text.find(marker_end, start) if start != -1 else -1
    if end == -1:
        return None
    block = text[start:end + len(marker_end)]
    return _VIZ_EXPORT_LINE_RE.sub("", _PINNED_LINE_RE.sub("_PINNED=''", block))

def _git_root(path: Path) -> Path | None:
    """Walk up to find .git directory."""
    current = path.resolve()
    for parent in [current, *current.parents]:
        if (parent / ".git").exists():
            return parent
    return None

def _has_merge_attr(content: str) -> bool:
    """True if a (non-comment) `<...>graph.json ... merge=graphify` line exists."""
    for raw in content.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        fields = line.split()
        if fields and fields[0].endswith("graph.json") and "merge=graphify" in fields[1:]:
            return True
    return False

def _is_within(child: Path, parent: Path) -> bool:
    """True if `child` is `parent` or a path underneath it."""
    try:
        child.resolve().relative_to(parent.resolve())
    except (ValueError, OSError):
        return False
    return True

def _merge_driver_status(root: Path) -> str:
    """Report whether the merge driver is registered (config + gitattributes)."""
    import subprocess as _sp
    try:
        res = _sp.run(
            ["git", "-C", str(root), "config", "--get", "merge.graphify.driver"],
            capture_output=True, text=True,
        )
        cfg_ok = res.returncode == 0 and bool(res.stdout.strip())
    except OSError:
        cfg_ok = False
    attrs = root / ".gitattributes"
    attr_ok = attrs.exists() and _has_merge_attr(attrs.read_text(encoding="utf-8"))
    if cfg_ok and attr_ok:
        return "registered"
    if cfg_ok:
        return "partially registered (git config set, .gitattributes line missing)"
    if attr_ok:
        return "partially registered (.gitattributes line set, git config missing)"
    return "not registered"

def _rev_parse_path(root: Path, flag: str) -> Path | None:
    """Resolve one ``git rev-parse`` path flag against ``root``.

    ``-c core.hooksPath=`` is not used: an empty value makes ``--git-path hooks``
    print ``./`` instead of the real hooks directory.
    """
    import subprocess as _sp
    try:
        res = _sp.run(
            ["git", "-C", str(root), "rev-parse", flag],
            capture_output=True, text=True,
        )
    except (OSError, FileNotFoundError):
        return None
    if res.returncode != 0:
        return None
    raw = res.stdout.strip()
    if not raw or any(c in raw for c in ("\n", "\r", "\x00")):
        return None
    path = Path(raw)
    if not path.is_absolute():
        path = root / path
    return path.resolve()

def _builtin_hooks_dir(root: Path) -> Path | None:
    """Git's own hooks directory, ignoring core.hooksPath.

    ``--git-path hooks`` follows core.hooksPath, so the default is derived from
    the common git dir. A linked worktree's hooks live in the main repo's
    ``.git/hooks``, which is outside the worktree root.
    """
    for flag in ("--git-common-dir", "--git-dir"):
        git_dir = _rev_parse_path(root, flag)
        if git_dir is not None:
            return (git_dir / "hooks").resolve()
    return None

def _hooks_path_allowed(root: Path, candidate: Path) -> bool:
    """Allow in-repo hook dirs (Husky) and git's own hooks dir only.

    A core.hooksPath that resolves anywhere else is repository-controlled
    local config. Honoring it makes `hook install` write outside the repo (#3869).
    """
    if _is_within(candidate, root):
        return True
    builtin = _builtin_hooks_dir(root)
    return builtin is not None and candidate.resolve() == builtin.resolve()

def _unregister_merge_driver(root: Path) -> str:
    """Remove the merge-driver git config keys and the .gitattributes line."""
    import subprocess as _sp
    for key in ("merge.graphify.name", "merge.graphify.driver"):
        try:
            # --unset exits nonzero if the key is absent; that is fine.
            _sp.run(
                ["git", "-C", str(root), "config", "--unset", key],
                capture_output=True, text=True,
            )
        except OSError:
            pass
    attrs = root / ".gitattributes"
    if not attrs.exists():
        return "not registered - nothing to remove."
    content = attrs.read_text(encoding="utf-8")
    kept = [
        raw for raw in content.splitlines()
        if not _has_merge_attr(raw)
    ]
    if kept == content.splitlines():
        return "gitattributes entry not found - nothing to remove."
    if kept:
        # Other entries survive; the file stays.
        attrs.write_text("\n".join(kept) + "\n", encoding="utf-8", newline="\n")
        return "removed from .gitattributes (other entries preserved)"
    attrs.unlink()
    return "removed (.gitattributes deleted - no other entries)"

def uninstall(path: Path = Path(".")) -> str:
    """Remove graphify's post-commit, post-checkout, post-merge, and post-rewrite hooks."""
    root = _git_root(path)
    if root is None:
        raise RuntimeError(f"No git repository found at or above {path.resolve()}")

    hooks_dir = _user_hooks_dir(_hooks_dir(root))
    commit_msg = _uninstall_hook(hooks_dir, "post-commit", _HOOK_MARKER, _HOOK_MARKER_END)
    checkout_msg = _uninstall_hook(hooks_dir, "post-checkout", _CHECKOUT_MARKER, _CHECKOUT_MARKER_END)
    post_merge_msg = _uninstall_hook(
        hooks_dir, "post-merge", _MERGE_HOOK_MARKER, _MERGE_HOOK_MARKER_END
    )
    post_rewrite_msg = _uninstall_hook(
        hooks_dir, "post-rewrite", _REWRITE_HOOK_MARKER, _REWRITE_HOOK_MARKER_END
    )
    merge_msg = _unregister_merge_driver(root)

    return (
        f"post-commit: {commit_msg}\npost-checkout: {checkout_msg}\n"
        f"post-merge: {post_merge_msg}\npost-rewrite: {post_rewrite_msg}\nmerge driver: {merge_msg}"
    )

def _host_is(host: str, *domains: str) -> bool:
    """True when *host* is one of *domains* or a subdomain of one."""
    return any(host == domain or host.endswith(f".{domain}") for domain in domains)

def _detect_url_type(url: str) -> str:
    """Classify the URL for targeted extraction."""
    parsed = urllib.parse.urlparse(url)
    # Match the host, not the URL text: dropbox.com and netflix.com contain "x.com".
    host = (parsed.hostname or "").rstrip(".")
    if _host_is(host, "twitter.com", "x.com"):
        return "tweet"
    if _host_is(host, "arxiv.org"):
        return "arxiv"
    if _host_is(host, "github.com"):
        return "github"
    if _host_is(host, "youtube.com", "youtu.be"):
        return "youtube"
    path = parsed.path.lower()
    if path.endswith(".pdf"):
        return "pdf"
    if any(path.endswith(ext) for ext in (".png", ".jpg", ".jpeg", ".webp", ".gif")):
        return "image"
    return "webpage"

def _html_to_markdown(html: str, url: str) -> str:
    """Convert HTML to clean markdown. Uses markdownify if available, else basic strip."""
    # Always pre-strip script/style so their text content never leaks into output
    html = re.sub(r"<script[^>]*>.*?</script>", "", html, flags=re.DOTALL | re.IGNORECASE)
    html = re.sub(r"<style[^>]*>.*?</style>", "", html, flags=re.DOTALL | re.IGNORECASE)
    try:
        from markdownify import markdownify
        return markdownify(html, heading_style="ATX", bullets="-", strip=["img"])
    except ImportError:
        # Fallback: basic tag strip
        text = re.sub(r"<[^>]+>", " ", html)
        text = re.sub(r"\s+", " ", text).strip()
        return text[:8000]

def _yaml_str(s: str) -> str:
    """Escape a string for embedding in a YAML double-quoted scalar.

    Handles every YAML 1.1/1.2 line-break and control character that could
    let a hostile value (e.g. a fetched page title) break out of the quoted
    scalar and inject sibling YAML keys (F-009 / F-019). The previous
    implementation missed `\\t`, `\\0`, the unicode line-separator U+2028 and
    paragraph-separator U+2029 — all of which YAML treats as line breaks.

    We intentionally do not depend on PyYAML (not in pyproject deps) and
    instead emit safely-escaped double-quoted scalars by hand: the YAML
    double-quoted form recognises `\\\\`, `\\"`, `\\n`, `\\r`, `\\t`, `\\0`,
    `\\L` (U+2028), `\\P` (U+2029), and `\\xNN`/`\\uNNNN` numeric escapes.
    """
    if s is None:
        return ""
    out: list[str] = []
    for ch in str(s):
        cp = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\0":
            out.append("\\0")
        elif cp == 0x2028:
            out.append("\\L")
        elif cp == 0x2029:
            out.append("\\P")
        elif cp < 0x20 or cp == 0x7F:
            out.append(f"\\x{cp:02x}")
        else:
            out.append(ch)
    return "".join(out)

def _fetch_arxiv(url: str, author: str | None, contributor: str | None) -> tuple[str, str]:
    """Fetch arXiv abstract page."""
    # Convert /abs/ or /pdf/ to abs for the API
    arxiv_id = re.search(r"(\d{4}\.\d{4,5})", url)
    if arxiv_id:
        api_url = f"https://export.arxiv.org/abs/{arxiv_id.group(1)}"
        try:
            html = _fetch_html(api_url)
            abstract_match = re.search(r'class="abstract[^"]*"[^>]*>(.*?)</blockquote>', html, re.DOTALL | re.IGNORECASE)
            abstract = re.sub(r"<[^>]+>", "", abstract_match.group(1)).strip() if abstract_match else ""
            title_match = re.search(r'class="title[^"]*"[^>]*>(.*?)</h1>', html, re.DOTALL | re.IGNORECASE)
            title = re.sub(r"<[^>]+>", " ", title_match.group(1)).strip() if title_match else arxiv_id.group(1)
            authors_match = re.search(r'class="authors"[^>]*>(.*?)</div>', html, re.DOTALL | re.IGNORECASE)
            paper_authors = re.sub(r"<[^>]+>", "", authors_match.group(1)).strip() if authors_match else ""
        except Exception:
            title, abstract, paper_authors = arxiv_id.group(1), "", ""
    else:
        return _fetch_webpage(url, author, contributor)

    now = datetime.now(timezone.utc).isoformat()
    content = f"""---
source_url: "{_yaml_str(url)}"
arxiv_id: "{_yaml_str(arxiv_id.group(1) if arxiv_id else '')}"
type: paper
title: "{_yaml_str(title)}"
paper_authors: "{_yaml_str(paper_authors)}"
captured_at: {now}
contributor: "{_yaml_str(contributor or author or 'unknown')}"
---

# {title}

**Authors:** {paper_authors}
**arXiv:** {arxiv_id.group(1) if arxiv_id else url}

## Abstract

{abstract}

Source: {url}
"""
    filename = f"arxiv_{arxiv_id.group(1).replace('.', '_')}.md" if arxiv_id else _safe_filename(url, ".md")
    return content, filename

def _canonical_platform(platform_name: str) -> str:
    """Resolve a CLI platform alias to its real _PLATFORM_CONFIG key."""
    return _PLATFORM_ALIASES.get(platform_name, platform_name)

def _drop_opencode_config_entry(project_dir: Path) -> bool:
    """Remove the plugin entry older releases wrote into opencode.json.

    The entry was the bare path ``.opencode/plugins/graphify.js``. OpenCode
    loads every file in ``.opencode/plugins/`` on its own, so the entry was
    never needed, and OpenCode 2 reads a bare path as an npm package name and
    fails to install it (#3732). Returns True when the config changed.
    """
    config_file = project_dir / _OPENCODE_CONFIG_PATH
    entry = _OPENCODE_PLUGIN_PATH.as_posix()
    try:
        raw = config_file.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False
    try:
        config = json.loads(raw)
    except ValueError:
        # OpenCode accepts comments in this file, json does not. Rewriting it
        # would drop them, so say what to remove instead.
        if f'"{entry}"' in raw:
            print(
                f"  {_OPENCODE_CONFIG_PATH}  ->  not plain JSON, left as is; "
                f'remove "{entry}" from its plugin list by hand'
            )
        return False
    if not isinstance(config, dict):
        return False
    changed = False
    for key in ("plugin", "plugins"):
        plugins = config.get(key)
        if isinstance(plugins, list) and entry in plugins:
            config[key] = [p for p in plugins if p != entry]
            if not config[key]:
                config.pop(key)
            changed = True
    if changed:
        # ensure_ascii=False: keep the user's non-ASCII values readable.
        _write_text_atomic(config_file, json.dumps(config, indent=2, ensure_ascii=False))
    return changed

def _is_graphify_hook_entry(entry: object) -> bool:
    """True when a single ``hooks[]`` element is a graphify command entry.

    Non-dict and non-command entries are never graphify's (the old uninstall
    filter called ``.get`` on every entry and raised ``AttributeError`` on a
    plain string, #4359).
    """
    if not isinstance(entry, dict) or entry.get("type") != "command":
        return False
    command = entry.get("command")
    return isinstance(command, str) and _is_graphify_hook_command(command)

def _kilo_config_path(project_dir: Path) -> Path:
    kilo_dir = (project_dir or Path(".")) / ".kilo"
    json_path = kilo_dir / _KILO_CONFIG_JSON_PATH.name
    if json_path.exists():
        return json_path
    jsonc_path = kilo_dir / _KILO_CONFIG_JSONC_PATH.name
    if jsonc_path.exists():
        return jsonc_path
    return json_path

def _opencode_config_names_plugin(project_dir: Path) -> bool:
    """True when opencode.json still mentions the bare plugin path."""
    try:
        raw = (project_dir / _OPENCODE_CONFIG_PATH).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False
    return f'"{_OPENCODE_PLUGIN_PATH.as_posix()}"' in raw

def _platform_skill_destination(platform_name: str, *, project: bool = False, project_dir: Path | None = None) -> Path:
    """Return the skill destination for a platform and scope."""
    if platform_name == "gemini":
        if project:
            return (project_dir or Path(".")) / ".gemini" / "skills" / "graphify" / "SKILL.md"
        if platform.system() == "Windows":
            return Path.home() / ".agents" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".gemini" / "skills" / "graphify" / "SKILL.md"

    if platform_name == "opencode":
        if project:
            return (project_dir or Path(".")) / ".opencode" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".config" / "opencode" / "skills" / "graphify" / "SKILL.md"

    if platform_name == "hermes":
        if project:
            return (project_dir or Path(".")) / ".hermes" / "skills" / "graphify" / "SKILL.md"
        # On Windows, Hermes scans %LOCALAPPDATA%\hermes\skills, not ~/.hermes (#1403).
        if platform.system() == "Windows":
            local_appdata = Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local"))
            return local_appdata / "hermes" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".hermes" / "skills" / "graphify" / "SKILL.md"

    if platform_name == "devin":
        if project:
            return (project_dir or Path(".")) / ".devin" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".config" / "devin" / "skills" / "graphify" / "SKILL.md"

    if platform_name == "amp":
        if project:
            return (project_dir or Path(".")) / ".agents" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".config" / "agents" / "skills" / "graphify" / "SKILL.md"

    if platform_name == "agents":
        # The generic Agent-Skills target: project ./.agents/skills, global the
        # spec's user-global ~/.agents/skills (read by `npx skills` and compliant
        # frameworks), NOT amp's ~/.config/agents/skills.
        if project:
            return (project_dir or Path(".")) / ".agents" / "skills" / "graphify" / "SKILL.md"
        return Path.home() / ".agents" / "skills" / "graphify" / "SKILL.md"

    if platform_name in ("antigravity", "antigravity-windows"):
        if project:
            return (project_dir or Path(".")) / ".agents" / "skills" / "graphify" / "SKILL.md"
        # Global Antigravity skill dir (all workspaces): ~/.gemini/config/skills/
        return Path.home() / ".gemini" / "config" / "skills" / "graphify" / "SKILL.md"

    cfg = _PLATFORM_CONFIG[platform_name]
    if project:
        return (project_dir or Path(".")) / cfg["skill_dst"]

    if platform_name in ("claude", "windows") and os.environ.get("CLAUDE_CONFIG_DIR"):
        return Path(os.environ["CLAUDE_CONFIG_DIR"]) / "skills" / "graphify" / "SKILL.md"
    return Path.home() / cfg["skill_dst"]

def _print_banner() -> None:
    """Green graphify logo banner on graphify install. TTY-only, never raises."""
    if not sys.stdout.isatty():
        return
    try:
        if sys.platform == "win32":
            import ctypes
            ctypes.windll.kernel32.SetConsoleMode(
                ctypes.windll.kernel32.GetStdHandle(-11), 7
            )
        G = "\033[38;2;17;141;79m"
        D = "\033[2m"
        R = "\033[0m"
        lines = [f"  {G}{line}{R}" for line in _BANNER_LOGO.splitlines()]
        # Version sits after the wordmark baseline, like the old banner.
        lines[6] += f"  {D}{__version__}{R}"
        print("\n" + "\n".join(lines) + "\n")
    except Exception:
        pass

def _print_project_git_add_hint(paths: list[Path]) -> None:
    unique: list[str] = []
    for path in paths:
        text = path.as_posix().rstrip("/")
        if path.exists() and path.is_dir():
            text += "/"
        if text not in unique:
            unique.append(text)
    if not unique:
        return
    print()
    print("Project-scoped install. Add to version control:")
    print(f"  git add {' '.join(unique)}")

def _project_scope_root(path: Path, project_dir: Path) -> Path:
    """Return the top-level project artifact for a project-scoped skill path."""
    try:
        rel = path.relative_to(project_dir)
    except ValueError:
        return path
    return project_dir / rel.parts[0] if rel.parts else path

def _read_settings_for_merge(settings_path: Path) -> dict:
    """Load an existing settings/hooks JSON file for a read-modify-write merge.

    A missing file yields a fresh ``{}`` (first install). An existing file that
    cannot be parsed as a JSON object aborts via ``_refuse_to_modify`` instead of
    silently falling back to ``{}`` — the old fallback rewrote the whole file and
    destroyed every setting the user had (#2167). Reads with ``utf-8-sig`` so a
    UTF-8 BOM (the most likely parse-error trigger, same class as #2163) is
    tolerated rather than fatal.
    """
    if not settings_path.exists():
        return {}
    try:
        settings = json.loads(settings_path.read_text(encoding="utf-8-sig"))
    except (json.JSONDecodeError, UnicodeDecodeError, OSError):
        settings = None
    if not isinstance(settings, dict):
        _refuse_to_modify(settings_path)
    return settings

def _release_skill_lock(fh) -> None:
    with contextlib.suppress(OSError):
        if fcntl is not None:
            fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
        else:
            fh.seek(0)
            msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)

def _gemini_hook(project: bool = False) -> dict:
    """Gemini CLI BeforeTool hook, resolved to a shell-agnostic `graphify` call.

    A project-scoped install emits the bare command, since .gemini/settings.json
    is then committed and an installing machine's path is wrong there (#3129).
    """
    exe = _resolve_graphify_exe(project=project)
    if " " in exe and not exe.startswith('"'):
        exe = f'"{exe}"'
    return {
        "matcher": "read_file|list_directory",
        "hooks": [{"type": "command", "command": f"{exe} hook-guard gemini"}],
    }

def _shown_path(path: Path) -> str:
    """Name *path* for install/uninstall output, plus the file it points to when it
    is a symlink. Writing through a symlinked CLAUDE.md edits the target, so
    printing only the link hid which file was changed (#3805)."""
    if path.is_symlink():
