    return cfg["default_model"]

def _claude_cli_envelope(stdout: str) -> dict:
    """Parse the JSON returned by `claude -p --output-format json`.

    Older Claude Code CLI versions returned a single envelope object. Newer
    versions (>= ~2.1) emit a JSON ARRAY of streamed event objects (a system
    init event, assistant turns, an optional rate_limit_event, and a final
    {"type":"result"} object). Normalize both shapes to the result dict that
    carries `result`, `usage`, `modelUsage`, and `stop_reason`.
    """
    try:
        envelope = json.loads(stdout)
    except json.JSONDecodeError as exc:
        envelope = _envelope_after_preamble(stdout)
        if envelope is None:
            raise RuntimeError(
                f"claude -p produced unparseable JSON envelope: {exc}; "
                f"first 500 chars of stdout: {stdout[:500]!r}"
            ) from exc
    if isinstance(envelope, list):
        result_events = [
            e for e in envelope
            if isinstance(e, dict) and e.get("type") == "result"
        ]
        if result_events:
            return result_events[-1]
        if envelope and isinstance(envelope[-1], dict):
            return envelope[-1]
        raise RuntimeError(
            "claude -p returned a JSON array with no result object; "
            f"first 500 chars of stdout: {stdout[:500]!r}"
        )
    return envelope

def _extraction_system(*, deep: bool = False) -> str:
    """Return the semantic-extraction system prompt, optionally in deep mode."""
    if not deep:
        return _EXTRACTION_SYSTEM
    return _EXTRACTION_SYSTEM + _DEEP_EXTRACTION_SUFFIX

def _file_to_text(path: Path) -> str:
    """Return a text-like file's content for the extraction prompt.

    Most files are read directly. PDFs are binary, so reading them with
    `read_text` yields garbage (the same failure images had); route them through
    pypdf instead. A scanned PDF with no text layer extracts to an empty string,
    which still produces a reference node rather than noise.
    """
    if path.suffix.lower() == ".pdf":
        from graphify.detect import extract_pdf_text
        return extract_pdf_text(path)
    return _read_source_text(path)

def _first_set_env(keys) -> str | None:
    """First non-empty variable in *keys*, for naming what selected a backend."""
    for key in keys:
        if os.environ.get(key):
            return key
    return None

def _get_backend_api_key(backend: str) -> str:
    """Return the first configured API key for backend, or an empty string."""
    for env_key in _backend_env_keys(backend):
        value = os.environ.get(env_key)
        if value:
            return value
    return ""

def _get_tokenizer():
    """Return a tiktoken encoder for accurate token counts, or None if tiktoken
    is not installed. We use `cl100k_base` (GPT-4 / GPT-3.5-turbo) as a proxy:
    Kimi-K2 ships a tiktoken-based tokenizer with very similar BPE behaviour,
    and Claude's tokenizer has a comparable token-to-char ratio for prose/code.
    Estimates only need to be within ~5%, not exact.
    """
    try:
        import tiktoken
    except ImportError:
        return None
    try:
        return tiktoken.get_encoding("cl100k_base")
    except Exception:  # network failure on first-use download, etc.
        return None

def _image_notes(refs: list[_ImageRef], *, with_paths: bool = False) -> str:
    """Text block listing the images so the model emits one node per image.

    Always included alongside the visual payload (and used on its own when the
    backend can't see pixels), so an image becomes a graph node either way.
    `with_paths=True` also lists the absolute path and asks the model to open it
    with the Read tool — used by the claude-cli backend.
    """
    if not refs:
        return ""
    if with_paths:
        header = (
            "Use the Read tool to open and view each image file at the path below, "
            "then emit one node per image"
        )
    else:
        header = (
            "The following image file(s) are attached as visual input. Emit one "
            "node per image"
        )
    lines = [
        "=== IMAGES ===",
        f"{header} with \"file_type\":\"image\" and the listed source_file, a label "
        "describing what it depicts (diagram, screenshot, chart, photo, UI, logo), "
        "and edges to any code/doc nodes the image clearly references.",
    ]
    for i, r in enumerate(refs, 1):
        note = f"[image {i}] source_file: {r.rel}"
        if with_paths:
            note += f"  path: {r.path}"
        if r.raw is None and not with_paths:
            note += " (not shown: unreadable or exceeds size limit)"
        lines.append(note)
    return "\n".join(lines)

def _looks_like_timeout(exc: BaseException) -> bool:
    """Classify an exception as a recognized subprocess or SDK timeout."""
    types: list[type[BaseException]] = [subprocess.TimeoutExpired]
    try:
        import openai
        types.append(openai.APITimeoutError)
    except ImportError:
        pass
    try:
        import anthropic
        types.append(anthropic.APITimeoutError)
    except ImportError:
        pass
    try:
        import botocore.exceptions
        types.extend([botocore.exceptions.ReadTimeoutError, botocore.exceptions.ConnectTimeoutError])
    except ImportError:
        pass
    return isinstance(exc, tuple(types))

def _merged_partial_files(*results: dict) -> list[str]:
    """Union of the ``_partial_files`` carried by each result (survives merges)."""
    out: set[str] = set()
    for r in results:
        out.update(r.get("_partial_files", []) or [])
    return sorted(out)

def _no_window_kwargs() -> dict:
    """subprocess kwargs that suppress the console window claude.cmd would
    otherwise pop on Windows. A labeling/extraction run spawns one `claude -p`
    per batch — with Windows Terminal as the default terminal each spawn
    becomes a visible window that appears and vanishes for the duration of the
    model call. CREATE_NO_WINDOW keeps the children invisible; no-op elsewhere."""
    import subprocess
    if sys.platform == "win32":
        return {"creationflags": subprocess.CREATE_NO_WINDOW}
    return {}

def _openai_max_tokens_kwarg(backend: str, max_tokens: int) -> dict[str, int]:
    """Map the output cap to the OpenAI-compatible field accepted by the backend."""
    # DeepSeek documents max_tokens and ignores max_completion_tokens.
    key = "max_tokens" if backend == "deepseek" else "max_completion_tokens"
    return {key: max_tokens}

def _parse_label_response(text: str, labeled_cids: list[int]) -> dict[int, str]:
    """Parse the backend's JSON ``{cid: name}`` reply. Raises on non-JSON or a
    non-object payload; silently ignores cids it didn't name."""
    cleaned = _LABEL_FENCE_RE.sub("", text.strip())
    if not cleaned.startswith("{"):
        start, end = cleaned.find("{"), cleaned.rfind("}")
        if start != -1 and end > start:
            cleaned = cleaned[start:end + 1]
    data: dict | None = None
    try:
        parsed = json.loads(cleaned)
        if isinstance(parsed, dict):
            data = parsed
    except (json.JSONDecodeError, ValueError):
        data = None
    if data is None:
        # Salvage: pull the complete "<cid>": "<name>" pairs directly. A model
        # can truncate its reply mid-object (a stingy token budget or a preamble
        # eating the completion), which used to hard-fail the whole batch with
        # e.g. `Expecting value: line 1 column 6` on a `{"0":` fragment (#1690).
        # Recovering the pairs that DID arrive labels those communities instead
        # of dropping the entire batch to placeholders.
        pairs = re.findall(r'"?(-?\d+)"?\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"', cleaned)
        if pairs:
            # The captured value is still a JSON string body, escapes and all;
            # decode it the way json.loads would have for a complete reply, so a
            # salvaged `Caf\u00e9 \"Core\"` reads `Café "Core"`, not the raw escapes.
            data = {k: _decode_json_string_body(v) for k, v in pairs}
        else:
            raise ValueError(f"label response is not parseable JSON: {text[:120]!r}")
    out: dict[int, str] = {}
    for cid in labeled_cids:
        name = data.get(str(cid))
        if name is None:
            name = data.get(cid)
        if isinstance(name, str) and name.strip():
            out[cid] = name.strip()
    return out

def _partial_source_files(result: dict) -> list[str]:
    """Source files known partial: those carrying a ``_partial`` item marker, plus
    any recorded in ``_partial_files`` (a chunk that truncated to an empty parse
    and so has no items to mark)."""
    seen: set[str] = set(result.get("_partial_files", []) or [])
    for bucket in ("nodes", "edges", "hyperedges"):
        for item in result.get(bucket, []):
            if isinstance(item, dict) and item.get("_partial"):
                sf = item.get("source_file")
                if sf:
                    seen.add(str(sf))
    return sorted(seen)

def _pdf_text_for_estimate(path: Path) -> str:
    """Extracted text of a PDF, memoised for the packing pass."""
    try:
        st = path.stat()
        key = (str(path), st.st_size, st.st_mtime_ns)
    except OSError:
        return ""
    hit = _PDF_ESTIMATE_CACHE.get(key)
    if hit is not None:
        return hit
    text = _file_to_text(path)
    if len(_PDF_ESTIMATE_CACHE) >= _PDF_ESTIMATE_CACHE_MAX:
        _PDF_ESTIMATE_CACHE.clear()
    _PDF_ESTIMATE_CACHE[key] = text
    return text

def _estimate_file_tokens(unit: "Path | FileSlice") -> int:
    """Estimate the prompt-token cost of a file or slice under `_read_files` rules.

    Uses tiktoken (`cl100k_base`) when available for accurate counts. Falls back
    to the chars/4 heuristic if tiktoken is not installed. Both paths cap at
    `_FILE_CHAR_CAP` to match `_read_files`'s truncation, plus a constant for
    the wrapper. Returns 0 for unreadable paths so they don't blow up packing.
    """
    if isinstance(unit, FileSlice):
        # A slice's size is its char range (already ≤ _FILE_CHAR_CAP). Use the
        # tokenizer on its text when available, else the chars/4 heuristic.
        if _TOKENIZER is None:
            return (min(unit.end - unit.start, _FILE_CHAR_CAP) + _PER_FILE_OVERHEAD_CHARS) // _CHARS_PER_TOKEN
        try:
            content = read_slice_text(unit)[:_FILE_CHAR_CAP]
        except OSError:
            return 0
        return len(_TOKENIZER.encode(content, disallowed_special=())) + (_PER_FILE_OVERHEAD_CHARS // _CHARS_PER_TOKEN)

    path = unit
    # Raster images are not read as text; a vision model bills them at a roughly
    # fixed token cost, so estimate by image count rather than (binary) byte size.
    if _is_vision_image(path):
        return _IMAGE_TOKEN_ESTIMATE

    # A PDF's bytes are not what the prompt carries. `_read_files` sends it
    # through `_file_to_text` -> `extract_pdf_text`, so estimating from the file
    # instead measures a compressed binary: every real PDF Flate-compresses its
    # text streams, so the estimate came out several times too SMALL and packing
    # overfilled the chunk. On a 400-line fixture the same document estimated at
    # 1,334 tokens uncompressed-vs-4,598 actual, and 1,334 vs 4,599 once
    # FlateDecode was applied — a 3.45x undercount, which is what a real PDF
    # looks like. The chunk then blows the context window and falls into
    # adaptive bisection, paying for the same content several times (#2903).
    if path.suffix.lower() == ".pdf":
        try:
            content = _pdf_text_for_estimate(path)[:_FILE_CHAR_CAP]
        except Exception:
            return 0
    elif _TOKENIZER is None:
        try:
            size = path.stat().st_size
        except OSError:
            return 0
        chars = min(size, _FILE_CHAR_CAP) + _PER_FILE_OVERHEAD_CHARS
        return chars // _CHARS_PER_TOKEN
    else:
        try:
            content = _read_source_text(path, warn=False)[:_FILE_CHAR_CAP]
        except OSError:
            return 0

    if _TOKENIZER is None:
        return (len(content) + _PER_FILE_OVERHEAD_CHARS) // _CHARS_PER_TOKEN
    return len(_TOKENIZER.encode(content, disallowed_special=())) + (_PER_FILE_OVERHEAD_CHARS // _CHARS_PER_TOKEN)

def _resolve_api_timeout(default: float = 600.0) -> float:
    """Honour GRAPHIFY_API_TIMEOUT env var override, else use default (seconds)."""
    raw = os.environ.get("GRAPHIFY_API_TIMEOUT", "").strip()
    if raw:
        try:
            v = float(raw)
            if v > 0:
                return v
        except ValueError:
            pass
    return default

def _azure_client(api_key: str, endpoint: str):
    """Construct an AzureOpenAI client with env-driven api_version and timeout."""
    try:
        from openai import AzureOpenAI
    except ImportError as exc:
        raise ImportError(
            "Azure OpenAI requires the openai package. Run: pip install openai"
        ) from exc
    api_version = os.environ.get("AZURE_OPENAI_API_VERSION", "2024-12-01-preview").strip()
    timeout_raw = os.environ.get("GRAPHIFY_API_TIMEOUT", "").strip()
    timeout_s: float = 600.0
    if timeout_raw:
        try:
            v = float(timeout_raw)
            if v > 0:
                timeout_s = v
        except ValueError:
            pass
    return AzureOpenAI(api_key=api_key, azure_endpoint=endpoint, api_version=api_version, timeout=timeout_s,
                       max_retries=_resolve_max_retries())

def _resolve_max_tokens(default: int) -> int:
    """Honour GRAPHIFY_MAX_OUTPUT_TOKENS env var override, else use backend default."""
    raw = os.environ.get("GRAPHIFY_MAX_OUTPUT_TOKENS", "").strip()
    if raw:
        try:
            v = int(raw)
            if v > 0:
                return v
        except ValueError:
            pass
    return default

def _resolve_ollama_seed() -> int | None:
    """Return the opt-in seed for built-in Ollama requests, if configured."""
    raw = os.environ.get("GRAPHIFY_OLLAMA_SEED")
    if raw is None or not raw.strip():
        return None
    value = raw.strip()
    max_seed = "9223372036854775807"
    normalized = value.lstrip("0") or "0"
    if (
        re.fullmatch(r"[0-9]+", value) is None
        or len(normalized) > len(max_seed)
        or (len(normalized) == len(max_seed) and normalized > max_seed)
    ):
        raise ValueError(
            "GRAPHIFY_OLLAMA_SEED must be an ASCII integer in the range "
            f"0..{max_seed}."
        )
    return int(normalized)

def _resolve_temperature(default: float | None, model: str = "") -> float | None:
    """Resolve the temperature to send, honouring GRAPHIFY_LLM_TEMPERATURE.

    Precedence (issue #1191):
      1. GRAPHIFY_LLM_TEMPERATURE env var, if set:
           - a numeric value (e.g. "0", "0.2", "1") is used verbatim;
           - the literal "none"/"omit"/"default" (case-insensitive) means
             "omit the temperature parameter entirely" (-> None).
      2. Otherwise, reasoning models (o1/o3/o4/gpt-5) get None — the parameter
         must be omitted or the API rejects the request.
      3. Otherwise, the backend config default (`default`, usually 0).

    Returns None when the temperature parameter should be omitted from the
    request; the call sites already guard `if temperature is not None`.
    """
    raw = os.environ.get("GRAPHIFY_LLM_TEMPERATURE", "").strip()
    if raw:
        if raw.lower() in ("none", "omit", "default"):
            return None
        try:
            return float(raw)
        except ValueError:
            print(
                f"[graphify] GRAPHIFY_LLM_TEMPERATURE={raw!r} is not a number or "
                "'none'; falling back to the backend default.",
                file=sys.stderr,
            )
    if _model_requires_default_temperature(model):
        return None
    return default

def _resolve_under_root(path: Path, root: Path) -> Path | None:
    """Return the resolved path only when it stays inside ``root``."""
    try:
        resolved_root = root.resolve()
        resolved_path = path.resolve()
        resolved_path.relative_to(resolved_root)
    except (OSError, RuntimeError, ValueError):
        return None
    return resolved_path

def _parse_llm_json(raw: str) -> dict:
    """Strip optional markdown fences and parse JSON. Returns empty fragment on failure.

    Caps the input at `_LLM_JSON_MAX_BYTES` so a hostile or runaway model
    response cannot exhaust memory inside `json.loads` (F-016).

    Plenty of models will not return a bare JSON object no matter how the
    prompt is worded: they think out loud first, wrap the answer in a fence, or
    do both (#2882). So the whole reply is tried first, then each candidate
    :func:`_json_fragment_candidates` finds. An object carrying none of the
    extraction keys is kept only as a last resort — reasoning-first models
    routinely restate the schema (``{"description": "graph fragment"}``) before
    answering, and the narration must never shadow the answer that follows it.
    """
    if len(raw) > _LLM_JSON_MAX_BYTES:
        print(
            f"[graphify] LLM response exceeds {_LLM_JSON_MAX_BYTES} bytes "
            f"({len(raw)} bytes); refusing to parse and dropping chunk.",
            file=sys.stderr,
        )
        return {"nodes": [], "edges": [], "hyperedges": []}

    stripped = _THINK_BLOCK_RE.sub(" ", raw).strip()

    try:
        parsed = json.loads(stripped)
        if isinstance(parsed, dict):
            return _sanitize_fragment(parsed)
        # Top-level array/scalar (common LLM output) is not a usable graph
        # fragment; fall through rather than returning a non-dict that callers
        # will try to subscript (e.g. result["input_tokens"]).
    except json.JSONDecodeError:
        pass

    # Preference ladder, weakest last. A model that restates the required shape
    # before answering — "the schema is `{"nodes": [], "edges": []}`" — produces
    # a candidate that carries the extraction keys but no content, and taking it
    # would let the restatement shadow the answer just as surely as a prose
    # object would (#2882).
    empty_fragment: dict | None = None   # right shape, nothing in it
    fallback: dict | None = None         # parses, but not a fragment at all
    for candidate in _json_fragment_candidates(stripped):
        try:
            parsed = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if not isinstance(parsed, dict):
            continue
        if any(k in parsed for k in _FRAGMENT_KEYS):
            # Gate on the SANITIZED content, not the raw value. A reasoning
            # sketch commonly lists ids as bare strings — `{"nodes": ["A", "B"]}`
            # — whose arrays are truthy but hold no edge/node objects. Testing
            # the raw value would let that sketch win and then sanitize down to
            # empty, shadowing the real answer that follows and re-triggering the
            # #2880 hollow-response bisection. Sanitizing first demotes it to the
            # empty-fragment tier so the genuine fragment below still wins.
            cand = _sanitize_fragment(parsed)
            if any(cand.get(k) for k in _FRAGMENT_KEYS):
                return cand
            if empty_fragment is None:
                empty_fragment = cand
        elif fallback is None:
            fallback = parsed

    # A genuinely empty extraction is still a valid answer, and still reads as
    # hollow downstream, so it outranks an object that is not a fragment at all.
    for weaker in (empty_fragment, fallback):
        if weaker is not None:
            return _sanitize_fragment(weaker)

    print(
        f"[graphify] LLM returned invalid JSON, skipping chunk "
        f"(first 200 chars: {raw[:200]!r})",
        file=sys.stderr,
    )
    return {"nodes": [], "edges": [], "hyperedges": []}

def _strip_partial_markers(result: dict) -> None:
    """Remove the internal ``_partial`` marker from every item in ``result``.

    Call this only AFTER the semantic cache has been saved (the save consumes the
    marker to stamp affected entries ``partial: True``). Stripping it keeps the
    internal flag out of the graph.json nodes/edges the corpus result feeds into.
    """
    for bucket in ("nodes", "edges", "hyperedges"):
        for item in result.get(bucket, []):
            if isinstance(item, dict):
                item.pop("_partial", None)

def _strip_pixels(refs: list[_ImageRef]) -> list[_ImageRef]:
    """Return refs with pixel data dropped (for non-vision backends)."""
    return [replace(r, raw=None) for r in refs]

def _with_image_notes(user_message: str, refs: list[_ImageRef], *, with_paths: bool = False) -> str:
    notes = _image_notes(refs, with_paths=with_paths)
    if not notes:
        return user_message
    if not user_message.strip():
        return notes
    return f"{user_message}\n\n{notes}"

def _anthropic_content(user_message: str, refs: list[_ImageRef]):
    """Build the Anthropic `messages[].content` value (str, or block list with images)."""
    blocks = [
        {"type": "image", "source": {"type": "base64", "media_type": r.media_type, "data": r.b64}}
        for r in refs
        if r.raw
    ]
    text = _with_image_notes(user_message, refs)
    if not blocks:
        return text
    return [*blocks, {"type": "text", "text": text}]

def _bedrock_content(user_message: str, refs: list[_ImageRef]) -> list[dict]:
    """Build the Bedrock Converse user content list (raw bytes, not base64)."""
    content: list[dict] = [
        {"image": {"format": r.bedrock_format, "source": {"bytes": r.raw}}}
        for r in refs
        if r.raw
    ]
    content.append({"text": _with_image_notes(user_message, refs)})
    return content

def _call_ollama_native(
    client,
    base_url: str,
    kwargs: dict,
    user_message: str,
    images: list[_ImageRef],
) -> tuple[str | None, int, int, str] | None:
    """Send an ollama request to /api/chat. Returns None when the server has no
    native endpoint, so the caller falls back to /v1."""
    root = base_url.rstrip("/")
    if root.endswith("/v1"):
        root = root[: -len("/v1")]
    if root in _OLLAMA_NO_NATIVE:
        return None
    from openai import APIStatusError

    extra = kwargs.get("extra_body", {})
    options = dict(extra.get("options", {}))
    options["num_predict"] = kwargs["max_completion_tokens"]
    if "temperature" in kwargs:
        options["temperature"] = kwargs["temperature"]
    if "seed" in kwargs:
        options["seed"] = kwargs["seed"]
    user: dict = {"role": "user", "content": _with_image_notes(user_message, images)}
    pixels = [r.b64 for r in images if r.raw]
    if pixels:
        user["images"] = pixels
    body: dict = {
        "model": kwargs["model"],
        "messages": [*kwargs["messages"][:-1], user],
        "stream": False,
        "options": options,
        "keep_alive": extra.get("keep_alive", "30m"),
    }
    if _thinking_disabled_via_env():
        body["think"] = False
    try:
        data = client.post(f"{root}/api/chat", body=body, cast_to=object)
    except APIStatusError as exc:
        # Ollama also 404s on an unknown model; surface that instead of
        # marking a real Ollama server as non-native.
        if exc.status_code not in (404, 405) or "model" in str(exc).lower():
            raise
        _OLLAMA_NO_NATIVE.add(root)
        print(
            f"[graphify] {root}/api/chat is not available; falling back to the "
            "OpenAI-compatible /v1 endpoint, which ignores num_ctx.",
            file=sys.stderr,
        )
        return None
    data = data or {}
    message = data.get("message") or {}
    finish_reason = "length" if data.get("done_reason") == "length" else "stop"
    return (
        message.get("content"),
        data.get("prompt_eval_count") or 0,
        data.get("eval_count") or 0,
        finish_reason,
    )

def _openai_content(user_message: str, refs: list[_ImageRef]):
    """Build the OpenAI-compatible user `content` value (str, or part list with images)."""
    parts: list[dict] = [
        {
            "type": "image_url",
            "image_url": {"url": f"data:{r.media_type};base64,{r.b64}", "detail": "auto"},
        }
        for r in refs
        if r.raw
    ]
    text = _with_image_notes(user_message, refs)
    if not parts:
        return text
    return [{"type": "text", "text": text}, *parts]

def _read_files(units: "list[Path | FileSlice]", root: Path) -> str:
    """Return file/slice contents formatted for the extraction prompt.

    Each unit is wrapped in an <untrusted_source> delimiter block and known
    injection sentinels are defanged, so attacker-controlled source text cannot
    be confused with the trusted system instructions (see issue #1210).

    A ``FileSlice`` (one chunk of an oversized document, #1369) reports its
    **parent file path** as ``rel`` so every slice of a file shares one
    source_file and the graph isn't fragmented per-slice.
    """
    parts: list[str] = []
    for u in units:
        p = unit_path(u)
        safe_path = _resolve_under_root(p, root)
        if safe_path is None:
            print(f"[graphify] skipping {p}: symlink target outside corpus root", file=sys.stderr)
            continue
        try:
            # as_posix, not str: `rel` is handed to the model as the literal
            # source_file to emit, so a native backslash spelling on Windows
            # lands in the graph and splits one file across two source_file
            # forms (#683 / #2259).
            rel = p.relative_to(root).as_posix()
        except ValueError:
            rel = Path(p).as_posix()
        try:
            if isinstance(u, FileSlice):
                content = read_slice_text(u)
            else:
                content = _file_to_text(safe_path)
        except OSError:
            continue
        # Whole files are still capped (covers non-splittable large files like
        # code); slices are already bounded to the cap, so the cap is a no-op.
        if len(content) > _FILE_CHAR_CAP:
            global _file_truncation_warned
            if not _file_truncation_warned:
                _file_truncation_warned = True
                print(
                    f"[graphify] WARNING: file {rel} exceeds {_FILE_CHAR_CAP} characters and was truncated",
                    file=sys.stderr,
                )
        parts.append(_wrap_untrusted(rel, content[:_FILE_CHAR_CAP]))
    return "\n\n".join(parts)

def backend_detection_env_vars() -> tuple[str, ...]:
    """Every environment variable ``detect_backend()`` consults, in probe order.

    Covers the API-key variables of every registered backend (built-in and
    custom) plus the endpoint/region/host variables checked directly.
    """
    seen: dict[str, None] = {}
    for name in BACKENDS:
        for env_key in _backend_env_keys(name):
            seen.setdefault(env_key, None)
    for env_key in _BACKEND_DETECTION_EXTRA_ENV:
        seen.setdefault(env_key, None)
    return tuple(seen)

def estimate_cost(backend: str, input_tokens: int, output_tokens: int) -> float:
    """Estimate USD cost for a given token count using published pricing."""
    if backend not in BACKENDS:
        return 0.0
    p = BACKENDS[backend]["pricing"]
    return (input_tokens * p["input"] + output_tokens * p["output"]) / 1_000_000

def _load_custom_providers() -> dict[str, dict]:
    # A project-local ./.graphify/providers.json travels with a cloned or shared
    # repo and defines where the corpus + API key are sent, so loading it
    # silently is a corpus/key exfiltration vector. Require an explicit opt-in;
    # the user's own global ~/.graphify/providers.json stays trusted.
    local_path = _custom_providers_path(global_=False)
    global_path = _custom_providers_path(global_=True)
    allow_local = os.environ.get("GRAPHIFY_ALLOW_LOCAL_PROVIDERS", "").strip().lower() in ("1", "true", "yes")
    if local_path.is_file() and not allow_local:
        print(
            f"[graphify] WARNING: ignoring project-local {local_path} (custom providers control "
            "where your corpus and API key are sent). Set GRAPHIFY_ALLOW_LOCAL_PROVIDERS=1 to load it.",
            file=sys.stderr,
        )

    providers: dict[str, dict] = {}
    paths = [local_path, global_path] if allow_local else [global_path]
    for path in paths:
        if path.is_file():
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    for name, cfg in data.items():
                        if not (isinstance(name, str) and isinstance(cfg, dict)):
                            continue
                        if name in BACKENDS or name in providers:
                            continue
                        if not provider_base_url_ok(str(cfg.get("base_url", "")), name):
                            continue
                        if "pricing" not in cfg:
                            cfg = dict(cfg, pricing={"input": 0.0, "output": 0.0})
                        providers[name] = cfg
            except Exception:
                pass
    return providers

def _coerce_deps(value: Any) -> list[str]:
    """A dependency block may be a list of names or a name->spec map."""
    if isinstance(value, dict):
        return [str(k) for k in value]
    if isinstance(value, list):
        out: list[str] = []
        for item in value:
            if isinstance(item, str):
                out.append(item)
            elif isinstance(item, dict) and item:
                out.append(str(next(iter(item))))
        return out
    return []

def _parse_apm(text: str) -> dict | None:
    try:
        import yaml
    except ImportError:
        return _parse_apm_fallback(text)
    data = yaml.safe_load(text)
    if not isinstance(data, dict):
        return None
    return {
        "name": data.get("name"),
        "version": data.get("version"),
        "deps": _coerce_deps(data.get("dependencies")),
    }

def _parse_cargo(text: str) -> dict | None:
    """Cargo.toml: name/version from ``[package]``, runtime deps from
    ``[dependencies]`` plus every ``[target.<cfg>.dependencies]`` table (mirrors
    ``_parse_pyproject``'s runtime-only scope; dev-/build-dependencies excluded)."""
    _toml = _load_toml_module()
    data = _toml.loads(text)
    pkg = data.get("package", {}) if isinstance(data.get("package"), dict) else {}
    name = pkg.get("name")
    # A virtual workspace root (``[workspace]``, no ``[package]``) declares no
    # package of its own — emit nothing rather than a fabricated node. ``name`` is
    # never workspace-inheritable in Cargo, but guard on the type anyway.
    if not isinstance(name, str) or not name:
        if isinstance(data.get("workspace"), dict):
            return {"name": None, "skipped": "virtual workspace root Cargo.toml"}
        return None
    # ``version`` may be workspace-inherited (``version.workspace = true``), which
    # parses to a table; keep only a concrete string version.
    version = pkg.get("version")
    if not isinstance(version, str):
        version = None
    # A dependency value is a bare version string or an inline table; either way
    # _coerce_deps keys it by the dependency NAME (the table/map key).
    deps = _coerce_deps(data.get("dependencies"))
    # Platform-conditional deps live under ``[target.<cfg>.dependencies]``; fold
    # them in so a crate whose deps are entirely cfg-gated still emits its edges.
    targets = data.get("target")
    if isinstance(targets, dict):
        for cfg in targets.values():
            if isinstance(cfg, dict):
                deps += _coerce_deps(cfg.get("dependencies"))
    return {"name": name, "version": version, "deps": deps}

def _parse_gomod(text: str) -> dict | None:
    name = None
    deps: list[str] = []
    in_block = False
    for line in text.splitlines():
        s = line.strip()
        if name is None:
            m = re.match(r'^module\s+(\S+)', s)
            if m:
                name = m.group(1)
                continue
        if re.match(r'^require\s*\(', s):
            in_block = True
            continue
        if in_block:
            if s.startswith(')'):
                in_block = False
                continue
            dm = re.match(r'^(\S+)\s+v\S+', s)
            if dm:
                deps.append(dm.group(1))
        else:
            dm = re.match(r'^require\s+(\S+)\s+v\S+', s)
            if dm:
                deps.append(dm.group(1))
    return {"name": name, "version": None, "deps": deps} if name else None

def _pep508_name(spec: str) -> str:
    """`requests>=2.0` -> `requests`; `pkg[extra]==1; python_version<'3.9'` -> `pkg`."""
    return re.split(r'[\s<>=!~;\[\(]', spec.strip(), maxsplit=1)[0]

def _parse_pyproject(text: str) -> dict | None:
    _toml = _load_toml_module()
    data = _toml.loads(text)
    proj = data.get("project", {}) if isinstance(data.get("project"), dict) else {}
    poetry = (data.get("tool", {}) or {}).get("poetry", {}) if isinstance(data.get("tool"), dict) else {}
    name = proj.get("name") or (poetry.get("name") if isinstance(poetry, dict) else None)
    if not name:
        return None
    deps: list[str] = [_pep508_name(s) for s in (proj.get("dependencies") or []) if isinstance(s, str)]
    if isinstance(poetry, dict):
        for dep in (poetry.get("dependencies") or {}):
            if str(dep).lower() != "python":
                deps.append(str(dep))
    return {"name": name, "version": proj.get("version") or (poetry.get("version") if isinstance(poetry, dict) else None), "deps": deps}

def _pkg_id(name: str) -> str:
    """Canonical package node id, keyed by package NAME so every reference to the
    same package -- its own manifest and any dependent's dependency line -- maps
    to one node."""
    return make_id("pkg", name)

def extract_package_manifest(path: Path) -> dict[str, Any]:
    """Parse a package manifest into a canonical package node + ``depends_on`` edges."""
    try:
        if path.stat().st_size > _MAX_MANIFEST_BYTES:
            return {"nodes": [], "edges": [], "error": "manifest too large to index"}
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        return {"nodes": [], "edges": [], "error": f"manifest read error: {exc}"}

    eco = PACKAGE_MANIFEST_NAMES[path.name.lower()]
    try:
        info = _PARSERS[eco](text)
    except Exception as exc:  # noqa: BLE001 — a malformed manifest must not abort extraction
        return {"nodes": [], "edges": [], "error": f"manifest parse error: {exc}"}
    if isinstance(info, dict) and info.get("skipped"):
        return {"nodes": [], "edges": [], "skipped": info["skipped"]}
    if not info or not info.get("name"):
        return {"nodes": [], "edges": []}

    name = info["name"]
    str_path = str(path)
    pkg_nid = _pkg_id(name)
    node: dict[str, Any] = {
        "id": pkg_nid,
        "label": name,
        "file_type": "code",   # valid schema type; `type` distinguishes packages
        "type": "package",
        "ecosystem": eco,
        "source_file": str_path,
        "source_location": "L1",
    }
    if info.get("version"):
        node["version"] = info["version"]
    nodes: list[dict] = [node]
    edges: list[dict] = []

    seen: set[str] = set()
    for dep in info.get("deps", []):
        if not dep:
            continue
        dep_nid = _pkg_id(dep)
        if dep_nid == pkg_nid or dep_nid in seen:
            continue
        seen.add(dep_nid)
        # The edge targets the dependency's canonical package id. If that package's
        # own manifest is in the corpus, the edge resolves to its (single) node; if
        # the dependency is external, build_from_json prunes the dangling edge. We
        # deliberately do NOT emit a stub node — a stub with an empty source_file
        # would risk clobbering the real node's source_file under id-dedup.
        edges.append({
            "source": pkg_nid,
            "target": dep_nid,
            "relation": "depends_on",
            "context": "dependency",
            "confidence": "EXTRACTED",
            "confidence_score": 1.0,
            "source_file": str_path,
            "source_location": "L1",
            "weight": 1.0,
        })
    return {"nodes": nodes, "edges": edges}

def is_package_manifest_path(path: Path) -> bool:
    """True if ``path`` is a recognized package manifest (by filename)."""
    return path.name.lower() in PACKAGE_MANIFEST_NAMES

def _is_file_node(node: dict[str, Any]) -> bool:
    label = str(node.get("label", ""))
    source_file = str(node.get("source_file", ""))
    return bool(source_file) and label == os.path.basename(source_file)

def _markdown_raw_calls(per_file: list[dict]) -> list[dict]:
    calls: list[dict] = []
    for result in per_file:
        if not isinstance(result, dict):
            continue
        for rc in result.get("raw_calls", []) or []:
            if isinstance(rc, dict) and rc.get("language") == "markdown":
                calls.append(rc)
    return calls

def _symbol_label(node: dict[str, Any]) -> str:
    """A node's label as a document would write it: no ``()``, no leading dot."""
    return str(node.get("label", "")).strip("()").lstrip(".")

def _make_id(*parts: str) -> str:
    """Build a stable node ID via the single shared recipe (#1378)."""
    return _shared_make_id(*parts)

def _detect_package_from_args(args: list[Any]) -> str | None:
    """Return the first arg that looks like an npm or pypi package id, else None.

    Skips short flags (-y, --yes) and option arguments (--local-timezone=UTC).
    """
    for raw in args:
        if not isinstance(raw, str):
            continue
        arg = raw.strip()
        if not arg or _ARG_FLAG_RE.match(arg):
            continue
        if _NPM_PKG_RE.match(arg):
            return _strip_version(arg)
        if _PY_MCP_PKG_RE.match(arg):
            return arg
    return None

def extract_mcp_config(path: Path) -> dict[str, Any]:
    """Parse an MCP config file into Graphify nodes and edges.

    Behaviour matches other extractors in `extract.py`:
      - returns ``{"nodes": [...], "edges": [...]}`` on success
      - returns ``{"nodes": [], "edges": [], "error": "<reason>"}`` on parse
        failure, oversize file, or missing ``mcpServers`` map
    """
    try:
        with path.open("rb") as fh:
            raw = fh.read(_MAX_BYTES + 1)
    except OSError as exc:
        return {"nodes": [], "edges": [], "error": f"mcp_ingest read error: {exc}"}

    if len(raw) > _MAX_BYTES:
        return {"nodes": [], "edges": [], "error": "mcp config too large to index"}

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        return {"nodes": [], "edges": [], "error": f"mcp_ingest decode error: {exc}"}

    try:
        doc = json.loads(text)
    except json.JSONDecodeError as exc:
        return {"nodes": [], "edges": [], "error": f"mcp_ingest json error: {exc}"}

    if not isinstance(doc, dict):
        return {"nodes": [], "edges": [], "error": "mcp_ingest: root is not an object"}

    servers = doc.get("mcpServers")
    if not isinstance(servers, dict):
        # Some tools nest the map (e.g., {"mcp": {"servers": {...}}}). Try one
        # well-known alternate shape but do not search exhaustively.
        nested = doc.get("mcp")
        if isinstance(nested, dict):
            servers = nested.get("servers")
        if not isinstance(servers, dict):
            return {"nodes": [], "edges": [], "error": "mcp_ingest: no mcpServers map"}

    str_path = str(path)
    file_nid = _make_id(str_path)
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []
    seen_node_ids: set[str] = set()
    seen_edge_keys: set[tuple[str, str, str]] = set()

    _add_node(
        nodes, seen_node_ids,
        nid=file_nid,
        label=path.name,
        kind="mcp_config_file",
        source_file=str_path,
        line=1,
    )

    file_stem = _file_stem(path)
    server_count = 0
    for server_name, spec in servers.items():
        if not isinstance(server_name, str) or not server_name:
            continue
        if not isinstance(spec, dict):
            # Skip non-object server entries silently — the broken entry is
            # the user's, not ours.
            continue
        if server_count >= _MAX_SERVERS_PER_FILE:
            break
        server_count += 1
        _emit_server(
            server_name=server_name,
            spec=spec,
            file_nid=file_nid,
            file_stem=file_stem,
            source_file=str_path,
            nodes=nodes,
            edges=edges,
            seen_node_ids=seen_node_ids,
            seen_edge_keys=seen_edge_keys,
        )

    return {"nodes": nodes, "edges": edges}

def is_mcp_config_path(path: Path) -> bool:
    """Return True when ``path`` is a recognised MCP config filename."""
    return path.name in MCP_CONFIG_FILENAMES

def _check(name: str, func: Callable[[], bool | str]) -> CapabilityCheck:
    try:
        detail = func()
    except Exception as exc:
        return CapabilityCheck(name, False, f"{type(exc).__name__}: {exc}")
    if detail is True:
        return CapabilityCheck(name, True, "ok")
    if isinstance(detail, str):
        return CapabilityCheck(name, False, detail)
    return CapabilityCheck(name, False, f"unexpected result {detail!r}")

def _probe_duplicate_key_overwrite_semantics() -> bool | str:
    graph = nx.MultiDiGraph()
    graph.add_edge("x", "y", key="same", marker="first")
    graph.add_edge("x", "y", key="same", marker="second")
    edges = list(graph.edges(keys=True, data=True))
    if len(edges) != 1:
        return f"expected one edge after duplicate-key add, got {len(edges)}"
    if edges[0][3].get("marker") != "second":
        return f"expected second attr overwrite, got {edges[0][3].get('marker')!r}"
    return True

def _probe_keyed_parallel_edges() -> bool | str:
    graph = _build_probe_graph()
    if not graph.is_multigraph() or not graph.is_directed():
        return f"probe graph type was {type(graph).__name__}"
    if graph.number_of_edges("a", "b") != 2:
        return f"expected 2 keyed parallel edges, got {graph.number_of_edges('a', 'b')}"
    keys = set(graph["a"]["b"].keys())
    expected = {"calls:a.py:L1", "imports:a.py:L2"}
    if keys != expected:
        return f"expected keys {sorted(expected)}, got {sorted(keys)}"
    return True

def _probe_node_link_round_trip() -> bool | str:
    graph = _build_probe_graph()
    data = json_graph.node_link_data(graph, edges="links")
    if data.get("multigraph") is not True:
        return f"serialized multigraph flag was {data.get('multigraph')!r}"
    if data.get("directed") is not True:
        return f"serialized directed flag was {data.get('directed')!r}"
    links = data.get("links")
    if not isinstance(links, list) or len(links) != 2:
        length = 0 if not isinstance(links, list) else len(links)
        return f"serialized links length was {length}"
    serialized_keys: set[str] = set()
    for edge in links:
        if isinstance(edge, dict):
            edge_key = edge.get("key")
            if isinstance(edge_key, str):
                serialized_keys.add(edge_key)
    expected = {"calls:a.py:L1", "imports:a.py:L2"}
    if serialized_keys != expected:
        return f"serialized keys {sorted(serialized_keys)} did not match {sorted(expected)}"
    loaded = json_graph.node_link_graph(data, edges="links")
    if not isinstance(loaded, nx.MultiDiGraph):
        return f"round-trip graph type was {type(loaded).__name__}"
    if loaded.number_of_edges("a", "b") != 2:
        return f"round-trip edge count was {loaded.number_of_edges('a', 'b')}"
    loaded_keys = set(loaded["a"]["b"].keys())
    if loaded_keys != expected:
        return f"round-trip keys {sorted(loaded_keys)} did not match {sorted(expected)}"
    return True

def _probe_to_undirected_preserves_multigraph_type() -> bool | str:
    graph = _build_probe_graph()
    undirected = graph.to_undirected()
    undirected_view = graph.to_undirected(as_view=True)
    if not isinstance(undirected, nx.MultiGraph):
        return f"to_undirected() returned {type(undirected).__name__}"
    if not isinstance(undirected_view, nx.MultiGraph):
        return f"to_undirected(as_view=True) returned {type(undirected_view).__name__}"
    return True

def _pascal_raw_calls(per_file: list[dict]) -> list[dict]:
    calls: list[dict] = []
    for result in per_file:
        if not isinstance(result, dict):
            continue
        for rc in result.get("raw_calls", []):
            if not isinstance(rc, dict):
                continue
            if str(rc.get("source_file", "")).endswith(_PASCAL_SUFFIXES):
                calls.append(rc)
    return calls

def os_long_path(path: "str | Path") -> str:
    r"""Return an OS path string safe for open()/stat() on Windows long paths.

    On win32, paths longer than the legacy MAX_PATH (260 chars) are rejected by
    the plain file APIs unless prefixed with the extended-length marker ``\\?\``
    (which also requires a fully-qualified path). Without it, _md5_file /
    save_manifest / count_words silently fail to hash deeply-nested files, so
    their manifest entry never stabilizes and detect_incremental re-flags them
    as changed on every run (#1655), and cache entries under a deep root cannot
    be written at all. cache._normalize_path strips this prefix for stable
    KEYS; this adds it for I/O. Non-win32 and already-prefixed paths pass
    through unchanged.
    """
    if sys.platform != "win32":
        return str(path)
    s = str(path)
    if s.startswith("\\\\?\\"):
        return s
    try:
        s = os.path.abspath(s)  # \\?\ requires a fully-qualified path
    except Exception:
        return str(path)
    if s.startswith("\\\\"):
        # UNC share \\server\share -> \\?\UNC\server\share
        return "\\\\?\\UNC\\" + s[2:]
    return "\\\\?\\" + s

def out_path(*parts: str) -> Path:
    """A path inside the configured output dir, e.g. ``out_path("cache")``.

    ``Path(GRAPHIFY_OUT) / ...`` resolves correctly for both a relative name
    ("graphify-out") and an absolute override ("/shared/graphify-out").
    """
    return Path(GRAPHIFY_OUT, *parts)

def write_text_atomic(path: "str | Path", text: str) -> None:
    """Atomically write ``text`` (UTF-8) to ``path``. See :func:`_atomic_replace`."""
    _atomic_replace(path, lambda f: f.write(text))

def _quote_ident(name: str) -> str:
    """Double-quote a PostgreSQL identifier, escaping embedded double-quotes."""
    return '"' + name.replace('"', '""') + '"'

function isRemote(path: string): boolean {
  if (FILE_URL_RE.test(path)) {
    try {
      const { hostname } = new URL(path);
      return !(hostname === "" || hostname.toLowerCase() === "localhost");
    } catch {
      return true;
    }
  }
  return SCHEME_RE.test(path) || /^www\./i.test(path) || path.includes("://");
}

function localPath(value: string, cwd: string, selectors: boolean): string {
  if (value.startsWith("@")) value = value.slice(1);
  if (value === "~" || value.startsWith("~/")) value = join(homedir(), value.slice(2));
  if (FILE_URL_RE.test(value)) return fileURLToPath(value.replace(/^file:\/\/localhost/i, "file://"));
  const literal = resolve(cwd, value);
  if (!selectors || existsSync(literal)) return literal;
  const match = SELECTOR_RE.exec(value);
  return match ? resolve(cwd, match[1]) : literal;
}

function runGuard(command: string, kind: string, payload: string, cwd: string, signal: AbortSignal, timeout: number, maxBuffer: number): Promise<string | undefined> {
  if (Buffer.byteLength(payload) > INPUT_LIMIT || signal.aborted) return Promise.resolve(undefined);
  const { promise, resolve: done } = Promise.withResolvers<string | undefined>();
  const child = execFile(command, ["hook-guard", kind], {
    cwd, encoding: "utf8", timeout, killSignal: "SIGKILL", maxBuffer, signal,
    env: { ...process.env, CLAUDE_PROJECT_DIR: cwd },
  }, (error, stdout) => done(error ? undefined : stdout.trim() || undefined));
  child.stdin?.on("error", () => {});
  child.stdin?.end(payload);
  return promise;
}

function which(name: string, path: string): string | undefined {
  const exts = process.platform === "win32" ? (process.env.PATHEXT ?? ".EXE;.CMD;.BAT").split(";") : [""];
  for (const dir of path.split(delimiter)) {
    for (const ext of exts) {
      const candidate = join(dir, name + ext);
      try {
        if (!statSync(candidate).isFile()) continue;
        accessSync(candidate, constants.X_OK);
        return candidate;
      } catch {
        // not here, or not executable
      }
    }
  }
}

function installedCommand(cwd: string): string | undefined {
  const project = realpathSync(cwd);
  for (const dir of (process.env.PATH ?? "").split(delimiter).filter(isAbsolute)) {
    const found = which("graphify", dir);
    if (!found) continue;
    const within = relative(project, realpathSync(found));
    if (within.startsWith(`..${sep}`) || isAbsolute(within)) return found;
  }
}

function graphify(api: HostAPI): void {
  // OMP delivers `additionalContext` from tool_call as a separate passive
  // developer message after the batch: deduplicated, dropped for denied or
  // failed calls, and shown on the tool card. Pi has no such channel, so it
  // gets the same text as a steering message, delivered after the tool batch
  // and before the next model call. Either way raw tool output stays untouched,
  // so a file or command cannot forge this instruction channel. Both hosts send
  // it as unlabelled user text, so it is wrapped the way Claude Code labels
  // PreToolUse context; bare text reads as noise and agents ignore it.
  const passive = typeof api.pi === "object" && api.pi !== null;
  let controller = new AbortController();
  const reset = () => {
    controller.abort();
    controller = new AbortController();
  };
  // session_switch and session_branch exist only on OMP; Pi reloads extensions
  // and emits session_shutdown + session_start instead.
  for (const event of ["session_start", "session_switch", "session_branch", "session_tree", "session_shutdown", "before_agent_start"]) {
    api.on(event, reset);
  }

  api.on("tool_call", async (event: HostEvent, ctx: HostContext) => {
    const trusted = () => ctx.isProjectTrusted?.() ?? true;
    const signal = ctx.signal ? AbortSignal.any([controller.signal, ctx.signal]) : controller.signal;
    const deadline = performance.now() + TIMEOUT_MS;
    const contexts: string[] = [];
    try {
      if (!trusted()) { reset(); return; }
      if (!Object.hasOwn(TOOL_NAMES, event.toolName)) return;
