    got = getattr(_local, "active", None)
    if got is None:
        got = {}
        _local.active = got
    return got

def _normalise_ext(raw: str) -> str:
    ext = raw.strip().lower()
    if not ext.startswith("."):
        ext = "." + ext
    return ext

def parse_language_value(value: str) -> str:
    """Resolve the right-hand side of ``language.<ext>=`` to a canonical suffix.

    Accepts a name from :data:`LANGUAGE_ALIASES` (case-insensitive) or an
    explicit dotted extension. Raises ``ValueError`` for anything else.
    """
    v = value.strip()
    if not v:
        raise ValueError("empty value")
    if v.startswith("."):
        ext = _normalise_ext(v)
        if len(ext) < 2 or any(ch.isspace() for ch in ext):
            raise ValueError(f"{value!r} is not an extension")
        from graphify.detect import CODE_EXTENSIONS, DOC_EXTENSIONS
        if ext not in CODE_EXTENSIONS and ext not in DOC_EXTENSIONS:
            raise ValueError(f"unknown extension {value!r}")
        return ext
    try:
        return LANGUAGE_ALIASES[v.lower()]
    except KeyError:
        known = ", ".join(sorted(LANGUAGE_ALIASES))
        raise ValueError(
            f"unknown language {value!r} (use one of: {known}; "
            f"or an explicit extension such as .php)"
        ) from None

def load_graphifyrc(root: Path) -> dict:
    """Parse ``<root>/.graphifyrc``. Returns ``{}`` when absent.

    Returned keys: ``viz_node_limit`` (int) and ``languages``
    (``{".inc": ".php", ...}``) — each present only when the file sets it.
    Unknown keys are ignored so a newer graphify's options do not break an
    older one. Malformed lines raise ``ValueError`` naming the line.
    """
    rc_path = Path(root) / RC_FILENAME
    if not rc_path.is_file():
        return {}

    cfg: dict = {}
    languages: dict[str, str] = {}
    # utf-8-sig: Windows PowerShell 5.1 (`Set-Content -Encoding UTF8`) and older
    # Notepad save UTF-8 with a BOM. Read as plain utf-8, the BOM became part of
    # the first key, which then matched nothing and was ignored without a word.
    content = rc_path.read_text(encoding="utf-8-sig")
    for line_num, raw in enumerate(content.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"Invalid line {line_num} in {rc_path}: {raw!r} (expected key=value)")
        key, val = line.split("=", 1)
        key = key.strip()
        val = val.strip()
        if key == "viz_node_limit":
            try:
                parsed_val = int(val)
                if parsed_val < 0:
                    raise ValueError("must be a non-negative integer")
                cfg["viz_node_limit"] = parsed_val
            except ValueError as exc:
                raise ValueError(
                    f"Invalid viz_node_limit in {rc_path} at line {line_num}: {val!r}. "
                    f"Must be a non-negative integer."
                ) from exc
        elif key.startswith("language."):
            ext_part = key[len("language."):].strip()
            if not ext_part or any(ch.isspace() for ch in ext_part):
                raise ValueError(
                    f"Invalid language key in {rc_path} at line {line_num}: {key!r} "
                    f"(expected language.<ext>=<language>)"
                )
            try:
                target = parse_language_value(val)
            except ValueError as exc:
                raise ValueError(
                    f"Invalid {key} in {rc_path} at line {line_num}: {exc}"
                ) from None
            languages[_normalise_ext(ext_part)] = target
    if languages:
        cfg["languages"] = languages
    return cfg

def set_language_overrides(mapping: dict[str, str] | None) -> None:
    """Replace this thread's extension overrides (``{".inc": ".php"}``)."""
    active = _active()
    active.clear()
    if mapping:
        for ext, target in mapping.items():
            active[_normalise_ext(ext)] = _normalise_ext(target)

def activate_language_overrides(root: Path) -> dict[str, str]:
    """Load ``<root>/.graphifyrc`` and make its language overrides active.

    A malformed file is reported once per root on stderr and treated as
    having no overrides — a scan must not die on a config typo, but the
    user must hear about it, or their ``.inc`` silently stays Pascal.
    Returns the mapping now active.
    """
    try:
        cfg = load_graphifyrc(Path(root))
    except (ValueError, OSError) as exc:
        key = str(root)
        if key not in _warned_roots:
            _warned_roots.add(key)
            print(f"[graphify] warning: ignoring {RC_FILENAME}: {exc}", file=sys.stderr)
        cfg = {}
    set_language_overrides(cfg.get("languages"))
    return get_language_overrides()

def _build_id_label_maps(graph_path: Path) -> tuple[dict[str, str], dict[str, list[str]],
                                                    dict[str, dict[str, Any]]]:
    """From graph.json build:

    - ``id_set``: id -> id (every node id, so an id-form citation resolves to itself)
    - ``label_to_ids``: label -> [ids] (so a label-form citation can be resolved,
      and ambiguity — one label, many ids — can be detected and skipped)
    - ``node_by_id``: id -> node dict (for source_file lookup)

    Best-effort; an unreadable/garbage graph yields empty maps.
    """
    id_set: dict[str, str] = {}
    label_to_ids: dict[str, list[str]] = {}
    node_by_id: dict[str, dict[str, Any]] = {}
    try:
        data = json.loads(Path(graph_path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return id_set, label_to_ids, node_by_id
    for n in data.get("nodes", []):
        if not isinstance(n, dict) or n.get("id") is None:
            continue
        nid = str(n["id"])
        id_set[nid] = nid
        node_by_id[nid] = n
        label = n.get("label")
        if label is not None:
            label_to_ids.setdefault(str(label), []).append(nid)
    return id_set, label_to_ids, node_by_id

def _content_hash(path: Path) -> str:
    """SHA256 of file CONTENT only (no path mixed in), so the fingerprint is
    independent of which root resolved the file — write and read agree, and a
    committed sidecar stays valid across machines/checkouts."""
    import hashlib
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return ""

def _dedupe_by_question(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse repeated questions to one entry. Docs are processed oldest-first, so
    the last write per question wins (recency — e.g. the most recent correction text).
    Output is deterministically ordered by (date, question). Without this, saving the
    same Q&A twice duplicated lines in the dead-ends / corrections lists, even though
    node scoring already dedups by node.
    """
    latest: dict[str, dict[str, Any]] = {}
    for it in items:
        latest[it.get("question", "")] = it
    return sorted(latest.values(),
                  key=lambda it: (it.get("date", ""), it.get("question", "")))

def _load_known_nodes(graph_path: Path) -> set[str] | None:
    """The set of node ids AND labels in the current graph, or None if unavailable.

    Used to drop source nodes from lessons once the code they pointed at is gone
    (deleted/renamed) — a stale lesson shouldn't keep getting recommended. Both ids
    and labels are collected because `save-result` records source nodes by their
    human-readable label (what an agent cites, e.g. ``build_from_json()``), while
    graph nodes are keyed by id (e.g. ``module_build_from_json``). Matching on either
    keeps a still-present node and only drops one that survives under neither name —
    indexing ids alone silently dropped every label-form citation (the common case).
    """
    try:
        data = json.loads(Path(graph_path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    nodes = data.get("nodes")
    if not isinstance(nodes, list):
        return None
    known: set[str] = set()
    for n in nodes:
        if not isinstance(n, dict):
            continue
        if n.get("id") is not None:
            known.add(str(n["id"]))
        if n.get("label") is not None:
            known.add(str(n["label"]))
    return known or None

def _load_node_community(graph_path: Path, analysis_path: Path,
                         labels_path: Path) -> dict[str, str] | None:
    """Build a lookup from node id AND node label -> community label, or None if the
    graph isn't available.

    Mirrors how `graphify export wiki` reads graph.json + .graphify_analysis.json +
    .graphify_labels.json. Community membership in the analysis sidecar is keyed by
    node id, but `save-result` cites nodes by label, so both are mapped — otherwise a
    cited ``build_from_json()`` never finds its community and every lesson collapses
    into Uncategorized. Best-effort: any missing/unparseable artifact disables grouping.
    """
    if not graph_path.exists() or not analysis_path.exists():
        return None
    try:
        analysis = json.loads(analysis_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    communities = analysis.get("communities", {})
    if not communities:
        return None
    labels: dict[str, str] = {}
    if labels_path.exists():
        try:
            labels = json.loads(labels_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            labels = {}
    # id -> label from the graph, so a label-form citation resolves to a community too.
    id_to_label: dict[str, str] = {}
    try:
        gdata = json.loads(graph_path.read_text(encoding="utf-8"))
        for n in gdata.get("nodes", []):
            if isinstance(n, dict) and n.get("id") is not None and n.get("label") is not None:
                id_to_label[str(n["id"])] = str(n["label"])
    except (OSError, ValueError):
        id_to_label = {}
    # Sorted cid iteration + setdefault makes any label collision resolve
    # deterministically (smallest community id wins).
    node_community: dict[str, str] = {}
    for cid in sorted(communities, key=str):
        label = labels.get(str(cid)) or labels.get(cid) or f"Community {cid}"
        for nid in communities[cid]:
            nid = str(nid)
            node_community.setdefault(nid, label)
            nlabel = id_to_label.get(nid)
            if nlabel is not None:
                node_community.setdefault(nlabel, label)
    return node_community

def _parse_dt(date_str: str) -> datetime | None:
    """Parse an ISO date/datetime to an aware UTC datetime, or None if unparseable."""
    if not date_str:
        return None
    try:
        dt = datetime.fromisoformat(date_str)
    except ValueError:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt

def _decay(date_str: str, now: datetime, half_life_days: float) -> float:
    """Time-decay weight in (0, 1]: halves every ``half_life_days``.

    Undated/unparseable signals keep full weight (1.0); future-dated ones are
    clamped to age 0 (also 1.0).
    """
    dt = _parse_dt(date_str)
    if dt is None or half_life_days <= 0:
        return 1.0
    age_days = max(0.0, (now - dt).total_seconds() / 86400.0)
    return 0.5 ** (age_days / half_life_days)

def _record_node(bucket: dict[str, Any], node: str, sign: int,
                 weight: float, date: str, *, outcome: str | None = None,
                 question: str = "") -> None:
    bucket["node_score"][node] = bucket["node_score"].get(node, 0.0) + sign * weight
    if sign > 0:
        bucket["node_pos"][node] += 1
    elif sign < 0:
        bucket["node_neg"][node] += 1
    if date > bucket["node_last"].get(node, ""):
        bucket["node_last"][node] = date
    # Provenance: only useful/corrected events are recorded (the experiential
    # trail an agent cares about — what cited this node, and how it turned out).
    if outcome in ("useful", "corrected"):
        bucket["node_provenance"].setdefault(node, []).append(
            (date, question, outcome))

def _render_bucket(out: list[str], data: dict[str, Any], k: int) -> None:
    preferred = data["preferred"]
    tentative = data["tentative"]
    contested = data["contested"]
    dead_ends = data["dead_ends"]
    corrections = data["corrections"]

    if preferred:
        out += [f"**Preferred sources** — corroborated by ≥{k} useful results; "
                "start here.", ""]
        for e in preferred:
            out.append(f"- `{e['node']}` ({e['n']}× useful)")
        out.append("")
    if tentative:
        out += [f"**Tentative** — useful in fewer than {k} results; verify before "
                "relying.", ""]
        for e in tentative:
            out.append(f"- `{e['node']}` ({e['n']}× useful)")
        out.append("")
    if contested:
        out += ["**Contested** — mixed signals; recency decides.", ""]
        for e in contested:
            day = e["last"][:10]
            verdict = ("evenly split" if e["verdict"] == "even"
                       else f"recency leans **{e['verdict']}**")
            out.append(
                f"- `{e['node']}` — {e['pos']}× useful, {e['neg']}× "
                f"dead end/corrected → {verdict}"
                + (f" (latest {day})" if day else ""))
        out.append("")
    if dead_ends:
        out += ["**Known dead ends** — led nowhere; don't re-derive.", ""]
        for d in dead_ends:
            nodes = ", ".join(f"`{n}`" for n in d["nodes"])
            out.append(f"- \"{d['question']}\"" + (f" — {nodes}" if nodes else ""))
        out.append("")
    if corrections:
        out += ["**Corrections** — do these differently.", ""]
        for c in corrections:
            out.append(f"- \"{c['question']}\" → {c['correction']}")
        out.append("")
    if not (preferred or tentative or contested or dead_ends or corrections):
        out += ["_No marked outcomes yet._", ""]

def _yaml_unescape(s: str) -> str:
    """Reverse the double-quoted escaping that ingest._yaml_str applies."""
    out: list[str] = []
    i = 0
    simple = {"n": "\n", "r": "\r", "t": "\t", "0": "\0", '"': '"', "\\": "\\",
              "L": "\u2028", "P": "\u2029"}  # YAML line/paragraph separators
    while i < len(s):
        ch = s[i]
        if ch == "\\" and i + 1 < len(s):
            nxt = s[i + 1]
            if nxt in simple:
                out.append(simple[nxt])
                i += 2
                continue
            if nxt == "x" and i + 3 < len(s):
                try:
                    out.append(chr(int(s[i + 2:i + 4], 16)))
                    i += 4
                    continue
                except ValueError:
                    pass
            if nxt == "u" and i + 5 < len(s):
                try:
                    out.append(chr(int(s[i + 2:i + 6], 16)))
                    i += 6
                    continue
                except ValueError:
                    pass
        out.append(ch)
        i += 1
    return "".join(out)

def lessons_fresh(out_path: Path, memory_dir: Path,
                  graph_path: Path | None = None,
                  analysis_path: Path | None = None,
                  labels_path: Path | None = None) -> bool:
    """True if ``out_path`` exists and is at least as new as every input that
    feeds it (the memory docs, and the graph/sidecars when one is used).

    Lets ``graphify reflect --if-stale`` skip a redundant run — e.g. when the git
    post-commit hook just regenerated ``LESSONS.md`` and an agent then runs reflect
    again at the start of a session. A missing output is never fresh (it must be
    built). Mtime-based and best-effort; it only gates whether to *recompute*, not
    what the recomputation produces (that stays deterministic).
    """
    out_path = Path(out_path)
    try:
        out_mtime = out_path.stat().st_mtime
    except OSError:
        return False  # missing/unreadable -> must build
    newest = 0.0
    md = Path(memory_dir)
    if md.is_dir():
        for f in md.glob("*.md"):
            try:
                newest = max(newest, f.stat().st_mtime)
            except OSError:
                pass
    for input_path in (graph_path, analysis_path, labels_path):
        if input_path is None:
            continue
        gp = Path(input_path)
        try:
            newest = max(newest, gp.stat().st_mtime)
        except OSError:
            pass
    return out_mtime >= newest

def load_learning_overlay(graph_path: Path) -> dict[str, dict[str, Any]]:
    """Load the sidecar next to ``graph_path`` and return ``{node_id -> entry}``
    with a recomputed ``stale: bool`` per entry. Best-effort -> {} on any error.

    Staleness: recompute ``file_hash(source_file)`` and compare to the entry's
    stored ``code_fingerprint``. Matching fingerprints -> not stale. Differing,
    missing-but-recomputable, or a vanished file -> stale (the safe, over-flagging
    direction). An entry with no stored fingerprint AND no current file is not
    marked stale (nothing to re-verify).
    """
    sidecar = Path(graph_path).parent / LEARNING_SIDECAR_NAME
    try:
        data = json.loads(sidecar.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    nodes = data.get("nodes")
    if not isinstance(nodes, dict):
        return {}
    out: dict[str, dict[str, Any]] = {}
    for nid, entry in nodes.items():
        if not isinstance(entry, dict):
            continue
        merged = dict(entry)
        merged["stale"] = _is_stale(entry, graph_path)
        out[str(nid)] = merged
    return out

def parse_memory_doc(text: str) -> dict[str, Any] | None:
    """Parse the frontmatter of a memory doc into a dict, or None if it has none.

    Returns the recognised fields (``type``, ``date``, ``question``, ``outcome``,
    ``correction``, ``source_nodes``). ``source_nodes`` is always a list.
    """
    if not text.startswith("---"):
        return None
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    fields: dict[str, Any] = {"source_nodes": []}
    for line in lines[1:]:
        if line.strip() == "---":
            break
        m = _LIST_RE.match(line)
        if m and m.group(1) == "source_nodes":
            fields["source_nodes"] = [
                _yaml_unescape(item) for item in _DQ_ITEM_RE.findall(m.group(2))
            ]
            continue
        m = _SCALAR_RE.match(line)
        if m:
            key, val = m.group(1), _yaml_unescape(m.group(2))
            if key in ("type", "date", "question", "outcome", "correction", "contributor"):
                fields[key] = val
    return fields

def _learning_section(lines: list, learning: dict | None, top_n: int = 10) -> None:
    """Append the ``## Work-memory lessons`` section, or nothing when empty."""
    if not learning:
        return
    overlay = learning.get("overlay") or {}
    dead_ends = learning.get("dead_ends") or []
    preferred = [
        (nid, e) for nid, e in overlay.items()
        if isinstance(e, dict) and e.get("status") == "preferred"
    ]
    # Most-corroborated first (uses desc), then by score, then id for stability.
    preferred.sort(key=lambda kv: (-kv[1].get("uses", 0),
                                   -float(kv[1].get("score", 0) or 0), kv[0]))
    if not preferred and not dead_ends:
        return
    lines += ["", "## Work-memory lessons"]
    if preferred:
        lines += ["", "**Preferred sources** — corroborated by past sessions; start here."]
        for nid, e in preferred[:top_n]:
            label = e.get("label") or nid
            stale = " _(code changed — re-verify)_" if e.get("stale") else ""
            lines.append(f"- `{label}` ({e.get('uses', 0)}× useful, "
                         f"score={e.get('score', 0)}){stale}")
    if dead_ends:
        lines += ["", "**Known dead ends** — questions that led nowhere; don't re-derive."]
        for d in dead_ends:
            nodes = ", ".join(f"`{n}`" for n in d.get("nodes", []))
            lines.append(f"- \"{d.get('question', '')}\""
                         + (f" -> {nodes}" if nodes else ""))

def registered_resolvers() -> list[LanguageResolver]:
    """Return a copy of the registered resolvers, in registration order."""
    return list(_REGISTRY)

def _key(label: str) -> str:
    """Normalize a class/method label to a comparison key (drop punctuation)."""
    return re.sub(r"[^a-zA-Z0-9]+", "", str(label)).lower()

def _ruby_lookup_unsafe(node: dict | None) -> bool:
    metadata = node.get("metadata") if isinstance(node, dict) else None
    return isinstance(metadata, dict) and bool(
        metadata.get("ruby_lookup_unsafe") or metadata.get("ruby_reopened")
    )

def _ruby_method_kind(node: dict | None) -> str | None:
    metadata = node.get("metadata") if isinstance(node, dict) else None
    if not isinstance(metadata, dict):
        return None
    kind = metadata.get("ruby_method_kind")
    return kind if kind in {"instance", "singleton"} else None

def _ruby_raw_calls(per_file: list[dict]) -> list[dict]:
    calls: list[dict] = []
    for result in per_file:
        if not isinstance(result, dict):
            continue
        for rc in result.get("raw_calls", []):
            if not isinstance(rc, dict):
                continue
            sf = str(rc.get("source_file", ""))
            if sf.endswith((".rb", ".rake")):
                calls.append(rc)
    return calls

def _build_scip_metadata(symbol_id: str, kind: str, description: str) -> dict[str, str]:
    """Build metadata for a SCIP node."""
    meta: dict[str, str] = {
        "scip_symbol": symbol_id,
        "scip_kind": kind,
    }
    if description:
        meta["scip_description"] = description
    return meta

def _coerce_str(value: object, default: str) -> str:
    """Return ``value`` if it is a string, else the ``default`` (also a string)."""
    if isinstance(value, str):
        return value
    if isinstance(default, str):
        return default
    return ""

def _scip_kind_to_file_type(kind: str) -> str:
    """Map SCIP symbol kind to a Graphify file_type."""
    # All SCIP symbols are code entities (functions, methods, classes, …);
    # the `kind` is preserved in metadata for downstream consumers.
    _ = kind  # acknowledged but not currently used for file_type routing
    return "code"

def _scip_relation_for(rel: dict[str, Any]) -> str:
    """Pick the Graphify relation tag for a SCIP relationship dict.

    Flags are accepted only when the value is exactly ``True`` — protects
    against truthy-but-misleading values like ``"false"`` in external JSON.
    """
    if _is_true(rel.get("is_implementation")):
        return "scip_impl"
    if _is_true(rel.get("is_type_definition")):
        return "scip_typed"
    if _is_true(rel.get("is_definition")):
        return "scip_def"
    return "scip_ref"

def _build_opener() -> urllib.request.OpenerDirector:
    # build_opener replaces the default HTTP(S)Handlers with our SSRF-guarded
    # subclasses, so every connection resolves+validates DNS once and connects
    # to that exact IP. Thread-safe: no process-global state is mutated.
    return urllib.request.build_opener(
        _SSRFGuardedHTTPHandler,
        _SSRFGuardedHTTPSHandler,
        _NoFileRedirectHandler,
    )

def _resolve_and_validate(host: str, port: int) -> tuple[int, str]:
    """Resolve *host* once and return (family, validated_ip) for the first
    address that is not in a blocked range.

    Raises OSError if every resolved address is private/reserved/internal,
    matching the failure mode urllib/http.client expect from connect().
    """
    infos = socket.getaddrinfo(host, port, socket.AF_UNSPEC, socket.SOCK_STREAM)
    for family, _type, _proto, _canon, sockaddr in infos:
        addr = sockaddr[0]
        try:
            ip = ipaddress.ip_address(addr)
        except ValueError:
            continue
        if _ip_is_blocked(ip):
            raise OSError(
                f"SSRF blocked: IP {addr} resolved from '{host}' is private/reserved"
            )
        return family, addr
    raise OSError(f"SSRF blocked: no usable address resolved from '{host}'")

def _sanitize_metadata_string(value: object) -> str:
    """Return a control-character-free, HTML-escaped, bounded string."""
    text = _CONTROL_CHAR_RE.sub("", str(value))
    text = html.escape(text, quote=True)
    if len(text) > _METADATA_MAX_VALUE_LEN:
        text = text[:_METADATA_MAX_VALUE_LEN]
    return text  # html is imported at module level (line 5)

def redact_secrets(text: str | None) -> str:
    """Replace credential-shaped substrings in *text* with ``[redacted]``.

    Applied to free text copied out of source files (docstrings and ``# WHY:``
    style comments) before it becomes a node label, so a token pasted into a
    comment does not land in graph.json / graph.html / GRAPH_REPORT.md.
    """
    if not text:
        return "" if text is None else text
    return _SECRET_SHAPE_RE.sub(REDACTED_MARKER, str(text))

def validate_graph_path(path: str | Path, base: Path | None = None) -> Path:
    """Resolve *path* and verify it stays inside *base*.

    *base* defaults to the `graphify-out` directory relative to CWD.
    Also requires the base directory to exist, so a caller cannot
    trick graphify into reading files before any graph has been built.

    Raises:
        ValueError  - path escapes base, or base does not exist
        FileNotFoundError - resolved path does not exist
    """
    if base is None:
        resolved_hint = Path(path).resolve()
        for candidate in [resolved_hint, *resolved_hint.parents]:
            if candidate.name == GRAPHIFY_OUT_NAME:
                base = candidate
                break
        if base is None:
            base = Path(GRAPHIFY_OUT).resolve()

    base = base.resolve()
    if not base.exists():
        raise ValueError(
            f"Graph base directory does not exist: {base}. "
            "Run /graphify first to build the graph."
        )

    resolved = Path(path).resolve()
    try:
        resolved.relative_to(base)
    except ValueError:
        raise ValueError(
            f"Path {path!r} escapes the allowed directory {base}. "
            "Only paths inside graphify-out/ are permitted."
        )

    if not resolved.exists():
        raise FileNotFoundError(f"Graph file not found: {resolved}")

    return resolved

def validate_url(url: str) -> str:
    """Raise ValueError if *url* is not http or https, or targets a private/internal IP.

    Blocks file://, ftp://, data:, and any other scheme that could be used
    for SSRF or local file access. Also blocks requests to private/reserved
    IP ranges (127.x, 10.x, 169.254.x, etc.) and cloud metadata endpoints
    to prevent SSRF in cloud environments.
    """
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme.lower() not in _ALLOWED_SCHEMES:
        raise ValueError(
            f"Blocked URL scheme '{parsed.scheme}' - only http and https are allowed. "
            f"Got: {url!r}"
        )

    if parsed.username is not None or parsed.password is not None:
        raise ValueError(f"Blocked URL containing embedded credentials. Got: {url!r}")

    try:
        port = parsed.port
    except ValueError as exc:
        raise ValueError(f"Blocked URL with an invalid port. Got: {url!r}") from exc
    if port == 0:
        raise ValueError(f"Blocked URL with port 0. Got: {url!r}")

    hostname = parsed.hostname
    if not hostname:
        raise ValueError(f"Blocked URL without a hostname. Got: {url!r}")

    if hostname:
        # Block known cloud metadata hostnames
        if hostname.lower() in _BLOCKED_HOSTS:
            raise ValueError(
                f"Blocked cloud metadata endpoint '{hostname}'. "
                f"Got: {url!r}"
            )

        # Resolve hostname and block private/reserved IP ranges
        try:
            infos = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
            for info in infos:
                addr = info[4][0]
                ip = ipaddress.ip_address(addr)
                if _ip_is_blocked(ip):
                    raise ValueError(
                        f"Blocked private/internal IP {addr} (resolved from '{hostname}'). "
                        f"Got: {url!r}"
                    )
        except socket.gaierror as exc:
            raise ValueError(
                f"DNS resolution failed for '{hostname}': {exc}. Got: {url!r}"
            ) from exc

    return url

def safe_fetch_text(url: str, max_bytes: int = _MAX_TEXT_BYTES, timeout: int = 15) -> str:
    """Fetch *url* and return decoded text (UTF-8, replacing bad bytes).

    Wraps safe_fetch with tighter defaults for HTML / text content.
    """
    raw = safe_fetch(url, max_bytes=max_bytes, timeout=timeout)
    return raw.decode("utf-8", errors="replace")

def _validate_semantic_id(errors: list[str], field: str, value: object) -> None:
    if not isinstance(value, str):
        errors.append(f"{field} must be a string")
        return
    if not value:
        errors.append(f"{field} must not be empty")
        return
    if len(value) > MAX_SEMANTIC_ID_LENGTH:
        errors.append(f"{field} is {len(value)} chars; max is {MAX_SEMANTIC_ID_LENGTH}")
    if "/" in value or "\\" in value or ".." in value:
        errors.append(f"{field} must not contain path separators or '..'")
    if not _SEMANTIC_ID_RE.fullmatch(value):
        errors.append(f"{field} contains unsupported characters")

def load_validated_semantic_fragment(path: Path) -> tuple[dict | None, list[str]]:
    """Load and validate a semantic chunk, rejecting oversize files before parsing.

    The size guard runs against `path.stat().st_size` so an attacker-supplied
    multi-gigabyte chunk file cannot blow up memory at `read_text()` time.
    JSON decode errors are returned as validation errors rather than raised,
    so callers can `continue` past bad chunks without a try/except.
    """
    try:
        size = path.stat().st_size
    except OSError as exc:
        return None, [f"could not stat {path}: {exc}"]
    if size > MAX_SEMANTIC_FRAGMENT_BYTES:
        return None, [f"payload is {size} bytes; max is {MAX_SEMANTIC_FRAGMENT_BYTES}"]
    try:
        fragment = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        return None, [f"invalid JSON: {exc}"]
    except OSError as exc:
        return None, [f"could not read {path}: {exc}"]
    errors = validate_semantic_fragment(fragment)
    return (None, errors) if errors else (fragment, [])

def _communities_from_graph(G: nx.Graph) -> dict[int, list[str]]:
    """Reconstruct community dict from community property stored on nodes."""
    communities: dict[int, list[str]] = {}
    for node_id, data in G.nodes(data=True):
        cid = data.get("community")
        if cid is not None:
            communities.setdefault(int(cid), []).append(node_id)
    return communities

def _community_header(cid: int, community_name) -> str:
    # Header for get_community: "Community N — Name", matching get_node / query
    # output which read the community_name attribute to_json writes onto nodes.
    # Skip the name when it is just the "Community N" placeholder (written for
    # unnamed communities) so the header never reads "Community 12 — Community 12";
    # also falls back to the bare id when there is no name. Name is sanitised
    # (F-010) like every other LLM-derived field.
    base = f"Community {cid}"
    if community_name:
        clean = sanitize_label(str(community_name))
        if clean and clean != base:
            return f"{base} — {clean}"
    return base

def _display_graph_path(graph_path: str) -> str:
    """Render a graph path for the query header.

    Relative to the CWD when it sits underneath it — `graphify-out/graph.json`,
    which is the ordinary case and stays short. Absolute otherwise, because a
    graph outside the directory you are standing in is precisely the situation
    the header exists to make visible (#2789). Always POSIX separators so the
    line reads the same on either platform. Falls back to the path as given if
    it cannot be resolved; this is a display helper and must never be the reason
    a query fails.
    """
    try:
        p = Path(graph_path).resolve()
        try:
            return p.relative_to(Path.cwd().resolve()).as_posix()
        except ValueError:
            return p.as_posix()
    except (OSError, RuntimeError, ValueError):
        return str(graph_path)

def _flatten_attr_text(val, parts: list[str]) -> None:
    if isinstance(val, dict):
        for k, v in val.items():
            parts.append(str(k))
            _flatten_attr_text(v, parts)
    elif isinstance(val, (list, tuple)):
        for item in val:
            _flatten_attr_text(item, parts)
    elif val is not None:
        parts.append(str(val))

def _is_ambiguity_refusal(message: str | None) -> bool:
    """True for a refusal that lists candidates, False for a miss (no node matched)."""
    return message is not None and message.startswith(_AMBIGUOUS)

def _is_searchable(term: str) -> bool:
    """True if term is Chinese, non-English, or an English word longer than 2 chars."""
    if all("a" <= ch <= "z" for ch in term):
        return len(term) > 2
    return True

def _max_server_contexts() -> int:
    """Return the project-context LRU capacity (default 8, minimum 1).

    ``GRAPHIFY_MAX_CONTEXTS`` overrides the default. Invalid or blank values
    use 8; zero and negative values clamp to 1, since each request needs a
    graph context. The server's configured default graph is pinned separately
    and does not count against this limit.
    """
    raw = os.environ.get("GRAPHIFY_MAX_CONTEXTS", "").strip()
    if not raw:
        return 8
    try:
        return max(1, int(raw))
    except ValueError:
        return 8

def _read_graph(graph_path: str) -> nx.Graph:
    """Load graph.json exactly as the MCP server does, raising on a bad path
    or file (ValueError, FileNotFoundError, json.JSONDecodeError) so a library
    caller such as the benchmark can handle it."""
    resolved = Path(graph_path).resolve()
    if resolved.suffix != ".json":
        raise ValueError(f"Graph path must be a .json file, got: {graph_path!r}")
    if not resolved.exists():
        raise FileNotFoundError(f"Graph file not found: {resolved}")
    check_graph_file_size_cap(resolved)
    safe = resolved
    data = json.loads(safe.read_text(encoding="utf-8"))
    if "links" not in data and "edges" in data:
        data = dict(data, links=data["edges"])
    # Stash the on-disk logical flag before the load-time override below:
    # `directed: True` exists only so renderers can recover stored arc
    # order (#2309); tools that care about logical direction (#2487) must
    # not mistake the override for graph truth.
    _logical_directed = bool(data.get("directed", False))
    data = {**data, "directed": True}
    # Repair files whose links hold parallel edges while the serialized flag says
    # otherwise (#4500): older writers restored original_links verbatim while
    # node_link_data derived "multigraph": false from the simple graph. Forced the
    # same way "directed" is forced above, so the load keeps every relationship
    # instead of collapsing parallel edges.
    if has_parallel_links(data.get("links"), directed=True):
        data = {**data, "multigraph": True}
    try:
        from graphify.build import graph_has_legacy_ids as _legacy
        if _legacy(data.get("nodes", [])):
            print(
                "[graphify] note: this graph uses the pre-#1504 node-ID scheme; "
                "rebuild with `graphify extract --force` for path-qualified IDs.",
                file=sys.stderr,
            )
    except Exception:
        pass
    try:
        G = json_graph.node_link_graph(data, edges="links")
    except TypeError:
        G = json_graph.node_link_graph(data)
    G.graph["_logical_directed"] = _logical_directed
    # node_link_graph drops top-level keys other than data["graph"], so the
    # build commit export.to_json writes there is stashed by hand (#3354).
    _commit = data.get("built_at_commit")
    if isinstance(_commit, str) and _commit.strip():
        G.graph["_built_at_commit"] = _commit.strip()
    # Attach the work-memory overlay (derived sidecar next to graph.json) so
    # the query/MCP read surface can annotate NODE lines display-only. Empty
    # when no sidecar exists, leaving un-annotated output byte-identical.
    try:
        from graphify.reflect import load_learning_overlay as _llo
        G.graph["_learning_overlay"] = _llo(resolved)
    except Exception:
        G.graph["_learning_overlay"] = {}
    return G

def _load_graph(graph_path: str) -> nx.Graph:
    try:
        return _read_graph(graph_path)
    except json.JSONDecodeError as exc:
        print(f"error: graph.json is corrupted ({exc}). Re-run /graphify to rebuild.", file=sys.stderr)
        sys.exit(1)
    except (ValueError, FileNotFoundError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        sys.exit(1)

def _same_file_ambiguity_message(G: nx.Graph, label: str, hits: list[str]) -> str:
    source = G.nodes[hits[0]].get("source_file")
    where = f"in {source}" if source else "with no source file"
    listing = "\n".join(
        f"  {G.nodes[h].get('source_location') or G.nodes[h].get('label', h)}\n    id: {h}"
        for h in hits
    )
    return (
        f"{_AMBIGUOUS}'{label}' matches {len(hits)} nodes {where}.\n"
        f"{listing}\n"
        f"Retry with the full node id."
    )

def _segment_chinese(text: str) -> list[str]:
    """Segment Chinese text and keep the original term for exact matching."""
    if _jieba is not None:
        segments = [w for w in _jieba.cut(text) if len(w.strip()) > 0]
    else:
        segments = [text[i:i + 2] for i in range(len(text) - 1)] or [text]
    if len(text) > 1 and text not in segments:
        segments.append(text)
    return segments

def _query_terms(question: str) -> list[str]:
    """Split a query into searchable terms, segmenting Chinese text, then drop
    question/filler words (`_QUERY_STOPWORDS`, English plus common German/
    Romance-language fillers) so content words drive seeding. Falls back to the
    unfiltered terms if the query is all stopwords, so a question like "how does
    it work" or "wie funktioniert das" still seeds on something."""
    terms: list[str] = []
    for raw in question.split():
        if _has_chinese(raw):
            for seg in _segment_chinese(raw.lower().strip()):
                seg = seg.strip()
                if seg and _is_searchable(seg):
                    terms.append(seg)
        else:
            # Strip punctuation without touching Unicode characters (avoid NFKD mangling non-Latin scripts)
            for tok in re.findall(r"\w+", raw.lower()):
                if _is_searchable(tok):
                    terms.append(tok)
    content = [t for t in terms if t not in _QUERY_STOPWORDS]
    return content or terms

def _strip_diacritics(text: str | None) -> str:
    import unicodedata
    if not isinstance(text, str):
        text = "" if text is None else str(text)
    nfkd = unicodedata.normalize("NFKD", text)
    return "".join(c for c in nfkd if not unicodedata.combining(c))

def _compute_idf(G: nx.Graph, terms: list[str]) -> dict[str, float]:
    """IDF weights for query terms, cached in G.graph['_idf_cache'].

    Common terms like 'error' or 'exception' that match hundreds of nodes get
    low weights; rare identifiers like 'FooBarService' get high weights.
    Cache is stored on the graph object itself so it auto-invalidates when
    a hot-reload replaces G with a new object.
    """
    cache: dict[str, float] = G.graph.setdefault("_idf_cache", {})
    N = G.number_of_nodes() or 1
    uncached = [t for t in terms if t not in cache]
    if uncached:
        df: dict[str, int] = {t: 0 for t in uncached}
        for _, data in G.nodes(data=True):
            norm_label = (
                data.get("norm_label") or _strip_diacritics(data.get("label") or "")
            ).lower()
            for t in uncached:
                if t in norm_label:
                    df[t] += 1
        for t in uncached:
            cache[t] = math.log(1 + N / (1 + df[t]))
    return {t: cache.get(t, math.log(1 + N)) for t in terms}

def _infer_context_filters(question: str) -> list[str]:
    lowered = {
        _strip_diacritics(token).lower()
        for token in question.replace("?", " ").replace(",", " ").split()
    }
    inferred: list[str] = []
    for context, hints in _CONTEXT_HINTS:
        if any(hint in lowered for hint in hints):
            inferred.append(context)
    return inferred

def _node_rationale_text(data: dict) -> str:
    """The node's `rationale` attribute normalized like a label (diacritics
    folded, lower-cased) for substring matching. Semantic cleanup writes it as
    one string (several sources joined with blank lines); an extractor may hand
    over a list — join it. Missing or empty -> "" so callers can `if rationale`.
    """
    raw = data.get("rationale")
    if not raw:
        return ""
    if isinstance(raw, (list, tuple)):
        raw = " ".join(str(part) for part in raw if part)
    return _strip_diacritics(str(raw)).lower()

def _normalize_context_filters(filters: list[str] | None) -> list[str]:
    if not filters:
        return []
    normalized: list[str] = []
    seen: set[str] = set()
    for value in filters:
        key = _strip_diacritics(str(value)).strip().lower()
        if not key:
            continue
        key = _CONTEXT_FILTER_ALIASES.get(key, key)
        if key not in seen:
            seen.add(key)
            normalized.append(key)
    return normalized

def _filter_graph_by_context(G: nx.Graph, context_filters: list[str] | None) -> nx.Graph:
    filters = set(_normalize_context_filters(context_filters))
    if not filters:
        return G
    H = G.__class__()
    H.add_nodes_from(G.nodes(data=True))
    if isinstance(G, (nx.MultiGraph, nx.MultiDiGraph)):
        for u, v, key, data in G.edges(keys=True, data=True):
            if data.get("context") in filters:
                H.add_edge(u, v, key=key, **data)
    else:
        for u, v, data in G.edges(data=True):
            if data.get("context") in filters:
                H.add_edge(u, v, **data)
    return H

def _resolve_context_filters(question: str, explicit_filters: list[str] | None = None) -> tuple[list[str], str | None]:
    normalized = _normalize_context_filters(explicit_filters)
    if normalized:
        return normalized, "explicit"
    inferred = _infer_context_filters(question)
    if inferred:
        return inferred, "heuristic"
    return [], None

def _trigrams(text: str) -> set[str]:
    """Character trigrams of `text`; for <3-char text the whole string is the key."""
    if len(text) < 3:
        return {text} if text else set()
    return {text[i:i + 3] for i in range(len(text) - 2)}

def _get_trigram_index(G: nx.Graph) -> dict:
    """Lazily build and cache a trigram -> node-position postings map on the graph.

    Cached on `G.graph` so it auto-invalidates when a hot-reload swaps in a
    fresh graph object, exactly like `_idf_cache`. `set_cache` memoizes per-trigram
    id-sets across queries within one graph generation.
    """
    idx = G.graph.get("_trigram_index")
    if idx is not None:
        return idx
    ids = list(G.nodes())
    postings: dict[str, array] = {}
    for i, nid in enumerate(ids):
        for g in _trigrams(_node_search_text(G.nodes[nid], nid)):
            bucket = postings.get(g)
            if bucket is None:
                bucket = array("i")
                postings[g] = bucket
            bucket.append(i)
    idx = {"ids": ids, "postings": postings, "set_cache": {}}
    G.graph["_trigram_index"] = idx
    return idx

def _resolve_python_qualified(G: nx.Graph, label: str) -> list[str]:
    """Nodes named by a dotted Python symbol such as `pkg.mod.func` (#4366)."""
    qualified = _PY_QUALIFIED_RE.match(label.strip())
    if not qualified:
        return []
    module_path = qualified.group(1).replace(".", "/")
    for path_part in (f"{module_path}.py", f"{module_path}/__init__.py"):
        scoped = _resolve_path_scoped_symbol(G, path_part, qualified.group(2))
        if scoped:
            return scoped
    return []

def _bash_make_id(*parts: str) -> str:
    """Bash symbol node ID via the single shared recipe (#1378).

    Previously an inline copy to dodge an import cycle; ``graphify.ids`` is
    dependency-free, so it can be imported directly.
    """
    return _shared_make_id(*parts)

def _file_node_id_for_path(path: Path, root: Path) -> str:
    # Produce the canonical {parent_dir}_{stem} file-node ID that extract()'s
    # id_remap generates (#1033), so bash `source` edges land on the real file
    # node instead of an orphan. _bash_make_id / _bash_file_stem are exact copies
    # of extract._make_id / extract._file_stem, so IDs match.
    try:
        rel = path.resolve().relative_to(root.resolve())
    except ValueError:
        return _bash_make_id(str(path))  # path outside root: hash absolute path as fallback
    return _bash_make_id(_bash_file_stem(rel))

def _module_stem(module_name: str | None) -> str:
    """Return the final module component used to match Graphify source stems."""

    if not module_name:
        return ""
    return module_name.strip(".").split(".")[-1]

def _node_source_stem(node: dict[str, Any]) -> str:
    """Return the stem of a node's source file."""

    source_file = str(node.get("source_file", ""))
    if not source_file:
        return ""
    return Path(source_file).stem

def find_unique_python_symbol(
    symbol_index: dict[tuple[str, str], list[str]],
    imported: ImportedSymbol,
) -> str | None:
    """Resolve one imported symbol to exactly one Graphify node id."""

    candidates = symbol_index.get((imported.module_stem, imported.imported_name.lower()), [])
    if len(candidates) == 1:
        return candidates[0]
    return None

def iter_raw_calls(per_file: Sequence[object]) -> list[dict[str, Any]]:
    """Return raw calls from all per-file extraction fragments.

    Parameter is ``Sequence[object]`` (not ``Sequence[dict[str, Any] | None]``)
    because external extraction output may contain arbitrary deserialized
    JSON. Defensive against malformed fragments: non-dict per-file entries
    are skipped, non-list ``raw_calls`` are treated as empty, and non-dict
    items inside the list are silently dropped. The downstream resolvers
    assume every returned item is a dict and they expect this guarantee.
    """

    calls: list[dict[str, Any]] = []
    for result in per_file:
        if not isinstance(result, dict):
            continue
        raw_calls = result.get("raw_calls", [])
        if not isinstance(raw_calls, list):
            continue
        for raw_call in raw_calls:
            if isinstance(raw_call, dict):
                calls.append(raw_call)
    return calls

def normalise_callable_label(label: str) -> str:
    """Normalize a node label into the key used for call resolution."""

    return label.strip().strip("()").lstrip(".").lower()

def build_label_index(
    nodes: list[dict[str, Any]],
    edges: "list[dict[str, Any]] | None" = None,
) -> dict[str, list[str]]:
    """Build label -> node id list for conservative cross-file resolution.

    An enum member can never be the target of a call, in any language that
    reaches this shared index — but it is a node like any other, and its
    label can collide with an unrelated bare name (a delegate-typed field
    named the same as one of its own enum's cases, #4245). When *edges* is
    given, a node that is the target of a `case_of` edge is excluded, the
    same way `_build_csharp_type_def_index` already excludes it from TYPE
    lookup (#3795).
    """

    case_of_targets: set[str] = set()
    if edges is not None:
        case_of_targets = {
            e.get("target") for e in edges if isinstance(e, dict) and e.get("relation") == "case_of"
        }
    index: dict[str, list[str]] = {}
    for node in nodes:
        if not node_is_resolvable_symbol(node):
            continue
        node_id = node.get("id")
        if not node_id:
            continue
        if node_id in case_of_targets:
            continue
        key = normalise_callable_label(str(node.get("label", "")))
        if not key:
            continue
        index.setdefault(key, []).append(str(node_id))
    return index

def build_python_symbol_index(nodes: list[dict[str, Any]]) -> dict[tuple[str, str], list[str]]:
    """Build ``(module_stem, normalized_symbol_name) -> node_ids``.

    This index is stricter than the global label index. It uses both the module
    stem and the symbol label, which allows import evidence to resolve calls that
    global label uniqueness alone cannot safely resolve.
    """

    index: dict[tuple[str, str], list[str]] = {}
    for node in nodes:
        if not node_is_resolvable_symbol(node):
            continue
        source_stem = _node_source_stem(node)
        if not source_stem:
            continue
        label = normalise_callable_label(str(node.get("label", "")))
        if not label:
            continue
        node_id = node.get("id")
        if not node_id:
            continue
        index.setdefault((source_stem, label), []).append(str(node_id))
    return index

def resolve_cross_file_raw_calls(
    per_file: Sequence[dict[str, Any] | None],
    all_nodes: list[dict[str, Any]],
    all_edges: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Resolve unqualified raw calls conservatively after all files are known.

    This intentionally preserves Graphify's existing behavior:
    - member calls are skipped;
    - ambiguous labels are skipped;
    - only a single unique candidate is emitted;
    - emitted edges are INFERRED because the raw call alone is not import proof.
    """

    label_index = build_label_index(all_nodes, all_edges)
    known_pairs = existing_edge_pairs(all_edges)
    # nid -> source_file, for the shared god-node tie-breakers (#1553) so a
    # same-named test mock no longer erases a real cross-file call.
    nid_to_source_file = {
        str(n.get("id")): str(n.get("source_file", ""))
        for n in all_nodes
        if n.get("id")
    }
    resolved: list[dict[str, Any]] = []

    for raw_call in iter_raw_calls(per_file):
        callee = str(raw_call.get("callee", "")).strip()
        if not callee:
            continue
        if raw_call.get("is_member_call"):
            continue
        candidates = label_index.get(callee.lower(), [])
        if not candidates:
            continue
        if len(candidates) == 1:
            target: str | None = candidates[0]
        else:
            # Ambiguous bare name. Apply the shared tie-breakers (non-test
            # preference, then path proximity); resolve only if exactly one
            # candidate survives, else preserve the god-node guard and skip.
            target = disambiguate_ambiguous_candidates(
                candidates,
                {c: nid_to_source_file.get(c, "") for c in candidates},
                str(raw_call.get("source_file", "")),
            )
            if target is None:
                continue
        caller = str(raw_call.get("caller_nid", ""))
        if not caller:
            continue
        if target == caller:
            continue
        pair = (caller, target, "calls")
        if pair in known_pairs:
            continue
        known_pairs.add(pair)
        resolved.append(
            {
                "source": caller,
                "target": target,
                "relation": "calls",
                "context": "call",
                "confidence": "INFERRED",
                # 0.85, not 0.8 — the extraction-spec rubric's INFERRED values
                # are a discrete set and 0.8 is not one of them (#2813).
                "confidence_score": 0.85,
                "source_file": raw_call.get("source_file", ""),
                "source_location": raw_call.get("source_location"),
                "weight": 1.0,
            }
        )

    return resolved

def _get_whisper():
    try:
        from faster_whisper import WhisperModel
        return WhisperModel
    except ImportError as exc:
        raise ImportError(
            "Video transcription requires faster-whisper. "
            "Run: pip install 'graphifyy[video]'"
        ) from exc

def _get_yt_dlp():
    try:
        import yt_dlp
        return yt_dlp
    except ImportError as exc:
        raise ImportError(
            "YouTube/URL download requires yt-dlp. "
            "Run: pip install 'graphifyy[video]'"
        ) from exc

def is_url(path: str) -> bool:
    """Return True if the string looks like a URL rather than a file path."""
    return any(path.startswith(p) for p in URL_PREFIXES)

def transcribe_all(
    video_files: list[str],
    output_dir: Path | None = None,
    initial_prompt: str | None = None,
) -> list[str]:
    """Transcribe a list of video/audio files or URLs, return paths to transcript .txt files.

    Already-transcribed files are returned from cache instantly.
    initial_prompt is shared across all files — built once from corpus god nodes.
    """
    if not video_files:
        return []

    transcript_paths = []
    for vf in video_files:
        try:
            t = transcribe(vf, output_dir, initial_prompt=initial_prompt)
            transcript_paths.append(str(t))
        except Exception as exc:
            print(f"  warning: could not transcribe {vf}: {exc}")
    return transcript_paths

def _common_root(paths: List[str]) -> str:
    if not paths:
        return ""
    parts = [Path(p).parts for p in paths if p]
    if not parts:
        return ""
    common = parts[0]
    for p in parts[1:]:
        i = 0
        while i < len(common) and i < len(p) and common[i] == p[i]:
            i += 1
        common = common[:i]
    return str(Path(*common)) if common else ""

def validate_extraction(data: dict) -> list[str]:
    """
    Validate an extraction JSON dict against the graphify schema.
    Returns a list of error strings - empty list means valid.
    """
    if not isinstance(data, dict):
        return ["Extraction must be a JSON object"]

    errors: list[str] = []

    # Collected during the node pass so the edge pass can reuse it. Only
    # hashable ids land here; a non-hashable id (e.g. a list emitted by a
    # malformed LLM extraction) is reported as an error rather than crashing
    # the validator on set construction.
    node_ids: set = set()

    # Nodes
    if "nodes" not in data:
        errors.append("Missing required key 'nodes'")
    elif not isinstance(data["nodes"], list):
        errors.append("'nodes' must be a list")
    else:
        for i, node in enumerate(data["nodes"]):
            if not isinstance(node, dict):
                errors.append(f"Node {i} must be an object")
                continue
            for field in REQUIRED_NODE_FIELDS:
                if field not in node:
                    errors.append(f"Node {i} (id={node.get('id', '?')!r}) missing required field '{field}'")
            if "id" in node:
                try:
                    hash(node["id"])
                except TypeError:
                    errors.append(
                        f"Node {i} has non-hashable id {node['id']!r} - id must be a string"
                    )
                else:
                    node_ids.add(node["id"])
            if "file_type" in node and node["file_type"] not in VALID_FILE_TYPES:
                errors.append(
                    f"Node {i} (id={node.get('id', '?')!r}) has invalid file_type "
                    f"'{node['file_type']}' - must be one of {sorted(VALID_FILE_TYPES)}"
                )

    # Edges - accept "links" (NetworkX <= 3.1) as fallback for "edges"
    edge_list = data.get("edges") if "edges" in data else data.get("links")
    if edge_list is None:
        errors.append("Missing required key 'edges'")
    elif not isinstance(edge_list, list):
        errors.append("'edges' must be a list")
    else:
        for i, edge in enumerate(edge_list):
            if not isinstance(edge, dict):
                errors.append(f"Edge {i} must be an object")
                continue
            for field in REQUIRED_EDGE_FIELDS:
                if field not in edge:
                    errors.append(f"Edge {i} missing required field '{field}'")
            if "confidence" in edge and edge["confidence"] not in VALID_CONFIDENCES:
                errors.append(
                    f"Edge {i} has invalid confidence '{edge['confidence']}' "
                    f"- must be one of {sorted(VALID_CONFIDENCES)}"
                )
            for endpoint in ("source", "target"):
                if endpoint not in edge:
                    continue
                val = edge[endpoint]
                try:
                    unmatched = bool(node_ids) and val not in node_ids
                except TypeError:
                    errors.append(
                        f"Edge {i} {endpoint} {val!r} is non-hashable - must be a string"
                    )
                    continue
                if unmatched:
                    errors.append(f"Edge {i} {endpoint} '{val}' does not match any node id")

    return errors

def assert_valid(data: dict) -> None:
    """Raise ValueError with all errors if extraction is invalid."""
    errors = validate_extraction(data)
    if errors:
        msg = f"Extraction JSON has {len(errors)} error(s):\n" + "\n".join(f"  • {e}" for e in errors)
        raise ValueError(msg)

def _apply_resource_limits() -> None:
    """Best-effort nice + memory cap. Called from inline hook scripts.

    GRAPHIFY_REBUILD_MEMORY_LIMIT_MB caps RSS-ish memory. Uses RLIMIT_DATA on
    macOS (RLIMIT_AS is unreliable under Apple's libmalloc) and RLIMIT_AS on
    Linux. Silently skips if the platform doesn't support it.
    """
    try:
        os.nice(10)
    except (OSError, AttributeError):
        pass
    mb = os.environ.get("GRAPHIFY_REBUILD_MEMORY_LIMIT_MB", "").strip()
    if not mb:
        return
    try:
        limit = int(mb) * 1024 * 1024
    except ValueError:
        return
    try:
        import resource
        which = resource.RLIMIT_DATA if sys.platform == "darwin" else resource.RLIMIT_AS
        soft, hard = resource.getrlimit(which)
        new_hard = hard if hard != resource.RLIM_INFINITY and hard < limit else limit
        resource.setrlimit(which, (limit, new_hard))
    except (ImportError, ValueError, OSError):
        pass

def _build_state_matches(out: Path, state: dict) -> bool:
    """True when ``out`` still holds exactly what the last stamped rebuild wrote.

    Fails closed on anything it cannot prove: a missing or unreadable stamp, a
    graph.json another writer replaced or partly wrote, a pending HTML re-render,
    or a last rebuild that was itself incremental (which is never a sound base
    for skipping a full one).
    """
    try:
        prev = json.loads((out / _BUILD_STATE_NAME).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    if not isinstance(prev, dict):
        return False
    for key, value in state.items():
        if prev.get(key) != value:
            return False
    # Only a full rebuild leaves a graph a full rebuild could have produced.
    if prev.get("full_clean") is not True:
        return False
    try:
        st = (out / "graph.json").stat()
    except OSError:
        return False
    if prev.get("graph_size") != st.st_size or prev.get("graph_mtime_ns") != st.st_mtime_ns:
        return False
    from graphify.exporters.html import _HTML_STALE_MARKER
    if (out / _HTML_STALE_MARKER).exists():
        return False
    return prev.get("html_present") is (out / "graph.html").exists()

def _drain_pending_full(out_dir: Path) -> bool:
    """Consume the full-rebuild marker. Returns True if one was queued."""
    try:
        (out_dir / _PENDING_FULL_FILENAME).unlink()
    except FileNotFoundError:
        return False
    return True

def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False

def _is_single_line(path: Path) -> bool:
    """True when ``path`` holds one line (the compact graph.json layout, #3413)."""
    with path.open("rb") as f:
        f.readline()
        return not f.readline()

def _node_community_map(graph_data: dict) -> dict[str, int]:
    out: dict[str, int] = {}
    for node in graph_data.get("nodes", []):
        node_id = node.get("id")
        cid = node.get("community")
        if node_id is None or cid is None:
            continue
        try:
            out[str(node_id)] = int(cid)
        except (TypeError, ValueError):
            print(
                f"[graphify watch] Skipping node with invalid community id: "
                f"node_id={node_id!r} community={cid!r}",
                file=sys.stderr,
            )
            continue
    return out

def _read_build_excludes(out_dir: Path) -> list[str]:
    """Return the persisted ``--exclude`` patterns for this graph, or []."""
    try:
        path = out_dir / _BUILD_CONFIG_FILENAME
        if path.is_file():
            cfg = json.loads(path.read_text(encoding="utf-8"))
            ex = cfg.get("excludes") if isinstance(cfg, dict) else None
            if isinstance(ex, list):
                return [str(x) for x in ex if isinstance(x, str) and x]
    except (OSError, json.JSONDecodeError):
        pass
    return []

def _read_build_gitignore(out_dir: Path) -> bool:
    """Return whether rebuilds should honor VCS ignore files (default True)."""
    try:
        path = out_dir / _BUILD_CONFIG_FILENAME
        if path.is_file():
            cfg = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(cfg, dict) and isinstance(cfg.get("gitignore"), bool):
                return cfg["gitignore"]
    except (OSError, json.JSONDecodeError):
        pass
    return True

def _rebase_relative_source_files(payload: dict, source_root: Path, target_root: Path) -> None:
    """Rebase cache-root-relative source paths onto the project root."""
    if source_root == target_root:
        return
    for bucket in ("nodes", "edges", "hyperedges"):
        for item in payload.get(bucket, []):
            for key in _PORTABLE_PATH_KEYS:
                source = item.get(key)
                if not source or Path(source).is_absolute():
                    continue
                try:
                    item[key] = (source_root / source).relative_to(target_root).as_posix()
                except ValueError:
                    continue

def _referenced_unscanned_identities(
    existing: dict,
    source_paths: "_StoredSourcePaths",
    *,
    out: Path,
    project_root: Path,
    live_sources: "set[str | None]",
    rebuilt_sources: "set[str | None]",
) -> set[str]:
    """Missing source paths that were never scanned but an unchanged file still points at.

    An extractor can mint a node for a file that is not in the checkout: the
    target of an unresolved dynamic import (``import('./queue.js')``) or a
    project a ``.sln`` / ``<ProjectReference>`` names. The node carries that
    path as its ``source_file``, but it is the REFERRING file's output. The
    corpus sweep read the missing path as a deleted source and evicted it, so
    the unchanged referrer's preserved edges to it dangled and were dropped,
    while a full rebuild of the same tree keeps both.

    Deletion evidence (#1795) is the previous scan: a path listed in
    manifest.json was a real file and is evicted as before. A path that was
    never scanned cannot have been deleted; its nodes stay while a referrer
    that is not re-extracted this run still points at them. A re-extracted
    referrer re-emits them (or not) itself. A path whose nodes carry a
    ``source_location``, or that is the ``source_file`` of any edge, was
    extracted itself and is evicted even if the manifest is stale. Without a
    readable manifest that lists today's files, the old behaviour is kept.
    """
    from graphify.build import _is_ast_tier

    try:
        scanned = json.loads((out / "manifest.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return set()
    if not isinstance(scanned, dict):
        return set()
    scanned_before = {source_paths.absolute_identity(str(key), project_root) for key in scanned}
    if not scanned_before & live_sources:
        # A manifest that lists none of today's files was anchored elsewhere
        # (or is unusable): it is no evidence either way.
        return set()

    owner: dict[str, str] = {}
    produced_by_itself: set[str] = set()
    for node in existing.get("nodes", []):
        source_file = node.get("source_file")
        if not source_file or not node.get("id") or not _is_ast_tier(node):
            continue
        identity = source_paths.identity(source_file)
        if identity and identity not in live_sources and identity not in scanned_before:
            owner[node["id"]] = identity
            if node.get("source_location"):
                produced_by_itself.add(identity)
    if not owner:
        return set()
    missing = set(owner.values())
    referenced: set[str] = set()
    for edge in existing.get("links", existing.get("edges", [])):
        edge_source = source_paths.identity(edge.get("source_file"))
        if edge_source in missing:
            # The missing path emitted edges itself, so it was extracted: a
            # real file, even if the manifest does not list it.
            produced_by_itself.add(edge_source)
            continue
        if edge_source not in live_sources or edge_source in rebuilt_sources:
            continue
        for endpoint in (edge.get("source"), edge.get("target")):
            identity = owner.get(endpoint)
            if identity:
                referenced.add(identity)
    return referenced - produced_by_itself

def _relativize_source_files(payload: dict, root: Path, *, scope: Path | None = None) -> None:
    for bucket in ("nodes", "edges", "hyperedges"):
        for item in payload.get(bucket, []):
            for key in _PORTABLE_PATH_KEYS:
                source = item.get(key)
                if not source:
                    continue
                source_path = Path(source)
                if not source_path.is_absolute():
                    continue
                try:
                    resolved = source_path.resolve()
                    if scope is not None and not _is_relative_to(resolved, scope):
                        continue
                    item[key] = resolved.relative_to(root).as_posix()
                except ValueError:
                    continue

def _report_root_label(watch_path: Path) -> str:
    if watch_path.is_absolute():
        return watch_path.name or str(watch_path)
    return Path.cwd().name if watch_path == Path(".") else str(watch_path)

def _scan_digest(detected: dict) -> str:
    """Fingerprint of WHICH files the scan covers, not what they contain (#4740).

    The manifest cannot answer this on its own: a source whose extraction fails
    is deliberately left unstamped (#2543), so it has no row and a row-based
    comparison cannot tell "same file, still failing" from "file is new". Only
    the in-scope path set separates those, and it is also what catches an edit to
    an ignore rule, a rename and an outright deletion.
    """
    import hashlib

    paths = [
        os.path.abspath(str(f))
        for flist in (detected.get("files") or {}).values()
        for f in flist
    ]
    paths += [
        os.path.abspath(str(f)) for f in (detected.get("resolution_inputs") or [])
    ]
    return hashlib.md5(
        "\n".join(sorted(paths)).encode("utf-8"), usedforsecurity=False
    ).hexdigest()

def _stabilize_rebuild_cwd(watch_path: Path) -> bool:
    """Ensure relative rebuild paths have a usable CWD before queue/lock setup.

    Detached git hooks can inherit a transient working directory that is deleted
    before the background rebuild starts. In that state Path.cwd(),
    Path('.').resolve(), and relative graphify-out mkdirs raise FileNotFoundError
    before the normal rebuild error handling can run. Hooks that know the repo
    root export GRAPHIFY_REPO_ROOT so the rebuild can recover by chdir'ing there.
    """
    if watch_path.is_absolute():
        return True

    repo_root = os.environ.get("GRAPHIFY_REPO_ROOT", "").strip()
    if repo_root and Path(repo_root).is_dir():
        try:
            os.chdir(repo_root)
            return True
        except OSError:
            pass

    try:
        Path.cwd()
        return True
    except FileNotFoundError:
        print(
            "[graphify watch] Rebuild failed: current working directory "
            "no longer exists and GRAPHIFY_REPO_ROOT is not set."
        )
        return False

def _topology_from_graph(G) -> dict:
    from networkx.readwrite import json_graph
    try:
        data = json_graph.node_link_data(G, edges="links")
    except TypeError:
        data = json_graph.node_link_data(G)
    data["hyperedges"] = getattr(G, "graph", {}).get("hyperedges", [])
    return data

def _write_build_config(
    out_dir: Path,
    *,
    excludes: "list[str] | None",
    gitignore: bool | None = None,
) -> None:
    """Persist corpus-shaping options under ``out_dir``.

    Best effort and non clobbering: omitted options retain their existing values.
    """
    if not excludes and gitignore is None:
        return
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
        path = out_dir / _BUILD_CONFIG_FILENAME
        try:
            config = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
        except (OSError, json.JSONDecodeError):
            config = {}
        if not isinstance(config, dict):
            config = {}
        if excludes:
            config["excludes"] = list(excludes)
        if gitignore is not None:
            config["gitignore"] = gitignore
        path.write_text(json.dumps(config), encoding="utf-8")
    except OSError:
        pass

def _cross_community_links(G: nx.Graph, nodes: list[str], own_cid: int, labels: dict[int, str], node_community: dict[str, int]) -> list[tuple[str, int]]:
    """Return (community_label, edge_count) pairs for cross-community connections, sorted descending."""
    counts: dict[str, int] = Counter()
    for nid in nodes:
        for neighbor in G.neighbors(nid):
            ncid = node_community.get(neighbor)
            if ncid is not None and ncid != own_cid:
                counts[labels.get(ncid, f"Community {ncid}")] += 1
    return sorted(counts.items(), key=lambda x: -x[1])

def op0():
    """initial opacity for a revealable element (1 when baking a static frame)."""
    return "1" if STATIC else "0"

def _count_by_ext(paths: list[Path]) -> dict[str, int]:
    """Count files by extension."""
    counter: Counter[str] = Counter()
    for p in paths:
        ext = p.suffix.lower()
        counter[ext] += 1
    return dict(counter.most_common())

def _format_languages(ext_counts: dict[str, int]) -> str:
    parts = []
    for ext, count in ext_counts.items():
        name = _EXT_NAMES.get(ext, ext)
        parts.append(f"{name} ({count})")
    return ", ".join(parts)

def _bench(fn, *, repeats: int) -> list[float]:
    # One uncounted warm-up — `_warm_caches` already populated caches, but
    # this also amortizes any per-call code-path setup unique to `fn`.
    fn()
    times: list[float] = []
    for _ in range(repeats):
        t0 = time.perf_counter()
        fn()
        times.append(time.perf_counter() - t0)
    return times

def _legacy_traversal_count(terms) -> int:
    # 1 combined pass + one per-token singleton pass.
    return 1 + len({tok for t in terms for tok in _search_tokens(t)})

def _load_real_graph(path: str) -> nx.Graph:
    """Light wrapper that just builds a NetworkX graph from a real
    `graphify-out/graph.json`, skipping the size cap and work-memory overlay
    that `serve._load_graph` enforces (the bench is read-only)."""
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    if "links" not in data and "edges" in data:
        data = dict(data, links=data["edges"])
    data = {**data, "directed": True}
    try:
        return nx.readwrite.json_graph.node_link_graph(data, edges="links")
    except TypeError:
        return nx.readwrite.json_graph.node_link_graph(data)

def _resolve_scenarios(args) -> list[list[str]]:
    if args.graph:
        # Real-graph mode: each --query is a natural-language sentence, tokenized
        # using the same helper the production path uses.
        sentences = args.query or ["what calls extract"]
        scenarios = [_query_terms(s) for s in sentences]
        # Dedupe identical token sets (multiple --query args may tokenize the same).
        seen: list[list[str]] = []
        for q in scenarios:
            if q not in seen:
                seen.append(q)
        return seen
    term_counts = [int(s.strip()) for s in args.term_counts.split(",") if s.strip()]
    scenarios: list[list[str]] = []
    for tc in term_counts:
        if tc in QUERIES_BY_TERM_COUNT:
            scenarios.append(QUERIES_BY_TERM_COUNT[tc])
        elif tc > 0:
            scenarios.append([SYLLABLES[i % len(SYLLABLES)] for i in range(tc)])
    return scenarios

def _verify_equality(G, terms) -> tuple[int, int]:
    leg_rank, leg_best, leg_seeds = _legacy_score_and_pick(G, terms)
    opt_rank, opt_best, opt_seeds = _optimized_score_and_pick(G, terms)
    assert leg_rank == opt_rank, (
        f"ranked diverged for terms={terms}: legacy[:5]={leg_rank[:5]} opt[:5]={opt_rank[:5]}"
    )
    assert leg_best == opt_best, (
        f"best_seed_by_term diverged for terms={terms}: legacy={leg_best} opt={opt_best}"
    )
    assert leg_seeds == opt_seeds, (
        f"seeds diverged for terms={terms}: legacy={leg_seeds} opt={opt_seeds}"
    )
    return len(leg_rank), len(leg_seeds)

