def _graph(*edges: tuple[str, str, str]) -> nx.DiGraph:
    g = nx.DiGraph()
    for src, tgt, rel in edges:
        for nid in (src, tgt):
            if nid not in g:
                g.add_node(nid, label=f".{nid.split('.')[-1]}()" if "." in nid else nid)
        g.add_edge(src, tgt, relation=rel)
    return g

