        "id": "requests", "label": "requests", "file_type": "concept", "type": "external",
        "external": True, "source_file": "", "_origin": "semantic",
    })
    graph_path.write_text(json.dumps(data), encoding="utf-8")

    assert _rebuild_code(corpus, no_cluster=True, acquire_lock=False) is True
    nodes = {n["id"]: n for n in _graph(corpus)["nodes"]}
    assert "requests" not in nodes
    assert "_origin" not in nodes["bisect"]

def _built(tmp_path, files):
    paths = []
    for name, body in files.items():
        path = tmp_path / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(body, encoding="utf-8")
        paths.append(path)
    return build_from_json(extract(paths, cache_root=tmp_path, parallel=False), directed=True)

def _hops(G, a, b):
    U = G.to_undirected()
    return nx.shortest_path_length(U, a, b) if nx.has_path(U, a, b) else None

def _inferred_uses(result):
    """(source, target) pairs of every INFERRED cross-file `uses` edge."""
    return {
