def test_ip_is_blocked_rejects_multicast_and_unspecified():
    """#4708: a host resolving to a multicast or unspecified address must be
    blocked by the SSRF guard; ordinary public IPs still pass."""
    for bad in ("224.0.0.1", "239.1.1.1", "ff02::1", "0.0.0.0", "::"):
        assert _ip_is_blocked(ipaddress.ip_address(bad)), f"{bad} should be blocked"
    for good in ("8.8.8.8", "1.1.1.1", "2606:4700:4700::1111"):
        assert not _ip_is_blocked(ipaddress.ip_address(good)), f"{good} should pass"

def _run(cwd, *, graph: bool):
    if graph:
        (cwd / "graphify-out").mkdir(parents=True, exist_ok=True)
        (cwd / "graphify-out" / "graph.json").write_text("{}", encoding="utf-8")
    return subprocess.run(
        [sys.executable, "-m", "graphify", "hook-guard", "gemini"],
        input="", capture_output=True, text=True, cwd=cwd, env=_env(),
    )

def _run(monkeypatch, argv):
    monkeypatch.setattr(mainmod, "_check_skill_version", lambda _: None)
    monkeypatch.setattr(mainmod.sys, "argv", argv)
    try:
        mainmod.main()
    except SystemExit as exc:
        return exc.code or 0
    return 0

def _graph_to_json(G, path):
    from networkx.readwrite import json_graph as jg
    try:
        data = jg.node_link_data(G, edges="links")
    except TypeError:
        data = jg.node_link_data(G)
    path.write_text(json.dumps(data), encoding="utf-8")

def _make_graph(nodes, edges=None):
    """Build a simple nx.Graph from node dicts."""
    G = nx.Graph()
    for n in nodes:
        nid = n["id"]
        G.add_node(nid, **{k: v for k, v in n.items() if k != "id"})
    for e in (edges or []):
        G.add_edge(
            e["source"],
            e["target"],
            **{k: v for k, v in e.items() if k not in ("source", "target")},
        )
    return G

def _edges_between(result, source_ids, target_ids):
