    )

def corpus(tmp_path):
    src = tmp_path / "src"
    src.mkdir()
    for i in range(3):
        (src / f"f{i}.md").write_text(f"# Doc {i}\n\nBody {i}.\n", encoding="utf-8")
    # manifest lives outside the scanned tree so it is never part of the corpus
    return src, str(tmp_path / "manifest.json")

def _shape(graph: dict) -> tuple[set, set]:
    drop = ("community", "community_name")
    nodes = {json.dumps({k: v for k, v in n.items() if k not in drop}, sort_keys=True) for n in graph["nodes"]}
    edges = {json.dumps({k: v for k, v in e.items() if k not in drop}, sort_keys=True)
             for e in graph.get("links", graph.get("edges", []))}
    return nodes, edges

def _extract_js_dir(tmp_path, files: dict[str, str]):
    base = tmp_path / "src"
    base.mkdir()
    for name, body in files.items():
        (base / name).write_text(body)
    old = os.getcwd()
    try:
        os.chdir(tmp_path)
        r = extract(
            [Path("src") / name for name in files],
            cache_root=Path(".cache"), parallel=False,
        )
    finally:
        os.chdir(old)
    nid = {n["label"].rstrip("()"): n["id"] for n in r["nodes"]}
    return r, nid

