def _import_edges(result: dict) -> set[tuple[str, str, str]]:
    return {
        (edge["source"], edge["target"], edge["relation"])
        for edge in result["edges"]
        if edge["relation"] == "imports"
    }

def _call_edges(path: Path, base: Path) -> set[tuple[str, str]]:
    result = extract([path], root=base, cache_root=base, parallel=False)
    label = {node["id"]: node["label"] for node in result["nodes"]}
    return {
        (label.get(edge["source"], edge["source"]), label.get(edge["target"], edge["target"]))
        for edge in result["edges"]
        if edge["relation"] in ("calls", "indirect_call")
    }

def _extract(tmp_path, files: dict[str, str]):
    for name, body in files.items():
        p = tmp_path / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(body)
    old = os.getcwd()
    try:
        os.chdir(tmp_path)
        return extract([Path(n) for n in files],
                       cache_root=tmp_path / ".cache", parallel=False)
    finally:
        os.chdir(old)

def _node(r, label, source_contains=""):
    return next(n for n in r["nodes"]
                if n["label"] == label and source_contains in str(n.get("source_file", "")))

def _references(r):
    return {(e["source"], e["target"]): e for e in r["edges"]
            if e["relation"] == "references"}

