def _edge_labels(result, relation, context=None):
    labels = {n["id"]: _normalize_symbol_label(n["label"]) for n in result["nodes"]}
    pairs = set()
    for e in result["edges"]:
        if e.get("relation") != relation:
            continue
        if context is not None and e.get("context") != context:
            continue
        pairs.add((labels.get(e["source"], e["source"]), labels.get(e["target"], e["target"])))
    return pairs

def _thing_targets_of_make(tmp_path, files):
    for name, text in files.items():
        (tmp_path / name).write_text(text, encoding="utf-8")
    r = extract(sorted(tmp_path.iterdir()), cache_root=tmp_path, parallel=False)
    by_id = {n["id"]: n for n in r["nodes"]}
    make = next(n["id"] for n in r["nodes"] if n["label"] == "make()")
    return [
        by_id[e["target"]]["source_file"] for e in r["edges"]
        if e["relation"] == "references" and e["source"] == make
        and by_id[e["target"]]["label"] == "Thing"
    ]

