def _extract(tmp_path, files: dict[str, str]) -> dict:
    for name, body in files.items():
        p = tmp_path / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(body)
    old = os.getcwd()
    try:
        os.chdir(tmp_path)
        return extract([Path(n) for n in files], cache_root=Path(tempfile.mkdtemp()))
    finally:
        os.chdir(old)

def _has_call_edge(graph: dict, src_label_sub: str, tgt_label_sub: str) -> dict | None:
    """Return the `calls` edge whose source/target labels contain the given
    substrings, or None."""
    labels = _labels(graph["nodes"])
    for e in graph["edges"]:
        if e.get("relation") != "calls":
            continue
        s = labels.get(e.get("source"), "")
        t = labels.get(e.get("target"), "")
        if src_label_sub in s and tgt_label_sub in t:
            return e
    return None

def _method_edges(result: dict) -> set[tuple[str, str]]:
    labels = _labels(result["nodes"])
    return {
        (labels.get(e["source"], ""), labels.get(e["target"], ""))
        for e in result["edges"] if e.get("relation") == "method"
    }

def _mixes_in(graph: dict) -> set[tuple[str, str]]:
    labels = _labels(graph["nodes"])
    return {
        (labels.get(e["source"], ""), labels.get(e["target"], ""))
        for e in graph["edges"] if e.get("relation") == "mixes_in"
    }

def _find_raw_call(result: dict, callee: str) -> dict | None:
    for rc in _raw_calls(result):
        if rc.get("callee") == callee:
            return rc
    return None

def _typed_member_inheritance_edges(
    file_nodes: list[dict],
    *,
    caller_source: str = "child.rb",
) -> list[dict]:
    nodes = [
        *file_nodes,
        {
            "id": "parent",
            "label": "Parent",
            "source_file": "parent.rb",
        },
        {
            "id": "child",
            "label": "Child",
            "source_file": "child.rb",
        },
        {"id": "caller", "label": ".process_all()", "source_file": caller_source},
        {
            "id": "run",
            "label": ".run()",
            "source_file": "parent.rb",
            "metadata": {"ruby_method_kind": "instance"},
        },
    ]
    edges = [
        {"source": "parent", "target": "run", "relation": "method"},
        {
            "source": "child",
            "target": "parent",
            "relation": "inherits",
            "metadata": {
                "ruby_superclass_ref": "Parent",
                "ruby_lexical_scopes": [],
            },
        },
    ]
    raw_call = {
        "caller_nid": "caller",
        "callee": "run",
        "is_member_call": True,
        "receiver_type": "Child",
        "source_file": caller_source,
        "source_location": "L3",
    }

    resolve_ruby_member_calls([{"raw_calls": [raw_call]}], nodes, edges)
    return edges

