        {"pattern": "foo", "path": "src/", "glob": "**/*.ts"},
    ):
        out = _run_grep_tool(tool_input, tmp_path, graph=True).stdout
        assert "graphify query" in out, f"Grep input {tool_input!r} should nudge"

