    even when their label looks like a callable identifier."""
    from graphify.symbol_resolution import node_is_resolvable_symbol

    code = {"id": "n1", "label": "helper", "file_type": "code"}
    doc = {"id": "n2", "label": "helper", "file_type": "document"}
