def _budget_hint(text: str) -> int:
    m = re.search(r"token budget to (\d+)", text)
    assert m, f"no budget hint in: {text[:300]!r}"
    return int(m.group(1))

def _chain_graph(n=60):
    G = nx.Graph()
    for i in range(n):
        G.add_node(f"n{i}", label=f"node_number_{i}", source_file=f"src/f{i}.py",
                   source_location="L1", community=0)
        if i:
            G.add_edge(f"n{i - 1}", f"n{i}", relation="calls", confidence="EXTRACTED")
    return G

def _calls(r: dict, src: str, tgt: str) -> bool:
    labels = {n["id"]: str(n.get("label", "")) for n in r["nodes"]}
    return any(
        e.get("relation") == "calls"
        and labels.get(e.get("source")) == src
        and labels.get(e.get("target")) == tgt
        for e in r["edges"]
    )

def _extract(tmp_path, files: dict[str, str]) -> dict:
    for name, body in files.items():
        p = tmp_path / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(body)
    old = os.getcwd()
    try:
        os.chdir(tmp_path)
        return extract([Path(n) for n in files], cache_root=Path(tempfile.mkdtemp()))
    finally:
        os.chdir(old)

def _method_edge(r: dict, owner: str, method: str) -> bool:
    labels = {n["id"]: str(n.get("label", "")) for n in r["nodes"]}
    return any(
        e.get("relation") == "method"
        and labels.get(e.get("source")) == owner
        and labels.get(e.get("target")) == method
        for e in r["edges"]
    )

def _has_deco(result: dict, owner_nid: str, deco: str) -> bool:
    target = _make_id(deco)
    return any(
        e["source"] == owner_nid
        and e["target"] == target
        and e["relation"] == "references"
        and e.get("context") == "decorator"
        for e in result["edges"]
    )

def _has_deco(result: dict, owner_nid: str, deco: str) -> bool:
    """True if owner_nid references the (cross-file, bare-stub) decorator symbol."""
    tgt = _make_id(deco)
    return any(
        e["source"] == owner_nid
        and e["target"] == tgt
        and e["relation"] == "references"
        and e.get("context") == "decorator"
        for e in result["edges"]
    )

