def __init__(self, workspace_root: Path):
        self.workspace_root = workspace_root.resolve()
        self.user_memory_root = Path("~/.buddhi/memory").expanduser().resolve()

def get_scope_dir(self, scope: str = "project") -> Path:
        """Resolve base directory for a given scope."""
        if scope == "project":
            return self.workspace_root / ".agents" / "memory"
        elif scope == "local":
            return self.workspace_root / ".agents" / "memory.local"
        elif scope == "user":
            return self.user_memory_root
        elif scope.startswith("agent:"):
            agent_name = scope.split(":", 1)[1].strip()
            return self.workspace_root / ".agents" / "agent-memory" / agent_name
        elif scope.startswith("agent-local:"):
            agent_name = scope.split(":", 1)[1].strip()
            return self.workspace_root / ".agents" / "agent-memory-local" / agent_name
        raise ValueError(f"Unknown scope: {scope}")

def check_budget(self, scope: str = "project") -> BudgetStatus:
        """Check MEMORY.md entrypoint line and byte caps."""
        base_dir = self.get_scope_dir(scope)
        memory_md = base_dir / "MEMORY.md"
        if not memory_md.is_file():
            return BudgetStatus(0, 0, 0, True, [])

        text = memory_md.read_text(encoding="utf-8")
        lines = text.splitlines()
        total_lines = len(lines)
        total_bytes = len(text.encode("utf-8"))
        max_line_len = max((len(line) for line in lines), default=0)

        violations: list[str] = []
        if total_lines > MAX_MEMORY_LINES:
            violations.append(
                f"Lines {total_lines} exceeds hard cap of {MAX_MEMORY_LINES}"
            )
        if total_bytes > MAX_MEMORY_BYTES:
            violations.append(
                f"Size {total_bytes} bytes exceeds hard cap of {MAX_MEMORY_BYTES} bytes"
            )
        for idx, line in enumerate(lines, 1):
            if line.startswith("* [") and len(line) > MAX_LINE_CHARS:
                violations.append(
                    f"Line {idx} exceeds {MAX_LINE_CHARS} chars: ({len(line)} chars)"
                )

        is_valid = len(violations) == 0
        return BudgetStatus(
            total_lines, total_bytes, max_line_len, is_valid, violations
        )

def init_bundle(self, scope: str = "project") -> Path:
        """Initialize directory layout, MEMORY.md, and log.md for scope."""
        base_dir = self.get_scope_dir(scope)
        base_dir.mkdir(parents=True, exist_ok=True)

        for topic in set(TOPIC_DIRS.values()):
            topic_dir = base_dir / topic
            topic_dir.mkdir(parents=True, exist_ok=True)
            topic_index = topic_dir / "index.md"
            if not topic_index.exists():
                topic_index.write_text(
                    f"# {topic.capitalize()} Index\n\n", encoding="utf-8"
                )

        memory_md = base_dir / "MEMORY.md"
        if not memory_md.exists():
            memory_md.write_text(
                '---\nokf_version: "0.2"\n---\n\n# Memory Index\n\n',
                encoding="utf-8",
            )

        log_md = base_dir / "log.md"
        if not log_md.exists():
            log_md.write_text("# Memory Mutation Log\n\n", encoding="utf-8")

        return base_dir

def load_node(self, path: Path) -> MemoryNode:
        """Load an OKF memory concept file."""
        text = path.read_text(encoding="utf-8")
        return MemoryNode.from_markdown(text, file_path=path)

def list_nodes(
        self,
        scopes: list[str] | None = None,
        kind: MemoryKind | None = None,
    ) -> list[MemoryNode]:
        """List all memory nodes across given scopes."""
        target_scopes = scopes or ["project", "local"]
        nodes: list[MemoryNode] = []

        for scope in target_scopes:
            try:
                base_dir = self.get_scope_dir(scope)
            except ValueError:
                continue

            if not base_dir.is_dir():
                continue

            for md_file in sorted(base_dir.rglob("*.md")):
                if md_file.name in ("MEMORY.md", "log.md", "index.md"):
                    continue
                try:
                    node = self.load_node(md_file)
                    if kind is None or node.kind == kind:
                        nodes.append(node)
                except (OSError, ValueError):
                    continue

        return nodes

def validate_bundle(self, scope: str = "project") -> dict[str, Any]:
        """Validate frontmatter, staleness of sources, broken relations, and budget."""
        nodes = self.list_nodes(scopes=[scope])
        budget = self.check_budget(scope)

        node_ids = {n.id for n in nodes}
        stale_nodes: list[dict[str, Any]] = []
        broken_relations: list[dict[str, Any]] = []

        for node in nodes:
            # Check source staleness
            for src in node.frontmatter.sources:
                res = verify_source_staleness(self.workspace_root, src)
                if res.is_stale:
                    stale_nodes.append(
                        {
                            "node_id": node.id,
                            "resource": src.resource,
                            "reason": res.reason,
                        }
                    )

            # Check internal memory relations
            for rel in node.frontmatter.relations:
                if rel.target.startswith("mem-") and rel.target not in node_ids:
                    broken_relations.append(
                        {
                            "node_id": node.id,
                            "relation": rel.to_dict(),
                        }
                    )

        return {
            "scope": scope,
            "total_nodes": len(nodes),
            "budget": {
                "total_lines": budget.total_lines,
                "total_bytes": budget.total_bytes,
                "is_valid": budget.is_valid,
                "violations": budget.violations,
            },
            "stale_nodes": stale_nodes,
            "broken_relations": broken_relations,
            "is_valid": budget.is_valid and len(stale_nodes) == 0,
        }

class FileViolation:
    path: str
    bytes: int
    before: int | None

    @property
    def tokens(self) -> int:
        return round(self.bytes / 4)

    @property
    def before_tokens(self) -> int | None:
        return round(self.before / 4) if self.before is not None else None

def check_staged_files(
    paths: list[str], max_tokens: int = 8000
) -> tuple[int, list[str]]:
    """Verify staged versions of paths against ratchet."""
    max_bytes = max_tokens * 4
    try:
        root = get_git_root()
    except (subprocess.CalledProcessError, OSError) as exc:
        return 2, [f"error: not a git repository: {exc}"]

    # Get renames from index
    renames: dict[str, str] = {}
    try:
        diff_out = run_git(["diff", "--cached", "--find-renames", "--name-status"])
        for line in diff_out.splitlines():
            parts = line.split("\t")
            if len(parts) >= 3 and parts[0].startswith("R"):
                renames[parts[2]] = parts[1]
    except (subprocess.CalledProcessError, OSError):
        pass

    normalized: list[str] = []
    for p in paths:
        try:
            rel = os.path.relpath(os.path.realpath(p), root)
        except (ValueError, OSError):
            rel = os.path.relpath(p, root)
        rel_posix = rel.replace("\\", "/")
        if is_source_file(rel_posix):
            normalized.append(rel_posix)

    unauthored = get_unauthored(normalized)
    eval_paths = [p for p in normalized if p not in unauthored]

    failures: list[FileViolation] = []
    for p in eval_paths:
        size = blob_bytes(f":{p}")
        if size is None or size <= max_bytes or is_ignored(f":{p}"):
            continue
        orig = renames.get(p, p)
        before = blob_bytes(f"HEAD:{orig}")
        if before is not None and size <= before:
            continue
        failures.append(FileViolation(path=p, bytes=size, before=before))

    if not failures:
        return 0, []

    lines = [
        f"Commit refused: source files over the budget of {format_tokens(max_bytes)} (bytes // 4)."
    ]
    for f in failures:
        frozen = f.before is not None and f.before > max_bytes
        limit: int = f.before if (frozen and f.before is not None) else max_bytes
        if frozen and f.before is not None:
            why = (
                f"already over budget at {format_tokens(f.before)}, so it may not grow"
            )
        elif f.before is None:
            why = "a new file, so it must fit the budget"
        else:
            why = f"was {format_tokens(f.before)}, so it must fit the budget"
        lines.append(f"  {f.path}: {format_tokens(f.bytes)}, {why}.")
        lines.append(f"    Cut at least {f.bytes - limit:,} bytes.")

    return 1, lines

def find_file(name: str) -> Path | None:
        for d in search_dirs:
            p = d / name
            if p.is_file():
                return p
        return None

def resolve_artifacts(root: Path, report_dir: Path | None = None) -> ResolvedArtifacts:
    search_dirs = []
    if report_dir:
        search_dirs.append(report_dir)
    search_dirs.extend([root, root / ".buddhi" / "a11y"])

    # Also search any active spec dir under .buddhi/specs/*
    specs_root = root / ".buddhi" / "specs"
    if specs_root.is_dir():
        for d in specs_root.iterdir():
            if d.is_dir() and d.name != "done":
                search_dirs.append(d)

    def find_file(name: str) -> Path | None:
        for d in search_dirs:
            p = d / name
            if p.is_file():
                return p
        return None

    return ResolvedArtifacts(
        report_path=find_file("REPORT.md"),
        exceptions_path=find_file("EXCEPTIONS.md"),
        decisions_path=find_file("A11Y-DECISIONS.md"),
    )

def chan(c: float) -> float:
        c /= 255.0
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb: tuple[int, int, int]) -> float:
    def chan(c: float) -> float:
        c /= 255.0
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4

    r, g, b = (chan(c) for c in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast(fg: str, bg: str) -> float:
    l1, l2 = sorted((luminance(hex_rgb(fg)), luminance(hex_rgb(bg))), reverse=True)
    return (l1 + 0.05) / (l2 + 0.05)

def check_contrast_evidence(
    root: Path,
    report: Path,
    src: Path,
    decisions_path: Path | None,
    findings: list[GateFinding],
) -> None:
    body = body_of(report)
    texts = [body] + (
        [body_of(decisions_path)] if decisions_path and decisions_path.is_file() else []
    )

    profile = (
        "shield"
        if re.search(r"\bShield\b|\bAAA\b", body)
        else "launchpad"
        if re.search(r"\bLaunchpad\b", body)
        else "standard"
    )
    floor_default = PROFILE_FLOORS[profile]

    hex_re = re.compile(r"(?<![\w#])#(?:[0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b")
    ratio_re = re.compile(r"(\d+(?:[.,]\d+)?)\s*:\s*1\b")
    rows = 0
    source_hex: set[str] | None = None

    for text in texts:
        for raw in text.splitlines():
            if not raw.lstrip().startswith("|"):
                continue
            line = raw.replace("**", "")
            colors = hex_re.findall(line)
            ratios = [float(r.replace(",", ".")) for r in ratio_re.findall(line)]
            if len(colors) < 2 or not ratios:
                continue
            rows += 1
            fg, bg = colors[0], colors[1]
            declared = ratios[0]
            floor = ratios[1] if len(ratios) > 1 else floor_default
            computed = contrast(fg, bg)
            label = f"{fg} on {bg}"
            if abs(computed - declared) > 0.1:
                findings.append(
                    GateFinding(
                        "ERROR",
                        "contrast-evidence",
                        f"REPORT.md records {label} as {declared:g}:1; the WCAG formula gives {computed:.2f}:1. Measured evidence must match the arithmetic (A11Y.md §3) — recompute with tools/contrast-check.py.",
                    )
                )
                continue
            marked_pass = bool(re.search(r"✅|\bPASS\b|\bOK\b", line, re.IGNORECASE))
            if computed < floor - 0.005 and marked_pass:
                findings.append(
                    GateFinding(
                        "ERROR",
                        "contrast-evidence",
                        f"REPORT.md marks {label} ({computed:.2f}:1) as passing, below the {floor:g}:1 floor it is measured against.",
                    )
                )
            elif computed < floor - 0.005:
                findings.append(
                    GateFinding(
                        "WARN",
                        "contrast-evidence",
                        f"{label} is {computed:.2f}:1, below the {floor:g}:1 floor — recorded honestly; fix it or open an EXCEPTIONS.md entry.",
                    )
                )
            if source_hex is None:
                source_hex = set()
                for path in source_files(root, src):
                    text_src = read(path) or ""
                    source_hex.update(
                        normalize_hex(h) for h in hex_re.findall(text_src)
                    )
            if source_hex:
                for color in (fg, bg):
                    if normalize_hex(color) not in source_hex:
                        findings.append(
                            GateFinding(
                                "WARN",
                                "contrast-evidence",
                                f"{color} (from the pair {label}) does not appear in the source. If tokens are computed at runtime (hsl(), color-mix()) this is expected; otherwise the pair measured a color the project does not use.",
                            )
                        )

    checkpoint_checked = re.search(
        r"^\s*-\s*\[x\][^\n]*(contrast|contraste)", body, re.IGNORECASE | re.MULTILINE
