        # Stored direction of an undirected edge (build_from_json, load_node_link_graph).
        if "_src" in data and "_tgt" in data:
            return (data["_src"], data["_tgt"])
        return None

def edge_key(G: nx.Graph, u: str, v: str, data: dict) -> tuple:
        if G.is_directed():
            return (u, v, data.get("relation", ""))
        return (min(u, v), max(u, v), data.get("relation", ""))

def graph_diff(G_old: nx.Graph, G_new: nx.Graph) -> dict:
    """Compare two graph snapshots and return what changed.

    Returns:
        {
          "new_nodes": [{"id": ..., "label": ...}],
          "removed_nodes": [{"id": ..., "label": ...}],
          "new_edges": [{"source": ..., "target": ..., "relation": ..., "confidence": ...}],
          "removed_edges": [...],
          "summary": "3 new nodes, 5 new edges, 1 node removed"
        }
    """
    old_nodes = set(G_old.nodes())
    new_nodes = set(G_new.nodes())

    added_node_ids = new_nodes - old_nodes
    removed_node_ids = old_nodes - new_nodes

    new_nodes_list = [
        {"id": n, "label": G_new.nodes[n].get("label", n)}
        for n in added_node_ids
    ]
    removed_nodes_list = [
        {"id": n, "label": G_old.nodes[n].get("label", n)}
        for n in removed_node_ids
    ]

    def edge_key(G: nx.Graph, u: str, v: str, data: dict) -> tuple:
        if G.is_directed():
            return (u, v, data.get("relation", ""))
        return (min(u, v), max(u, v), data.get("relation", ""))

    def edge_dir(data: dict) -> tuple | None:
        # Stored direction of an undirected edge (build_from_json, load_node_link_graph).
        if "_src" in data and "_tgt" in data:
            return (data["_src"], data["_tgt"])
        return None

    old_edge_dirs = {
        edge_key(G_old, u, v, d): edge_dir(d)
        for u, v, d in G_old.edges(data=True)
    }
    new_edge_dirs = {
        edge_key(G_new, u, v, d): edge_dir(d)
        for u, v, d in G_new.edges(data=True)
    }
    old_edge_keys = set(old_edge_dirs)
    new_edge_keys = set(new_edge_dirs)

    # A reversed edge (a->b became b->a) keeps its undirected key. Report it as
    # removed + added only when both snapshots carry _src/_tgt and they differ,
    # so graphs without the markers diff exactly as before (#4067).
    reversed_edge_keys = {
        k for k in old_edge_keys & new_edge_keys
        if old_edge_dirs[k] and new_edge_dirs[k] and old_edge_dirs[k] != new_edge_dirs[k]
    }
    added_edge_keys = (new_edge_keys - old_edge_keys) | reversed_edge_keys
    removed_edge_keys = (old_edge_keys - new_edge_keys) | reversed_edge_keys

    new_edges_list = []
    for u, v, d in G_new.edges(data=True):
        if edge_key(G_new, u, v, d) in added_edge_keys:
            new_edges_list.append({
                "source": d.get("_src", u),
                "target": d.get("_tgt", v),
                "relation": d.get("relation", ""),
                "confidence": d.get("confidence", ""),
            })

    removed_edges_list = []
    for u, v, d in G_old.edges(data=True):
        if edge_key(G_old, u, v, d) in removed_edge_keys:
            removed_edges_list.append({
                "source": d.get("_src", u),
                "target": d.get("_tgt", v),
                "relation": d.get("relation", ""),
                "confidence": d.get("confidence", ""),
            })

    parts = []
    if new_nodes_list:
        parts.append(f"{len(new_nodes_list)} new node{'s' if len(new_nodes_list) != 1 else ''}")
    if new_edges_list:
        parts.append(f"{len(new_edges_list)} new edge{'s' if len(new_edges_list) != 1 else ''}")
    if removed_nodes_list:
        parts.append(f"{len(removed_nodes_list)} node{'s' if len(removed_nodes_list) != 1 else ''} removed")
    if removed_edges_list:
        parts.append(f"{len(removed_edges_list)} edge{'s' if len(removed_edges_list) != 1 else ''} removed")
    summary = ", ".join(parts) if parts else "no changes"

    return {
        "new_nodes": new_nodes_list,
        "removed_nodes": removed_nodes_list,
        "new_edges": new_edges_list,
        "removed_edges": removed_edges_list,
        "summary": summary,
    }

def _lost_saved_semantic_nodes(
    saved_nodes: list,
    new_nodes: list,
    deleted_sources: set[str] | None = None,
) -> list[dict]:
    """Saved semantic nodes whose ids are absent from the new graph.

    A node created in this run is not in ``saved_nodes``, so a sourceless stub
    cannot stand in for a missing id. ``deleted_sources`` is the files the user
    removed. A code rebuild is not a deletion: do not pass the rebuilt set.

    An auto-minted import stub (``external`` true, or ``type`` ``external``) is
    rebuilt from the import edges of this run. Dropping one is not a lost
    rationale or document node.
    """
    deleted = {
        norm
        for source in (deleted_sources or ())
        if (norm := _norm_source_file(source))
    }
    new_ids = {node.get("id") for node in new_nodes if isinstance(node, dict)}
    # A semantic ghost deduplicated into its AST twin (#1145) loses its id but
    # the symbol survives at the same (source_file, label).
    new_ast_loc_nodes: set[tuple[str, str]] = set()
    ast_loc_collisions: set[tuple[str, str]] = set()
    for node in new_nodes:
        # Match build_from_json's strict canonical-AST check (#2334).
        if not isinstance(node, dict) or node.get("_origin") != "ast":
            continue
        sf = node.get("source_file")
        if not isinstance(sf, str) or not sf:
            continue
        lbl = str(node.get("label", "")).strip()
        if not lbl:
            continue
        norm_sf = _norm_source_file(sf)
        if not norm_sf:
            continue
        key = (norm_sf, lbl)
        if key in new_ast_loc_nodes:
            ast_loc_collisions.add(key)
        new_ast_loc_nodes.add(key)
    # cluster-only and build_from_json rewrite a legacy semantic id to its
    # canonical stem, then fold a bare doc id into its `_doc` twin. That id
    # is the same node. A missing rationale id has no such successor.
    stem_remap = _semantic_id_remap(saved_nodes, None)
    rewritten = [
        {**node, "id": stem_remap[node["id"]]}
        if isinstance(node, dict) and node.get("id") in stem_remap
        else node
        for node in saved_nodes
    ]
    doc_remap = _doc_twin_remap(rewritten)

    def _renamed_present(node_id: str) -> bool:
        renamed = stem_remap.get(node_id, node_id)
        renamed = doc_remap.get(renamed, renamed)
        return renamed in new_ids

    lost: list[dict] = []
    for node in saved_nodes:
        if not isinstance(node, dict) or _is_ast_tier(node):
            continue
        if node.get("external") is True or node.get("type") == "external":
            continue
        node_id = node.get("id")
        if node_id in new_ids:
            continue
        if isinstance(node_id, str) and _renamed_present(node_id):
            continue
        sf_val = node.get("source_file")
        source = _norm_source_file(sf_val) if isinstance(sf_val, str) else None
        lbl = str(node.get("label", "")).strip()
        if source and lbl:
            loc_key = (source, lbl)
            if loc_key in new_ast_loc_nodes and loc_key not in ast_loc_collisions:
                continue
        if source and source in deleted:
            continue
        lost.append(node)
    return lost

