        "block_parameters",
        "lambda_parameters",
        "bare_parameters",
    }
    param_wrappers = {
        "optional_parameter",
        "splat_parameter",
        "hash_splat_parameter",
        "keyword_parameter",
        "block_parameter",
        "destructured_parameter",
        "forward_parameter",
    }

