        if imp_pkg == tgt_pkg:
            return True
        # `import p.Outer.Inner` against a nested type defined in package p:
        # the leftover segments must all be type-like (uppercase-first), which
        # conventional lowercase external packages can never satisfy.
        if tgt_pkg:
