                local_name,
                node,
                kind="namespace",
                metadata={"full_name": full_namespace},
            )
            add_edge(parent_id, namespace_id, "contains", node)
            for child in node.named_children:
                if child != name_node:
                    scan(child, namespace_id, full_namespace)
            return
