def _peak_tracker():
    lock = threading.Lock()
    state = {"now": 0, "peak": 0}

    def fake_batch(batch_cids, batch_lines, *, backend, model=None):
        with lock:
            state["now"] += 1
            state["peak"] = max(state["peak"], state["now"])
        _time.sleep(0.03)
        with lock:
            state["now"] -= 1
        return {cid: f"n-{cid}" for cid in batch_cids}

    return fake_batch, state

