def test_changed_files_rebuild_keeps_inherited_calls(tmp_path: Path):
    from graphify.watch import _rebuild_code

    files = {
        "Context.sol": _CONTEXT,
        "Ownable.sol": _OWNABLE,
        "Vault.sol": (
            "pragma solidity ^0.8.20;\n"
            'import {Ownable} from "./Ownable.sol";\n'
            "contract Vault is Ownable {\n"
            "    function sweep() external onlyOwner { _msgSender(); }\n"
            "}\n"
        ),
    }
    roots = []
    for name in ("inc", "full"):
        root = tmp_path / name
        root.mkdir()
        for fname, text in files.items():
            (root / fname).write_text(text, encoding="utf-8")
        roots.append(root)
    inc, full = roots
    assert _rebuild_code(inc, no_cluster=True, acquire_lock=False, force=True)
    for root in roots:
        p = root / "Vault.sol"
        p.write_text(p.read_text(encoding="utf-8") + "// touched\n", encoding="utf-8")
    assert _rebuild_code(inc, changed_paths=[inc / "Vault.sol"], no_cluster=True, acquire_lock=False)
    assert _rebuild_code(full, no_cluster=True, acquire_lock=False, force=True)

    def edges_of(root: Path) -> set[tuple[object, object, object]]:
        g = json.loads((root / "graphify-out" / "graph.json").read_text(encoding="utf-8"))
        label = {n["id"]: n.get("label") for n in g["nodes"]}
        links = g.get("links", g.get("edges", []))
        return {
            (label.get(e["source"]), e["relation"], label.get(e["target"]))
            for e in links if e["relation"] in ("calls", "uses")
        }

    full_edges = edges_of(full)
    assert ("sweep()", "uses", "onlyOwner()") in full_edges
    assert ("sweep()", "calls", "_msgSender()") in full_edges
    assert edges_of(inc) == full_edges

def test_ambiguous_absolute_from_import_does_not_bind_symbols_or_calls(tmp_path):
    """An importer-relative hit must not bypass corpus-wide module ambiguity."""
    def write_file(path: Path, content: str) -> Path:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        return path

    paths = []
    for sub in ("a", "b"):
        pkg = tmp_path / sub / "src" / "pkg"
        pkg.mkdir(parents=True)
        paths.append(write_file(pkg / "__init__.py", ""))
        paths.append(write_file(
            pkg / "mod.py",
            "class Thing:\n    pass\n\ndef run():\n    return 1\n",
        ))
    app_path = write_file(
        tmp_path / "a" / "src" / "pkg" / "app.py",
        "from pkg.mod import Thing, run\n\n"
        "def invoke():\n    return Thing(), run()\n",
    )
    paths.append(app_path)

    result = extract(
        paths, cache_root=tmp_path / "cache", root=tmp_path, parallel=False
    )

    app = next(
        node["id"] for node in result["nodes"]
        if node.get("label") == "app.py"
    )
    module_targets = {
        node["id"] for node in result["nodes"]
        if node["id"].startswith(("a_src_pkg_mod", "b_src_pkg_mod"))
    }
    app_edges = [
        edge for edge in result["edges"]
        if edge.get("source", "").startswith("a_src_pkg_app")
    ]

    assert any(
        edge.get("source") == app and edge.get("relation") == "imports_from"
        for edge in app_edges
    ), "keep the unresolved import evidence"
    assert not any(
        edge.get("target") in module_targets
        and edge.get("relation") in ("imports", "imports_from", "calls", "uses")
        for edge in app_edges
    ), f"ambiguous module was resolved to one src tree: {app_edges}"

