def _sanitize_metadata_value(value: object) -> object:
    """Sanitize a metadata value while preserving simple JSON-compatible types."""
    if isinstance(value, bool):
        # bool is a subclass of int — must be checked first to avoid coercion.
        return value
    if isinstance(value, str):
        return _sanitize_metadata_string(value)
    if isinstance(value, dict):
        return sanitize_metadata(value)
    if isinstance(value, (list, tuple)):
        return [_sanitize_metadata_value(item) for item in value[:_METADATA_MAX_LIST_ITEMS]]
    if isinstance(value, (int, float)) or value is None:
        return value
    return _sanitize_metadata_string(value)

def sanitize_metadata(metadata: Mapping[str, Any] | None) -> dict[str, object]:
    """Sanitize metadata keys and values before graph export.

    Metadata is less constrained than node labels: it can contain nested
    dicts, lists, source snippets, external index symbols, and docstring
    text. This helper keeps the data JSON-compatible, strips control
    characters, escapes HTML-sensitive characters in strings, caps long
    strings/lists, and drops entries whose key becomes empty after
    sanitization.
    """
    if metadata is None:
        return {}

    result: dict[str, object] = {}
    for key, value in metadata.items():
        clean_key = _sanitize_metadata_string(key)
        if not clean_key:
            continue
        result[clean_key] = _sanitize_metadata_value(value)
    return result

def _replace_import(match: re.Match) -> str:
        indent = match.group("indent")
        raw_target = match.group("path")

        try:
            target_path = resolve_and_sandbox_import(
                raw_ref=f"@{raw_target}",
                base_dir=base_dir,
                workspace_root=workspace_root,
                user_memory_root=user_memory_root,
            )
        except PermissionError as exc:
            return f"{indent}<!-- @import-forbidden-path: {exc} -->"
        except FileNotFoundError:
            return f"{indent}<!-- @import-missing-file: @{raw_target} -->"
        except (OSError, ValueError) as exc:
            return f"{indent}<!-- @import-error: {exc} -->"

        if target_path in visited:
            return f"{indent}<!-- @import-cycle-detected: @{raw_target} -->"

        if len(visited) >= max_depth:
            return f"{indent}<!-- @import-depth-exceeded: max {max_depth} hops -->"

        file_size = target_path.stat().st_size
        if file_size > MAX_FILE_BYTES:
            return f"{indent}<!-- @import-file-too-large: {file_size} bytes exceeds {MAX_FILE_BYTES} max -->"

        cumulative_bytes[0] += file_size
        if cumulative_bytes[0] > MAX_EXPANSION_BYTES:
            return f"{indent}<!-- @import-budget-exceeded: {cumulative_bytes[0]} bytes exceeds {MAX_EXPANSION_BYTES} max -->"

        sub_visited = set(visited)
        sub_visited.add(target_path)

        child_content = target_path.read_text(encoding="utf-8")
        child_expanded = resolve_imports(
            text=child_content,
            base_file=target_path,
            workspace_root=workspace_root,
            user_memory_root=user_memory_root,
            max_depth=max_depth,
            visited=sub_visited,
            cumulative_bytes=cumulative_bytes,
        )

        indented_lines = [
            f"{indent}{line}" if line.strip() else line
            for line in child_expanded.splitlines()
        ]
        return "\n".join(indented_lines)

